.aq-iso-figure__label--above { transform: translate(-50%, -100%); text-align: center; }

@container (max-width: 860px) {
  .aq-iso-figure__label { white-space: normal; max-width: 40%; }
}

/* ---------- SplitSection: heading column left, content right ---------- */
.aq-split-section { display: grid; grid-template-columns: minmax(0, 4fr) minmax(0, 8fr); gap: var(--space-12); align-items: start; }
.aq-split-section__head { position: sticky; top: var(--space-8); display: flex; flex-direction: column; gap: var(--space-4); }
.aq-split-section__head .aq-h1 { font-size: 32px; line-height: 38px; }
.aq-split-section__head .aq-lead { font-size: 16px; line-height: 26px; }
.aq-split-section__body { min-width: 0; display: flex; flex-direction: column; gap: var(--space-6); }
.aq-split-section__body .aq-prose p:first-child { font: 400 20px/30px var(--font-sans); color: var(--ink); }
.aq-split-section__body .aq-prose p:not(:first-child) { color: var(--ink-muted); }

@container (max-width: 860px) {
  /* Phones: the head stacks above the body with the same head as every other section (aq-h1 30/36, lead 18/28)
     and the same space-8 gap to the content, so split and stacked sections keep one rhythm. */
  .aq-split-section { grid-template-columns: minmax(0, 1fr); gap: var(--space-8); }
  .aq-split-section__head { position: static; }
  .aq-split-section__head .aq-h1 { font-size: 30px; line-height: 36px; }
  .aq-split-section__head .aq-lead { font-size: 18px; line-height: 28px; }
}

/* ---------- Spot: an Icon drawn larger as a figure (assets/icons/<name>.svg), painted with a colour token through a mask ----------
   Sized by the component that holds it, kept icon-sized (36 to 96 px): a diagram stage, a route stop, a plant-map zone. The file comes in
   through an inline mask-image (core.js wSpot) so its URL resolves against the page, not this stylesheet. */
.aq-spot {
  display: inline-block; flex: none; width: var(--space-32); height: var(--space-32);
  background-color: var(--ink);
  -webkit-mask-position: center; mask-position: center; -webkit-mask-size: contain; mask-size: contain;
  -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat;
}
.aq-spot--s { width: var(--space-24); height: var(--space-24); }
.aq-spot--l { width: calc(var(--space-32) + var(--space-8)); height: calc(var(--space-32) + var(--space-8)); }
.aq-spot.aq-spot--icon { width: var(--space-16); height: var(--space-16); }
.aq-spot--muted { background-color: var(--ink-muted); }
.aq-spot--flow { background-color: var(--flow); }
.aq-spot--on-navy { background-color: var(--on-navy-muted); }

/* Phones: one step down (160 -> 128, 128 -> 96); 96 stays, smaller and the drawings close up. */
@container (max-width: 860px) {
  .aq-spot { width: var(--space-24); height: var(--space-24); }
  .aq-spot--l { width: var(--space-32); height: var(--space-32); }
  .aq-spot.aq-spot--icon { width: calc(var(--space-12) + var(--space-2)); height: calc(var(--space-12) + var(--space-2)); }
}

/* ---------- Button ---------- */
.aq-btn {
  display: inline-flex; align-items: center; gap: var(--space-2);
  height: 44px; padding: 0 var(--space-6);
  border: 1px solid transparent; border-radius: var(--radius-sm);
  font: 500 14px/20px var(--font-sans); letter-spacing: 0; white-space: nowrap;
  text-decoration: none; cursor: pointer;
  transition: background-color 200ms cubic-bezier(0.2, 0, 0, 1), border-color 200ms cubic-bezier(0.2, 0, 0, 1), transform 120ms cubic-bezier(0.2, 0, 0, 1);
}
/* Pass 9b motion (Button/motion.js). The transform is one composition so every effect can share it:
   --aq-mx / --aq-my: the primary's magnetic pull (px, numbers); --aq-px / --aq-py: where the press landed (-1..1).
   Press (press-depth): the button sinks a pixel, shrinks to 0.97 and tips up to 3 deg toward the press point, 60 ms
   down and 180 ms back; the arrow pulls back, like a key going down. While the magnet follows the pointer (is-magnet)
   the transform is driven frame by frame, so its transition is dropped. */
.aq-btn { transform: translate(calc(var(--aq-mx, 0) * 1px), calc(var(--aq-my, 0) * 1px)); }
.aq-btn:active:not([disabled]) {
  transform: translate(calc(var(--aq-mx, 0) * 1px), calc(var(--aq-my, 0) * 1px)) perspective(340px)
    rotateX(calc(var(--aq-py, 0) * -3deg)) rotateY(calc(var(--aq-px, 0) * 3deg)) translateY(1px) scale(0.97);
  transition-duration: 60ms;
}
.aq-btn:not(:active) { transition-duration: 200ms, 200ms, 180ms; }
.aq-btn.is-magnet:not(:active) { transition-property: background-color, border-color; }
/* Secondary hover (slide-text): the label rolls up and its copy (a text-shadow one button-height down) rolls in */
.aq-btn--secondary { overflow: hidden; }
.aq-btn__label { display: inline-flex; align-items: center; gap: inherit; }
.aq-btn:active:not([disabled]) .aq-btn__arrow { transform: translateX(1px); }
.aq-btn--primary { background: var(--action); color: var(--on-action); }
.aq-btn--primary:hover { background: var(--action-hover); }
.aq-btn--secondary { background: transparent; color: var(--ink); border-color: var(--line-strong); }
.aq-btn--secondary:hover { border-color: var(--ink); }
.aq-btn--link { height: auto; padding: 0; color: var(--flow); background: none; }
.aq-btn--link:hover { text-decoration: underline; text-underline-offset: 4px; }
.aq-btn[disabled] { background: var(--surface-sunken); color: var(--ink-subtle); border-color: transparent; cursor: not-allowed; }
/* Pending call: a call button whose number is still a [placeholder]. A <span>, not a link: the label as plain text in the
   ground's own colour, no fill or frame, so the draft shows the missing number and nothing pretends to dial */
.aq-btn.aq-btn--pending { padding: 0; background: none; border-color: transparent; color: inherit; cursor: default; }
.aq-btn.aq-btn--pending:active { transform: none; }
.aq-btn__arrow { transition: transform 200ms cubic-bezier(0.2, 0, 0, 1); }
.aq-btn:hover .aq-btn__arrow, .aq-btn:focus-visible .aq-btn__arrow { transform: translateX(4px); }

@media (prefers-reduced-motion: reduce) {
  .aq-btn, .aq-btn__arrow { transition: none; }
  .aq-btn, .aq-btn:active:not([disabled]), .aq-btn:active:not([disabled]) .aq-btn__arrow { transform: none; }
}

/* Narrow containers: long labels wrap inside the button instead of running off the screen */
@container (max-width: 860px) {
  .aq-btn { height: auto; min-height: 44px; max-width: 100%; padding-block: var(--space-3); white-space: normal; text-align: left; }
  .aq-btn--link { min-height: 44px; padding: 0; justify-content: flex-start; }
}

/* ---------- BackToTop: a quiet floating button that returns to the top of a long page ---------- */
/* Fixed bottom right. Hidden (and out of the tab order) until the reader is well down the page, then it fades in.
   A control, so radius-sm and a line-strong rule; it floats, so it takes shadow-overlay (the brand book's one shadow). */
.aq-back-to-top {
  position: fixed; right: var(--space-8); bottom: var(--space-8); z-index: 30;
  display: inline-flex; align-items: center; gap: var(--space-2); height: 44px; padding: 0 var(--space-4);
  background: var(--surface-raised); color: var(--ink); border: 1px solid var(--line-strong); border-radius: var(--radius-sm);
  box-shadow: var(--shadow-overlay); font: 500 14px/20px var(--font-sans); cursor: pointer;
  opacity: 0; visibility: hidden; transform: translateY(var(--space-2));
  transition: opacity 200ms cubic-bezier(0.2, 0, 0, 1), transform 200ms cubic-bezier(0.2, 0, 0, 1), visibility 0s linear 200ms, border-color 200ms, color 200ms;
}
.aq-back-to-top.is-shown { opacity: 1; visibility: visible; transform: none; transition-delay: 0s; }
.aq-back-to-top:hover { border-color: var(--ink); }
.aq-back-to-top:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-back-to-top__arrow { color: var(--flow); font-family: var(--font-mono); transition: transform 200ms cubic-bezier(0.2, 0, 0, 1); }
.aq-back-to-top:hover .aq-back-to-top__arrow { transform: translateY(calc(-1 * var(--space-1))); }

@media (prefers-reduced-motion: reduce) {
  .aq-back-to-top, .aq-back-to-top__arrow { transition: none; transform: none; }
}

/* Phones: the arrow alone in a 44 px square, inside the 16 px gutter; the label stays for screen readers */
@container (max-width: 860px) {
  .aq-back-to-top { right: var(--space-4); bottom: var(--space-4); width: 44px; padding: 0; justify-content: center; }
  .aq-back-to-top__label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
}

/* ---------- Footer: the site map on navy ---------- */
/* The brand footer as the site first drew it, with its spacing: navy in both themes; the Limestone logo at 160 px with one line of
   description and the contact line, then four sitemap columns in one row, headed in the eyebrow style in Limestone; the legal
   line under a faint Limestone hairline. Phones: the head and the columns two by two. */
.aq-footer { background: var(--navy); color: var(--on-navy-muted); padding-block: var(--space-16) var(--space-8); }
.aq-footer__cols { display: grid; grid-template-columns: minmax(0, 1.3fr) repeat(4, minmax(0, 1fr)); gap: var(--space-8); }
.aq-footer__head { display: flex; flex-direction: column; gap: var(--space-4); min-width: 0; }
.aq-footer__logo { display: block; width: 160px; height: auto; }
.aq-footer__desc { margin: 0; font: 400 14px/22px var(--font-sans); color: var(--on-navy-muted); }
.aq-footer__col { min-width: 0; }
.aq-footer .aq-footer__colhead { margin: 0 0 var(--space-3); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--limestone); }
.aq-footer a { display: block; color: var(--on-navy-muted); text-decoration: none; font: 400 14px/28px var(--font-sans); }
.aq-footer a:hover { color: var(--on-navy); text-decoration: underline; text-underline-offset: 4px; }
.aq-footer a:focus-visible { outline: 2px solid var(--limestone); outline-offset: 2px; }

/* Contact line under the description: service number, sales number, head office, one per line in 14/22 on-navy-muted.
   A confirmed number is a tel: link (hover and focus as the other links); a [placeholder] stays text. */
.aq-footer__contact { display: flex; flex-direction: column; align-items: flex-start; margin: 0; font: 400 14px/22px var(--font-sans); font-style: normal; color: var(--on-navy-muted); }
/* Links inside the contact and legal lines keep the line's own type */
.aq-footer .aq-footer__contact a, .aq-footer .aq-footer__legal a { display: inline; font: inherit; }

/* Legal line along the bottom, under a faint Limestone hairline */
.aq-footer__legal {
  display: flex; justify-content: space-between; gap: var(--space-4); flex-wrap: wrap;
  margin-top: var(--space-12); padding-top: var(--space-6);
  border-top: 1px solid color-mix(in srgb, var(--limestone) 25%, transparent);
  font: 400 13px/20px var(--font-sans); color: var(--on-navy-muted);
}

@container (max-width: 860px) {
  .aq-footer__cols { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* ---------- NavBar and phone menu ---------- */
/* Quiet header on surface: logo left, six sections in sentence case, the "Service request" link and one primary button
   right, a line rule below. */
.aq-nav {
  position: relative; display: flex; align-items: center; gap: var(--space-8);
  height: 72px; padding: 0 var(--space-8);
  background: var(--surface); border-bottom: 1px solid var(--line);
}
.aq-nav__home { display: flex; align-items: center; }
.aq-nav__logo { width: 112px; height: auto; }
.aq-nav__logo--lockup { width: 152px; }

.aq-nav__links { display: flex; gap: var(--space-6); margin: 0; padding: 0; list-style: none; flex: 1; min-width: 0; }
/* Section links, and the service link (a utility link, not a section) styled as one */
.aq-nav__links a, .aq-nav__service {
  color: var(--ink-muted); text-decoration: none; font: 500 14px/20px var(--font-sans); white-space: nowrap;
  transition: color 200ms cubic-bezier(0.2, 0, 0, 1);
}
.aq-nav__links a:hover, .aq-nav__links a[aria-current="page"], .aq-nav__service:hover, .aq-nav__service[aria-current="page"] { color: var(--ink); }
/* The links take the free width on wide screens; the spacer only works in the compact bar (here it would add a gap) */
.aq-nav__spacer { display: none; }
.aq-nav__frame { display: inline-flex; }
.aq-nav__toggle { display: none; }

/* Menu: the urgent block, the sections, the page's section jump, then the proposal button, on surface */
.aq-menu { display: none; }
.aq-menu__list { display: grid; margin: 0; padding: 0; list-style: none; }
.aq-menu__list a {
  display: flex; align-items: baseline; gap: var(--space-3); min-height: 44px;
  padding: var(--space-3) 0; color: var(--ink); text-decoration: none;
  font: 400 20px/28px var(--font-sans); letter-spacing: -0.005em; border-bottom: 1px solid var(--line);
}
.aq-menu__list--jump a { font: 400 16px/24px var(--font-sans); color: var(--ink-muted); padding-block: var(--space-2); }
.aq-menu__list a[aria-current] { color: var(--ink); }
.aq-menu__list a[aria-current]::after { content: "→"; content: "→" / ""; margin-left: auto; color: var(--flow); }
.aq-menu__jump { display: grid; }
.aq-menu__label {
  padding: var(--space-6) 0 var(--space-2);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted);
}
.aq-menu__cta { display: flex; }
.aq-menu__cta .aq-btn { flex: 1; justify-content: center; }

/* Urgent block, first in the menu: "Production stopped?", the service number (a tel: link once confirmed, the
   placeholder until then) under a "Call" eyebrow, the hours it is answered, then the service request row. On limestone
   with on-limestone text; data-theme="light" on the block keeps its placeholder, hairline, arrow and focus ring on the
   light values, since limestone stays light in both themes. Text, not a heading: the menu's outline does not change. */
.aq-menu__urgent { display: grid; gap: var(--space-2); padding: var(--space-4); background: var(--limestone); color: var(--on-limestone); }
.aq-menu__ask { margin: 0; font: 500 14px/20px var(--font-sans); color: var(--on-limestone); }
.aq-menu__call {
  display: block; min-height: 44px; padding-block: var(--space-2);
  font: 400 20px/28px var(--font-mono); font-variant-numeric: tabular-nums; color: var(--on-limestone); text-decoration: none; overflow-wrap: anywhere;
}
.aq-menu__k {
  display: inline-block; margin-right: var(--space-3);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-limestone-muted);
}
a.aq-menu__call:hover { text-decoration: underline; text-underline-offset: 4px; text-decoration-thickness: 1px; }
/* The hours the number is answered, right under it: the number never shows without them */
.aq-menu__hours { margin: 0; font: 400 14px/20px var(--font-sans); color: var(--on-limestone-muted); }
.aq-menu__service {
  display: flex; align-items: baseline; gap: var(--space-3); min-height: 44px;
  padding-top: var(--space-3); border-top: 1px solid var(--line-strong); color: var(--on-limestone); text-decoration: none;
  font: 400 20px/28px var(--font-sans); letter-spacing: -0.005em;
}
.aq-menu__service[aria-current]::after { content: "→"; content: "→" / ""; margin-left: auto; color: var(--flow); }

@media (prefers-reduced-motion: reduce) {
  .aq-nav__links a, .aq-nav__service { transition: none; }
}

/* Hover and focus: a flow rule draws under the label from its left end */
.aq-nav__links a, .aq-nav__service { position: relative; }
.aq-nav__links a::before, .aq-nav__service::before {
  content: ""; position: absolute; left: 0; right: 0; bottom: calc(-1 * var(--space-1)); height: 1px; background: var(--flow);
  transform: scaleX(0); transform-origin: 0 50%; transition: transform 240ms cubic-bezier(0.2, 0, 0, 1);
}
.aq-nav__links a:hover::before, .aq-nav__links a:focus-visible::before, .aq-nav__service:hover::before, .aq-nav__service:focus-visible::before { transform: scaleX(1); }
.aq-nav__links a[aria-current="page"]::before, .aq-nav__service[aria-current="page"]::before { content: none; }
.aq-menu__list a, .aq-menu__service { transition: color 160ms cubic-bezier(0.2, 0, 0, 1); }
@media (prefers-reduced-motion: reduce) { .aq-nav__links a::before, .aq-nav__service::before, .aq-menu__list a, .aq-menu__service { transition: none; } }

/* Mid widths: tighten the gaps (at the wide spacing the full bar needs about 1,085 px) */
@container (max-width: 1120px) {
  .aq-nav { gap: var(--space-6); padding: 0 var(--space-6); }
  .aq-nav__links { gap: var(--space-4); }
  .aq-nav .aq-nav__logo--lockup { width: 140px; }
}

/* Compact bar: the logo, six sections, service link and button need about 990 px at the mid spacing, so up to 1,020 px
   the links and the button hide and the toggle opens the menu, which carries all of them */
@container (max-width: 1020px) {
  .aq-nav__links, .aq-nav__service, .aq-nav > .aq-nav__frame { display: none; }
  .aq-nav__spacer { display: block; flex: 1; }
  .aq-nav__toggle { display: inline-flex; }
  .aq-menu {
    display: grid; gap: var(--space-6); padding: var(--space-2) var(--space-6) var(--space-8);
    background: var(--surface); border-bottom: 1px solid var(--line);
  }
}

@container (max-width: 860px) {
  .aq-nav { height: 64px; padding: 0 var(--space-4); gap: var(--space-4); }
  .aq-nav .aq-nav__logo--lockup { width: 112px; }
  .aq-menu { padding-inline: var(--space-4); }
}

/* Pass 9b (NavBar/motion.js). The wide bar's sliding rule (sliding-tabs): one flow rule under the current section that
   slides to the link under the pointer or keyboard focus; 100 px wide, scaled to the link, so it moves on transforms.
   With it on (has-mark) the per-link rules stand down. Without motion the per-link rules above stay. */
.aq-nav__links { position: relative; }
.aq-nav__links > .aq-nav__mark { position: absolute; left: 0; bottom: calc(-1 * var(--space-1)); width: 100px; height: 1px; background: var(--flow); transform-origin: 0 50%; opacity: 0; pointer-events: none; }
.aq-nav.has-mark .aq-nav__links a::before { content: none; }
/* The toggle's mark: two bars that cross while the menu is open (curtain-index's toggle), beside the words */
.aq-nav__toggle { gap: var(--space-3); }
.aq-nav__burger { position: relative; display: inline-block; flex: none; width: 18px; height: 12px; }
.aq-nav__burger > i { position: absolute; left: 0; width: 100%; height: 1.5px; background: currentColor; transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1); }
.aq-nav__burger > i:first-child { top: 2.25px; }
.aq-nav__burger > i:last-child { top: 8.25px; }
.aq-nav__toggle[aria-expanded="true"] .aq-nav__burger > i:first-child { transform: translateY(3px) rotate(45deg); }
.aq-nav__toggle[aria-expanded="true"] .aq-nav__burger > i:last-child { transform: translateY(-3px) rotate(-45deg); }
@media (prefers-reduced-motion: reduce) { .aq-nav__burger > i { transition: none; } }
.aq-nav__toggle-t { white-space: nowrap; }

/* ---------- SectionNav ---------- */
/* A quiet sticky bar: eyebrow label, numbered jump links (the one being read is underlined in `flow`), page progress. */
.aq-section-nav { position: sticky; top: 0; z-index: 5; background: var(--surface); border-bottom: 1px solid var(--line); transition: transform 240ms cubic-bezier(0.2, 0, 0, 1); }
.aq-section-nav .aq-in { display: flex; align-items: stretch; min-height: 56px; }
.aq-section-nav__label {
  display: flex; align-items: center; gap: var(--space-1); flex: none;
  padding-right: var(--space-4); border-right: 1px solid var(--line);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); white-space: nowrap;
}
.aq-section-nav__links {
  display: flex; align-items: center; gap: var(--space-1); flex: 1; min-width: 0;
  margin: 0; padding: 0 var(--space-3); list-style: none;
  overflow-x: auto; scrollbar-width: none; white-space: nowrap;
}
.aq-section-nav__links::-webkit-scrollbar { display: none; }
.aq-section-nav__links li { flex: none; }
.aq-section-nav__links a {
  display: inline-flex; align-items: baseline; gap: var(--space-2);
  padding: var(--space-2) var(--space-3); border-bottom: 1px solid transparent;
  font: 400 14px/20px var(--font-sans); color: var(--ink-muted); text-decoration: none;
  transition: color 200ms cubic-bezier(0.2, 0, 0, 1), border-color 200ms cubic-bezier(0.2, 0, 0, 1);
}
.aq-section-nav__num { font: 400 12px/16px var(--font-mono); letter-spacing: 0.02em; color: var(--ink-subtle); font-variant-numeric: tabular-nums; }
.aq-section-nav__links a:hover { color: var(--ink); }
.aq-section-nav__links a[aria-current="true"] { color: var(--ink); border-bottom-color: var(--flow); }
.aq-section-nav__links a:focus-visible { outline-offset: 0; }

/* Page progress: ten hairline segments and a percentage, updated on scroll */
.aq-section-nav__progress {
  display: flex; flex-direction: column; justify-content: center; align-items: flex-end; gap: var(--space-1); flex: none;
  padding-left: var(--space-4); border-left: 1px solid var(--line);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted);
}
.aq-section-nav__readout { display: flex; align-items: center; gap: var(--space-2); }
.aq-section-nav__meter { display: inline-flex; gap: calc(var(--space-1) / 2); }
.aq-section-nav__seg { display: block; width: var(--space-2); height: 2px; background: var(--line); transition: background-color 200ms cubic-bezier(0.2, 0, 0, 1); }
.aq-section-nav__seg.is-on { background: var(--flow); }
.aq-section-nav__pct { min-width: 4ch; text-align: right; letter-spacing: 0.02em; color: var(--ink-muted); font-variant-numeric: tabular-nums; }

/* Jumped-to sections clear the sticky bar (56 px desktop, 44 px phones) with room above the heading */
.aq-page:has(.aq-section-nav) section[id] { scroll-margin-top: var(--space-16); }

@media (prefers-reduced-motion: reduce) {
  .aq-section-nav, .aq-section-nav__links a, .aq-section-nav__seg { transition: none; }
}

/* Motion marker (SectionNav/motion.js adds has-mark): one flow bar along the bottom edge that slides to the link being
   read. It is 100 px wide and scaled to the link's width, so it moves on transforms only. */
.aq-section-nav__links { position: relative; }
.aq-section-nav__links > .aq-section-nav__mark { position: absolute; left: 0; bottom: 0; width: 100px; height: 1px; background: var(--flow); pointer-events: none; }
.aq-section-nav.has-mark .aq-section-nav__links a[aria-current="true"] { box-shadow: none; text-decoration: none; border-color: transparent; }
/* Hover highlight (fluid-tab-rail): a flow-tint plate that glides under the link the pointer is on; it sits behind the
   links (they stack above it) and is sized and placed by SectionNav/motion.js. Height 0 while it is not showing. */
.aq-section-nav__links > .aq-section-nav__glow { position: absolute; left: 0; top: 0; width: 0; height: 0; border-radius: var(--radius-sm); background: var(--flow-tint); pointer-events: none; opacity: 0; }
.aq-section-nav__links > li:not(.aq-section-nav__glow, .aq-section-nav__mark) { position: relative; z-index: 1; }
.aq-section-nav__links > .aq-section-nav__mark { z-index: 2; }

@container (max-width: 860px) {
  /* Phones: a slim 44 px strip of links; the progress meter becomes a 2 px flow line along its bottom edge, and
     the bar tucks away while the reader scrolls down (is-tucked, set by SectionNav.js), so it never sits on content. */
  .aq-section-nav { border-bottom-color: var(--line); }
  .aq-section-nav.is-tucked { transform: translateY(calc(-100% - 2px)); }
  .aq-section-nav .aq-in { position: relative; min-height: 44px; padding-inline: 0; }
  .aq-section-nav__label, .aq-section-nav__progress-label, .aq-section-nav__pct { display: none; }
  .aq-section-nav__links { padding: 0 var(--space-2); gap: 0; }
  .aq-section-nav__links a { align-items: center; min-height: 44px; padding: 0 var(--space-3); font-size: 13px; line-height: 18px; }
  .aq-section-nav__links a[aria-current="true"] { border-bottom-color: var(--ink); }
  .aq-section-nav__progress { position: absolute; left: 0; right: 0; bottom: -1px; padding: 0; border: 0; pointer-events: none; }
  .aq-section-nav__readout { width: 100%; }
  .aq-section-nav__meter { display: flex; flex: 1; gap: 0; padding: 0; border: 0; }
  .aq-section-nav__seg { flex: 1; width: auto; height: 2px; background: transparent; }
  .aq-section-nav__seg.is-on { background: var(--flow); }
  .aq-page:has(.aq-section-nav) section[id] { scroll-margin-top: var(--space-12); }
}
@container (max-width: 860px) { .aq-section-nav.has-mark .aq-section-nav__links a[aria-current="true"] { border-bottom-color: transparent; } }

/* ---------- ApprovalMerge: who prepares, one approval (look "approval-merge") ----------
   Heading on the left, the intro's figure echoed huge and light on the right. Under it a header strip, then rows on
   hairlines in four fixed tracks (index 4 %, request 40 %, lanes 36 %, wire 20 %), the merged approval in a column of
   its own to the right. Lanes: a vertical hairline per party at its lane centre, continuous through the rows; a row's
   node sits on its party's lane (Aquemi: flow fill; your side: ring in ink; shared: dashed ring), the party and the
   detail centred under it. The wire runs from the node to the bus (a vertical flow line), the bus ends in one stamp.
   Phones: rows stack (request, then the party chip, then the approver stamp); lanes, wires and bus are dropped. */
.aq-approval-merge__top { display: flex; align-items: flex-end; justify-content: space-between; gap: var(--space-8); }
.aq-approval-merge-sec .aq-sec-head .aq-h1 { font: 300 56px/60px var(--font-sans); letter-spacing: -0.03em; max-width: 18ch; }
.aq-approval-merge__hero { margin: 0; display: flex; flex-direction: column; align-items: flex-end; flex: none; }
.aq-approval-merge__fig { font: 300 168px/0.82 var(--font-sans); letter-spacing: -0.06em; color: var(--ink); font-variant-numeric: tabular-nums; }
.aq-approval-merge__unit { margin-top: var(--space-3); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-approval-merge { --bus: calc(var(--space-32) + var(--space-16)); }
.aq-approval-merge__heads { display: grid; grid-template-columns: 44% 36% 20%; padding-right: var(--bus, var(--space-32)); border-bottom: 1px solid var(--line-strong); padding-bottom: var(--space-2); }
.aq-approval-merge:not(.is-one) .aq-approval-merge__heads { padding-right: 0; }
.aq-approval-merge__hk { font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); padding-left: 9%; }
.aq-approval-merge__hk--prep { display: grid; grid-template-columns: repeat(var(--lanes, 2), minmax(0, 1fr)); padding: 0; }
.aq-approval-merge__lane-h { text-align: center; color: var(--ink); }
.aq-approval-merge__lane-h.is-ours { color: var(--flow); }
.aq-approval-merge__hk--appr { text-align: right; padding: 0; }
.aq-approval-merge.is-one .aq-approval-merge__hk--appr { display: none; }
.aq-approval-merge__body { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) var(--bus, var(--space-32)); }
.aq-approval-merge:not(.is-one) .aq-approval-merge__body { grid-template-columns: minmax(0, 1fr); }
.aq-approval-merge__rows { list-style: none; margin: 0; padding: 0; }
.aq-approval-merge__row { position: relative; display: grid; grid-template-columns: 4% 40% 36% 20%; align-items: start; min-height: calc(var(--space-24) + var(--space-4)); border-bottom: 1px solid var(--line); }
.aq-approval-merge__row > .aq-index { grid-column: 1; grid-row: 1; padding-top: var(--space-6); line-height: 28px; }
.aq-approval-merge__t { grid-column: 2; grid-row: 1; margin: 0; padding: var(--space-6) var(--space-4) var(--space-6) 0; font: 300 24px/30px var(--font-sans); letter-spacing: -0.015em; color: var(--ink); text-wrap: balance; }
.aq-approval-merge__lanes { grid-column: 3; grid-row: 1; align-self: stretch; display: grid; grid-template-columns: repeat(var(--lanes, 2), minmax(0, 1fr)); }
.aq-approval-merge__track { position: relative; }
.aq-approval-merge__track::before { content: ""; position: absolute; left: 50%; top: 0; bottom: -1px; border-left: 1px solid var(--line-strong); }
.aq-approval-merge__track.is-ours::before { border-left-color: color-mix(in srgb, var(--flow) 50%, transparent); }
.aq-approval-merge__prep { grid-column: 3; grid-row: 1; position: relative; z-index: 1; margin: 0; display: grid; grid-template-columns: repeat(var(--lanes, 2), minmax(0, 1fr)); justify-items: center; text-align: center; padding-top: calc(var(--space-6) + var(--space-1)); }
.aq-approval-merge__prep > * { grid-column: var(--lane, 1); }
.aq-approval-merge__k { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.aq-approval-merge__node { width: var(--space-4); height: var(--space-4); border-radius: 50%; background: var(--surface); border: 2px solid var(--ink); transition: transform 200ms ease; }
.aq-section--alt .aq-approval-merge__node { background: var(--surface-sunken); }
.aq-approval-merge__prep.is-ours .aq-approval-merge__node { background: var(--flow); border-color: var(--flow); }
.aq-approval-merge__prep.is-shared .aq-approval-merge__node { border-style: dashed; }
.aq-approval-merge__who { margin-top: var(--space-2); padding-inline: var(--space-2); background: var(--surface); font: 500 13px/18px var(--font-mono); color: var(--ink); }
.aq-section--alt .aq-approval-merge__who, .aq-section--alt .aq-approval-merge__det { background: var(--surface-sunken); }
.aq-approval-merge__prep.is-ours .aq-approval-merge__who { color: var(--flow); }
.aq-approval-merge__det { padding: var(--space-1) var(--space-2) var(--space-4); background: var(--surface); font: 400 13px/18px var(--font-sans); color: var(--ink-muted); max-width: 18ch; text-wrap: balance; }
.aq-approval-merge__wire { position: absolute; top: calc(var(--space-6) + var(--space-1) + var(--space-2)); left: calc(44% + 36% * (var(--lane, 1) - 0.5) / var(--lanes, 2)); right: 0; border-top: 1.5px solid var(--line-strong); transform-origin: 0 50%; }
.aq-approval-merge__row:has(.is-ours) .aq-approval-merge__wire { border-top-color: color-mix(in srgb, var(--flow) 60%, var(--line-strong)); }
.aq-approval-merge__appr { grid-column: 4; grid-row: 1; position: relative; z-index: 1; margin: 0; justify-self: end; padding-top: var(--space-6); }
.aq-approval-merge__appr.is-merged { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
.aq-approval-merge__stamp { display: inline-block; padding: var(--space-1) var(--space-3); border: 1.5px solid var(--ink); background: var(--surface); font: 500 13px/18px var(--font-mono); color: var(--ink); }
.aq-approval-merge__row:hover .aq-approval-merge__node { transform: scale(1.35); }
.aq-approval-merge__row:hover .aq-approval-merge__wire { border-top-color: var(--flow); }
.aq-approval-merge__row:hover .aq-approval-merge__t { color: var(--ink); }
/* the bus and its one stamp */
.aq-approval-merge__bus { position: relative; }
.aq-approval-merge__busline { position: absolute; left: 0; top: calc(var(--space-6) + var(--space-3)); bottom: calc(var(--space-24) + var(--space-4) - var(--space-6) - var(--space-3)); border-left: 2px solid var(--flow); transform-origin: 50% 0; }
.aq-approval-merge__big { position: absolute; left: var(--space-6); top: 0; bottom: 0; margin-block: auto; height: fit-content; display: flex; flex-direction: column; gap: var(--space-2); padding: var(--space-4) var(--space-6); border: 2px solid var(--ink); background: var(--surface-raised); }
.aq-approval-merge__big::before { content: ""; position: absolute; right: 100%; top: 50%; width: var(--space-6); border-top: 2px solid var(--flow); }
/* the traced route (hover): an ink wire over the row's wire, an ink stretch of bus from the row to the stamp */
.aq-approval-merge__lit { position: absolute; left: 0; right: 0; top: -2px; border-top: 2.5px solid var(--ink); transform: scaleX(0); transform-origin: 0 50%; }
.aq-approval-merge__buslit { position: absolute; left: -1px; top: 0; height: 0; border-left: 3px solid var(--ink); transform: scaleY(0); transform-origin: 50% 0; }
.aq-approval-merge__bigk { font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-approval-merge__bigv { font: 300 44px/44px var(--font-sans); letter-spacing: -0.03em; color: var(--ink); }

@container (max-width: 860px) {
  .aq-approval-merge__top { flex-direction: column; align-items: flex-start; gap: var(--space-4); }
  .aq-approval-merge-sec .aq-sec-head .aq-h1 { font: 300 36px/42px var(--font-sans); }
  .aq-approval-merge__hero { flex-direction: row; align-items: baseline; gap: var(--space-3); }
  .aq-approval-merge__fig { font-size: 88px; }
  .aq-approval-merge__heads, .aq-approval-merge__lanes, .aq-approval-merge__wire, .aq-approval-merge__bus { display: none; }
  .aq-approval-merge__body { display: block; }
  .aq-approval-merge__row { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2) var(--space-3); min-height: 0; padding: var(--space-4) 0; }
  .aq-approval-merge__row > .aq-index { padding: 0; flex-basis: 100%; line-height: 16px; }
  .aq-approval-merge__t { flex-basis: 100%; padding: 0; font-size: 20px; line-height: 26px; }
  .aq-approval-merge__prep { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; padding: 0; text-align: left; }
  .aq-approval-merge__node { width: var(--space-3); height: var(--space-3); }
  .aq-approval-merge__who, .aq-approval-merge__det { margin: 0; padding: 0; max-width: none; background: none; }
  .aq-approval-merge__appr, .aq-approval-merge__appr.is-merged { position: static; width: auto; height: auto; overflow: visible; clip-path: none; padding: 0; margin-left: auto; }
}

/* ---------- Band ---------- */
/* Ground modifiers: change the section ground for one section. Used on their own by StandardsGrid and DocList (sunken)
   and Closing (navy), and together with .aq-band for the statement band. */
.aq-band--sunken { background: var(--surface-sunken); }
.aq-band--limestone { background: var(--limestone); color: var(--on-limestone); }
.aq-band--limestone .aq-lead, .aq-band--limestone .aq-small { color: var(--on-limestone-muted); }
.aq-band--navy { background: var(--navy); color: var(--on-navy); position: relative; overflow: hidden; }
.aq-band--navy .aq-lead, .aq-band--navy .aq-small { color: var(--on-navy-muted); }
.aq-band--navy .aq-btn--primary { background: var(--limestone); color: var(--navy); }
.aq-band--navy .aq-btn--primary:hover { background: var(--on-navy); }
.aq-band--navy .aq-arc__outer { stroke: var(--on-navy-muted); opacity: 0.5; }
.aq-band--navy .aq-arc__inner { stroke: var(--limestone); }

/* ---------- Statement band: one sentence set large on a quiet ground ---------- */
/* No frame: the band's ground is the separation. The statement in Geist Light (display scale), a supporting line,
   and a faint line drawing of pipework at the right, drawn in currentColor so it follows every ground and theme. */
.aq-band__frame { position: relative; isolation: isolate; padding-block: var(--space-8); }

.aq-band__text { position: relative; z-index: 1; display: flex; flex-direction: column; gap: var(--space-6); max-width: 64%; }
.aq-band__h {
  margin: 0; max-width: 20ch;
  font: 300 56px/60px var(--font-sans); letter-spacing: -0.025em;
  color: inherit; text-wrap: balance; overflow-wrap: break-word;
}
.aq-band__lead { margin: 0; }

/* Mark: one word or phrase named by the content, underlined with a flow hairline */
.aq-band__mark {
  text-decoration: underline; text-decoration-color: var(--flow); text-decoration-thickness: 1px;
  text-underline-offset: 0.14em;
}

/* Pipework drawing: decoration only (aria-hidden), quiet, kept clear of the text */
.aq-band__motif {
  position: absolute; z-index: 0; right: 0; top: 0;
  width: 28%; height: 100%;
  fill: none; stroke: currentColor; stroke-width: 1; vector-effect: non-scaling-stroke;
  opacity: 0.3; pointer-events: none;
}
.aq-band__motif * { vector-effect: non-scaling-stroke; }
.aq-band__motif path, .aq-band__motif rect { stroke: currentColor; }
.aq-band__motif-fine { display: none; }

@container (max-width: 860px) {
  .aq-band__frame { padding-block: 0; }
  .aq-band__text { max-width: none; gap: var(--space-4); }
  .aq-band__h { font-size: 38px; line-height: 44px; }
  .aq-band__lead { font-size: 16px; line-height: 24px; }
  /* The drawing is dropped on phones: the statement needs the full width */
  .aq-band__motif { display: none; }
}

/* ---------- BatteryLimit: site requirements on a navy / limestone split; the divide is the battery limit (look "battery-limit") ----------
   Desktop: the section is limestone with a navy left half (a real element, so motion can open it from the seam); the
   seam is a dash-and-dot battery limit line at the centre, which is also the centre of the content column. Two grid
   columns meet exactly on it: package cards on the left reach right to it, site cards on the right reach left to it.
   The battery-limit row sits on the seam across both grounds. Phones: one column; the navy runs full bleed behind the
   heading and the package cards, the seam turns into the battery-limit card, the limestone carries the site cards. */
.aq-battery-limit-sec { position: relative; overflow: hidden; background: var(--limestone); color: var(--on-limestone); border-top: 0; }
.aq-section + .aq-battery-limit-sec { border-top: 0; }
.aq-battery-limit__navy { position: absolute; left: 0; top: 0; bottom: 0; width: 50%; background: var(--navy); pointer-events: none; }
.aq-battery-limit__line { position: absolute; left: calc(50% - var(--space-2)); top: 0; height: 100%; width: var(--space-4); overflow: visible; pointer-events: none; }
.aq-battery-limit__line line { stroke: var(--flow); stroke-width: 1.5; stroke-dasharray: 18 5 3 5; }
.aq-battery-limit__seam-t {
  /* set on the navy side of the line, near the foot, where no card or leader crosses it (at the top the limit card
     covered it) */
  position: absolute; right: calc(50% + var(--space-3)); bottom: var(--space-6); writing-mode: vertical-rl; transform: rotate(180deg);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.16em; text-transform: uppercase; color: var(--on-navy-muted);
}
.aq-battery-limit-sec > .aq-in { position: relative; }
.aq-battery-limit {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); column-gap: 0;
}
/* desktop placement: the two lists share one set of rows (subgrid), each card spanning two; site cards start a row
   lower, so the tie-in nodes alternate down the seam like a zip (up to seven cards a side) */
.aq-battery-limit__head { grid-row: 1; grid-column: 1; }
.aq-battery-limit__limit { grid-row: 2; grid-column: 1 / -1; }
.aq-battery-limit__side.is-pkg { grid-row: 3; grid-column: 1; }
.aq-battery-limit__side.is-site { grid-row: 3; grid-column: 2; }
.aq-battery-limit__list { grid-row: 4 / span 16; grid-template-rows: subgrid; row-gap: 0; }
.aq-battery-limit__list.is-pkg { grid-column: 1; }
.aq-battery-limit__list.is-site { grid-column: 2; }
.aq-battery-limit__item { padding-block: var(--space-3); }
.is-pkg > [data-k="0"] { grid-row: 1 / span 2; } .is-site > [data-k="0"] { grid-row: 2 / span 2; }
.is-pkg > [data-k="1"] { grid-row: 3 / span 2; } .is-site > [data-k="1"] { grid-row: 4 / span 2; }
.is-pkg > [data-k="2"] { grid-row: 5 / span 2; } .is-site > [data-k="2"] { grid-row: 6 / span 2; }
.is-pkg > [data-k="3"] { grid-row: 7 / span 2; } .is-site > [data-k="3"] { grid-row: 8 / span 2; }
.is-pkg > [data-k="4"] { grid-row: 9 / span 2; } .is-site > [data-k="4"] { grid-row: 10 / span 2; }
.is-pkg > [data-k="5"] { grid-row: 11 / span 2; } .is-site > [data-k="5"] { grid-row: 12 / span 2; }
.is-pkg > [data-k="6"] { grid-row: 13 / span 2; } .is-site > [data-k="6"] { grid-row: 14 / span 2; }
.aq-battery-limit__head { padding-right: var(--space-12); padding-bottom: var(--space-8); }
.aq-battery-limit__head .aq-h1 { color: var(--on-navy); }
.aq-battery-limit__head .aq-lead, .aq-battery-limit__head .aq-eyebrow { color: var(--on-navy-muted); }

/* the battery limit itself: one card across the seam */
.aq-battery-limit__limit { justify-self: center; width: min(100%, 34rem); position: relative; z-index: 1; margin-bottom: var(--space-12); }
.aq-battery-limit__limit .aq-battery-limit__card { background: var(--surface-raised); color: var(--ink); border: 1.5px solid var(--flow); padding: var(--space-6); }
.aq-battery-limit__limit .aq-battery-limit__card dt { color: var(--ink-muted); }
.aq-battery-limit__limit .aq-battery-limit__m { color: var(--ink-muted); }

.aq-battery-limit__side { margin: 0 0 var(--space-4); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; }
.aq-battery-limit__side.is-pkg { color: var(--on-navy-muted); }
.aq-battery-limit__side.is-site { color: var(--on-limestone-muted); padding-left: var(--space-12); }
.aq-battery-limit__list { list-style: none; margin: 0; padding: 0; display: grid; }

/* a card and its leader to the seam */
.aq-battery-limit__item { display: flex; align-items: center; }
.aq-battery-limit__item > .aq-battery-limit__card { flex: 0 1 26rem; min-width: 0; }
.aq-battery-limit__tie { flex: 1 1 var(--space-12); min-width: var(--space-12); display: flex; align-items: center; position: relative; align-self: stretch; }
.aq-battery-limit__lead { flex: 1; height: 0; border-top: 1px solid var(--on-navy-muted); transform-origin: left center; transition: border-color 200ms ease; }
.is-site .aq-battery-limit__lead { border-top-color: var(--on-limestone-muted); transform-origin: right center; }
.aq-battery-limit__node {
  width: 11px; height: 11px; flex: none; border: 1.5px solid var(--flow); background: var(--surface-raised); transform: rotate(45deg);
  transition: background-color 200ms ease;
}
.is-pkg .aq-battery-limit__node { margin-right: -6px; }
.is-site .aq-battery-limit__node { margin-left: -6px; }
.aq-battery-limit__item.is-hot .aq-battery-limit__lead { border-top-color: var(--flow); border-top-width: 1.5px; }
.aq-battery-limit__item.is-hot .aq-battery-limit__node { background: var(--flow); }
.is-pkg .aq-battery-limit__card { border: 1px solid color-mix(in srgb, var(--on-navy-muted) 40%, transparent); color: var(--on-navy); }
.is-site .aq-battery-limit__card { border: 1px solid color-mix(in srgb, var(--on-limestone-muted) 45%, transparent); color: var(--on-limestone); }
.aq-battery-limit__item.is-hot .aq-battery-limit__card { border-color: var(--flow); }
.is-pkg .aq-battery-limit__item.is-hot .aq-battery-limit__card { border-color: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }

.aq-battery-limit__card { padding: var(--space-4) var(--space-6) var(--space-6); display: grid; gap: var(--space-2); transition: border-color 200ms ease; }
.aq-battery-limit__card .aq-index { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; color: var(--flow); }
.is-site .aq-battery-limit__card .aq-index { color: var(--navy); }
.is-pkg .aq-battery-limit__card .aq-index { color: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-battery-limit__p { margin: 0; font: 500 17px/24px var(--font-sans); }
.aq-battery-limit__dl { margin: 0; display: grid; gap: var(--space-2); }
.aq-battery-limit__dl dt { font: 400 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; }
.is-pkg .aq-battery-limit__dl dt { color: var(--on-navy-muted); }
.is-site .aq-battery-limit__dl dt { color: var(--on-limestone-muted); }
.aq-battery-limit__dl dd { margin: 0; font: 400 15px/22px var(--font-sans); }
.aq-battery-limit__v { overflow-wrap: anywhere; }
.is-pkg .aq-battery-limit__m { color: var(--on-navy-muted); }
.is-site .aq-battery-limit__m { color: var(--on-limestone-muted); }
.aq-battery-limit__link { color: var(--flow); }
.is-pkg .aq-battery-limit__link { color: var(--on-navy); text-decoration-color: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-battery-limit__link::after { content: " →"; }

/* the fold is for phones; desktop shows every card */
.aq-fold:not(.is-open) .aq-battery-limit__item.aq-fold-x { display: flex; }
.aq-fold:has(> .aq-battery-limit) > .aq-fold__btn { display: none; }

@container (max-width: 860px) {
  .aq-battery-limit__navy, .aq-battery-limit__line, .aq-battery-limit__seam-t { display: none; }
  .aq-battery-limit { grid-template-columns: minmax(0, 1fr); }
  .aq-battery-limit > *, .aq-battery-limit > .aq-battery-limit__side, .aq-battery-limit > .aq-battery-limit__list { grid-column: 1; grid-row: auto; }
  .aq-battery-limit__side.is-pkg { order: 1; } .aq-battery-limit__list.is-pkg { order: 2; } .aq-battery-limit__limit { order: 3; }
  .aq-battery-limit__side.is-site { order: 4; } .aq-battery-limit__list.is-site { order: 5; }
  .aq-battery-limit__list { grid-row: auto; grid-template-rows: none; gap: var(--space-4); }
  .aq-battery-limit__list > .aq-battery-limit__item { grid-row: auto; padding-block: 0; }
  .aq-battery-limit__head, .aq-battery-limit__side.is-pkg, .aq-battery-limit__list.is-pkg {
    background: var(--navy); box-shadow: 0 0 0 100vmax var(--navy); clip-path: inset(0 -100vmax);
  }
  .aq-battery-limit-sec { padding-top: 0; }
  .aq-battery-limit__head { padding: var(--space-12) 0 var(--space-6); }
  .aq-battery-limit__list.is-pkg { padding-bottom: var(--space-16); }
  .aq-battery-limit__side.is-site { padding-left: 0; }
  /* the seam becomes the battery-limit card, half on each ground */
  .aq-battery-limit__limit { margin: calc(-1 * var(--space-12)) 0 var(--space-8); width: 100%; }
  .aq-battery-limit__tie { display: none; }
  .aq-battery-limit__item > .aq-battery-limit__card { flex: 1 1 auto; }
  .aq-fold:not(.is-open) .aq-battery-limit__item.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-battery-limit) > .aq-fold__btn { display: flex; color: var(--on-limestone-muted); }
}

/* Marks the section as a band of its own ground, so page.js restarts the surface alternation after it. */
.aq-band--split { position: relative; }

/* Border beam (motion only, ported from Subframe Motion "Border beam"): a small light runs round the edge of the card
   the visitor points at. A border-wide ring masks a square of light that travels the card's outline (offset-path). */
.aq-battery-limit__card { position: relative; }
.aq-battery-limit__beam { position: absolute; inset: -1.5px; padding: 2px; pointer-events: none; display: none; visibility: hidden; opacity: 0; overflow: hidden;
  -webkit-mask: linear-gradient(var(--ink) 0 0) content-box, linear-gradient(var(--ink) 0 0); -webkit-mask-composite: xor;
  mask: linear-gradient(var(--ink) 0 0) content-box exclude, linear-gradient(var(--ink) 0 0); }
.aq-battery-limit__light { position: absolute; width: var(--space-24, 6rem); height: var(--space-24, 6rem); offset-path: rect(0 auto auto 0); offset-distance: 0%;
  background: linear-gradient(to left, var(--bl-beam, var(--flow)), var(--flow), transparent); }
.is-pkg .aq-battery-limit__light { --bl-beam: var(--on-navy); }

/* ---------- BinderSpines: an evidence table as ring binders standing on the QA shelf, one per inspector ---------- */
.aq-binder-spines-sec { position: relative; }
.aq-binder-spines { position: relative; margin-top: var(--space-8); }
.aq-binder-spines__row { list-style: none; margin: 0; padding: 0 var(--space-4); display: grid; grid-template-columns: repeat(var(--n, 5), minmax(0, 1fr));
  gap: var(--space-3); align-items: end; height: calc(var(--space-32) * 4.75); }
.aq-fold:not(.is-open) .aq-binder-spines__book.aq-fold-x { display: flex; }
.aq-fold:has(> .aq-binder-spines) > .aq-fold__btn { display: none; }
.aq-binder-spines__shelf { display: block; height: var(--space-3); background: var(--navy); border-top: 1px solid var(--line-strong); transform-origin: 0 50%; }
.aq-binder-spines__shelf::after { content: ""; display: block; height: var(--space-2); margin: var(--space-3) var(--space-8) 0; border-top: 1px solid var(--line-strong); }

/* One binder: caps top and bottom, a paper label, the clause, the reading, the finger hole, the answer at the foot */
.aq-binder-spines__book { position: relative; display: flex; flex-direction: column; gap: var(--space-4); height: var(--h, 100%); min-width: 0;
  padding: var(--space-4) var(--space-4) 0; background: var(--navy); color: var(--on-navy); border: 1px solid var(--navy);
  transition: transform 400ms cubic-bezier(0.2, 0, 0, 1); }
.aq-binder-spines__book.is-lime { background: var(--limestone); color: var(--on-limestone); border-color: color-mix(in srgb, var(--on-limestone) 25%, transparent); }
.aq-binder-spines__book:hover, .aq-binder-spines__book:focus-within { transform: translateY(calc(var(--space-3) * -1)); }
.aq-binder-spines__cap { display: block; height: var(--space-2); margin: 0 calc(var(--space-4) * -1); border-block: 1px solid color-mix(in srgb, currentColor 35%, transparent); flex: none; }
.aq-binder-spines__cap:first-child { margin-top: calc(var(--space-4) * -1); margin-bottom: 0; border-top: 0; }
.aq-binder-spines__cap:last-child { margin-top: 0; border-bottom: 0; }

.aq-binder-spines__label { display: flex; flex-direction: column; gap: var(--space-1); padding: var(--space-3); background: var(--surface-raised); color: var(--ink);
  border: 1px solid var(--line-strong); outline: 1px solid var(--line); outline-offset: calc(var(--space-1) * -1); }
.aq-binder-spines__label .aq-binder-spines__k { color: var(--ink-subtle); }
.aq-binder-spines__who { margin: 0; font: 500 15px/20px var(--font-sans); }
.aq-binder-spines__k { font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-binder-spines__book.is-lime .aq-binder-spines__k { color: var(--on-limestone-muted); }
.aq-binder-spines__book.is-lime .aq-binder-spines__label .aq-binder-spines__k { color: var(--ink-subtle); }

.aq-binder-spines__read { display: flex; flex-direction: column; gap: var(--space-3); min-height: 0; }
.aq-binder-spines__code { margin: 0; font: 300 26px/30px var(--font-mono); letter-spacing: -0.02em; overflow-wrap: anywhere; }
.aq-binder-spines__d { margin: 0; font: 400 14px/21px var(--font-sans); color: var(--on-navy-muted); }
.aq-binder-spines__book.is-lime .aq-binder-spines__d { color: var(--on-limestone-muted); }

.aq-binder-spines__hole { flex: none; align-self: center; width: var(--space-12); height: var(--space-12); margin-top: auto; border-radius: 50%;
  border: 1.5px solid color-mix(in srgb, currentColor 55%, transparent); }
.aq-binder-spines__go { display: flex; flex-direction: column; gap: var(--space-1); min-height: var(--space-16); margin: 0 calc(var(--space-4) * -1); padding: var(--space-3) var(--space-4);
  border-top: 1px solid color-mix(in srgb, currentColor 35%, transparent); color: inherit; text-decoration: none; transition: background-color 300ms cubic-bezier(0.2, 0, 0, 1); }
.aq-binder-spines__to { font: 400 15px/20px var(--font-sans); }
a.aq-binder-spines__go .aq-binder-spines__to::after { content: " →"; color: var(--limestone); transition: margin 300ms; }
.aq-binder-spines__book.is-lime a.aq-binder-spines__go .aq-binder-spines__to::after { color: var(--flow); }
a.aq-binder-spines__go:hover { background: color-mix(in srgb, var(--on-navy) 10%, transparent); }
.aq-binder-spines__book.is-lime a.aq-binder-spines__go:hover { background: color-mix(in srgb, var(--on-navy) 50%, transparent); }
a.aq-binder-spines__go:hover .aq-binder-spines__to::after { margin-left: var(--space-1); }
a.aq-binder-spines__go:focus-visible { outline: 2px solid var(--focus); outline-offset: -2px; }

@container (max-width: 1100px) {
  .aq-binder-spines__row { padding: 0; gap: var(--space-2); height: calc(var(--space-32) * 5.25); }
  .aq-binder-spines__book { padding-inline: var(--space-3); }
  .aq-binder-spines__code { font-size: 21px; line-height: 26px; }
}

/* Phones: the binders lie flat, stacked on the shelf, spines facing you; the fold comes back */
@container (max-width: 860px) {
  .aq-binder-spines { margin-top: var(--space-4); }
  .aq-binder-spines__row { grid-template-columns: minmax(0, 1fr); height: auto; align-items: stretch; gap: var(--space-2); padding: 0; }
  .aq-binder-spines__book { height: auto; margin-right: calc(100% - var(--h, 100%)); padding: var(--space-3) var(--space-4) 0; gap: var(--space-3); }
  .aq-binder-spines__book:hover, .aq-binder-spines__book:focus-within { transform: translateX(var(--space-2)); }
  .aq-binder-spines__cap { display: none; }
  .aq-binder-spines__hole { position: absolute; right: var(--space-4); top: var(--space-4); width: var(--space-8); height: var(--space-8); margin: 0; }
  .aq-binder-spines__label { margin-right: var(--space-12); }
  .aq-binder-spines__code { font-size: 24px; line-height: 28px; }
  .aq-fold:not(.is-open) .aq-binder-spines__book.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-binder-spines) > .aq-fold__btn { display: flex; }
}

/* ---------- BudgetBento: budget ranges as a Swiss bento of numbered tiles (look "budget-bento") ----------
   Desktop: two columns; the lead tile (navy) fills the left column at full height, the module tiles stack on the right
   as wide rows (numeral and icon | scope and range | basis). Hairline grid, square corners, no shadows. Every tile keys
   its fields with the table's column names in mono, so the sheet still reads as scope / range / basis. */
.aq-budget-bento-sec .aq-sec-head { max-width: var(--text-max); }
.aq-budget-bento { display: grid; gap: var(--space-6); }
.aq-budget-bento__grid {
  list-style: none; margin: 0; padding: 0; display: grid;
  grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); grid-auto-rows: auto;
  border-top: 1px solid var(--line-strong); border-left: 1px solid var(--line-strong);
}
.aq-budget-bento__tile {
  position: relative; overflow: hidden; display: grid; background: var(--surface-raised); border-right: 1px solid var(--line-strong); border-bottom: 1px solid var(--line-strong);
  grid-template-columns: var(--space-24) minmax(0, 1fr); column-gap: var(--space-6);
  padding: var(--space-6); min-height: 0;
}
.aq-budget-bento__tile.is-lead { grid-row: span 3; grid-template-columns: minmax(0, 1fr); background: var(--navy); color: var(--on-navy); padding: var(--space-8); align-content: end; }
.aq-budget-bento__n {
  font: 300 64px/0.9 var(--font-sans); letter-spacing: -0.04em; color: var(--ink-subtle); font-variant-numeric: tabular-nums;
  grid-row: 1; grid-column: 1; align-self: start;
}
.aq-budget-bento__tile.is-lead .aq-budget-bento__n {
  position: absolute; top: calc(-1 * var(--space-6)); right: calc(-1 * var(--space-4)); font-size: 240px; line-height: 1;
  color: transparent; -webkit-text-stroke: 1px color-mix(in srgb, var(--on-navy-muted) 45%, transparent); pointer-events: none;
}
.aq-budget-bento__spot { grid-row: 1; grid-column: 1; align-self: end; width: var(--space-16); height: var(--space-16); background-color: var(--ink-muted); margin-top: var(--space-12); }
.aq-budget-bento__body { grid-column: 2; display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); column-gap: var(--space-6); row-gap: var(--space-3); align-content: start; }
.aq-budget-bento__tile.is-lead .aq-budget-bento__body { grid-column: 1; grid-template-columns: minmax(0, 1fr); position: relative; row-gap: var(--space-6); padding-top: var(--space-32); }
.aq-budget-bento__k { margin: 0 0 var(--space-1); font: 400 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-budget-bento__tile.is-lead .aq-budget-bento__k { color: var(--on-navy-muted); }
.aq-budget-bento__p { margin: 0; grid-column: 1 / -1; font: 400 20px/28px var(--font-sans); letter-spacing: -0.01em; color: var(--ink); }
.aq-budget-bento__tile.is-lead .aq-budget-bento__p { font-size: 28px; line-height: 36px; font-weight: 300; color: var(--on-navy); }
.aq-budget-bento__val { min-width: 0; }
.aq-budget-bento__v { margin: 0; font: 400 20px/28px var(--font-mono); font-variant-numeric: tabular-nums; color: var(--ink); }
.aq-budget-bento__tile.is-lead .aq-budget-bento__v { font-size: 30px; line-height: 40px; color: var(--on-navy); }
.aq-budget-bento__v .aq-ph { font-size: 0.8em; }
.aq-budget-bento__m { margin: 0; font: 400 14px/21px var(--font-sans); color: var(--ink-muted); }
.aq-budget-bento__basis { min-width: 0; }
/* lead basis: what the band includes, ticked */
.aq-budget-bento__incl { list-style: none; margin: 0; padding: 0; display: grid; gap: var(--space-2); }
.aq-budget-bento__incl li { position: relative; padding-left: var(--space-6); font: 400 15px/22px var(--font-sans); color: var(--on-navy); }
.aq-budget-bento__incl li::before {
  content: ""; position: absolute; left: 0; top: 5px; width: 10px; height: 6px;
  border-left: 1.5px solid var(--on-navy-muted); border-bottom: 1.5px solid var(--on-navy-muted); transform: rotate(-45deg);
}
/* the range bracket: ruler ticks, the band marked between brackets */
.aq-budget-bento__range { position: relative; display: block; height: var(--space-6); margin-top: var(--space-2); }
.aq-budget-bento__ruler { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.aq-budget-bento__ruler .aq-budget-bento__base { stroke-width: 1; }
.aq-budget-bento__ruler line { stroke: var(--line-strong); stroke-width: 1; vector-effect: non-scaling-stroke; }
.aq-budget-bento__tile.is-lead .aq-budget-bento__ruler line { stroke: color-mix(in srgb, var(--on-navy-muted) 50%, transparent); }
.aq-budget-bento__band { position: absolute; left: 22%; right: 30%; top: 11px; height: 7px; background: var(--flow-tint); border-top: 2px solid var(--flow); }
.aq-budget-bento__tile.is-lead .aq-budget-bento__band { background: color-mix(in srgb, var(--flow) 30%, var(--navy)); border-top-color: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); left: 18%; right: 26%; }
.aq-budget-bento__bk { position: absolute; left: 0; top: -9px; width: 1.5px; height: 16px; background: var(--flow); }
.aq-budget-bento__bk.is-r { left: auto; right: 0; }
.aq-budget-bento__tile.is-lead .aq-budget-bento__bk { background: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-budget-bento__link { grid-column: 1 / -1; color: var(--flow); font: 400 14px/21px var(--font-sans); }

/* the note as chips: what moves the price, what is not included (struck), then the link */
.aq-budget-bento__notes { display: grid; grid-template-columns: max-content minmax(0, 1fr); column-gap: var(--space-6); row-gap: var(--space-3); align-items: baseline; }
.aq-budget-bento__note { display: contents; }
.aq-budget-bento__nk { margin: 0; font: 400 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-budget-bento__chips { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: var(--space-2); }
.aq-budget-bento__chip {
  display: inline-flex; align-items: center; gap: var(--space-2); padding: var(--space-1) var(--space-3);
  border: 1px solid var(--line-strong); font: 400 14px/20px var(--font-sans); color: var(--ink);
}
.aq-budget-bento__cg { width: 9px; height: 12px; flex: none; position: relative; }
.aq-budget-bento__cg::before, .aq-budget-bento__cg::after { content: ""; position: absolute; left: 1px; width: 5px; height: 5px; border-left: 1.5px solid var(--flow); border-top: 1.5px solid var(--flow); }
.aq-budget-bento__cg::before { top: 1px; transform: rotate(45deg); }
.aq-budget-bento__cg::after { bottom: 1px; transform: rotate(-135deg); }
.aq-budget-bento__note.is-out .aq-budget-bento__chip { border-style: dashed; color: var(--ink-muted); }
.aq-budget-bento__note.is-out .aq-budget-bento__cg::before { top: 50%; left: 0; width: 9px; height: 0; border: 0; border-top: 1.5px solid var(--ink-muted); transform: none; }
.aq-budget-bento__note.is-out .aq-budget-bento__cg::after { display: none; }
.aq-budget-bento__more { grid-column: 2; margin: 0; }
.aq-budget-bento__go { display: inline-flex; align-items: center; min-height: 44px; color: var(--flow); font: 400 15px/22px var(--font-sans); text-decoration: none; }
.aq-budget-bento__go::after { content: "→"; margin-left: var(--space-2); transition: transform 200ms ease; }
.aq-budget-bento__go:hover::after, .aq-budget-bento__go:focus-visible::after { transform: translateX(3px); }

/* hover: a tile's band and brackets go flow-strong, the numeral steps in */
.aq-budget-bento__tile { transition: background-color 200ms ease; }
.aq-budget-bento__tile:not(.is-lead):hover { background: var(--surface); }
.aq-budget-bento__tile:not(.is-lead):hover .aq-budget-bento__n { color: var(--flow); }

@container (max-width: 860px) {
  .aq-budget-bento__grid { grid-template-columns: minmax(0, 1fr); }
  .aq-budget-bento__tile.is-lead { grid-row: auto; padding: var(--space-6); }
  .aq-budget-bento__tile.is-lead .aq-budget-bento__n { font-size: 160px; }
  .aq-budget-bento__tile.is-lead .aq-budget-bento__body { padding-top: var(--space-24); }
  .aq-budget-bento__tile { grid-template-columns: var(--space-12) minmax(0, 1fr); column-gap: var(--space-4); padding: var(--space-4); }
  .aq-budget-bento__n { font-size: 36px; }
  .aq-budget-bento__spot { width: var(--space-12); height: var(--space-12); margin-top: var(--space-4); }
  .aq-budget-bento__body { grid-template-columns: minmax(0, 1fr); }
  .aq-budget-bento__tile.is-lead .aq-budget-bento__p { font-size: 24px; line-height: 32px; }
  .aq-budget-bento__tile.is-lead .aq-budget-bento__v { font-size: 22px; line-height: 30px; }
  .aq-budget-bento__notes { grid-template-columns: minmax(0, 1fr); }
  .aq-budget-bento__more { grid-column: 1; }
}

/* Spotlight (motion only, ported from Subframe Motion "Spotlight card"): a soft flow light under the pointer, behind the
   tile's type; on the navy lead tile it is the water's lightened flow */
.aq-budget-bento__tile { position: relative; overflow: hidden; isolation: isolate; }
.aq-budget-bento__spot-light { position: absolute; left: calc(-1 * var(--space-32, 8rem)); top: calc(-1 * var(--space-32, 8rem)); width: calc(2 * var(--space-32, 8rem)); height: calc(2 * var(--space-32, 8rem));
  border-radius: var(--radius-pill); pointer-events: none; display: none; opacity: 0; z-index: -1;
  background: radial-gradient(circle, color-mix(in srgb, var(--flow) 22%, transparent) 0%, color-mix(in srgb, var(--flow) 9%, transparent) 35%, transparent 70%); }
.aq-budget-bento__tile.is-lead .aq-budget-bento__spot-light { background: radial-gradient(circle, color-mix(in srgb, var(--flow) 40%, transparent) 0%, color-mix(in srgb, var(--flow) 16%, transparent) 35%, transparent 70%); }

/* ---------- CapaRing: a defect's way from hold to close as one ring that closes (look "capa-ring"), on a navy ground
   (aq-band--navy). The steps sit in three rows a side of the ring; each row lines up with its node, joined by a
   leader. Lines on-navy-muted, the water and lit nodes flow (lightened towards on-navy so it reads on navy). ---------- */
.aq-capa-ring-sec { position: relative; }
.aq-capa-ring { --ring: calc(var(--space-32) * 3.5); --fl: color-mix(in srgb, var(--flow) 55%, var(--on-navy)); position: relative; }
.aq-capa-ring__fig { position: absolute; left: 50%; top: 0; width: var(--ring, var(--space-32)); height: var(--ring, var(--space-32)); transform: translateX(-50%); }
.aq-capa-ring__svg { display: block; width: 100%; height: 100%; overflow: visible; }
.aq-capa-ring__far { fill: none; stroke: color-mix(in srgb, var(--on-navy-muted) 25%, transparent); stroke-width: 1; }
.aq-capa-ring__tick { stroke: color-mix(in srgb, var(--on-navy-muted) 45%, transparent); stroke-width: 1; }
.aq-capa-ring__base { fill: none; stroke: color-mix(in srgb, var(--on-navy-muted) 35%, transparent); stroke-width: 1.5; }
.aq-capa-ring__flow { fill: none; stroke: var(--fl, var(--flow)); stroke-width: 3; stroke-linecap: round; }
.aq-capa-ring__lead { fill: none; stroke: color-mix(in srgb, var(--on-navy-muted) 50%, transparent); stroke-width: 1; stroke-dasharray: 2 4; }
.aq-capa-ring__dot { fill: var(--navy); stroke: var(--fl, var(--flow)); stroke-width: 2; transition: fill 240ms cubic-bezier(0.2, 0, 0, 1); }
.aq-capa-ring__no { font: 500 13px var(--font-mono); fill: var(--on-navy); transition: fill 240ms cubic-bezier(0.2, 0, 0, 1); }
.aq-capa-ring__valve { fill: none; stroke: var(--on-navy); stroke-width: 1.5; stroke-linejoin: round; }
.aq-capa-ring__node.is-hover .aq-capa-ring__dot { fill: var(--fl, var(--flow)); }
.aq-capa-ring__node.is-hover .aq-capa-ring__no { fill: var(--navy); }
.aq-capa-ring__node.is-hover .aq-capa-ring__valve { stroke: var(--navy); }
.aq-capa-ring__node.is-hover .aq-capa-ring__lead { stroke: var(--fl, var(--flow)); stroke-dasharray: none; }
.aq-capa-ring__core {
  position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
  font: 300 72px/1 var(--font-sans); letter-spacing: -0.03em; color: var(--on-navy);
}

/* the steps: three rows a side, the ring's column empty */
.aq-capa-ring__steps {
  position: relative; list-style: none; margin: 0; padding: 0; display: grid; min-height: var(--ring, var(--space-32));
  grid-template-columns: minmax(0, 1fr) var(--ring, var(--space-32)) minmax(0, 1fr); grid-template-rows: repeat(var(--rows, 3), minmax(0, 1fr)); column-gap: var(--space-6);
}
.aq-capa-ring__step { grid-row: var(--row, 1); align-self: center; max-width: 40ch; padding-block: var(--space-2); }
.aq-capa-ring__step.is-r { grid-column: 3; }
.aq-capa-ring__step.is-l { grid-column: 1; justify-self: end; text-align: right; }
.aq-capa-ring__n { display: block; font: 500 12px/16px var(--font-mono); letter-spacing: 0.04em; color: var(--on-navy-muted); }
.aq-capa-ring__t { margin: var(--space-1) 0 var(--space-2); font: 300 24px/30px var(--font-sans); letter-spacing: -0.015em; color: var(--on-navy); }
.aq-capa-ring__t a { color: inherit; }
.aq-capa-ring__d { margin: 0; font: 400 15px/23px var(--font-sans); color: var(--on-navy-muted); text-wrap: pretty; }
.aq-capa-ring__hold { display: inline-flex; gap: var(--space-2); align-items: baseline; margin: var(--space-3) 0 0; padding: var(--space-1) var(--space-3); border: 1.5px solid var(--limestone); font: 500 12px/18px var(--font-mono); letter-spacing: 0.04em; color: var(--on-navy); }
.aq-capa-ring__hk { text-transform: uppercase; letter-spacing: 0.08em; color: var(--limestone); }

@media (prefers-reduced-motion: reduce) { .aq-capa-ring__dot, .aq-capa-ring__no { transition: none; } }

@container (max-width: 1100px) {
  .aq-capa-ring { --ring: calc(var(--space-32) * 2.75); }
  .aq-capa-ring__t { font-size: 21px; line-height: 27px; }
  .aq-capa-ring__d { font-size: 14px; line-height: 21px; }
}
@container (max-width: 860px) {
  .aq-capa-ring { --ring: min(calc(var(--space-32) * 2.25), 76cqi); }
  .aq-capa-ring__fig { position: relative; left: auto; transform: none; margin: 0 auto var(--space-8); }
  .aq-capa-ring__lead { display: none; }
  .aq-capa-ring__core { font-size: 44px; }
  .aq-capa-ring__steps { display: block; min-height: 0; border-top: 1px solid color-mix(in srgb, var(--on-navy-muted) 35%, transparent); }
  .aq-capa-ring__step, .aq-capa-ring__step.is-l {
    display: grid; grid-template-columns: var(--space-8) minmax(0, 1fr); column-gap: var(--space-3); max-width: none; text-align: left;
    padding: var(--space-4) 0; border-bottom: 1px solid color-mix(in srgb, var(--on-navy-muted) 35%, transparent);
  }
  .aq-capa-ring__n { grid-row: 1 / span 3; padding-top: var(--space-1); }
  .aq-capa-ring__t { margin-top: 0; font-size: 20px; line-height: 26px; }
  .aq-capa-ring__hold { justify-self: start; }
}

/* ---------- CaseStudy: facts beside one large measured-outcome figure ---------- */
/* Cases stack, each opened by a line hairline. Desktop: Client, Problem and System delivered as hairline rows in the
   left column; the outcome on a surface-raised panel spanning their height on the right, its top edge a flow
   hairline and the figure set large in Geist Mono Light. No heavy boxes, no shadows. */
.aq-cases { counter-reset: aq-case; display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-16); }
.aq-case {
  counter-increment: aq-case;
  display: flex; flex-direction: column; gap: var(--space-6);
  min-width: 0; padding-top: var(--space-8);
  border-top: 1px solid var(--line);
}

/* Header: "Case 01" eyebrow, then the title */
.aq-case__title { margin: 0; text-wrap: pretty; overflow-wrap: break-word; }
.aq-case__title::before {
  content: "Case " counter(aq-case, decimal-leading-zero);
  display: block; margin-bottom: var(--space-2);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase;
  font-variant-numeric: tabular-nums; color: var(--ink-muted);
}

/* The dl is the grid; each dt/dd pair is a div (which dl allows) */
.aq-case__facts {
  margin: 0;
  display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
  grid-auto-rows: auto; column-gap: var(--space-12); row-gap: 0;
}
.aq-case__fact, .aq-case__outcome { min-width: 0; display: flex; flex-direction: column; gap: var(--space-2); }
.aq-case__fact { grid-column: 1; padding: var(--space-4) 0; border-top: 1px solid var(--line); }
.aq-case__fact:first-child { border-top: 0; padding-top: 0; }
.aq-case__facts dt, .aq-case__entries dt, .aq-case__figures dt { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-case dd { margin: 0; overflow-wrap: break-word; }
.aq-case__fact dd { font: 400 16px/26px var(--font-sans); color: var(--ink); text-wrap: pretty; }

/* Outcome: spans the fact rows; the flow top hairline is the case's one accent */
.aq-case__outcome {
  grid-column: 2; grid-row: 1 / span 3; align-self: stretch;
  padding: var(--space-6) var(--space-8) var(--space-8);
  background: var(--surface-raised);
  border-top: 1px solid var(--flow);
}
.aq-case__facts:not(:has(> .aq-case__fact)) > .aq-case__outcome { grid-column: 1 / -1; grid-row: auto; }
.aq-case__outcome dd { flex: 1; display: flex; flex-direction: column; justify-content: space-between; gap: var(--space-6); }
.aq-case__figure { display: flex; flex-wrap: wrap; align-items: baseline; column-gap: var(--space-3); row-gap: var(--space-2); min-width: 0; padding-top: var(--space-4); }
.aq-case__num {
  min-width: 0; overflow-wrap: anywhere;
  font: 300 clamp(64px, 9cqi, 128px)/1 var(--font-mono);
  letter-spacing: -0.04em; font-variant-numeric: tabular-nums;
  color: var(--flow);
}
.aq-case__unit { font: 400 28px/34px var(--font-mono); letter-spacing: 0; color: var(--ink); }
/* A bracketed value inside the figure keeps the placeholder look, scaled to the slot */
.aq-case__num .aq-ph, .aq-case__unit .aq-ph { font-size: 0.4em; vertical-align: middle; }
.aq-case__result { max-width: var(--text-max); font: 400 18px/28px var(--font-sans); color: var(--ink); text-wrap: pretty; }

/* No figure supplied yet: a dashed placeholder slot the size of the figure, so the gap is obvious in review */
.aq-case__figure.is-empty {
  align-items: center; justify-content: center;
  min-height: clamp(96px, 9cqi, 128px);
  margin-top: var(--space-4); padding: var(--space-4);
  border: 1px dashed var(--caution);
  background: var(--caution-tint);
}
.aq-case__figure.is-empty .aq-ph { font-size: 18px; line-height: 24px; text-align: center; }
.is-clean .aq-case__figure.is-empty { border-color: var(--line); background: none; color: var(--ink-subtle); }

/* Outcome spans however many fact rows there are (three by default; Standard met makes four). Two-column widths only. */
@container (min-width: 861px) {
  .aq-case__facts:has(> .aq-case__fact:nth-child(4)) > .aq-case__outcome { grid-row: 1 / span 4; }
  .aq-case__facts:not(:has(> .aq-case__fact:nth-child(3))) > .aq-case__outcome { grid-row: 1 / span 2; }
  .aq-case__facts:not(:has(> .aq-case__fact:nth-child(2))) > .aq-case__outcome { grid-row: 1; }
}

/* How it was measured: a full-width hairline row under the facts and outcome, quieter than the facts */
.aq-case__method {
  grid-column: 1 / -1; min-width: 0;
  display: flex; flex-direction: column; gap: var(--space-2);
  margin-top: var(--space-6); padding-top: var(--space-4);
  border-top: 1px solid var(--line);
}
.aq-case__method dd { font: 400 15px/24px var(--font-sans); color: var(--ink-muted); text-wrap: pretty; }

/* Status label: says the case is a template or awaiting client approval (a draft flag, like a placeholder) */
.aq-case__status {
  align-self: flex-start;
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--caution); background: var(--caution-tint);
  padding: var(--space-1) var(--space-2); border-radius: var(--radius-sm);
}

/* Project profile: the KeyFacts strip of headline KPIs, under the title, as KeyFacts draws it (between hairlines,
   on the page ground); the case's own dt/dd rules are scoped so they do not reach it */
.aq-case__profile { background: none; }

/* Motion hook (CaseStudy/motion.js): the timeline line runs out stop by stop through --aq-run; complete without script */
.aq-case__timeline li::before { transform: scaleX(var(--aq-run, 1)); transform-origin: left; }

@container (max-width: 860px) {
  /* Phones: one column. Facts and method are hairline rows (label above text); the outcome panel follows them,
     figure scaled to the screen. */
  .aq-cases { gap: var(--space-12); }
  .aq-case { padding-top: var(--space-6); gap: var(--space-4); }
  .aq-case__facts { grid-template-columns: minmax(0, 1fr); }
  .aq-case__fact, .aq-case__outcome { grid-column: 1; grid-row: auto; }
  .aq-case__fact { gap: var(--space-1); padding: var(--space-3) 0; }
  .aq-case__outcome { margin-block: var(--space-3) 0; padding: var(--space-4); }
  .aq-case__method { grid-column: 1; gap: var(--space-1); margin-top: var(--space-4); padding-top: var(--space-3); }
  .aq-case__fact dd { font-size: 15px; line-height: 24px; }
  .aq-case__outcome dd { gap: var(--space-4); }
  .aq-case__figure { padding-top: var(--space-2); }
  .aq-case__num { font-size: clamp(48px, 16cqi, 80px); }
  .aq-case__unit { font-size: 20px; line-height: 24px; }
  .aq-case__result { font-size: 16px; line-height: 26px; }
  .aq-case__figure.is-empty { min-height: var(--space-24); margin-top: var(--space-2); }
  .aq-case__figure.is-empty .aq-ph { font-size: 15px; }
}

/* ---------- Project record (.aq-case--record): the case told as a project record ----------
   Facts as hairline rows beside the system's equipment drawing with what changed marked on it, then the measured
   outcomes as large figures with the method beneath, then the order-to-release milestones on one hairline. */
.aq-case__label { margin: 0; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-case__brief { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: var(--space-12); align-items: start; }
.aq-case__brief.is-bare { grid-template-columns: minmax(0, 1fr); }
.aq-case__entries { margin: 0; display: flex; flex-direction: column; }
.aq-case__entry { display: flex; flex-direction: column; gap: var(--space-1); padding: var(--space-3) 0; border-top: 1px solid var(--line); }
.aq-case__entry:first-child { border-top: 0; padding-top: 0; }
.aq-case__entry dd { font: 400 16px/26px var(--font-sans); color: var(--ink); text-wrap: pretty; }

/* Drawing: the page's equipment mask on a Plate (base.css: a line frame on surface-raised); numbered marks pin what changed */
.aq-case__drawing { margin: 0; display: flex; flex-direction: column; gap: var(--space-4); min-width: 0; }
/* The inner box is the drawing's own square, so pin positions (% of the drawing) land on the equipment at any width */
.aq-case__plate { position: relative; width: min(100%, 26rem); margin-inline: auto; }
.aq-case__art .aq-illustration { max-width: none; }
.aq-case__mark {
  flex: none; display: inline-grid; place-items: center; box-sizing: border-box; width: var(--space-6); height: var(--space-6);
  border: 1px solid var(--flow); border-radius: var(--radius-sm); background: var(--surface-raised); color: var(--flow);
  font: 500 12px/1 var(--font-mono); font-variant-numeric: tabular-nums;
}
.aq-case__pin { position: absolute; transform: translate(-50%, -50%); display: flex; }
.aq-case__changes { display: flex; flex-direction: column; gap: var(--space-2); }
.aq-case__changes ol { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: var(--space-2); }
.aq-case__changes li { display: flex; align-items: flex-start; gap: var(--space-3); font: 400 15px/24px var(--font-sans); color: var(--ink); text-wrap: pretty; }

/* Outcomes, the hero of the record: large mono figures with the unit, an eyebrow caption, and the method beneath;
   two per row on desktop, one per row on phones */
.aq-case__outcomes { display: flex; flex-direction: column; gap: var(--space-4); padding-top: var(--space-6); border-top: 1px solid var(--line); }
.aq-case__outcomes > .aq-case__result { margin: 0; font-size: 16px; line-height: 26px; }
.aq-case__figures { margin: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: var(--space-12); row-gap: var(--space-8); }
.aq-case__fig { display: flex; flex-direction: column; gap: var(--space-2); min-width: 0; padding-top: var(--space-4); border-top: 1px solid var(--line); }
.aq-case__fig dt { order: 2; }
.aq-case__fig dd { display: contents; }
.aq-case__val { order: 1; display: flex; flex-wrap: wrap; align-items: baseline; column-gap: var(--space-3); row-gap: var(--space-1); min-width: 0; }
.aq-case__fig .aq-case__num { font: 300 clamp(48px, 5.4cqi, 64px)/1.05 var(--font-mono); letter-spacing: -0.04em; color: var(--ink); overflow-wrap: anywhere; }
.aq-case__fig .aq-case__num .aq-ph { font-size: 1em; padding: 0 var(--space-1); }
.aq-case__fig .aq-case__unit { font: 400 clamp(20px, 2.4cqi, 28px)/1.2 var(--font-mono); letter-spacing: 0; color: var(--ink); }
.aq-case__how { order: 3; font: 400 14px/22px var(--font-sans); color: var(--ink-muted); text-wrap: pretty; overflow-wrap: break-word; }

/* Timeline: order to release, milestones as small square stops on one hairline */
.aq-case__timeline { display: flex; flex-direction: column; gap: var(--space-4); padding-top: var(--space-6); border-top: 1px solid var(--line); }
.aq-case__timeline ol { margin: 0; padding: 0; list-style: none; display: grid; grid-template-columns: repeat(var(--n, 6), minmax(0, 1fr)); }
.aq-case__timeline li { position: relative; display: flex; flex-direction: column; align-items: center; gap: var(--space-1); padding-top: var(--space-8); text-align: center; min-width: 0; }
.aq-case__timeline li::before { content: ""; position: absolute; top: var(--space-2); left: 0; right: 0; border-top: 1px solid var(--line-strong); }
.aq-case__timeline li:first-child::before { left: 50%; }
.aq-case__timeline li:last-child::before { right: 50%; }
.aq-case__stop {
  position: absolute; top: calc(var(--space-2) - 4px); left: 50%; transform: translateX(-50%); box-sizing: border-box;
  width: 9px; height: 9px; border: 1px solid var(--flow); background: var(--surface);
}
.aq-case__timeline li:last-child .aq-case__stop { background: var(--flow); }
.aq-case__mt { font: 500 14px/20px var(--font-sans); color: var(--ink); overflow-wrap: break-word; }
.aq-case__when { font: 400 13px/20px var(--font-mono); color: var(--ink-muted); font-variant-numeric: tabular-nums; }

@container (max-width: 860px) {
  /* Phones: drawing first, then the facts, outcomes one per row, then a vertical timeline */
  .aq-case__brief { grid-template-columns: minmax(0, 1fr); gap: var(--space-4); }
  .aq-case__drawing { order: -1; }
  .aq-case__plate { width: min(100%, 17.5rem); }
  .aq-case__entry { padding: var(--space-3) 0; }
  .aq-case__entry dd { font-size: 15px; line-height: 24px; }
  .aq-case__changes li { font-size: 14px; line-height: 22px; }
  .aq-case__outcomes, .aq-case__timeline { padding-top: var(--space-4); }
  .aq-case__figures { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-6); }
  .aq-case__fig .aq-case__num { font-size: clamp(40px, 13cqi, 52px); }
  .aq-case__fig .aq-case__unit { font-size: 20px; }
  .aq-case__how { font-size: 13px; line-height: 20px; }
  .aq-case__timeline ol { grid-template-columns: minmax(0, 1fr); }
  .aq-case__timeline li { flex-direction: row; flex-wrap: wrap; align-items: baseline; justify-content: space-between; column-gap: var(--space-3); padding: 0 0 var(--space-4) var(--space-8); text-align: left; }
  .aq-case__timeline li::before { top: var(--space-2); bottom: 0; left: 4px; right: auto; border-top: 0; border-left: 1px solid var(--line-strong); }
  .aq-case__timeline li:first-child::before { left: 4px; }
  .aq-case__timeline li:last-child::before { display: none; }
  .aq-case__timeline li:last-child { padding-bottom: 0; }
  .aq-case__stop { top: 6px; left: 0; transform: none; }
}
@container (max-width: 860px) { .aq-case__timeline li::before { transform: scaleY(var(--aq-run, 1)); transform-origin: top; } }

/* ---------- CertSeals: certification status as certificate tiles in a Swiss row (look "cert-seals"). Square tiles,
   no gaps but a hairline: the first navy (on-navy text), the rest limestone in two shades (on-limestone text). Each
   tile: a seal (ring of ticks, icon at its centre, flow on navy lightened), the tag large and light, title, status. ---------- */
.aq-cert-seals-sec { position: relative; }
.aq-cert-seals { position: relative; }
.aq-cert-seals__list {
  list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(var(--n, 4), minmax(0, 1fr)); gap: 1px;
  background: color-mix(in srgb, var(--on-limestone) 18%, transparent); border: 1px solid color-mix(in srgb, var(--on-limestone) 18%, transparent);
}
.aq-cert-seals__item { display: flex; }
.aq-cert-seals__tile {
  position: relative; flex: 1 1 auto; display: flex; flex-direction: column; gap: var(--space-3); min-height: calc(var(--space-32) * 3);
  padding: var(--space-8) var(--space-6) var(--space-8); background: var(--limestone); color: var(--on-limestone); text-decoration: none;
  transition: background 240ms cubic-bezier(0.2, 0, 0, 1);
}
.aq-cert-seals__item:nth-child(odd) .aq-cert-seals__tile { background: color-mix(in srgb, var(--limestone) 88%, var(--on-limestone)); }
.aq-cert-seals__item:first-child .aq-cert-seals__tile { background: var(--navy); color: var(--on-navy); }
a.aq-cert-seals__tile:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; z-index: 1; }

/* the seal */
.aq-cert-seals__seal { position: relative; display: block; width: var(--space-24); height: var(--space-24); margin-bottom: var(--space-8); color: var(--on-limestone); }
.aq-cert-seals__item:first-child .aq-cert-seals__seal { color: var(--on-navy); }
.aq-cert-seals__seal svg { display: block; width: 100%; height: 100%; overflow: visible; }
.aq-cert-seals__ticks { fill: none; stroke: currentColor; stroke-width: 1; opacity: 0.7; vector-effect: non-scaling-stroke; }
.aq-cert-seals__ring { fill: none; stroke: currentColor; stroke-width: 1.5; vector-effect: non-scaling-stroke; }
.aq-cert-seals__icon { position: absolute; left: 50%; top: 50%; width: var(--space-8); height: var(--space-8); transform: translate(-50%, -50%); background-color: currentColor; }

/* the words */
.aq-cert-seals__tag { margin: 0; font: 300 48px/52px var(--font-sans); letter-spacing: -0.03em; overflow-wrap: anywhere; }
.aq-cert-seals__tag.is-long { font-size: 20px; line-height: 28px; letter-spacing: -0.01em; }
.aq-cert-seals__t { margin: auto 0 0; padding-top: var(--space-4); border-top: 1px solid color-mix(in srgb, currentColor 30%, transparent); font: 500 17px/24px var(--font-sans); }
.aq-cert-seals__d { margin: 0; font: 400 15px/22px var(--font-sans); color: var(--on-limestone-muted); }
.aq-cert-seals__item:first-child .aq-cert-seals__d { color: var(--on-navy-muted); }
.aq-cert-seals__go { position: absolute; right: var(--space-6); top: var(--space-8); width: var(--space-4); height: var(--space-4); border-top: 1.5px solid currentColor; border-right: 1.5px solid currentColor; transform: rotate(45deg); transition: transform 240ms cubic-bezier(0.2, 0, 0, 1); }
a.aq-cert-seals__tile:hover .aq-cert-seals__go { transform: translateX(var(--space-1)) rotate(45deg); }
a.aq-cert-seals__tile:hover .aq-cert-seals__t { text-decoration: underline; text-underline-offset: 4px; }
a.aq-cert-seals__tile:hover .aq-cert-seals__seal svg { transform: rotate(10deg); transition: transform 400ms cubic-bezier(0.2, 0, 0, 1); }

@media (prefers-reduced-motion: reduce) { .aq-cert-seals__tile, .aq-cert-seals__go, a.aq-cert-seals__tile:hover .aq-cert-seals__seal svg { transition: none; } }

@container (max-width: 1100px) {
  .aq-cert-seals__list { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .aq-cert-seals__tile { min-height: calc(var(--space-32) * 2.5); }
}
@container (max-width: 560px) {
  .aq-cert-seals__list { grid-template-columns: minmax(0, 1fr); }
  .aq-cert-seals__tile { min-height: 0; padding: var(--space-6) var(--space-4); display: grid; grid-template-columns: var(--space-16) minmax(0, 1fr); column-gap: var(--space-4); row-gap: var(--space-2); }
  .aq-cert-seals__seal { grid-row: 1 / span 3; width: var(--space-16); height: var(--space-16); margin: 0; }
  .aq-cert-seals__icon { width: var(--space-6); height: var(--space-6); }
  .aq-cert-seals__tag { font-size: 32px; line-height: 36px; }
  .aq-cert-seals__tag.is-long { font-size: 18px; line-height: 25px; }
  .aq-cert-seals__t { margin: 0; padding-top: var(--space-2); }
  .aq-cert-seals__go { top: var(--space-6); right: var(--space-4); }
}

/* Engraving (pass 9b): FxGuilloche's rosette on the navy tile, centred low and right so it sits behind the tag and
   lines as a certificate's security print; on-navy at a ninth, so the white type keeps its contrast. */
.aq-cert-seals__tile > .aq-fx-shader { --fx-amt: 0.11; --fx-x: 0.72; --fx-y: 0.42; --fx-size: 1.5; }

/* ---------- CheckLedger: checks as a two-sided ledger, what each lets you see | the route on the seam | what it does not prove ---------- */
.aq-check-ledger-sec { }
.aq-check-ledger { --cl-cols: minmax(0, 5fr) minmax(0, 3fr) minmax(0, 4fr); margin-top: var(--space-4); }
.aq-check-ledger__head { display: grid; grid-template-columns: var(--cl-cols, minmax(0, 5fr) minmax(0, 3fr) minmax(0, 4fr)); column-gap: var(--space-6); padding-bottom: var(--space-4);
  border-bottom: 1px solid color-mix(in srgb, var(--on-navy) 30%, transparent); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-check-ledger__hl, .aq-check-ledger__hr { display: flex; align-items: center; gap: var(--space-2); }
.aq-check-ledger__hl { padding-left: var(--space-16); }
.aq-check-ledger__hm { text-align: center; }
.aq-check-ledger__sq { flex: none; display: inline-block; width: var(--space-3); height: var(--space-3); border: 1px solid var(--on-navy-muted); }
.aq-check-ledger__sq.is-fill { background: var(--limestone); border-color: var(--limestone); }

.aq-check-ledger__rows { list-style: none; margin: 0; padding: 0; }
.aq-check-ledger__row { display: grid; grid-template-columns: var(--cl-cols, minmax(0, 5fr) minmax(0, 3fr) minmax(0, 4fr)); column-gap: var(--space-6); align-items: start;
  border-bottom: 1px solid color-mix(in srgb, var(--on-navy) 16%, transparent); transition: background-color 300ms; }
.aq-check-ledger__row:hover { background: color-mix(in srgb, var(--on-navy) 4%, transparent); }
.aq-check-ledger__l { display: grid; grid-template-columns: var(--space-12) minmax(0, 1fr); column-gap: var(--space-4); padding: var(--space-8) 0; }
.aq-check-ledger__n { font: 300 40px/36px var(--font-sans); letter-spacing: -0.03em; color: transparent; -webkit-text-stroke: 1px var(--on-navy-muted); font-variant-numeric: tabular-nums; }
.aq-check-ledger__t { margin: 0; font: 300 26px/34px var(--font-sans); letter-spacing: -0.015em; color: var(--on-navy); text-wrap: balance; }
.aq-check-ledger .aq-ph { background: color-mix(in srgb, var(--limestone) 22%, transparent); color: var(--on-navy); }

/* the seam: a hairline pipe down the middle column, a node per row, the route button sitting on it */
.aq-check-ledger__m { position: relative; align-self: stretch; display: flex; flex-direction: column; align-items: center; gap: var(--space-3); padding: var(--space-8) 0; text-align: center; }
.aq-check-ledger__pipe { position: absolute; left: 50%; top: 0; bottom: 0; width: 1px; background: color-mix(in srgb, var(--on-navy) 30%, transparent); }
.aq-check-ledger__flow { position: absolute; inset: 0; background: var(--on-navy); transform-origin: 50% 0; transform: scaleY(0); }
.aq-check-ledger__node { position: relative; width: var(--space-3); height: var(--space-3); background: var(--navy); border: 1px solid var(--on-navy); transition: background-color 250ms; }
.aq-check-ledger__node.is-wet, .aq-check-ledger__row:hover .aq-check-ledger__node, .aq-check-ledger__row:focus-within .aq-check-ledger__node { background: var(--limestone); }
.aq-check-ledger__go { position: relative; display: inline-flex; align-items: center; justify-content: center; gap: var(--space-2); min-height: var(--space-12); max-width: 100%;
  padding: var(--space-2) var(--space-4); background: var(--limestone); color: var(--on-limestone); border-radius: var(--radius-sm); text-decoration: none; font: 500 14px/20px var(--font-sans);
  transition: background-color 200ms; }
.aq-check-ledger__go::after { content: "→"; transition: transform 200ms; }
.aq-check-ledger__go:hover { background: var(--on-navy); }
.aq-check-ledger__go:hover::after { transform: translateX(var(--space-1)); }
.aq-check-ledger__go:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }
.aq-check-ledger__go.is-plain { background: none; color: var(--on-navy); }
.aq-check-ledger__go.is-plain::after { content: none; }
.aq-check-ledger__time { position: relative; margin: 0; padding: var(--space-1) var(--space-2); background: var(--navy); font: 400 12px/18px var(--font-mono); color: var(--on-navy-muted); max-width: 100%; overflow-wrap: anywhere; }

.aq-check-ledger__r { padding: var(--space-8) 0; }
.aq-check-ledger__no { margin: 0; display: grid; grid-template-columns: var(--space-3) minmax(0, 1fr); gap: var(--space-3); font: 400 17px/27px var(--font-sans); color: var(--on-navy-muted); }
.aq-check-ledger__no .aq-check-ledger__sq { margin-top: var(--space-2); }
/* column names per cell: for screen readers on wide screens (the head row is aria-hidden), shown on phones */
.aq-check-ledger__k { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@container (max-width: 1100px) {
  .aq-check-ledger { --cl-cols: minmax(0, 4fr) minmax(0, 3fr) minmax(0, 3fr); }
  .aq-check-ledger__t { font-size: 22px; line-height: 30px; }
  .aq-check-ledger__hl { padding-left: var(--space-12); }
  .aq-check-ledger__l { grid-template-columns: var(--space-8) minmax(0, 1fr); }
  .aq-check-ledger__n { font-size: 28px; line-height: 30px; }
}
/* Phones: a card per check, the seam a rule down the left edge carrying the node */
@container (max-width: 860px) {
  .aq-check-ledger__head { display: none; }
  .aq-check-ledger__row { grid-template-columns: minmax(0, 1fr); position: relative; padding: var(--space-6) 0 var(--space-6) var(--space-6); }
  .aq-check-ledger__l { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-2); padding: 0; }
  .aq-check-ledger__n { font-size: 28px; line-height: 30px; }
  .aq-check-ledger__t { font-size: 22px; line-height: 30px; }
  .aq-check-ledger__m { position: static; align-items: flex-start; text-align: left; padding: var(--space-4) 0 0; gap: var(--space-2); }
  .aq-check-ledger__pipe { left: 0; }
  .aq-check-ledger__node { position: absolute; left: calc(var(--space-3) / -2 + 0.5px); top: var(--space-8); }
  .aq-check-ledger__time { padding: 0; }
  .aq-check-ledger__time > .aq-check-ledger__k { position: static; width: auto; height: auto; clip-path: none; margin-right: var(--space-1); }
  .aq-check-ledger__time > .aq-check-ledger__k::after { content: ":"; }
  .aq-check-ledger__r { padding: var(--space-4) 0 0; }
  .aq-check-ledger__r > .aq-check-ledger__k { position: static; width: auto; height: auto; clip-path: none; display: block; margin-bottom: var(--space-1);
    font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
  .aq-check-ledger__no { font-size: 16px; line-height: 25px; }
}

/* ---------- ClauseCrosswalk: requirements wired to two regulations' clauses (look "clause-crosswalk") ---------- */
/* Editorial: requirement names large and light down the middle, each regulation a spine at the outer edge with its
   name set big and vertical and its clauses as mono chips. Five tracks: spine | wires | rows | wires | spine. The rows
   share equal heights (grid-auto-rows 1fr) and the chips spread with space-around, so row i sits at (i + 0.5) / N and
   chip j at (j + 0.5) / M of the same height: the wires (a stretched svg, non-scaling strokes) need no measuring.
   Phones: spines and wires go; each row shows its clause chips under how. */
.aq-clause-crosswalk { display: grid; grid-template-columns: auto minmax(var(--space-12), 1fr) minmax(0, 7fr) minmax(var(--space-12), 1fr) auto; grid-template-rows: auto 1fr; column-gap: 0; }
.aq-clause-crosswalk__heads { grid-row: 1; grid-column: 3; display: grid; grid-template-columns: var(--space-12) minmax(0, 0.9fr) minmax(0, 1.1fr); column-gap: var(--space-6); padding: 0 var(--space-4) var(--space-3); border-bottom: 1px solid var(--line-strong); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-clause-crosswalk__heads span:first-child { grid-column: 2; }
.aq-clause-crosswalk__spine, .aq-clause-crosswalk__wires, .aq-clause-crosswalk__mid { grid-row: 2; }
.aq-clause-crosswalk__spine { display: flex; align-items: stretch; gap: var(--space-3); }
.aq-clause-crosswalk__spine--a { grid-column: 1; }
.aq-clause-crosswalk__spine--b { grid-column: 5; flex-direction: row-reverse; }
.aq-clause-crosswalk__reg { margin: 0; writing-mode: vertical-rl; transform: rotate(180deg); font: 300 40px/44px var(--font-sans); letter-spacing: -0.02em; color: var(--ink); white-space: nowrap; text-align: end; }
.aq-clause-crosswalk__spine--b .aq-clause-crosswalk__reg { transform: none; text-align: start; }
.aq-clause-crosswalk__nodes { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; justify-content: space-around; }
.aq-clause-crosswalk__node {
  height: var(--space-6); display: flex; align-items: center; padding: 0 var(--space-2); border: 1px solid var(--line-strong); background: var(--surface-raised);
  font: 400 12px/16px var(--font-mono); color: var(--ink); white-space: nowrap; cursor: default; transition: background-color 200ms ease, border-color 200ms ease, color 200ms ease;
}
.aq-clause-crosswalk__spine--a .aq-clause-crosswalk__node { justify-content: flex-end; }
.aq-clause-crosswalk__wires { grid-column: 2; display: block; width: 100%; height: 100%; overflow: visible; }
.aq-clause-crosswalk__wires--b { grid-column: 4; }
.aq-clause-crosswalk__wire { fill: none; stroke: var(--line-strong); stroke-width: 1; vector-effect: non-scaling-stroke; transition: stroke 200ms ease, opacity 200ms ease; }
.aq-clause-crosswalk__mid { grid-column: 3; min-width: 0; }
.aq-clause-crosswalk__rows { list-style: none; margin: 0; padding: 0; display: grid; grid-auto-rows: 1fr; height: 100%; }
.aq-clause-crosswalk__row {
  display: grid; grid-template-columns: var(--space-12) minmax(0, 0.9fr) minmax(0, 1.1fr); column-gap: var(--space-6); align-items: center;
  padding: var(--space-4); border-bottom: 1px solid var(--line); position: relative; transition: background-color 200ms ease;
}
.aq-clause-crosswalk__row .aq-index { font: 400 12px/16px var(--font-mono); color: var(--ink-subtle); }
.aq-clause-crosswalk__t { margin: 0; font: 300 28px/32px var(--font-sans); letter-spacing: -0.02em; color: var(--ink); text-wrap: balance; }
.aq-clause-crosswalk__how { margin: 0; font: 400 15px/22px var(--font-sans); color: var(--ink-muted); text-wrap: pretty; }
.aq-clause-crosswalk__refs { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.aq-clause-crosswalk__ref { display: block; }
.aq-clause-crosswalk__rk { font: 500 12px/16px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-clause-crosswalk__chip { display: inline-block; padding: 0 var(--space-2); border: 1px solid var(--line-strong); font: 400 12px/20px var(--font-mono); color: var(--ink); }
/* the fold: desktop shows every requirement (the wires need all rows); phones fold */
.aq-fold:not(.is-open) .aq-clause-crosswalk__row.aq-fold-x { display: grid; }
.aq-fold:has(> .aq-clause-crosswalk) > .aq-fold__btn { display: none; }
/* hover */
.aq-clause-crosswalk.has-hot .aq-clause-crosswalk__wire { opacity: 0.25; }
.aq-clause-crosswalk.has-hot .aq-clause-crosswalk__wire.is-hot { opacity: 1; stroke: var(--flow); stroke-width: 1.5; }
.aq-clause-crosswalk__row.is-hot { background: var(--flow-tint); }
.aq-clause-crosswalk__node.is-hot { border-color: var(--flow); background: var(--flow); color: var(--surface); }

@container (max-width: 860px) {
  .aq-clause-crosswalk { display: block; }
  .aq-clause-crosswalk__spine, .aq-clause-crosswalk__wires, .aq-clause-crosswalk__heads { display: none; }
  .aq-clause-crosswalk__rows { display: block; }
  .aq-clause-crosswalk__row, .aq-fold:not(.is-open) .aq-clause-crosswalk__row.aq-fold-x { display: grid; grid-template-columns: var(--space-8) minmax(0, 1fr); row-gap: var(--space-2); padding: var(--space-4) 0; }
  .aq-fold:not(.is-open) .aq-clause-crosswalk__row.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-clause-crosswalk) > .aq-fold__btn { display: flex; }
  .aq-clause-crosswalk__t { font-size: 24px; line-height: 28px; }
  .aq-clause-crosswalk__how, .aq-clause-crosswalk__refs { grid-column: 2; }
  .aq-clause-crosswalk__refs { position: static; width: auto; height: auto; clip-path: none; white-space: normal; display: flex; flex-direction: column; gap: var(--space-2); }
  .aq-clause-crosswalk__ref { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-1) var(--space-2); }
  .aq-clause-crosswalk__rk { flex-basis: 100%; }
}
@container (max-width: 860px) {
  .aq-clause-crosswalk__refs { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); column-gap: var(--space-4); }
}
.aq-clause-crosswalk-sec { position: relative; }

/* ---------- Closing: the call to action at the end of every page, on the navy band ---------- */
/* The brand's closing band: one centred headline at display size, a lead sentence and a large Limestone primary
   button, with the brand mark large and faint (Limestone at 6 %), cut by the top-left corner, fading into the navy.
   The only centred text on the site. Below the button, the exchange is drawn as a small process on the navy: what you
   send feeds a manifold, one pipe carries it across with the turnaround as its label, and what comes back leaves as
   drawn sheets. Hairlines on navy are on-navy-muted at 30 % strength; drawing lines at 55 %; water in flow lifted
   towards on-navy (--aq-c-water), so it reads on the dark ground in both themes. */
.aq-closing {
  --aq-c-hair: color-mix(in srgb, var(--on-navy-muted) 30%, transparent);
  --aq-c-line: color-mix(in srgb, var(--on-navy-muted) 55%, transparent);
  --aq-c-water: color-mix(in srgb, var(--flow) 55%, var(--on-navy));
  position: relative; overflow: hidden; text-align: center;
}
/* A little more room above the headline, clear of the mark in the corner */
.aq-closing.aq-section { padding-top: calc(var(--space-24) + var(--space-8)); padding-bottom: var(--space-24); }
/* Navy depth (brand book, Gradient grounds): navy lifting slightly at the top left and deepening to the bottom right */
.aq-closing.aq-band--navy { background: linear-gradient(160deg, color-mix(in srgb, var(--navy) 88%, var(--on-navy)) 0%, var(--navy) 45%, color-mix(in srgb, var(--navy) 70%, var(--on-limestone)) 100%); }
/* The mark: the supplied brand mark at min(44%, 640px), its centre 15 % of its width inside the band's top-left
   corner, so the corner cuts the three outer dots about in half and the wave and lower-right dot show whole. Limestone
   at 6 %, with a radial mask that fades it away from the corner; it ends before the headline. */
.aq-closing__mark {
  position: absolute; left: 0; top: 0; width: min(44%, 640px); height: auto; transform: translate(-35%, -35%);
  fill: var(--limestone); opacity: 0.06; pointer-events: none;
  -webkit-mask-image: radial-gradient(circle at 35% 35%, var(--navy) 0%, var(--navy) 30%, transparent 75%);
  mask-image: radial-gradient(circle at 35% 35%, var(--navy) 0%, var(--navy) 30%, transparent 75%);
}
/* The water line: one flow hairline along the band's top edge (Closing/motion.js runs it in from the left) */
.aq-closing::before {
  content: ""; position: absolute; left: 0; right: 0; top: 0; height: 1.5px; background: var(--aq-c-water, var(--flow));
  transform-origin: 0 50%; transform: scaleX(var(--aq-c-run, 1)); pointer-events: none;
}
.aq-closing__frame { position: relative; display: flex; flex-direction: column; align-items: center; gap: var(--space-6); }

/* Headline: display size, light and tracked tight, in on-navy (stays light on navy in both themes) */
.aq-closing__h {
  max-width: 20ch; margin: 0; font: 300 clamp(40px, 4.8cqi, 68px)/1.04 var(--font-sans); letter-spacing: -0.035em;
  color: var(--on-navy); overflow-wrap: break-word; text-wrap: balance;
}
.aq-closing .aq-closing__lead { max-width: 52ch; margin: 0 auto; color: var(--on-navy-muted); }
.aq-closing__action { display: flex; justify-content: center; min-width: 0; max-width: 100%; margin-top: var(--space-2); }
/* The one large button on the site: taller and wider than a section's, the Limestone primary of aq-band--navy */
.aq-closing__action .aq-btn--primary { min-height: var(--space-16); padding-inline: var(--space-8); font-size: 16px; gap: var(--space-3); }
.aq-closing__action .aq-btn__arrow { transition: transform 240ms cubic-bezier(0.2, 0, 0, 1); }
.aq-closing__action .aq-btn--primary:hover .aq-btn__arrow, .aq-closing__action .aq-btn--primary:focus-visible .aq-btn__arrow { transform: translateX(var(--space-1)); }

/* Below the button: the checklist or exchange, then the proof, left-aligned in a centred column */
.aq-closing__more {
  display: flex; flex-direction: column; gap: var(--space-8); width: 100%; max-width: 1040px; margin-top: var(--space-12);
  text-align: start;
}

/* Proof: one confirmed figure from the page, in mono, under a hairline */
.aq-closing__proof {
  display: flex; flex-direction: column; gap: var(--space-1); min-width: 0; max-width: 100%;
  padding-top: var(--space-3); border-top: 1px solid var(--aq-c-hair, var(--line));
}
.aq-closing__tag { margin: 0; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-closing__value {
  font: 300 40px/44px var(--font-mono); letter-spacing: -0.02em; font-variant-numeric: tabular-nums;
  color: var(--on-navy); overflow-wrap: break-word;
}
.aq-closing__label { font: 400 14px/22px var(--font-sans); color: var(--on-navy-muted); }

/* Checklist (cta.include): what to send us, as numbered rows on faint hairlines */
.aq-closing__include { display: flex; flex-direction: column; gap: var(--space-3); width: 100%; max-width: var(--text-max); min-width: 0; margin-inline: auto; }
.aq-closing__include ol {
  list-style: none; margin: 0; padding: 0; columns: 2; column-gap: var(--space-8);
  border-bottom: 1px solid var(--aq-c-hair, var(--line));
}
.aq-closing__include li {
  position: relative; break-inside: avoid; display: grid; grid-template-columns: var(--space-8) minmax(0, 1fr); align-items: baseline;
  padding-block: var(--space-3); border-top: 1px solid var(--aq-c-hair, var(--line));
  font: 400 16px/24px var(--font-sans); color: var(--on-navy);
}
.aq-closing__include .aq-index { color: var(--on-navy-muted); line-height: 24px; }
.aq-closing__t { min-width: 0; overflow-wrap: break-word; }

/* Exchange (cta.include + cta.returns): send rows → manifold → pipe with the turnaround → manifold → returned sheets */
.aq-closing__plate { width: 100%; min-width: 0; }
.aq-closing__swap { display: grid; grid-template-columns: minmax(0, 1fr) minmax(var(--space-32), 200px) minmax(0, 1fr); column-gap: 0; align-items: center; }
.aq-closing__swap .aq-closing__include { max-width: none; margin: 0; }
.aq-closing__swap .aq-closing__include ol { columns: 1; border: 0; }
.aq-closing__swap .aq-closing__include li {
  min-height: var(--space-12); box-sizing: border-box; align-items: center; padding: var(--space-2) var(--space-6) var(--space-2) 0;
  border-top: 0; font-size: 15px; line-height: 22px;
}
.aq-closing__swap .aq-closing__include li + li { border-top: 1px solid var(--aq-c-hair, var(--line)); }
.aq-closing__swap .aq-index { line-height: 22px; }
/* Manifolds: a stub from each row to a bus down the list's inner edge (send: right; returns: left) */
.aq-closing__swap .aq-closing__include li::before, .aq-closing__swap .aq-closing__include li::after { content: ""; position: absolute; pointer-events: none; }
.aq-closing__swap .aq-closing__include li::after { top: 50%; height: 1px; width: var(--space-4); background: var(--aq-c-line, var(--line-strong)); transform: scaleX(var(--aq-stub, 1)); }
.aq-closing__swap .aq-closing__include li::before { top: 0; bottom: 0; width: 1px; background: var(--aq-c-line, var(--line-strong)); transform-origin: 50% 0; transform: scaleY(var(--aq-bus, 1)); }
.aq-closing__swap .aq-closing__include li:first-child::before { top: 50%; }
.aq-closing__swap .aq-closing__include li:last-child::before { bottom: 50%; }
.aq-closing__swap .aq-closing__include li:only-child::before { display: none; }
.aq-closing__swap .aq-closing__include:not(.aq-closing__returns) li::after { right: 0; transform-origin: 0 50%; }
.aq-closing__swap .aq-closing__include:not(.aq-closing__returns) li::before { right: 0; }
.aq-closing__swap .aq-closing__returns li { padding: var(--space-2) 0 var(--space-2) var(--space-6); grid-template-columns: var(--space-8) var(--space-8) minmax(0, 1fr); column-gap: 0; }
.aq-closing__swap .aq-closing__returns li::after { left: 0; transform-origin: 0 50%; }
.aq-closing__swap .aq-closing__returns li::before { left: 0; }
/* The tags hang above the rows, out of the flow, so the two lists and the pipe centre on one line */
.aq-closing__swap { padding-top: var(--space-8); }
.aq-closing__swap .aq-closing__include { position: relative; }
.aq-closing__swap .aq-closing__include > .aq-closing__tag { position: absolute; bottom: 100%; left: 0; right: 0; padding-bottom: var(--space-2); border-bottom: 1px solid var(--aq-c-hair, var(--line)); }
.aq-closing__swap .aq-closing__include:not(.aq-closing__returns) > .aq-closing__tag { margin-right: var(--space-6); }
.aq-closing__swap .aq-closing__returns > .aq-closing__tag { margin-left: var(--space-6); }

/* A returned document: a small drawn sheet with a folded corner and three text lines (decoration) */
.aq-closing__doc {
  position: relative; width: var(--space-6); height: var(--space-8); box-sizing: border-box; align-self: center;
  border: 1px solid var(--aq-c-line, var(--line-strong)); border-top-right-radius: 0;
  clip-path: polygon(0 0, 66% 0, 100% 25%, 100% 100%, 0 100%);
}
.aq-closing__doc::before { content: ""; position: absolute; right: -1px; top: -1px; width: 34%; height: 25%; box-sizing: border-box; border-left: 1px solid var(--aq-c-line, var(--line-strong)); border-bottom: 1px solid var(--aq-c-line, var(--line-strong)); }
.aq-closing__doc::after { content: ""; position: absolute; left: 20%; right: 20%; top: 42%; height: 30%; border-top: 1px solid var(--aq-c-line, var(--line-strong)); border-bottom: 1px solid var(--aq-c-line, var(--line-strong)); }
.aq-closing__returns li:hover .aq-closing__doc, .aq-closing__returns li:hover .aq-closing__doc::before, .aq-closing__returns li:hover .aq-closing__doc::after { border-color: var(--aq-c-water, var(--flow)); }

/* The pipe between the manifolds: twin walls, the water line in its bore and a chevron at its outlet; the turnaround
   rides above it as the pipe's label (real text) */
.aq-closing__turn {
