  .aq-closing__swap .aq-closing__returns > .aq-closing__tag { margin: 0; padding: var(--space-2) 0 var(--space-2) var(--space-6); border-left: 1px solid var(--aq-c-line, var(--line-strong)); }
  .aq-closing__pipe { flex: none; width: var(--space-2); height: auto; align-self: stretch; margin-left: calc(-0.5 * var(--space-2) + 0.5px); border: 0; border-left: 1px solid var(--aq-c-line, var(--line-strong)); border-right: 1px solid var(--aq-c-line, var(--line-strong)); transform-origin: 50% 0; transform: scaleY(var(--aq-pipe, 1)); }
  .aq-closing__pipe::before { left: calc(50% - 0.75px); right: auto; top: 0; bottom: 0; width: 1.5px; height: auto; transform-origin: 50% 0; transform: scaleY(var(--aq-water, 1)); }
  .aq-closing__pipe::after { right: auto; left: 50%; top: auto; bottom: calc(-1 * var(--space-1)); transform: translate(-50%, -50%) rotate(135deg); }
  .aq-closing__pipe > i { left: 50%; top: 0; }
