/* Captions on the limestone below, one column each; the leader lands on each column's top-left */
.aq-loop-dock__cards { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(var(--n, 3), minmax(0, 1fr)); gap: 0; }
.aq-loop-dock__card { display: flex; }
.aq-loop-dock__body { flex: 1; display: flex; flex-direction: column; gap: var(--space-2); padding: var(--space-6) var(--space-8) 0 var(--space-6); color: var(--on-limestone); text-decoration: none;
  border-left: 1px solid var(--on-limestone-muted); transition: border-color 200ms cubic-bezier(0.2, 0, 0, 1); }
