.aq-loop-dock__t { margin: var(--space-2) 0 0; font: 400 24px/30px var(--font-sans); letter-spacing: -0.01em; }
.aq-loop-dock__d { margin: 0; font: 400 15px/23px var(--font-sans); color: var(--on-limestone-muted); max-width: 36ch; }
