  .aq-loop-dock__base { position: static; translate: none; white-space: normal; margin: var(--space-2) var(--space-4) 0; flex-direction: row; align-items: center; width: auto; max-width: none; text-align: left; }
  .aq-loop-dock__cards { grid-template-columns: minmax(0, 1fr); }
