.aq-macro-leaders__svg { position: absolute; top: calc(-1 * var(--space-8)); bottom: calc(-1 * var(--space-8)); left: calc(50% - 50vw); width: calc(50vw - 50% + (100% - var(--space-8)) / 3); height: calc(100% + 2 * var(--space-8)); }
