/* Table */
.aq-macro-leaders__table { position: relative; z-index: 1; width: 100%; border-collapse: collapse; table-layout: fixed; }
.aq-macro-leaders__table thead th { padding: 0 var(--space-3) var(--space-3) 0; text-align: left; vertical-align: bottom; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); border-bottom: 1px solid var(--line-strong); }
.aq-macro-leaders__table thead th:first-child { width: 29%; }
.aq-macro-leaders__table thead th:nth-child(2) { width: 25%; }
.aq-macro-leaders__table thead th:nth-child(3) { width: 22%; }
.aq-macro-leaders__table tbody tr { border-bottom: 1px solid var(--line); transition: background-color 200ms cubic-bezier(0.2, 0, 0, 1); }
.aq-macro-leaders__table tbody th, .aq-macro-leaders__table td { padding: var(--space-4) var(--space-3) var(--space-4) 0; text-align: left; vertical-align: top; }
.aq-macro-leaders__table td { font: 400 14px/22px var(--font-sans); color: var(--ink-muted); overflow-wrap: break-word; }
.aq-macro-leaders__table td:nth-child(2) { color: var(--ink); }
.aq-macro-leaders__ind { position: relative; padding-left: var(--space-3) !important; }
.aq-macro-leaders__name { display: block; font: 300 24px/30px var(--font-sans); letter-spacing: -0.015em; color: var(--ink); text-wrap: balance; }
.aq-macro-leaders__name a { color: var(--ink); text-decoration: none; }
.aq-macro-leaders__name a::after { content: "\a0\2192"; font-size: 0.7em; color: var(--flow); }
.aq-macro-leaders__name a:hover { color: var(--flow); }
