@container (max-width: 1180px) {
  .aq-macro-leaders { grid-template-columns: minmax(0, 3fr) minmax(0, 9fr); column-gap: var(--space-6); }
  .aq-macro-leaders__svg { width: calc(50vw - 50% + (100% - var(--space-6)) / 4); }
