@container (max-width: 860px) {
  .aq-macro-leaders { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-6); }
  .aq-macro-leaders__fig { position: relative; height: calc(var(--space-32) + var(--space-16)); margin-inline: calc(-1 * var(--space-4)); overflow: hidden; }
  .aq-macro-leaders__svg { inset: 0; width: 100%; height: 100%; }
  .aq-macro-leaders__table, .aq-macro-leaders__table tbody, .aq-macro-leaders__table tr, .aq-macro-leaders__table th, .aq-macro-leaders__table td { display: block; width: auto !important; }
  .aq-macro-leaders__table thead { display: none; }
  .aq-macro-leaders__table tbody { position: relative; }
  .aq-macro-leaders__table tbody::before { content: ""; position: absolute; left: calc(var(--space-4) - 0.5px); top: var(--space-6); bottom: var(--space-6); width: 1px; background: var(--line-strong); }
  .aq-macro-leaders__table tbody tr { position: relative; padding: var(--space-4) 0 var(--space-4) var(--space-12); }
  .aq-macro-leaders__table tbody th, .aq-macro-leaders__table td { padding: 0; }
  .aq-macro-leaders__ind { position: static; padding-left: 0 !important; margin-bottom: var(--space-2); }
  .aq-macro-leaders__name { font-size: 22px; line-height: 28px; }
  .aq-macro-leaders__lead { right: auto; left: var(--space-4); top: calc(var(--space-4) + 14px); width: var(--space-6); }
  .aq-macro-leaders__lead::after { display: none; }
  .aq-macro-leaders__mk { left: 0; }
  .aq-macro-leaders__table td { display: grid; grid-template-columns: minmax(0, 7.5em) minmax(0, 1fr); column-gap: var(--space-3); padding-block: var(--space-1); font-size: 14px; line-height: 21px; }
  .aq-macro-leaders__k { display: block; font: 500 11px/21px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-muted); }
