/* ---------- ManifoldRouter: situations as branches off one manifold, large type on a limestone sheet ---------- */
/* Left: the manifold, a twin-wall pipe (on-limestone-muted hairlines over the limestone ground) with one branch per
   situation, the situation set large beside its branch. The water (flow) fills the manifold down to the open
   situation and along its branch. Right: the open route on a raised sheet, its left edge in flow where the branch
   meets it. Each option segment draws its own piece of the manifold, so rows of any height join up. */
.aq-manifold-router { --pipe: var(--space-4); --reach: var(--space-12); position: relative; display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
  align-items: start; padding-top: var(--space-8); }
.aq-manifold-router__opt { grid-column: 1; position: relative; display: flex; align-items: baseline; gap: var(--space-4); width: 100%; min-height: 44px; margin: 0;
  padding: var(--space-4) var(--space-8) var(--space-4) calc(var(--pipe, var(--space-4)) + var(--reach, var(--space-12)) + var(--space-4)); border: 0; background: none; text-align: left; cursor: pointer;
  font: inherit; color: var(--on-limestone-muted); transition: color 300ms; }
/* the pipe reads as a pipe, not a comb: its bore is a shade deeper than the sheet, and each branch ends in a flange */
.aq-manifold-router { --bore: color-mix(in srgb, var(--on-limestone) 8%, var(--limestone)); }
.aq-manifold-router__seg { position: absolute; left: 0; top: 0; bottom: 0; width: var(--pipe, var(--space-4)); box-sizing: border-box; border-inline: 1.5px solid var(--on-limestone-muted); background: var(--bore, var(--limestone)); }
.aq-manifold-router__opt.is-first .aq-manifold-router__seg { top: calc(-1 * var(--space-8)); }
.aq-manifold-router__opt.is-first .aq-manifold-router__seg::before { content: ""; position: absolute; left: 50%; top: 0; width: var(--space-2); height: var(--space-2); border-right: 2px solid var(--flow); border-bottom: 2px solid var(--flow); transform: translate(-50%, -60%) rotate(45deg); }
.aq-manifold-router__opt.is-last .aq-manifold-router__seg { bottom: calc(50% - var(--pipe, var(--space-4)) / 2); border-bottom: 1.5px solid var(--on-limestone-muted); }
.aq-manifold-router__branch { position: absolute; left: calc(var(--pipe, var(--space-4)) - 1px); top: calc(50% - var(--pipe, var(--space-4)) / 2); width: var(--reach, var(--space-12)); height: var(--pipe, var(--space-4)); box-sizing: border-box;
  border-block: 1.5px solid var(--on-limestone-muted); background: var(--bore, var(--limestone)); transition: border-color 300ms; }
.aq-manifold-router__branch::after { content: ""; position: absolute; right: 0; top: calc(-1 * var(--space-1) - 1.5px); bottom: calc(-1 * var(--space-1) - 1.5px); width: var(--space-1);
  box-sizing: border-box; border: 1.5px solid; border-color: inherit; background: var(--bore, var(--limestone)); }
.aq-manifold-router__water { position: absolute; background: var(--flow); transition: transform 450ms cubic-bezier(0.65, 0, 0.35, 1); }
.aq-manifold-router__seg .aq-manifold-router__water { left: 50%; width: 2px; margin-left: -1px; top: 0; bottom: 0; transform: scaleY(0); transform-origin: 50% 0; }
.aq-manifold-router__branch .aq-manifold-router__water { top: 50%; height: 2px; margin-top: -1px; left: 0; right: 0; transform: scaleX(0); transform-origin: 0 50%; transition-delay: 200ms; }
.aq-manifold-router__opt.is-wet .aq-manifold-router__seg .aq-manifold-router__water { transform: scaleY(1); }
.aq-manifold-router__opt[aria-expanded="true"] .aq-manifold-router__seg .aq-manifold-router__water { bottom: 50%; }
.aq-manifold-router__opt[aria-expanded="true"] .aq-manifold-router__branch .aq-manifold-router__water { transform: scaleX(1); }
.aq-manifold-router__n { flex: none; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; color: var(--on-limestone-muted); }
.aq-manifold-router__t { font: 300 30px/36px var(--font-sans); letter-spacing: -0.02em; text-wrap: balance; }
.aq-manifold-router__opt::after { content: ""; position: absolute; left: calc(var(--pipe, var(--space-4)) + var(--reach, var(--space-12))); right: 0; bottom: 0; height: 1px; background: color-mix(in srgb, var(--on-limestone-muted) 30%, transparent); }
.aq-manifold-router__opt[aria-expanded="true"] { color: var(--on-limestone); }
.aq-manifold-router__opt[aria-expanded="true"]::after { height: 2px; background: var(--flow); }
.aq-manifold-router__opt[aria-expanded="true"] .aq-manifold-router__branch { border-color: var(--on-limestone); }
.aq-manifold-router__opt:hover { color: var(--on-limestone); }
.aq-manifold-router__opt:hover .aq-manifold-router__branch { border-color: var(--on-limestone); }
.aq-manifold-router__opt:focus-visible { outline: 2px solid var(--focus); outline-offset: -2px; }

/* The open route: a raised sheet, flow on the edge the branch runs into */
.aq-manifold-router__route { grid-column: 2; align-self: stretch; position: relative; display: flex; flex-direction: column; gap: var(--space-6);
  padding: var(--space-8); background: var(--surface-raised); color: var(--ink); border-left: 2px solid var(--flow); }
.aq-manifold-router__route[hidden] { display: none; }
.aq-manifold-router__hit { position: absolute; inset: 0; z-index: 0; }
.aq-manifold-router__sit { margin: 0; font: 500 12px/18px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-manifold-router__stations { list-style: none; margin: 0; padding: 0; flex: 1; display: flex; flex-direction: column; }
.aq-manifold-router__st { position: relative; z-index: 1; display: flex; flex-direction: column; gap: var(--space-2); pointer-events: none; }
.aq-manifold-router__st a { pointer-events: auto; }
/* between stations the water runs down a line that takes the free height, an arrowhead into the next */
.aq-manifold-router__st:not(:last-child) { flex: 1; }
.aq-manifold-router__st:not(:last-child)::after { content: ""; flex: 1; min-height: var(--space-8); width: 1px; margin: var(--space-3) 0 var(--space-3) var(--space-2); background: var(--flow); transform-origin: 50% 0; }
.aq-manifold-router__st + .aq-manifold-router__st::before { content: ""; position: absolute; left: var(--space-2); top: calc(-1 * var(--space-3)); width: var(--space-2); height: var(--space-2); border-right: 1px solid var(--flow); border-bottom: 1px solid var(--flow); transform: translate(-50%, -50%) rotate(45deg); }
.aq-manifold-router__k { margin: 0; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-manifold-router__v { margin: 0; font: 400 20px/28px var(--font-sans); letter-spacing: -0.01em; color: var(--ink); }
.aq-manifold-router__st.is-go .aq-manifold-router__v { font: 300 32px/38px var(--font-sans); letter-spacing: -0.02em; }
.aq-manifold-router__st.is-go a { color: var(--ink); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 0.16em; text-decoration-color: var(--flow); }
.aq-manifold-router__st.is-go a::after { content: "\00a0\2192"; display: inline-block; color: var(--flow); transition: transform 200ms; }
.aq-manifold-router__route.is-link:hover .aq-manifold-router__st.is-go a::after { transform: translateX(var(--space-2)); }
.aq-manifold-router__st a:focus-visible { outline: 2px solid var(--focus); outline-offset: var(--space-1); }
.aq-manifold-router__st.is-pending .aq-manifold-router__v { padding-top: var(--space-2); border-top: 1px dashed var(--line-strong); }
.aq-manifold-router__tbc { display: inline-block; font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }

@container (max-width: 1100px) {
  .aq-manifold-router__t { font-size: 24px; line-height: 30px; }
  .aq-manifold-router__st.is-go .aq-manifold-router__v { font-size: 26px; line-height: 32px; }
}

/* Phones: the route opens under its situation; the manifold runs on past it */
@container (max-width: 860px) {
  .aq-manifold-router { --reach: var(--space-6); grid-template-columns: minmax(0, 1fr); padding-top: var(--space-6); }
  .aq-manifold-router__opt { padding: var(--space-4) 0 var(--space-4) calc(var(--pipe, var(--space-4)) + var(--reach, var(--space-12)) + var(--space-3)); gap: var(--space-3); }
  .aq-manifold-router__opt.is-first .aq-manifold-router__seg { top: calc(-1 * var(--space-6)); }
  .aq-manifold-router__t { font-size: 20px; line-height: 26px; }
  .aq-manifold-router__route { grid-column: 1; grid-row: auto !important; margin-left: calc(var(--pipe, var(--space-4)) + var(--reach, var(--space-12)) + var(--space-3)); padding: var(--space-6) var(--space-4); }
  .aq-manifold-router__route::before { content: ""; position: absolute; top: 0; bottom: 0; left: calc(-1 * (var(--pipe, var(--space-4)) + var(--reach, var(--space-12)) + var(--space-3)) - 2px); width: var(--pipe, var(--space-4)); box-sizing: border-box; border-inline: 1.5px solid var(--on-limestone-muted); background: var(--bore, var(--limestone)); }
  .aq-manifold-router__opt.is-last + .aq-manifold-router__route::before { display: none; }
  .aq-manifold-router__sit { display: none; }
  .aq-manifold-router__st:not(:last-child)::after { min-height: var(--space-6); }
  .aq-manifold-router__v { font-size: 18px; line-height: 26px; }
  .aq-manifold-router__st.is-go .aq-manifold-router__v { font-size: 24px; line-height: 30px; }
}

/* the heading on the limestone sheet takes the on-limestone ink */
.aq-manifold-router-sec .aq-sec-head .aq-h1 { color: var(--on-limestone); }

/* Pipework ground (pass 9b): FxTruchet's twin-wall pipe tiles in on-limestone-muted, faint, masked so they run behind
   the route sheet and the band's right side and are gone before the manifold and the situations (one pipe reads as
   the pipe). */
.aq-manifold-router-sec > .aq-fx-shader { --fx-amt: 0.16;
  -webkit-mask-image: linear-gradient(to right, transparent 38%, var(--ink) 62%); mask-image: linear-gradient(to right, transparent 38%, var(--ink) 62%); }
@container (max-width: 860px) {
  .aq-manifold-router-sec > .aq-fx-shader { -webkit-mask-image: radial-gradient(circle at 100% 0, var(--ink), transparent 32%); mask-image: radial-gradient(circle at 100% 0, var(--ink), transparent 32%); }
}

/* ---------- MarketCallouts: one machine, several markets (look "market-callouts") ----------
   A navy band. The stage is one plane with the viewBox's aspect (1200 x 660): the IsoKit drawing (limestone solids,
   so it reads as a white object on navy), its leaders and numbered markers share it, and the callouts are placed on
   it by --x / --y percentages. Phones: the plane is cropped to the
   machine (twice as wide, centred, clipped) and the callouts stack under it. */
.aq-market-callouts-band .aq-sec-head .aq-h1 { color: var(--on-navy); }
.aq-market-callouts { color: var(--on-navy); }
.aq-market-callouts__stage { position: relative; }
.aq-market-callouts__plane { position: relative; aspect-ratio: 1200 / 660; }
.aq-market-callouts__svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.aq-market-callouts .aq-iso--limestone .aq-iso__eq--glass { fill: color-mix(in srgb, var(--limestone) 72%, var(--flow)); }
.aq-market-callouts .aq-iso--limestone .aq-iso__eq--alt { fill: color-mix(in srgb, var(--limestone) 86%, var(--navy)); }
.aq-market-callouts .aq-iso--limestone .aq-iso__eq--sheet { fill: var(--on-navy); }
.aq-market-callouts .aq-iso--limestone .aq-iso__eq, .aq-market-callouts .aq-iso--limestone .aq-iso__ln, .aq-market-callouts .aq-iso--limestone .aq-iso__thin, .aq-market-callouts .aq-iso--limestone .aq-iso__pipe-wall { stroke: var(--on-limestone-muted); }
.aq-market-callouts .aq-iso .aq-iso__flow, .aq-market-callouts .aq-iso .aq-iso__arrow { stroke: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-market-callouts .aq-iso .aq-iso__drop { fill: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-market-callouts__leads path { fill: none; stroke: var(--on-navy-muted); stroke-width: 1; vector-effect: non-scaling-stroke; }
.aq-market-callouts__leads .aq-market-callouts__halo { stroke: var(--navy); stroke-width: 3.5; }
.aq-market-callouts__leads circle { fill: var(--on-navy-muted); }
.aq-market-callouts__lead.is-on path:not(.aq-market-callouts__halo) { stroke: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); stroke-width: 1.5; }
.aq-market-callouts__lead.is-on circle { fill: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }

/* numbered marker on the part */
.aq-market-callouts__mk {
  position: absolute; display: grid; place-items: center; width: var(--space-6); height: var(--space-6); margin: calc(-1 * var(--space-3)) 0 0 calc(-1 * var(--space-3));
  border-radius: var(--radius-pill); background: var(--navy); border: 1.5px solid var(--on-navy); box-sizing: border-box;
  font: 500 11px/1 var(--font-mono); color: var(--on-navy); font-variant-numeric: tabular-nums;
}
.aq-market-callouts__mk.is-on { background: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); border-color: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); color: var(--navy); }

/* callouts */
.aq-market-callouts__list { list-style: none; margin: 0; padding: 0; }
.aq-market-callouts__c { position: absolute; left: var(--x, 0); top: var(--y, 0); width: 24%; display: flex; flex-direction: column; gap: var(--space-2); }
.aq-market-callouts__t { margin: 0 0 var(--space-1); font: 400 26px/30px var(--font-sans); letter-spacing: -0.015em; color: var(--on-navy); text-wrap: balance; }
.aq-market-callouts__n { display: block; margin-bottom: var(--space-1); font: 400 14px/20px var(--font-mono); color: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-market-callouts__scope { margin: 0; font: 500 12px/18px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-market-callouts__scope .aq-ph { text-transform: none; letter-spacing: 0; }
.aq-market-callouts__tags { margin: 0; }
.aq-market-callouts .aq-tag { border-color: var(--on-navy-muted); color: var(--on-navy); }
.aq-market-callouts__note { margin: 0; font: 400 14px/22px var(--font-sans); color: var(--on-navy-muted); }
.aq-market-callouts__c, .aq-market-callouts__mk { transition: opacity 200ms cubic-bezier(0.2, 0, 0, 1); }

/* Mid widths: the machine full width, the callouts in a row under it (leaders off, numbered markers keep the pairing) */
/* Inspection spotlight (motion only, ported from Subframe Motion "Guided inspection"): the drawing dims round the part
   the callout being read is about; the window glides between parts */
.aq-market-callouts__dim { position: absolute; inset: 0; overflow: hidden; pointer-events: none; display: none; opacity: 0; visibility: hidden; }
.aq-market-callouts__spot { position: absolute; left: 0; top: 0; width: 0; height: 0; border: 1px solid color-mix(in srgb, var(--flow) 45%, var(--on-navy));
  box-shadow: 0 0 0 200vmax color-mix(in srgb, var(--navy) 80%, transparent); }

@container (max-width: 1180px) {
  .aq-market-callouts__leads { display: none; }
  .aq-market-callouts__list { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); column-gap: var(--space-8); margin-top: var(--space-6); }
  .aq-market-callouts__c { position: static; width: auto; padding-top: var(--space-4); border-top: 1px solid color-mix(in srgb, var(--on-navy-muted) 35%, transparent); }
  .aq-market-callouts__plane { width: 140%; margin: -10% 0 -4% -20%; }
  .aq-market-callouts__stage { overflow: hidden; }
}

@container (max-width: 860px) {
  .aq-market-callouts__stage { overflow: hidden; margin-inline: calc(-1 * var(--space-4)); padding-inline: var(--space-4); }
  .aq-market-callouts__plane { width: 190%; margin: -16% 0 -6% -45%; }
  .aq-market-callouts__leads { display: none; }
  .aq-market-callouts__mk { width: var(--space-8); height: var(--space-8); margin: calc(-1 * var(--space-4)) 0 0 calc(-1 * var(--space-4)); font-size: 12px; }
  .aq-market-callouts__list { display: grid; grid-auto-flow: row; gap: var(--space-8); margin-top: var(--space-6); }
  .aq-market-callouts__c { position: static; width: auto; padding-top: var(--space-4); border-top: 1px solid color-mix(in srgb, var(--on-navy-muted) 35%, transparent); }
  .aq-market-callouts__t { font-size: 22px; line-height: 28px; }
}

/* ---------- MarkingMatch: supplier control as the receiving check (look "marking-match"). Part drawn in flat line art
   (line-strong, the marking ringed in flow), the requirement on a certificate paper (surface-raised, data-theme
   "light"), a double-ended check line between them. Rows on line hairlines; the column names head the list once. ---------- */
.aq-marking-match-sec { position: relative; }
.aq-marking-match { --cols: minmax(0, 4fr) minmax(0, 3fr) minmax(0, 4fr); }
.aq-marking-match__cols { display: grid; grid-template-columns: var(--cols, 1fr); column-gap: var(--space-8); padding-bottom: var(--space-3); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-marking-match__cols span:nth-child(2) { text-align: center; }
.aq-marking-match__list { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line-strong); }
.aq-marking-match__row {
  display: grid; grid-template-columns: var(--cols, 1fr); grid-template-areas: "sup ver req"; column-gap: var(--space-8); align-items: center;
  padding: var(--space-6) 0; border-bottom: 1px solid var(--line);
}
.aq-marking-match__k { display: none; margin: 0 0 var(--space-2); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }

/* the part */
.aq-marking-match__sup { grid-area: sup; display: grid; grid-template-columns: minmax(0, 1fr); row-gap: var(--space-2); }
.aq-marking-match__fig { display: block; width: 100%; max-width: calc(var(--space-32) * 1.75); height: auto; }
.aq-marking-match__ln { fill: none; stroke: var(--line-strong); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.aq-marking-match__eq { fill: var(--surface-sunken); stroke: var(--line-strong); stroke-width: 1.5; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.aq-marking-match__thin { fill: none; stroke: var(--line-strong); stroke-width: 1; vector-effect: non-scaling-stroke; }
.aq-marking-match__print { fill: none; stroke: var(--ink-subtle); stroke-width: 2; vector-effect: non-scaling-stroke; }
.aq-marking-match__mark { fill: var(--flow-tint); stroke: var(--flow); stroke-width: 1.5; vector-effect: non-scaling-stroke; }
.aq-marking-match__name { margin: 0; display: flex; gap: var(--space-3); align-items: baseline; font: 300 22px/28px var(--font-sans); letter-spacing: -0.015em; color: var(--ink); text-wrap: balance; }
.aq-marking-match__name a { color: inherit; }

/* the check line between part and paper */
.aq-marking-match__ver { grid-area: ver; display: flex; flex-direction: column; align-items: center; text-align: center; gap: var(--space-3); }
.aq-marking-match__line { position: relative; display: block; width: 100%; height: var(--space-8); }
.aq-marking-match__line::before { content: ""; position: absolute; left: 0; right: 0; top: 50%; border-top: 1.5px solid var(--flow); }
.aq-marking-match__line::after {
  content: ""; position: absolute; left: 0; right: 0; top: 50%; height: var(--space-2); transform: translateY(-50%);
  border-left: 1.5px solid var(--flow); border-right: 1.5px solid var(--flow);
}
.aq-marking-match__ok {
  position: absolute; z-index: 1; left: 50%; top: 50%; width: var(--space-8); height: var(--space-8); transform: translate(-50%, -50%);
  background: var(--surface); border: 1.5px solid var(--flow); border-radius: var(--radius-pill);
}
.aq-section--alt .aq-marking-match__ok { background: var(--surface-sunken); }
.aq-marking-match__ok::after {
  content: ""; position: absolute; left: 50%; top: 45%; width: var(--space-3); height: calc(var(--space-2) - 1px);
  border-left: 2px solid var(--flow); border-bottom: 2px solid var(--flow); transform: translate(-50%, -50%) rotate(-45deg);
}
.aq-marking-match__how { margin: 0; max-width: 30ch; font: 400 15px/22px var(--font-sans); color: var(--ink-muted); text-wrap: balance; }

/* the paper */
.aq-marking-match__req { grid-area: req; }
.aq-marking-match__paper {
  position: relative; padding: var(--space-8) var(--space-6) var(--space-6); background: var(--surface-raised); color: var(--ink);
  border: 1px solid var(--line); box-shadow: var(--space-1) var(--space-1) 0 color-mix(in srgb, var(--limestone) 80%, transparent);
}
.aq-marking-match__head { position: absolute; left: var(--space-6); top: var(--space-3); width: 40%; height: var(--space-2); border-top: 3px solid var(--line); border-bottom: 3px solid var(--line); }
.aq-marking-match__seal { position: absolute; right: var(--space-4); top: var(--space-3); width: var(--space-6); height: var(--space-6); border: 1.5px solid var(--flow); border-radius: var(--radius-pill); }
.aq-marking-match__seal::after { content: ""; position: absolute; inset: calc(var(--space-1) - 1px); border: 1px dashed var(--flow); border-radius: var(--radius-pill); }
.aq-marking-match__rq { margin: 0; font: 400 16px/24px var(--font-sans); text-wrap: pretty; }
.aq-marking-match__row:hover .aq-marking-match__mark { fill: var(--flow); }
.aq-marking-match__row:hover .aq-marking-match__paper { border-color: var(--flow); }

/* Fold: desktop shows every supply; the fold works on phones only */
.aq-fold:not(.is-open) .aq-marking-match__row.aq-fold-x { display: grid; }
.aq-fold:has(> .aq-marking-match__list) > .aq-fold__btn { display: none; }

@container (max-width: 860px) {
  .aq-marking-match__cols { display: none; }
  .aq-marking-match__k { display: block; }
  .aq-marking-match__row { grid-template-columns: minmax(0, 1fr); grid-template-areas: "sup" "ver" "req"; row-gap: var(--space-4); padding: var(--space-6) 0 var(--space-8); }
  .aq-marking-match__fig { max-width: calc(var(--space-32) * 1.5); }
  .aq-marking-match__name { font-size: 20px; line-height: 26px; }
  .aq-marking-match__ver { display: grid; grid-template-columns: var(--space-8) minmax(0, 1fr); column-gap: var(--space-4); align-items: center; text-align: left; }
  .aq-marking-match__ver .aq-marking-match__k { grid-column: 1 / -1; margin: 0; }
  .aq-marking-match__line { width: var(--space-8); height: var(--space-16); }
  .aq-marking-match__line::before { left: 50%; right: auto; top: 0; bottom: 0; border-top: 0; border-left: 1.5px solid var(--flow); }
  .aq-marking-match__line::after { left: 50%; right: auto; top: 0; bottom: 0; height: auto; width: var(--space-2); transform: translateX(-50%); border: 0; border-top: 1.5px solid var(--flow); border-bottom: 1.5px solid var(--flow); }
  .aq-marking-match__how { max-width: none; text-wrap: pretty; }
  .aq-marking-match__paper { padding: var(--space-8) var(--space-4) var(--space-4); }
  .aq-fold:not(.is-open) .aq-marking-match__row.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-marking-match__list) > .aq-fold__btn { display: flex; }
}

/* ---------- MembraneAtlas: feed conditions as a numbered table, each row headed by a navy numeral tile ---------- */
/* Four columns: the navy tile (huge light slash numeral over a soft micrograph), then condition, effect and design.
   Column names sit over a heavy rule; hairlines between rows. */
.aq-membrane-atlas-sec .aq-sec-head .aq-h1 { font: 300 56px/60px var(--font-sans); letter-spacing: -0.03em; max-width: 24ch; }
.aq-membrane-atlas { --ma-tile: calc(var(--space-32) + var(--space-12)); }
.aq-membrane-atlas__vh { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.aq-membrane-atlas__tr { display: grid; grid-template-columns: var(--ma-tile, var(--space-32)) repeat(3, minmax(0, 1fr)); }
.aq-membrane-atlas__thead .aq-membrane-atlas__tr { border-bottom: 2px solid var(--navy); }
.aq-membrane-atlas__th { padding: 0 var(--space-6) var(--space-3); font: 400 16px/22px var(--font-sans); color: var(--ink-muted); }
.aq-membrane-atlas__plate { border-bottom: 1px solid var(--line-strong); }
.aq-membrane-atlas__td { padding: var(--space-4) var(--space-6) var(--space-6); border-left: 1px solid var(--line); display: flex; flex-direction: column; gap: var(--space-2); min-width: 0; }
.aq-membrane-atlas__k { display: none; font: 500 12px/16px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-membrane-atlas__t { font: 300 24px/30px var(--font-sans); letter-spacing: -0.01em; color: var(--ink); }
.aq-membrane-atlas__c { font: 400 16px/24px var(--font-sans); color: var(--ink-muted); }
.aq-membrane-atlas__td--ours .aq-membrane-atlas__c { color: var(--ink); }

/* The tile: navy square, the numeral top-left, the micrograph soft behind it at the lower right */
.aq-membrane-atlas__tile { position: relative; overflow: hidden; background: var(--navy); color: var(--on-navy); min-height: calc(var(--ma-tile, var(--space-32)) * 0.8); }
.aq-membrane-atlas__n { position: absolute; left: var(--space-4); top: var(--space-3); z-index: 1; font: 300 72px/1 var(--font-sans); letter-spacing: -0.05em; font-variant-numeric: tabular-nums; color: var(--on-navy); }
.aq-membrane-atlas__sl { color: var(--on-navy-muted); margin-left: 0.02em; }
.aq-membrane-atlas__scope { position: absolute; right: calc(-1 * var(--space-8)); bottom: calc(-1 * var(--space-8)); width: calc(var(--ma-tile, var(--space-32)) * 0.95); aspect-ratio: 1; }
.aq-membrane-atlas__scope > .aq-membrane-atlas__svg { opacity: 0.55; filter: blur(1.4px); }
.aq-membrane-atlas__plate:hover .aq-membrane-atlas__sl, .aq-membrane-atlas__plate:focus-within .aq-membrane-atlas__sl { color: var(--limestone); }

/* The micrograph, drawn in navy-ground inks */
.aq-membrane-atlas__svg { display: block; width: 100%; height: auto; overflow: visible; }
.aq-membrane-atlas__svg * { vector-effect: non-scaling-stroke; stroke-linecap: round; stroke-linejoin: round; }
.aq-membrane-atlas__field { fill: color-mix(in srgb, var(--navy) 85%, var(--on-navy)); }
.aq-membrane-atlas__rim { fill: none; stroke: var(--on-navy); stroke-width: 1.5; }
.aq-membrane-atlas__tick, .aq-membrane-atlas__cross { fill: none; stroke: var(--on-navy-muted); stroke-width: 1; }
.aq-membrane-atlas__tex { fill: none; stroke: var(--on-navy-muted); stroke-width: 0.75; opacity: 0.38; }
.aq-membrane-atlas__hole { fill: var(--on-navy); stroke: var(--on-navy); stroke-width: 1; }
.aq-membrane-atlas__crack { fill: none; stroke: var(--on-navy); stroke-width: 1; }
.aq-membrane-atlas__split { fill: none; stroke: var(--on-navy-muted); stroke-width: 1; stroke-dasharray: 3 3; }
.aq-membrane-atlas__perm { fill: none; stroke: var(--limestone); stroke-width: 1.5; }
.aq-membrane-atlas__dot { fill: var(--limestone); }
.aq-membrane-atlas__rod { fill: color-mix(in srgb, var(--navy) 85%, var(--on-navy)); stroke: var(--on-navy); stroke-width: 1; }
.aq-membrane-atlas__cake { fill: none; stroke: var(--on-navy-muted); stroke-width: 0.9; }
.aq-membrane-atlas__cake--fill { fill: var(--on-navy-muted); }
.aq-membrane-atlas__xtal { fill: color-mix(in srgb, var(--navy) 70%, var(--on-navy)); stroke: var(--on-navy); stroke-width: 1; }
.aq-membrane-atlas__glass { fill: color-mix(in srgb, var(--navy) 70%, var(--on-navy)); stroke: var(--on-navy); stroke-width: 1; }
.aq-membrane-atlas__glint { fill: none; stroke: var(--on-navy-muted); stroke-width: 0.75; }
.aq-membrane-atlas__rust { fill: var(--on-navy-muted); }
.aq-membrane-atlas__eps { fill: color-mix(in srgb, var(--navy) 70%, var(--on-navy)); stroke: var(--on-navy-muted); stroke-width: 1; stroke-dasharray: 2 2; }


/* The scope's lens (added by motion.js): a sharp copy of the micrograph shows through a ring that follows the pointer */
.aq-membrane-atlas__lens { position: absolute; inset: 0; pointer-events: none; clip-path: inset(50%); transition: clip-path 150ms cubic-bezier(0.2, 0, 0, 1); }
.aq-membrane-atlas__lens.is-on { clip-path: inset(0); }
.aq-membrane-atlas__lens > .aq-membrane-atlas__svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.aq-membrane-atlas__ring { position: absolute; left: 0; top: 0; width: var(--space-24); height: var(--space-24); margin: calc(-1 * var(--space-12)) 0 0 calc(-1 * var(--space-12)); border: 1px solid var(--limestone); border-radius: var(--radius-pill); pointer-events: none; }

/* Desktop shows every row; the fold is for phones */
.aq-fold:not(.is-open) .aq-membrane-atlas__plate.aq-fold-x { display: grid; }
.aq-fold:has(> .aq-membrane-atlas) > .aq-fold__btn { display: none; }

@container (max-width: 1100px) {
  .aq-membrane-atlas { --ma-tile: calc(var(--space-24) + var(--space-8)); }
  .aq-membrane-atlas__n { font-size: 56px; }
  .aq-membrane-atlas__td { padding: var(--space-4); }
  .aq-membrane-atlas__t { font-size: 20px; line-height: 26px; }
  .aq-membrane-atlas__c { font-size: 14px; line-height: 22px; }
}
/* Phones: the tile becomes a band over its row (numeral left, micrograph right), the cells stack under their names */
@container (max-width: 860px) {
  .aq-membrane-atlas-sec .aq-sec-head .aq-h1 { font-size: 36px; line-height: 42px; }
  .aq-membrane-atlas__thead { display: none; }
  .aq-membrane-atlas__tr { grid-template-columns: minmax(0, 1fr); }
  .aq-membrane-atlas__plate { padding-bottom: var(--space-4); }
  .aq-membrane-atlas__tile { min-height: var(--space-24); }
  .aq-membrane-atlas__n { font-size: 56px; top: var(--space-4); }
  .aq-membrane-atlas__scope { width: var(--space-32); right: calc(-1 * var(--space-4)); bottom: auto; top: calc(-1 * var(--space-4)); }
  .aq-membrane-atlas__td { border-left: 0; padding: var(--space-3) 0 0; gap: var(--space-1); }
  .aq-membrane-atlas__k { display: block; }
  .aq-fold:not(.is-open) .aq-membrane-atlas__plate.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-membrane-atlas) > .aq-fold__btn { display: flex; }
}

/* ---------- MembraneFace: RO feed targets as a bento around the feed end of a spiral-wound element ---------- */
/* Desktop: four columns. Heading over two, two targets beside it; the element (navy, 2 x 2) in the middle, the other
   four targets either side of it. Further targets run on underneath. */
.aq-membrane-face { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-3);
  grid-template-areas: "head head t1 t2" "t3 core core t4" "t5 core core t6"; }
.aq-membrane-face__head { grid-area: head; align-self: end; padding: 0 var(--space-6) var(--space-6) 0; }
.aq-membrane-face__head .aq-h1 { font-size: 56px; line-height: 60px; letter-spacing: -0.035em; font-weight: 300; max-width: 10ch; }
.aq-membrane-face__tiles { display: contents; list-style: none; margin: 0; padding: 0; }
.aq-membrane-face__tile:nth-child(1) { grid-area: t1; }
.aq-membrane-face__tile:nth-child(2) { grid-area: t2; }
.aq-membrane-face__tile:nth-child(3) { grid-area: t3; }
.aq-membrane-face__tile:nth-child(4) { grid-area: t4; }
.aq-membrane-face__tile:nth-child(5) { grid-area: t5; }
.aq-membrane-face__tile:nth-child(6) { grid-area: t6; }
.aq-membrane-face__tile:nth-child(n+7) { grid-column: span 2; }

/* Target tile */
.aq-membrane-face__tile { position: relative; display: flex; flex-direction: column; gap: var(--space-3); min-height: 248px; padding: var(--space-6);
