/* ---------- MethodBento: methods compared as a bento of drawn tiles; the missing method is a dashed gap ---------- */
.aq-method-bento { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); grid-auto-flow: row dense; gap: var(--space-4); }
.aq-method-bento__head { grid-column: 1; grid-row: 1; align-self: end; padding: 0 var(--space-6) var(--space-6) 0; }
