.aq-method-bento__dl { margin: auto 0 0; display: grid; gap: var(--space-3); padding-top: var(--space-4); border-top: 1px solid var(--line); }
.is-hot .aq-method-bento__dl { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-6); border-top-color: color-mix(in srgb, var(--on-navy) 25%, transparent); }
.aq-method-bento__dl div { display: grid; gap: var(--space-1); align-content: start; }
