/* ---------- NotesRegister: technical notes as a register (block "register") ----------
   On the page ground, no plate. Desktop: a row of topic filter chips across the top (quiet controls, radius-sm);
   the featured note on a surface-raised panel on the left with a flow top hairline and an equipment Spot vignette;
   the register on the right as a table on line hairlines with eyebrow column heads.
   Phones: the chips scroll sideways in their own row, the panel sits above, rows become a number column, then the
   title with mono meta (topic · date · standard). */
.aq-notes-register__plate { min-width: 0; }
.aq-notes-register {
  display: grid; grid-template-columns: minmax(0, 300px) minmax(0, 1fr);
  grid-template-areas: "filter filter" "count count" "feature reg"; column-gap: var(--space-12); align-items: start;
}

/* Filter row: an eyebrow caption, then the chips */
.aq-notes-register__filter {
  grid-area: filter; display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); margin-bottom: var(--space-8);
}
.aq-notes-register__fk { margin-right: var(--space-2); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-notes-register__chip {
  display: inline-flex; align-items: center; gap: var(--space-2); min-height: 44px; padding: 0 var(--space-4); margin: 0;
  background: transparent; border: 1px solid var(--line); border-radius: var(--radius-sm); cursor: pointer;
  font: 500 14px/20px var(--font-sans); color: var(--ink-muted); white-space: nowrap;
}
.aq-notes-register__chip span { font: 400 12px/16px var(--font-mono); font-variant-numeric: tabular-nums; color: var(--ink-subtle); }
.aq-notes-register__chip:hover { color: var(--ink); border-color: var(--line-strong); }
.aq-notes-register__chip:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-notes-register__chip[aria-pressed="true"] { background: var(--surface-sunken); border-color: var(--line-strong); color: var(--ink); }
.aq-notes-register__count { grid-area: count; position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* Featured note: a surface-raised panel with a flow top hairline and a Spot vignette */
.aq-notes-register__feature {
  grid-area: feature; display: flex; flex-direction: column; gap: var(--space-4);
  padding: var(--space-6); background: var(--surface-raised); border-top: 1px solid var(--flow);
}
.aq-notes-register__flabel { display: flex; flex-wrap: wrap; gap: var(--space-2); margin: 0; }
.aq-notes-register__flabel span { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-notes-register__flabel span + span::before { content: "·"; content: "·" / ""; margin-right: var(--space-2); }
.aq-notes-register__ft { margin: 0; font: 400 22px/30px var(--font-sans); letter-spacing: -0.01em; color: var(--ink); }
.aq-notes-register__fd { margin: 0; font: 400 15px/24px var(--font-sans); color: var(--ink-muted); text-wrap: pretty; }
/* Phones set .aq-tag to height: auto; keep its pill padded */
.aq-notes-register__feature .aq-tag { padding-block: var(--space-1); }
.aq-notes-register__vig { display: flex; justify-content: center; padding-block: var(--space-4); }
.aq-notes-register__spot { background-color: var(--ink-muted); }
.aq-notes-register__go { margin: 0; padding-top: var(--space-4); border-top: 1px solid var(--line); font: 400 14px/22px var(--font-sans); color: var(--ink-muted); }
.aq-notes-register__go a { margin-left: var(--space-1); color: var(--flow); text-decoration: none; }
.aq-notes-register__go a:hover { text-decoration: underline; text-underline-offset: 4px; }

/* Register: a table on hairlines */
.aq-notes-register__reg { grid-area: reg; min-width: 0; }
.aq-notes-register__table { width: 100%; border-collapse: collapse; }
.aq-notes-register__table thead th {
  padding: 0 var(--space-3) var(--space-3); border-bottom: 1px solid var(--line-strong); text-align: left; vertical-align: bottom;
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted);
}
.aq-notes-register__table thead th:first-child { padding-left: 0; }
.aq-notes-register__table tbody tr { position: relative; border-bottom: 1px solid var(--line); }
.aq-notes-register__table tbody tr[hidden] { display: none; }
.aq-notes-register__table tbody tr:hover { background: var(--surface-sunken); }
.aq-notes-register__table td, .aq-notes-register__table tbody th { padding: var(--space-3); text-align: left; vertical-align: top; }
.aq-notes-register__table td:first-child { padding-left: 0; }
.aq-notes-register__date, .aq-notes-register__no, .aq-notes-register__topic, .aq-notes-register__std {
  font: 400 13px/22px var(--font-mono); color: var(--ink-muted);
}
.aq-notes-register__date, .aq-notes-register__no { white-space: nowrap; font-variant-numeric: tabular-nums; }
.aq-notes-register__std { width: 24%; color: var(--ink); }
.aq-notes-register__planned { color: var(--ink-subtle); }
.aq-notes-register__t { font: 400 15px/22px var(--font-sans); color: var(--ink); text-wrap: pretty; }
.aq-notes-register__t a { color: var(--ink); text-decoration: none; }
.aq-notes-register__t a::after { content: ""; position: absolute; inset: 0; }
.aq-notes-register__t a:hover { color: var(--flow); }
.aq-notes-register__table tr.is-featured .aq-notes-register__no { color: var(--flow); }
/* A topic filter shows every matching row, folded or not, and hides the fold button */
.aq-notes-register .aq-fold.is-filtered .aq-fold-x { display: table-row; }
.aq-notes-register .aq-fold.is-filtered .aq-fold-x[hidden] { display: none; }
.aq-notes-register .aq-fold.is-filtered .aq-fold__btn { display: none; }

@container (max-width: 860px) {
  .aq-notes-register { grid-template-columns: minmax(0, 1fr); grid-template-areas: "filter" "count" "feature" "reg"; }
  /* Chips scroll sideways in their own row, never the page */
  .aq-notes-register__filter { flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; margin-bottom: var(--space-6); }
  .aq-notes-register__filter::-webkit-scrollbar { display: none; }
  .aq-notes-register__chip, .aq-notes-register__fk { flex: none; }
  .aq-notes-register__feature { padding: var(--space-4); gap: var(--space-3); margin-bottom: var(--space-6); }
  .aq-notes-register__ft { font-size: 19px; line-height: 26px; }
  .aq-notes-register__vig { padding-block: var(--space-2); }
  .aq-notes-register__spot { width: var(--space-24); height: var(--space-24); }
  /* Rows: a mono number column, then title and mono meta */
  .aq-notes-register__table, .aq-notes-register__table tbody { display: block; }
  .aq-notes-register__table thead { display: none; }
  .aq-notes-register__table tbody tr { display: grid; grid-template-columns: var(--space-12) minmax(0, 1fr) auto; column-gap: var(--space-3); }
  .aq-notes-register__table td, .aq-notes-register__table tbody th { padding: 0; }
  .aq-notes-register__no { grid-column: 1; grid-row: 1 / 4; padding: var(--space-3) 0 !important; }
  .aq-notes-register__t { grid-column: 2 / -1; grid-row: 1; padding: var(--space-3) 0 var(--space-1) !important; font-size: 15px; line-height: 22px; }
  .aq-notes-register__topic, .aq-notes-register__std, .aq-notes-register__date { width: auto; font-size: 12px; line-height: 18px; }
  .aq-notes-register__topic { grid-column: 2; grid-row: 2; }
  .aq-notes-register__date { grid-column: 3; grid-row: 2; text-align: right; }
  .aq-notes-register__std { grid-column: 2 / -1; grid-row: 3; padding: var(--space-1) 0 var(--space-3) !important; }
  .aq-notes-register .aq-fold.is-filtered .aq-fold-x { display: grid; }
}

/* ---------- NumeralIndex: a router as a Swiss index of situations under huge light outline numerals ---------- */
.aq-numeral-index-sec .aq-sec-head .aq-h1 { font: 300 56px/60px var(--font-sans); letter-spacing: -0.03em; max-width: 18ch; }
.aq-numeral-index { list-style: none; margin: var(--space-8) 0 0; padding: 0; counter-reset: none; }
.aq-numeral-index__row { position: relative; display: grid; grid-template-columns: minmax(0, 2fr) minmax(0, 6fr) minmax(0, 3fr);
  column-gap: var(--space-8); align-items: start; padding: var(--space-8) 0; }
.aq-numeral-index__row:last-child { border-bottom: 1px solid var(--line-strong); }
.aq-numeral-index__rule { position: absolute; left: 0; right: 0; top: 0; height: 1px; background: var(--line-strong); transform-origin: 0 50%; }
.aq-numeral-index__rule::after { content: ""; position: absolute; inset: 0; background: var(--flow); transform: scaleX(0); transform-origin: 0 50%;
  transition: transform 500ms cubic-bezier(0.2, 0, 0, 1); }
.aq-numeral-index__row:hover .aq-numeral-index__rule::after, .aq-numeral-index__row:focus-within .aq-numeral-index__rule::after { transform: scaleX(1); }

/* The numeral: Geist Light, outlined in line-strong, filled with flow when the row is active */
.aq-numeral-index__n { display: block; overflow: hidden; margin-top: calc(var(--space-2) * -1); font: 300 128px/104px var(--font-sans); letter-spacing: -0.06em;
  font-variant-numeric: tabular-nums; color: transparent; -webkit-text-stroke: 1.5px var(--line-strong); }
.aq-numeral-index__n > span { display: block; transition: color 400ms cubic-bezier(0.2, 0, 0, 1); }
.aq-numeral-index__row:hover .aq-numeral-index__n > span, .aq-numeral-index__row:focus-within .aq-numeral-index__n > span { color: var(--flow); }
.aq-numeral-index__row:hover .aq-numeral-index__n, .aq-numeral-index__row:focus-within .aq-numeral-index__n { -webkit-text-stroke-color: var(--flow); }

.aq-numeral-index__body { display: flex; flex-direction: column; gap: var(--space-4); min-width: 0; padding-top: var(--space-1); }
.aq-numeral-index__t { margin: 0; font: 300 32px/40px var(--font-sans); letter-spacing: -0.02em; color: var(--ink); max-width: 22ch; }
.aq-numeral-index__need { margin: 0; display: grid; grid-template-columns: minmax(0, 9rem) minmax(0, 1fr); gap: var(--space-4);
  padding-top: var(--space-3); border-top: 1px solid var(--line); font: 400 17px/26px var(--font-sans); color: var(--ink-muted); max-width: 40rem; }
.aq-numeral-index__k { font: 500 12px/20px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }

/* The go-cell: a square tile, page icon, the start page, an arrow that runs on hover */
.aq-numeral-index__go { position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr); grid-template-rows: auto 1fr auto; gap: var(--space-3) var(--space-3);
  min-height: calc(var(--space-32) + var(--space-8)); margin: 0; padding: var(--space-4); border: 1px solid var(--line-strong); color: var(--ink); text-decoration: none;
  background: var(--surface-raised); transition: background-color 300ms cubic-bezier(0.2, 0, 0, 1), border-color 300ms cubic-bezier(0.2, 0, 0, 1), color 300ms; }
.aq-numeral-index__go .aq-numeral-index__k { grid-column: 1 / -1; }
.aq-numeral-index__ic { grid-row: 3; grid-column: 1; width: var(--space-8); height: var(--space-8); background-color: var(--ink-muted); align-self: end; }
.aq-numeral-index__to { grid-column: 1 / -1; grid-row: 2; font: 400 20px/28px var(--font-sans); letter-spacing: -0.01em; }
.aq-numeral-index__arrow { grid-row: 3; grid-column: 2; justify-self: end; align-self: end; position: relative; width: var(--space-12); height: var(--space-4); }
.aq-numeral-index__arrow::before { content: ""; position: absolute; left: 0; right: 1px; top: 50%; height: 1.5px; background: currentColor; transform-origin: 100% 50%;
  transform: scaleX(0.5); transition: transform 400ms cubic-bezier(0.2, 0, 0, 1); }
.aq-numeral-index__arrow::after { content: ""; position: absolute; right: 1px; top: 50%; width: var(--space-2); height: var(--space-2); border-top: 1.5px solid currentColor;
  border-right: 1.5px solid currentColor; transform: translateY(-50%) rotate(45deg); transform-origin: 75% 25%; }
.aq-numeral-index__go:hover, .aq-numeral-index__go:focus-visible { background: var(--navy); border-color: var(--navy); color: var(--on-navy); }
.aq-numeral-index__go:hover .aq-numeral-index__k, .aq-numeral-index__go:focus-visible .aq-numeral-index__k { color: var(--on-navy-muted); }
.aq-numeral-index__go:hover .aq-numeral-index__ic, .aq-numeral-index__go:focus-visible .aq-numeral-index__ic { background-color: var(--limestone); }
.aq-numeral-index__go:hover .aq-numeral-index__arrow::before, .aq-numeral-index__go:focus-visible .aq-numeral-index__arrow::before { transform: scaleX(1); }
.aq-numeral-index__go:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-numeral-index__go.is-flat { border-style: dashed; background: transparent; }

@container (max-width: 1100px) {
  .aq-numeral-index__row { grid-template-columns: minmax(0, 2fr) minmax(0, 7fr); row-gap: var(--space-6); }
  .aq-numeral-index__go { grid-column: 2; min-height: 0; grid-template-rows: auto auto; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; }
  .aq-numeral-index__go .aq-numeral-index__k { grid-column: 1 / -1; }
  .aq-numeral-index__ic { grid-row: 2; align-self: center; }
  .aq-numeral-index__to { grid-row: 2; grid-column: 2; }
  .aq-numeral-index__arrow { grid-row: 2; grid-column: 3; align-self: center; }
}

/* Phones: numeral over the row, need stacked, go-cell full width */
@container (max-width: 860px) {
  .aq-numeral-index-sec .aq-sec-head .aq-h1 { font-size: 36px; line-height: 42px; }
  .aq-numeral-index { margin-top: var(--space-4); }
  .aq-numeral-index__row { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-4); padding: var(--space-6) 0; }
  .aq-numeral-index__n { font-size: 72px; line-height: 60px; margin-top: 0; }
  .aq-numeral-index__t { font-size: 24px; line-height: 32px; }
  .aq-numeral-index__need { grid-template-columns: minmax(0, 1fr); gap: var(--space-1); font-size: 16px; line-height: 24px; }
  .aq-numeral-index__go { grid-column: 1; }
  .aq-numeral-index__to { font-size: 17px; line-height: 24px; }
}

/* ---------- OptionChecker: options as a Swiss grid beside a checkerboard field with one blueprint tile (look "option-checker") ---------- */
/* The field (left, 4 x 4 squares) is decoration except the blueprint tile, whose parts light with their option.
   The body (right): the section head in the top cell, then the option cells (two wide, three narrow) on 1 px rules. */
.aq-option-checker {
  display: grid; grid-template-columns: minmax(0, 34fr) minmax(0, 66fr);
  border-top: 1px solid var(--line-strong); border-bottom: 1px solid var(--line-strong);
}
.aq-option-checker__field { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-template-rows: repeat(4, minmax(0, 1fr)); }
.aq-option-checker__tile { min-height: var(--space-16); }
.aq-option-checker__tile--n { background: var(--navy); }
.aq-option-checker__tile--l { background: var(--limestone); }
.aq-option-checker__tile--s { background: var(--surface-sunken); }
.aq-option-checker__tile--b { background: var(--navy); position: relative; outline: 1px solid var(--flow); outline-offset: -1px; }
.aq-option-checker__bp { position: absolute; inset: 0; width: 100%; height: 100%; }
.aq-option-checker__bp * { vector-effect: non-scaling-stroke; }
.aq-option-checker__grid { fill: none; stroke: var(--on-navy-muted); stroke-width: 1; opacity: 0.12; }
.aq-option-checker__part, .aq-option-checker__fixed, .aq-option-checker__link { fill: none; stroke: var(--on-navy-muted); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; transition: stroke 200ms ease, opacity 200ms ease; }
.aq-option-checker__part circle { fill: var(--on-navy-muted); stroke: none; transition: fill 200ms ease; }
.aq-option-checker__link { stroke-dasharray: 3 3; }
.aq-option-checker.has-hot .aq-option-checker__part:not(.is-hot), .aq-option-checker.has-hot .aq-option-checker__fixed { opacity: 0.35; }
.aq-option-checker__part.is-hot { stroke: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); stroke-width: 2; }
.aq-option-checker__part.is-hot circle { fill: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }

.aq-option-checker__body { display: flex; flex-direction: column; border-left: 1px solid var(--line-strong); }
.aq-option-checker__head { padding: var(--space-8) var(--space-8) var(--space-6); display: flex; justify-content: flex-end; border-bottom: 1px solid var(--line-strong); }
.aq-option-checker__head .aq-sec-head { margin: 0; }
.aq-option-checker__head .aq-h1 { font-size: clamp(56px, 7vw, 104px); line-height: 1; font-weight: 300; letter-spacing: -0.03em; }
.aq-option-checker__cells { list-style: none; margin: 0; padding: 0; flex: 1; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); }
.aq-option-checker__cell {
  grid-column: span 2; display: flex; flex-direction: column; gap: var(--space-3); padding: var(--space-6) var(--space-6) var(--space-8);
  border-left: 1px solid var(--line-strong); border-top: 1px solid var(--line-strong); margin: 0 0 0 -1px; transition: background-color 200ms ease;
}
.aq-option-checker__cell--wide { grid-column: span 3; border-top: 0; }
.aq-option-checker__cell:hover, .aq-option-checker__cell:focus-within { background: var(--flow-tint); }
.aq-option-checker__n { display: flex; align-items: baseline; font: 300 clamp(56px, 6vw, 88px)/1 var(--font-sans); letter-spacing: -0.04em; color: var(--ink); margin-bottom: var(--space-4); }
.aq-option-checker__sl { color: var(--line-strong); }
.aq-option-checker__cell:hover .aq-option-checker__sl, .aq-option-checker__cell:focus-within .aq-option-checker__sl { color: var(--flow); }
.aq-option-checker__t { margin: 0; font: 400 20px/26px var(--font-sans); letter-spacing: -0.01em; color: var(--ink); text-wrap: balance; }
.aq-option-checker__t a { color: inherit; text-decoration: underline; text-decoration-color: var(--line-strong); text-underline-offset: 0.2em; }
.aq-option-checker__t a:hover { text-decoration-color: var(--flow); }
.aq-option-checker__t a:focus-visible { outline: 2px solid var(--focus); outline-offset: var(--space-1); }
.aq-option-checker__arrow { color: var(--flow); }
.aq-option-checker__d { margin: 0; font: 400 15px/22px var(--font-sans); color: var(--ink-muted); text-wrap: pretty; }

@container (max-width: 860px) {
  .aq-option-checker { grid-template-columns: minmax(0, 1fr); }
  .aq-option-checker__field { grid-template-rows: repeat(2, minmax(0, 1fr)); }
  .aq-option-checker__tile { aspect-ratio: 1; min-height: 0; }
  .aq-option-checker__tile[data-r="1"], .aq-option-checker__tile[data-r="4"] { display: none; }
  .aq-option-checker__tile--b { grid-row: 1 / span 2 !important; }
  .aq-option-checker__tile[data-r="2"]:not(.aq-option-checker__tile--b) { grid-row: 1 !important; }
  .aq-option-checker__tile[data-r="3"] { grid-row: 2 !important; }
  .aq-option-checker__body { border-left: 0; }
  .aq-option-checker__head { justify-content: flex-start; padding: var(--space-6) 0; border-top: 1px solid var(--line-strong); }
  .aq-option-checker__cells { grid-template-columns: minmax(0, 1fr); }
  .aq-option-checker__cell, .aq-option-checker__cell--wide { grid-column: 1; border-left: 0; border-top: 1px solid var(--line-strong); margin: 0; padding: var(--space-6) 0;
    display: grid; grid-template-columns: var(--space-24) minmax(0, 1fr); column-gap: var(--space-4); row-gap: var(--space-2); }
  .aq-option-checker__n { grid-row: 1 / span 2; font-size: 56px; margin: 0; }
  .aq-option-checker__t { font-size: 18px; line-height: 24px; }
}
.aq-option-checker-sec { position: relative; }
.aq-option-checker__num { font-variant-numeric: tabular-nums; }

/* ---------- OptionList: configuration options as rows of the shared list grammar ---------- */
/* Layout comes from .aq-rows in base.css (index | option | one line on desktop; index | option, line below on phones),
   with `line` hairlines between rows. Options never get a box, a grid ground or a decorative glyph. */
.aq-options { min-width: 0; }

/* Plain rows (no icons, OptionList and plain ProcessSteps): a fixed 280 px title column with the line straight after it
   (capped at the reading measure), so short titles never leave a 400 px gap before their line. */
ol.aq-rows.aq-options:not(:has(.aq-rows__lead)) .aq-rows__row, ol.aq-rows.aq-steps:not(:has(.aq-rows__lead)) .aq-rows__row { grid-template-columns: var(--space-12) calc(var(--space-32) * 2 + var(--space-6)) minmax(0, var(--text-max)); column-gap: var(--space-6); padding-block: var(--space-6); }
ol.aq-rows.aq-options:not(:has(.aq-rows__lead)) .aq-rows__t, ol.aq-rows.aq-steps:not(:has(.aq-rows__lead)) .aq-rows__t { font-size: 18px; line-height: 26px; }
ol.aq-rows.aq-options:not(:has(.aq-rows__lead)) .aq-rows__row > .aq-index, ol.aq-rows.aq-steps:not(:has(.aq-rows__lead)) .aq-rows__row > .aq-index { line-height: 26px; }

/* Decisions (as: "decisions"): the index with a "?" beside it in flow (a word, not a badge), an optional fork mark
   (line art) before a two-way decision, an optional "Decide by" eyebrow under the line. */
.aq-options--decide .aq-rows__row { align-items: baseline; }
.aq-options__q { display: flex; align-items: baseline; gap: var(--space-2); }
.aq-options__q > .aq-index { line-height: 26px; }
.aq-options__qt { font: 500 13px/26px var(--font-mono); color: var(--flow); }
.aq-options__fork { display: inline-block; width: var(--space-8); height: 20px; margin-right: var(--space-2); vertical-align: -4px; overflow: visible; }
.aq-options__fork path { fill: none; stroke: var(--flow); stroke-width: 1.5; }
.aq-options__fork circle { fill: var(--flow); }
.aq-options__by { display: block; margin-top: var(--space-2); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }

@container (max-width: 860px) {
  ol.aq-rows.aq-options:not(:has(.aq-rows__lead)) .aq-rows__row, ol.aq-rows.aq-steps:not(:has(.aq-rows__lead)) .aq-rows__row { grid-template-columns: var(--space-8) minmax(0, 1fr); column-gap: var(--space-3); padding-block: var(--space-4); }
  ol.aq-rows.aq-options:not(:has(.aq-rows__lead)) .aq-rows__t, ol.aq-rows.aq-steps:not(:has(.aq-rows__lead)) .aq-rows__t { font-size: 16px; line-height: 24px; }
  ol.aq-rows.aq-options:not(:has(.aq-rows__lead)) .aq-rows__row > .aq-index, ol.aq-rows.aq-steps:not(:has(.aq-rows__lead)) .aq-rows__row > .aq-index,
  .aq-options__q > .aq-index, .aq-options__qt { line-height: 24px; }
  .aq-options__q { grid-row: span 2; gap: var(--space-1); }
  .aq-options__fork { width: var(--space-6); height: 16px; }
}

/* ---------- OptionModules: options as modules around the base skid (options block, as: "modules") ----------
   Desktop: three columns, modules | base drawing in a Plate | modules, each module wired to the plate by a dashed
   hairline. A module is a `line` frame on surface with a hairline under its title. Phones: the plate on top, then one
   column of modules hanging off a dashed vertical spine. */
.aq-option-modules {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr) minmax(0, 1fr);
  column-gap: var(--space-12); align-items: stretch; min-width: 0;
}
.aq-option-modules--bare { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
.aq-option-modules__list {
  list-style: none; margin: 0; padding: 0; min-width: 0;
  display: flex; flex-direction: column; justify-content: space-around; gap: var(--space-8);
}
.aq-option-modules__m { display: flex; flex-direction: column; gap: var(--space-2); min-width: 0; }
.aq-option-modules__cat { margin: 0; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-option-modules__m--l .aq-option-modules__cat { text-align: right; }

/* The module: a hairline frame with the title over a hairline, the vignette at left and the line beside it. */
.aq-option-modules__box {
  position: relative; display: grid; grid-template-columns: calc(var(--space-24) + var(--space-3)) minmax(0, 1fr); align-items: center;
  justify-items: center;
  border: 1px solid var(--line); background: var(--surface);
}
.aq-option-modules__box--bare { grid-template-columns: minmax(0, 1fr); }
.aq-option-modules__t {
  grid-column: 1 / -1; justify-self: stretch; display: flex; justify-content: space-between; align-items: baseline; gap: var(--space-3);
  margin: 0; padding: var(--space-3) var(--space-4); border-bottom: 1px solid var(--line);
  font: 500 16px/24px var(--font-sans); letter-spacing: -0.005em; color: var(--ink);
}
.aq-option-modules__plus { flex: none; font: 400 16px/24px var(--font-mono); color: var(--flow); }
/* Linked module (item link): the box is the link, as a row of the shared grammar is: the title ends in a flow arrow and
   turns flow on hover with the vignette, a focus ring round the frame. The frame and the + stay as they are. */
a.aq-option-modules__box { color: var(--ink); text-decoration: none; }
a.aq-option-modules__box .aq-option-modules__t > span:first-child::after { content: "\a0\2192"; content: "\a0\2192" / ""; color: var(--flow); }
a.aq-option-modules__box:hover .aq-option-modules__t { color: var(--flow); }
a.aq-option-modules__box:hover .aq-option-modules__vig { background-color: var(--flow); }
a.aq-option-modules__box:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-option-modules__vig { margin: var(--space-3) 0 var(--space-3) var(--space-3); }
.aq-option-modules__d { justify-self: stretch; margin: 0; padding: var(--space-3) var(--space-4); font: 400 14px/22px var(--font-sans); color: var(--ink-muted); }

/* Connector: a dashed hairline from the title to the plate edge, ending in a node on the plate. */
.aq-option-modules__wire {
  position: absolute; top: 0; height: calc(var(--space-12) + 1px); width: var(--space-12); overflow: visible; pointer-events: none;
}
.aq-option-modules__m--l .aq-option-modules__wire { left: 100%; }
.aq-option-modules__m--r .aq-option-modules__wire { right: 100%; }
.aq-option-modules__wire line { stroke: var(--line-strong); stroke-width: 1; stroke-dasharray: 4 3; }
.aq-option-modules__wire circle { fill: var(--flow); }

/* The base: the page's own equipment drawing in a Plate, as tall as the module columns. */
.aq-option-modules__base { display: flex; align-items: center; justify-content: center; min-width: 0; }
.aq-option-modules__fig { margin: 0; width: 100%; height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--space-4); }
.aq-option-modules__art { width: 100%; max-width: calc(var(--space-32) * 3); aspect-ratio: 1; background-color: var(--ink-muted); }
/* The base is the page icon, drawn at 96 px: an icon, not a picture, so it stays icon-sized in the centre of the frame */
.aq-option-modules__art--spot.aq-spot { width: var(--space-24); height: var(--space-24); background-color: var(--ink-muted); }
.aq-option-modules__label { display: flex; flex-direction: column; align-items: center; gap: var(--space-1); text-align: center; }
.aq-option-modules__label span:first-child { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-option-modules__label span + span { font: 400 14px/22px var(--font-sans); color: var(--ink); }

/* Fold: on desktop every module stays on the drawing (the layout needs both columns); the fold works on phones. */
.aq-fold:not(.is-open) .aq-option-modules__m.aq-fold-x { display: flex; }
.aq-fold:has(> .aq-option-modules) > .aq-fold__btn { display: none; }

@container (max-width: 860px) {
  .aq-option-modules, .aq-option-modules--bare { display: flex; flex-direction: column; }
  .aq-option-modules__base { order: -1; padding: var(--space-4) var(--space-4) var(--space-4) var(--space-8); justify-content: flex-start; }
  .aq-option-modules__fig { flex-direction: row; gap: var(--space-4); }
  .aq-option-modules__art { width: var(--space-24); flex: none; }
  .aq-option-modules__label { align-items: flex-start; text-align: left; min-width: 0; overflow-wrap: break-word; }
  .aq-option-modules__art--spot.aq-spot { width: var(--space-24); max-width: var(--space-24); flex: none; }

  /* The spine: one dashed line from the plate down past every module. */
  .aq-option-modules__list {
    justify-content: flex-start; gap: var(--space-4);
    margin-left: var(--space-3); padding: var(--space-4) 0 0 var(--space-4); border-left: 1px dashed var(--line-strong);
  }
  /* The second list joins the first without a gap of its own while all its modules are folded away. */
  .aq-option-modules__list--r { padding-top: 0; }
  .aq-fold.is-open .aq-option-modules__list--r, .aq-option-modules__list--r:has(> li:not(.aq-fold-x)) { padding-top: var(--space-4); }
  .aq-option-modules__m--l .aq-option-modules__cat { text-align: left; }
  .aq-option-modules__m--l .aq-option-modules__wire, .aq-option-modules__m--r .aq-option-modules__wire {
    left: auto; right: 100%; width: calc(var(--space-4) + 1px); height: calc(var(--space-8) + var(--space-2));
  }
  .aq-option-modules__m--l .aq-option-modules__wire { transform: scaleX(-1); }
  .aq-option-modules__box { grid-template-columns: auto minmax(0, 1fr); }
  .aq-option-modules__box--bare { grid-template-columns: minmax(0, 1fr); }
  .aq-option-modules__t { padding: var(--space-2) var(--space-3); font-size: 15px; line-height: 24px; }
  .aq-option-modules__vig.aq-spot { width: var(--space-16); height: var(--space-16); }
  .aq-option-modules__vig.aq-spot--icon { width: var(--space-12); height: var(--space-12); }
  .aq-option-modules__vig { margin: var(--space-2) 0 var(--space-2) var(--space-3); }
  .aq-option-modules__d { padding: var(--space-2) var(--space-3); font-size: 13px; line-height: 20px; }

  .aq-fold:not(.is-open) .aq-option-modules__m.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-option-modules) > .aq-fold__btn { display: flex; }
}

/* ---------- OptionTags: options as physical tags laid out on a limestone table ---------- */
/* Three columns: the label card and the tags in the first two, folders on a navy strip that runs off the right edge. */
.aq-option-tags-sec { overflow: hidden; }
.aq-option-tags { position: relative; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); grid-auto-flow: row dense;
  column-gap: var(--space-12); row-gap: var(--space-16); align-items: start; padding-block: var(--space-4); }
.aq-option-tags::before { content: ""; position: absolute; z-index: 0; top: calc(-1 * var(--space-32)); bottom: calc(-1 * var(--space-32));
  left: calc(200% / 3 + var(--space-4)); right: calc(-1 * var(--space-32) * 4); background: var(--navy); }
.aq-option-tags__list { display: contents; list-style: none; }

/* Label card: the section heading on a printed label */
.aq-option-tags__label { position: relative; z-index: 1; grid-column: 1; grid-row: 1; display: flex; flex-direction: column; gap: var(--space-6);
  padding: var(--space-6); background: var(--surface-raised); color: var(--ink); border: 1px solid var(--line-strong); transform: rotate(-1deg); }
.aq-option-tags__label .aq-h1 { font-size: 34px; line-height: 40px; }
.aq-option-tags__base { margin: 0; display: flex; align-items: center; gap: var(--space-3); padding-top: var(--space-3); border-top: 1px solid var(--line);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-option-tags__base .aq-option-tags__base-ic { width: var(--space-8); height: var(--space-8); }

/* A tag: string from the eyelet, kraft-free paper (surface-raised), tilted by --r; hover picks it up */
.aq-option-tags__item { grid-column: var(--c, auto); grid-row: var(--rw, auto); position: relative; z-index: 1; transform: rotate(var(--r, 0deg)); transition: transform 350ms cubic-bezier(0.2, 0, 0, 1); }
.aq-option-tags__item:hover, .aq-option-tags__item:focus-within { transform: rotate(0deg) translateY(calc(-1 * var(--space-2))); z-index: 2; }
.aq-option-tags__tag { position: relative; }
.aq-option-tags__body { position: relative; display: flex; flex-direction: column; gap: var(--space-3); min-height: calc(var(--space-32) + var(--space-24));
  padding: var(--space-6) var(--space-6) var(--space-4) var(--space-16); background: var(--surface-raised); color: var(--ink); text-decoration: none;
  border: 1px solid var(--line-strong);
  clip-path: polygon(var(--space-8) 0, 100% 0, 100% 100%, var(--space-8) 100%, 0 calc(100% - var(--space-8)), 0 var(--space-8)); }
.aq-option-tags__eyelet { position: absolute; z-index: 2; left: var(--space-6); top: 50%; width: var(--space-4); height: var(--space-4); transform: translate(-50%, -50%);
  border-radius: var(--radius-pill); background: var(--limestone); border: 3px solid var(--line-strong); }
.aq-option-tags__string { position: absolute; z-index: 0; right: calc(100% - var(--space-6)); top: 50%; width: var(--space-24); height: var(--space-16); transform: translateY(-40%); overflow: visible; pointer-events: none; }
.aq-option-tags__string path { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1.5; vector-effect: non-scaling-stroke; }

.aq-option-tags__t { margin: 0; font: 500 22px/28px var(--font-sans); letter-spacing: -0.01em; }
.aq-option-tags__d { margin: 0; font: 400 14px/22px var(--font-sans); color: var(--ink-muted); }
.aq-option-tags__foot { margin-top: auto; display: flex; align-items: flex-end; justify-content: space-between; }
.aq-option-tags__no { font: 400 20px/1 var(--font-mono); color: var(--ink-muted); font-variant-numeric: tabular-nums; }
.aq-option-tags__stamp { display: grid; place-items: center; width: var(--space-12); height: var(--space-12); border: 1.5px solid var(--flow); border-radius: var(--radius-pill); transform: rotate(-12deg); }
.aq-option-tags__glyph.aq-spot.aq-spot--icon { width: var(--space-8); height: var(--space-8); background-color: var(--flow); }

/* Round tag: string from the top */
.aq-option-tags__item--round { justify-self: center; width: min(100%, calc(var(--space-32) * 2 + var(--space-16))); margin-top: var(--space-8); }
.aq-option-tags__item--round .aq-option-tags__body { aspect-ratio: 1; border-radius: var(--radius-pill); clip-path: none; align-items: center; justify-content: center; text-align: center;
  padding: var(--space-12) var(--space-8) var(--space-8); }
.aq-option-tags__item--round .aq-option-tags__foot { margin-top: var(--space-2); flex-direction: column; align-items: center; gap: var(--space-2); }
.aq-option-tags__item--round .aq-option-tags__eyelet { left: 50%; top: var(--space-6); }
.aq-option-tags__item--round .aq-option-tags__string { right: auto; left: 50%; top: auto; bottom: calc(100% - var(--space-6)); width: var(--space-8); height: var(--space-16); transform: translateX(-50%); }

/* Folder: a manila folder with a tab, on the navy strip */
.aq-option-tags__item--folder { margin-top: var(--space-6); }
.aq-option-tags__item--folder .aq-option-tags__body { clip-path: none; padding: var(--space-6); background: var(--limestone); color: var(--on-limestone); border-color: var(--limestone); }
.aq-option-tags__item--folder .aq-option-tags__d, .aq-option-tags__item--folder .aq-option-tags__no { color: var(--on-limestone-muted); }
.aq-option-tags__item--folder .aq-option-tags__tag::before { content: ""; position: absolute; left: 0; bottom: 100%; width: 40%; height: var(--space-6); background: var(--limestone);
  clip-path: polygon(0 0, 85% 0, 100% 100%, 0 100%); }
.aq-option-tags__item--folder .aq-option-tags__tag::after { content: ""; position: absolute; left: var(--space-3); right: calc(-1 * var(--space-2)); top: calc(-1 * var(--space-2)); bottom: var(--space-3);
  z-index: -1; background: color-mix(in srgb, var(--limestone) 70%, var(--navy)); }

.aq-option-tags__body:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }

/* Vials: decoration between the tags */
.aq-option-tags__vial { position: absolute; z-index: 0; width: var(--space-8); height: auto; pointer-events: none; overflow: visible; }
.aq-option-tags__vial path, .aq-option-tags__vial rect { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1.5; vector-effect: non-scaling-stroke; stroke-linejoin: round; }
.aq-option-tags__vial .aq-option-tags__cap { fill: var(--on-limestone-muted); }
.aq-option-tags__vial .aq-option-tags__liquid { stroke: var(--flow); }
.aq-option-tags__vial .aq-option-tags__hair { stroke-width: 1; }
.aq-option-tags__vial--a { left: 31%; top: 50%; transform: rotate(-24deg); }
.aq-option-tags__vial--b { left: 2%; bottom: -4%; transform: rotate(-78deg); }

@container (max-width: 1100px) {
  .aq-option-tags { column-gap: var(--space-8); }
  .aq-option-tags__body { padding-left: var(--space-12); }
  .aq-option-tags__t { font-size: 19px; line-height: 26px; }
}

/* Phones: one column of tags, alternating a slight tilt; folders on the limestone ground; the fold back on */
@container (max-width: 860px) {
  .aq-option-tags { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-8); padding-inline: var(--space-2); }
  .aq-option-tags::before, .aq-option-tags__vial { display: none; }
  .aq-option-tags__item, .aq-option-tags__item--folder { grid-column: 1; grid-row: auto; margin-top: 0; transform: rotate(calc(var(--r, 0deg) * 0.4)); }
  .aq-option-tags__item--round { width: 86%; }
  .aq-option-tags__item--folder { margin-top: var(--space-6); }
  .aq-option-tags__item--folder .aq-option-tags__body { border-color: var(--line-strong); background: var(--surface-raised); color: var(--ink); }
  .aq-option-tags__item--folder .aq-option-tags__tag::before { background: var(--surface-raised); border: 1px solid var(--line-strong); border-bottom: 0; }
  .aq-option-tags__item--folder .aq-option-tags__tag::after { display: none; }
  .aq-option-tags__label .aq-h1 { font-size: 30px; line-height: 36px; }
  .aq-option-tags__body { min-height: 0; padding: var(--space-4) var(--space-4) var(--space-4) var(--space-12); }
  .aq-option-tags__string { width: var(--space-8); }
}
.aq-fold:not(.is-open) .aq-option-tags__item.aq-fold-x { display: block; }
.aq-fold:has(> .aq-option-tags) > .aq-fold__btn { display: none; }
@container (max-width: 860px) {
  .aq-fold:not(.is-open) .aq-option-tags__item.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-option-tags) > .aq-fold__btn { display: flex; }
}
.aq-option-tags__vial .aq-option-tags__lab { stroke-width: 1; }

/* ---------- OptionTaps: options as dashed parts on dashed tees off the standard train, one limestone drawing sheet ---------- */
/* The sheet: a navy hairline frame, the heading at display scale over the drawing, the notes in a narrow column right of
   a vertical rule, the title block at its foot. */
.aq-option-taps { display: grid; grid-template-columns: minmax(0, 3fr) minmax(0, 1fr); border: 1px solid var(--on-limestone); outline: 1px solid var(--on-limestone); outline-offset: var(--space-2); margin: var(--space-2); }
.aq-option-taps__main { display: flex; flex-direction: column; gap: var(--space-6); padding: var(--space-12) var(--space-8) var(--space-8); min-width: 0; }
.aq-option-taps__main .aq-sec-head .aq-eyebrow { color: var(--on-limestone-muted); }
.aq-option-taps__main .aq-sec-head .aq-h1 { font: 300 120px/112px var(--font-sans); letter-spacing: -0.045em; color: var(--on-limestone); max-width: none; }
.aq-option-taps__side { display: flex; flex-direction: column; border-left: 1px solid var(--on-limestone); min-width: 0; }

/* the drawing: a camera that frames one part when a note is chosen */
.aq-option-taps__fig { position: relative; overflow: hidden; margin-top: auto; }
.aq-option-taps__cam { position: relative; transform-origin: 0 0; transition: transform 600ms cubic-bezier(0.2, 0, 0, 1); }
.aq-option-taps__svg { display: block; width: 100%; height: auto; }
/* optional: every line of the part and its tee dashed; lit (note hovered or chosen) in flow */
.aq-option-taps__svg .aq-option-taps__ghost .aq-iso__eq, .aq-option-taps__svg .aq-option-taps__ghost .aq-iso__ln, .aq-option-taps__svg .aq-option-taps__ghost .aq-iso__thin,
.aq-option-taps__svg .aq-option-taps__tee .aq-iso__pipe-wall { stroke-dasharray: 4 3; }
.aq-option-taps__svg .aq-option-taps__ghost .aq-iso__acc, .aq-option-taps__svg .aq-option-taps__ghost .aq-iso__trace { stroke-dasharray: 2 3; }
.aq-option-taps__svg [data-iso-id] { transition: opacity 300ms cubic-bezier(0.2, 0, 0, 1); }
.aq-option-taps.is-focus .aq-option-taps__svg [data-iso-id]:not(.is-lit) { opacity: 0.35; }
.aq-option-taps__label, .aq-option-taps__mark { position: absolute; transform: translate(-50%, -100%); white-space: nowrap; pointer-events: none; }
.aq-option-taps__label { font: 500 12px/16px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--on-limestone-muted); }
.aq-option-taps__mark { display: grid; place-items: center; min-width: var(--space-8); height: var(--space-8); padding: 0 var(--space-1);
  border: 1px solid var(--on-limestone); background: var(--limestone); font: 500 13px/1 var(--font-mono); color: var(--on-limestone); transition: background-color 200ms cubic-bezier(0.2, 0, 0, 1), color 200ms cubic-bezier(0.2, 0, 0, 1); }
.aq-option-taps__mark.is-on { background: var(--navy); color: var(--on-navy); border-color: var(--navy); }

/* Notes: numbered like the pins, hairlines between */
.aq-option-taps__side .aq-fold { flex: 1; }
.aq-option-taps__cards { list-style: none; margin: 0; padding: var(--space-8) 0 0; display: flex; flex-direction: column; }
.aq-option-taps__card { display: flex; flex-direction: column; gap: var(--space-1); padding: var(--space-4) var(--space-6); border-bottom: 1px solid color-mix(in srgb, var(--on-limestone) 22%, transparent); color: var(--on-limestone); }
.aq-option-taps__no { margin: 0; }
.aq-option-taps__pin { display: inline-grid; place-items: center; min-width: var(--space-12); min-height: var(--space-12); margin: calc(-1 * var(--space-2)) 0 0 calc(-1 * var(--space-2)); padding: 0;
  border: 0; background: transparent; color: var(--on-limestone); font: 400 15px/1 var(--font-mono); cursor: pointer; }
.aq-option-taps__pin::before { content: ""; position: absolute; width: var(--space-8); height: var(--space-8); border: 1px solid var(--on-limestone); box-sizing: border-box; transition: background-color 150ms cubic-bezier(0.2, 0, 0, 1); z-index: -1; }
.aq-option-taps__pin { position: relative; z-index: 0; }
.aq-option-taps__pin:hover::before { background: color-mix(in srgb, var(--on-limestone) 10%, transparent); }
.aq-option-taps__pin[aria-pressed="true"] { color: var(--on-navy); }
.aq-option-taps__pin[aria-pressed="true"]::before { background: var(--navy); border-color: var(--navy); }
.aq-option-taps__pin:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-option-taps__t { margin: 0; font: 400 17px/23px var(--font-sans); }
.aq-option-taps__d { margin: 0; font: 400 14px/21px var(--font-sans); color: var(--on-limestone-muted); }
.aq-option-taps__card.is-on .aq-option-taps__t { text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 4px; }
.aq-option-taps__mini { display: none; }
.aq-fold:not(.is-open) .aq-option-taps__card.aq-fold-x { display: flex; }
.aq-fold:has(> .aq-option-taps__cards) > .aq-fold__btn { display: none; }

/* title block */
.aq-option-taps__block { display: grid; grid-template-columns: minmax(0, 1fr); margin-top: auto; border-top: 1px solid var(--on-limestone); }
.aq-option-taps__block span { padding: var(--space-2) var(--space-4); border-top: 1px solid color-mix(in srgb, var(--on-limestone) 22%, transparent); font: 400 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-limestone-muted); }
.aq-option-taps__block span:first-child { border-top: 0; color: var(--on-limestone); }

@container (max-width: 1100px) {
  .aq-option-taps__main .aq-sec-head .aq-h1 { font-size: 88px; line-height: 88px; }
  .aq-option-taps__label { display: none; }
  .aq-option-taps__card { padding: var(--space-3) var(--space-4); }
}
@container (max-width: 860px) {
  .aq-option-taps { grid-template-columns: minmax(0, 1fr); margin: var(--space-1); outline-offset: var(--space-1); }
  .aq-option-taps__main { padding: var(--space-8) var(--space-4) var(--space-4); }
  .aq-option-taps__main .aq-sec-head .aq-h1 { font-size: 56px; line-height: 56px; }
  .aq-option-taps__side { border-left: 0; border-top: 1px solid var(--on-limestone); }
  .aq-option-taps__label { display: none; }
  /* the pins stay on the small drawing (they pair each dashed part with its note), at a phone size */
  .aq-option-taps__mark { min-width: var(--space-6); height: var(--space-6); font-size: 12px; }
  .aq-option-taps__fig { padding-top: var(--space-6); }
  .aq-option-taps__cards { padding-top: var(--space-2); }
  .aq-option-taps__card { display: grid; grid-template-columns: 72px minmax(0, 1fr); column-gap: var(--space-4); row-gap: var(--space-1); align-items: start; padding: var(--space-4); }
  .aq-option-taps__no { grid-column: 1 / -1; }
  .aq-option-taps__mini { display: block; grid-row: 2 / 4; width: 72px; height: auto; background: transparent; }
  .aq-fold:not(.is-open) .aq-option-taps__card.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-option-taps__cards) > .aq-fold__btn { display: flex; }
}
@media (prefers-reduced-motion: reduce) {
  .aq-option-taps__cam, .aq-option-taps__svg [data-iso-id] { transition: none; }
}

/* ---------- PackMatrix: one pack per client and period, drawn as a matrix of packs with one pulled out and opened ---------- */
.aq-pack-matrix-sec { position: relative; }
.aq-pack-matrix { display: grid; grid-template-columns: auto minmax(0, 1fr); column-gap: var(--space-16); align-items: center; margin-top: var(--space-8); }

/* The matrix: identical packs on a grid, the axis words, the pulled pack in navy, a leader out to the sheet */
.aq-pack-matrix__grid { --s: var(--space-16); --g: var(--space-4); display: grid; grid-template-columns: auto auto; grid-template-rows: auto auto; column-gap: var(--space-3); row-gap: var(--space-3); }
.aq-pack-matrix__ax { font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-pack-matrix__ax--y { grid-column: 1; grid-row: 1; writing-mode: vertical-rl; transform: rotate(180deg); align-self: center; padding-block: var(--space-2);
  border-right: 1px solid var(--line-strong); padding-right: var(--space-1); }
.aq-pack-matrix__ax--x { grid-column: 2; grid-row: 2; padding-top: var(--space-2); border-top: 1px solid var(--line-strong); }
.aq-pack-matrix__ax--x::after, .aq-pack-matrix__ax--y::after { content: " →"; }
.aq-pack-matrix__cells { grid-column: 2; grid-row: 1; position: relative; display: grid; grid-template-columns: repeat(var(--cols, 4), var(--s, 48px)); grid-template-rows: repeat(var(--rows, 3), var(--s, 48px)); gap: var(--g, 12px); }
.aq-pack-matrix__pk { grid-column: var(--c, 1); grid-row: var(--r, 1); position: relative; border: 1.5px solid var(--line-strong); background: var(--surface-raised); margin-top: var(--space-2); }
.aq-pack-matrix__pk::before { content: ""; position: absolute; left: -1.5px; top: calc(var(--space-2) * -1 - 1.5px); width: 45%; height: var(--space-2); border: 1.5px solid var(--line-strong); border-bottom: 0; background: inherit; }
.aq-pack-matrix__pk::after { content: ""; position: absolute; left: 20%; right: 20%; top: 40%; height: 0; border-top: 1px solid var(--line); box-sizing: border-box; }
.aq-pack-matrix__pk.is-open { background: var(--navy); border-color: var(--navy); transform: translate(var(--space-2), calc(var(--space-2) * -1)); z-index: 1; }
.aq-pack-matrix__pk.is-open::before { border-color: var(--navy); }
.aq-pack-matrix__pk.is-open::after { border-top-color: color-mix(in srgb, var(--on-navy) 50%, transparent); }
.aq-pack-matrix__lead { grid-column: 2; grid-row: 1; position: relative; align-self: start; height: 0; pointer-events: none;
  margin-top: calc((var(--ar, 2) - 1) * (var(--s, 48px) + var(--g, 12px)) + var(--s, 48px) / 2 + var(--space-1)); margin-left: calc(var(--ac, 3) * var(--s, 48px) + (var(--ac, 3) - 1) * var(--g, 12px) + var(--space-2));
  margin-right: calc(var(--space-16) * -1); border-top: 1.5px solid var(--action); transform-origin: 0 50%; }
.aq-pack-matrix__lead::after { content: ""; position: absolute; right: 0; top: calc(var(--space-2) * -0.5 - 0.75px); width: var(--space-2); height: var(--space-2); background: var(--action); }

/* The open pack: a sheet with a navy strip, documents in two columns */
.aq-pack-matrix__sheet { min-width: 0; background: var(--surface-raised); border: 1px solid var(--line-strong); }
.aq-pack-matrix__strip { display: flex; justify-content: space-between; gap: var(--space-4); padding: var(--space-2) var(--space-6); background: var(--navy); color: var(--on-navy-muted);
  font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; }
.aq-pack-matrix__sheet > .aq-fold, .aq-pack-matrix__docs { padding: 0 var(--space-6); }
.aq-pack-matrix__sheet > .aq-fold > .aq-pack-matrix__docs { padding: 0; }
.aq-fold:not(.is-open) .aq-pack-matrix__doc.aq-fold-x { display: grid; }
.aq-pack-matrix__sheet .aq-fold__btn { display: none; }
.aq-pack-matrix__docs { list-style: none; margin: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: var(--space-8); }
.aq-pack-matrix__doc { display: grid; grid-template-columns: auto minmax(0, 1fr); column-gap: var(--space-4); row-gap: var(--space-1); align-content: start; padding: var(--space-6) 0;
  border-top: 1px solid var(--line); }
.aq-pack-matrix__doc:nth-child(-n+2) { border-top: 0; }
.aq-pack-matrix__n { grid-row: 1 / span 2; font: 300 48px/44px var(--font-sans); letter-spacing: -0.05em; color: var(--ink-subtle); font-variant-numeric: tabular-nums; }
.aq-pack-matrix__t { margin: 0; font: 400 19px/26px var(--font-sans); letter-spacing: -0.01em; color: var(--ink); }
.aq-pack-matrix__t a { color: inherit; }
.aq-pack-matrix__d { margin: 0; font: 400 14px/21px var(--font-sans); color: var(--ink-muted); }
.aq-pack-matrix__doc.is-key { position: relative; }
.aq-pack-matrix__doc.is-key:nth-child(-n+2)::before { display: none; }
.aq-pack-matrix__doc.is-key::before { content: ""; position: absolute; left: 0; top: -1px; width: var(--space-12); height: 2px; background: var(--flow); }
.aq-pack-matrix__doc.is-key .aq-pack-matrix__n { color: var(--flow); }
.aq-pack-matrix__doc:hover .aq-pack-matrix__n { color: var(--ink); }

@container (max-width: 1100px) {
  .aq-pack-matrix { column-gap: var(--space-8); }
  .aq-pack-matrix__grid { --s: var(--space-8); --g: var(--space-2); }
  .aq-pack-matrix__lead { margin-right: calc(var(--space-8) * -1); }
  .aq-pack-matrix__docs { grid-template-columns: minmax(0, 1fr); }
  .aq-pack-matrix__doc:nth-child(2) { border-top: 1px solid var(--line); }
  .aq-pack-matrix__doc.is-key:nth-child(2)::before { display: block; }
}

/* Phones: the matrix small above the sheet, its leader dropping into it; the fold comes back */
@container (max-width: 860px) {
  .aq-pack-matrix { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-6); margin-top: var(--space-4); }
  .aq-pack-matrix__grid { --s: var(--space-8); --g: var(--space-2); justify-self: start; }
  .aq-pack-matrix__lead { display: none; }
  .aq-pack-matrix__sheet > .aq-fold, .aq-pack-matrix__docs { padding: 0 var(--space-4); }
  .aq-pack-matrix__strip { padding-inline: var(--space-4); }
  .aq-pack-matrix__n { font-size: 36px; line-height: 36px; }
  .aq-pack-matrix__t { font-size: 17px; line-height: 24px; }
  .aq-pack-matrix__doc { padding: var(--space-4) 0; }
  .aq-fold:not(.is-open) .aq-pack-matrix__doc.aq-fold-x { display: none; }
  .aq-pack-matrix__sheet .aq-fold__btn { display: flex; }
}

/* ---------- ParamTiles: design parameters as a Swiss grid of numbered tiles, one cell a blueprint of the skid ---------- */
/* Four columns on a navy field with hairline gutters: limestone tiles, the lead tile wide and navy, the blueprint two by
   two. An empty cell left by the count shows the navy field (the concept's checkerboard). */
.aq-param-tiles { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-auto-flow: row dense; gap: 1px;
  background: var(--navy); border: 1px solid var(--navy); margin-top: var(--space-4); }
.aq-param-tiles__list { display: contents; list-style: none; }
.aq-param-tiles__fig { grid-column: 3 / span 2; grid-row: 1 / span 2; background: var(--navy); display: grid; place-items: center; padding: var(--space-6); overflow: hidden; }
.aq-param-tiles__svg { width: 100%; max-height: 100%; }
.aq-param-tiles__svg .aq-iso__flow { stroke: var(--on-navy); }

.aq-param-tiles__tile { position: relative; display: flex; flex-direction: column; gap: var(--space-4); min-width: 0; min-height: calc(var(--space-32) * 2);
  padding: var(--space-6); background: var(--limestone); color: var(--on-limestone); transition: background-color 300ms cubic-bezier(0.2, 0, 0, 1); }
.aq-fold:not(.is-open) .aq-param-tiles__tile.aq-fold-x { display: flex; }
.aq-fold:has(> .aq-param-tiles) > .aq-fold__btn { display: none; }
.aq-param-tiles__tile.is-lead { grid-column: 1 / span 2; background: var(--navy); color: var(--on-navy); }

.aq-param-tiles__head { display: flex; align-items: flex-start; gap: var(--space-2); }
.aq-param-tiles__n { display: block; overflow: hidden; flex: none; font: 300 64px/60px var(--font-sans); letter-spacing: -0.04em; font-variant-numeric: tabular-nums; }
.aq-param-tiles__n > span { display: block; }
.aq-param-tiles__slash { flex: none; width: 1px; height: var(--space-12); margin-inline: var(--space-1) var(--space-2); background: currentColor; transform: skewX(-18deg); opacity: 0.6; }
.aq-param-tiles__p { margin: 0; padding-top: var(--space-1); font: 500 12px/16px var(--font-sans); letter-spacing: 0.08em; text-transform: uppercase; }
/* The value in Geist Light (mono stays for the placeholders and figures inside it) */
.aq-param-tiles__v { margin: 0; font: 300 22px/30px var(--font-sans); letter-spacing: -0.01em; overflow-wrap: anywhere; }
/* A count that leaves one cell empty in the last row: the last tile takes it, so the grid closes square */
.aq-param-tiles__tile:last-child:nth-child(4n+2):not(.is-lead) { grid-column: span 2; }
.aq-param-tiles__tile.is-lead .aq-param-tiles__v { font-size: 32px; line-height: 42px; font-weight: 300; }
.aq-param-tiles__m { margin: auto 0 0; padding-top: var(--space-3); border-top: 1px solid color-mix(in srgb, currentColor 30%, transparent);
  display: flex; flex-direction: column; gap: var(--space-2); font: 400 13px/20px var(--font-sans); color: var(--on-limestone-muted); }
.aq-param-tiles__tile.is-lead .aq-param-tiles__m { color: var(--on-navy-muted); }
.aq-param-tiles__link { align-self: flex-start; display: inline-flex; align-items: center; min-height: var(--space-6); color: var(--flow); text-decoration: none; font: 500 13px/20px var(--font-sans); }
.aq-param-tiles__link::after { content: "→"; margin-left: var(--space-1); transition: transform 200ms; }
.aq-param-tiles__link:hover::after { transform: translateX(var(--space-1)); }
.aq-param-tiles__link:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }

/* Hover: the tile's number turns flow */
.aq-param-tiles__tile:hover .aq-param-tiles__n { color: var(--flow); }
.aq-param-tiles__tile.is-lead:hover .aq-param-tiles__n { color: var(--limestone); }
.aq-param-tiles__n { transition: color 300ms; }

@container (max-width: 1100px) {
  .aq-param-tiles { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .aq-param-tiles__fig { grid-column: 2 / span 2; }
  .aq-param-tiles__tile:last-child:nth-child(4n+2):not(.is-lead) { grid-column: auto; }
  .aq-param-tiles__n { font-size: 52px; line-height: 50px; }
}

/* Phones: one column, the lead tile first, the blueprint after it, the fold back on */
@container (max-width: 860px) {
  .aq-param-tiles { grid-template-columns: minmax(0, 1fr); }
  .aq-param-tiles__tile.is-lead { grid-column: auto; order: -2; }
  .aq-param-tiles__fig { grid-column: auto; grid-row: auto; order: -1; padding: var(--space-4); }
  .aq-param-tiles__tile { min-height: 0; padding: var(--space-4) var(--space-4) var(--space-6); }
  .aq-fold:not(.is-open) .aq-param-tiles__tile.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-param-tiles) > .aq-fold__btn { display: flex; }
  .aq-param-tiles__n { font-size: 48px; line-height: 46px; }
  .aq-param-tiles__tile.is-lead .aq-param-tiles__v { font-size: 22px; line-height: 30px; }
  .aq-param-tiles__v { font-size: 18px; line-height: 26px; }
}

/* ---------- ParameterCallouts ---------- */
/* Design parameters called out on the page's equipment drawing. Desktop: a 2:1 figure (viewBox 200 x 100 for the
   leaders): label columns 0-25 % and 75-100 %, the drawing a centred square between them on the plain section ground.
   Labels hang from a flow rule (the bottom label of a side stands on one); flow leaders run from the rule's inner end
   to a numbered pin on the drawing. Any rows that are not called out follow as a SpecTable. */
.aq-parameter-callouts { display: flex; flex-direction: column; gap: var(--space-8); }
.aq-parameter-callouts__fig { position: relative; aspect-ratio: 2 / 1; }
.aq-parameter-callouts__art { position: absolute; top: 0; bottom: 0; left: 25%; right: 25%; }
.aq-parameter-callouts__art .aq-illustration { position: absolute; inset: 0; width: 100%; height: 100%; max-width: none; aspect-ratio: auto; margin: 0; }
.aq-parameter-callouts__pins { position: absolute; inset: 0; }
.aq-parameter-callouts__pin { position: absolute; transform: translate(-50%, -50%); padding: 0 var(--space-1); border: 1px solid var(--flow); border-radius: var(--radius-sm); background: var(--surface); font: 400 12px/18px var(--font-mono); font-variant-numeric: tabular-nums; color: var(--ink); }
.aq-parameter-callouts__leaders { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; pointer-events: none; }
.aq-parameter-callouts__leaders line { stroke: var(--flow); stroke-width: 1; vector-effect: non-scaling-stroke; }
.aq-parameter-callouts__list { list-style: none; margin: 0; padding: 0; }
.aq-parameter-callouts__item { position: absolute; width: 25%; display: grid; grid-template-columns: auto minmax(0, 1fr); column-gap: var(--space-3); row-gap: var(--space-1); align-content: start; padding-top: var(--space-2); border-top: 1px solid var(--flow); }
.aq-parameter-callouts__item.is-l { left: 0; padding-right: var(--space-4); }
.aq-parameter-callouts__item.is-r { right: 0; padding-left: var(--space-4); }
.aq-parameter-callouts__item.is-up { border-top: 0; padding-top: 0; padding-bottom: var(--space-2); border-bottom: 1px solid var(--flow); }
.aq-parameter-callouts__item > .aq-index { grid-row: 1 / span 3; }
.aq-parameter-callouts__p { grid-column: 2; margin: 0; font: 500 14px/20px var(--font-sans); color: var(--ink); }
.aq-parameter-callouts__v { grid-column: 2; margin: 0; font: 400 16px/22px var(--font-mono); letter-spacing: -0.01em; font-variant-numeric: tabular-nums; color: var(--ink); overflow-wrap: break-word; }
.aq-parameter-callouts__v .aq-ph { font-size: inherit; }
.aq-parameter-callouts__m { grid-column: 2; margin: 0; font: 400 13px/18px var(--font-sans); color: var(--ink-muted); }

@container (max-width: 860px) {
  /* Phone: the drawing with its numbered pins on top, the numbered list below on hairlines */
  .aq-parameter-callouts { gap: var(--space-6); }
  .aq-parameter-callouts__fig { aspect-ratio: auto; }
  .aq-parameter-callouts__leaders { display: none; }
  /* the drawing runs edge to edge (into the section gutters) as a full-width square, pins at a readable size */
  .aq-parameter-callouts__art { position: relative; inset: auto; width: calc(100% + 2 * var(--space-4)); aspect-ratio: 1; margin-inline: calc(-1 * var(--space-4)); }
  .aq-parameter-callouts__pin, .aq-parameter-callouts__item > .aq-index { min-width: var(--space-8); padding: var(--space-1) var(--space-2); box-sizing: border-box; text-align: center; border: 1px solid var(--flow); border-radius: var(--radius-sm); background: var(--surface); font: 400 13px/16px var(--font-mono); font-variant-numeric: tabular-nums; color: var(--ink); }
  .aq-parameter-callouts__list { margin-top: var(--space-4); border-bottom: 1px solid var(--line); }
  /* List rows as SpecTable phone rows: the parameter, then the value and " · " basis in one run */
  .aq-parameter-callouts__item, .aq-parameter-callouts__item.is-l, .aq-parameter-callouts__item.is-r, .aq-parameter-callouts__item.is-up { position: relative; display: block; width: auto; padding: var(--space-4) 0 var(--space-4) var(--space-12); border: 0; border-top: 1px solid var(--line); }
  .aq-parameter-callouts__item > .aq-index { position: absolute; left: 0; top: var(--space-4); }
  .aq-parameter-callouts__p { margin-bottom: var(--space-1); }
  .aq-parameter-callouts__v, .aq-parameter-callouts__m { display: inline; }
  .aq-parameter-callouts__m::before { content: "\a0\b7\a0"; content: "\a0\b7\a0" / ""; color: var(--ink-subtle); }
  .aq-parameter-callouts__p { font: 400 16px/24px var(--font-sans); }
  .aq-parameter-callouts__v { font-size: 14px; line-height: 22px; letter-spacing: 0; }
  .aq-parameter-callouts__m { font-size: 12px; line-height: 18px; }
}

/* ---------- PdfAnatomy: delivery terms as a figure plate of the delivered document (look "pdf-anatomy"). The plate is
   line art on surface-raised (line-strong frame, line text bars, flow for what the callouts point at); callouts sit in
   the plate's left column on hairline leaders. The other rows stand beside it: choices as signature lines, a single
   value set large in light type. ---------- */
.aq-pdf-anatomy-sec { position: relative; }
.aq-pdf-anatomy__front, .aq-pdf-anatomy__stack, .aq-pdf-anatomy__search { transform-box: fill-box; }
.aq-pdf-anatomy__go { margin: var(--space-4) 0 0; }
.aq-pdf-anatomy { display: grid; grid-template-columns: minmax(0, 8fr) minmax(0, 4fr); column-gap: var(--space-12); align-items: start; }
.aq-pdf-anatomy__plate { margin: 0; }
.aq-pdf-anatomy__cap { display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: baseline; column-gap: var(--space-4); margin-bottom: var(--space-4); }
.aq-pdf-anatomy__cap .aq-pdf-anatomy__k { grid-column: 1 / -1; }
.aq-pdf-anatomy__k { margin: 0 0 var(--space-2); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-pdf-anatomy__h { margin: 0; font: 300 28px/34px var(--font-sans); letter-spacing: -0.02em; color: var(--ink); }
.aq-pdf-anatomy__note { margin: 0; font: 400 14px/22px var(--font-sans); color: var(--ink-muted); }

/* the plate */
.aq-pdf-anatomy__draw { position: relative; }
.aq-pdf-anatomy__crop { position: relative; }
.aq-pdf-anatomy__art { position: relative; }
.aq-pdf-anatomy__svg { display: block; width: 100%; height: auto; }
.aq-pdf-anatomy__win { fill: var(--surface-raised); stroke: var(--line-strong); stroke-width: 1.5; }
.aq-pdf-anatomy__rule { fill: none; stroke: var(--line); stroke-width: 1; }
.aq-pdf-anatomy__ln { fill: none; stroke: var(--line-strong); stroke-width: 1.5; stroke-linecap: round; }
.aq-pdf-anatomy__txt { fill: none; stroke: var(--line); stroke-width: 4; }
.aq-pdf-anatomy__txtf { fill: none; stroke: var(--flow); stroke-width: 4; }
.aq-pdf-anatomy__tri { fill: none; stroke: var(--ink-subtle); stroke-width: 1; }
.aq-pdf-anatomy__field { fill: var(--surface); stroke: var(--flow); stroke-width: 1.5; }
.aq-pdf-anatomy__cur { fill: var(--flow-tint); }
.aq-pdf-anatomy__page { fill: var(--surface-raised); stroke: var(--line-strong); stroke-width: 1; }
.aq-pdf-anatomy__logo { fill: var(--ink); }
.aq-pdf-anatomy__hit { fill: var(--flow-tint); stroke: var(--flow); stroke-width: 1.5; }
.aq-pdf-anatomy__box { fill: none; stroke: var(--line-strong); stroke-width: 1; }
.aq-pdf-anatomy__box.is-on { stroke: var(--flow); stroke-width: 1.5; }
.aq-pdf-anatomy__leader { fill: none; stroke: var(--ink-muted); stroke-width: 1; }
.aq-pdf-anatomy__dot { fill: var(--flow); }
.aq-pdf-anatomy__lead.is-on .aq-pdf-anatomy__leader { stroke: var(--flow); stroke-width: 1.5; }

/* callouts: in the plate's left column, each at its leader's height */
.aq-pdf-anatomy__calls { list-style: none; margin: 0; padding: 0; position: absolute; left: 0; top: 0; bottom: 0; width: 21.5%; }
.aq-pdf-anatomy__call { position: absolute; left: 0; right: 0; transform: translateY(-50%); display: flex; flex-direction: column; align-items: flex-end; text-align: right; gap: var(--space-1); padding-right: var(--space-2); font: 400 16px/22px var(--font-sans); color: var(--ink); text-wrap: balance; cursor: default; }
.aq-pdf-anatomy__cn { font: 500 12px/16px var(--font-mono); color: var(--flow); }
.aq-pdf-anatomy__pin { display: none; }

/* the other rows */
.aq-pdf-anatomy__side { display: flex; flex-direction: column; gap: var(--space-12); padding-top: var(--space-12); }
.aq-pdf-anatomy__row { border-top: 1px solid var(--line-strong); padding-top: var(--space-4); }
.aq-pdf-anatomy__row > .aq-pdf-anatomy__h { margin-bottom: var(--space-6); }
.aq-pdf-anatomy__sigs { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--space-6); }
.aq-pdf-anatomy__sigs li { display: flex; flex-direction: column; gap: var(--space-2); }
.aq-pdf-anatomy__sl { display: block; height: var(--space-6); border-bottom: 1.5px solid var(--line-strong); position: relative; }
.aq-pdf-anatomy__sl::before { content: "×"; position: absolute; left: 0; bottom: var(--space-1); font: 400 14px/1 var(--font-mono); color: var(--ink-subtle); }
.aq-pdf-anatomy__sv { font: 400 15px/22px var(--font-sans); color: var(--ink); }
.aq-pdf-anatomy__or { font: 500 12px/16px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-pdf-anatomy__big { margin: 0; font: 300 30px/38px var(--font-sans); letter-spacing: -0.02em; color: var(--ink); text-wrap: balance; }
.aq-pdf-anatomy__m { margin-top: var(--space-6); padding-top: var(--space-3); border-top: 1px dashed var(--line); }
.aq-pdf-anatomy__m p:last-child { margin: 0; font: 400 15px/23px var(--font-sans); color: var(--ink-muted); }

@container (max-width: 1100px) {
  .aq-pdf-anatomy { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-8); }
  .aq-pdf-anatomy__side { padding-top: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-8); }
}
@container (max-width: 860px) {
  .aq-pdf-anatomy__h { font-size: 24px; line-height: 30px; }
  .aq-pdf-anatomy__crop { overflow: hidden; }
  .aq-pdf-anatomy__art { width: 128%; margin-left: -28.7%; }
  .aq-pdf-anatomy__pin {
    display: grid; place-items: center; position: absolute; width: var(--space-6); height: var(--space-6); transform: translate(-50%, -50%);
    background: var(--flow); color: var(--surface-raised); font: 500 12px/1 var(--font-mono); border-radius: var(--radius-pill);
  }
  .aq-pdf-anatomy__calls { position: static; width: auto; display: flex; flex-direction: column; gap: var(--space-2); margin-top: var(--space-4); }
  .aq-pdf-anatomy__call { position: static; transform: none; flex-direction: row; align-items: baseline; text-align: left; gap: var(--space-3); padding: 0; font-size: 15px; }
  .aq-pdf-anatomy__side { grid-template-columns: minmax(0, 1fr); gap: var(--space-8); }
  .aq-pdf-anatomy__big { font-size: 24px; line-height: 31px; }
}

/* ---------- PidRoutes: a router drawn as a P&ID on a navy blueprint ground (look "pid-routes") ----------
   Desktop: one grid, five tracks (situation | run | system | run | start with). Every route is one grid row (its li is
   display: contents); runs stretch to the row so pipes meet the boxes at their middle. Pipe lines are a stretched svg
   with non-scaling 1.5 px strokes; valve, instrument, port, junction and arrow symbols are fixed-size and centred on it.
   Phones: each route stacks and its runs turn vertical (the horizontal line hides, the vertical shows). */
.aq-pid-routes-band .aq-sec-head .aq-h1 { color: var(--on-navy); }
.aq-pid-routes {
  position: relative; padding: var(--space-6) var(--space-6) var(--space-4);
  border: 1px solid color-mix(in srgb, var(--on-navy-muted) 30%, transparent);
  color: var(--on-navy);
}
/* registration marks in two corners */
.aq-pid-routes__mark { position: absolute; top: calc(-1 * var(--space-2)); width: var(--space-4); height: var(--space-4); pointer-events: none; }
.aq-pid-routes__mark::before, .aq-pid-routes__mark::after { content: ""; position: absolute; background: var(--on-navy-muted); }
.aq-pid-routes__mark::before { left: 50%; top: 0; width: 1px; height: 100%; }
.aq-pid-routes__mark::after { top: 50%; left: 0; height: 1px; width: 100%; }
.aq-pid-routes__mark--tl { left: calc(-1 * var(--space-2)); }
.aq-pid-routes__mark--tr { right: calc(-1 * var(--space-2)); }

.aq-pid-routes__heads, .aq-pid-routes__list {
  display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr) minmax(0, 1fr) minmax(0, 0.62fr) minmax(0, 1fr);
}
.aq-pid-routes__head { margin: 0; padding-bottom: var(--space-2); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy); }
.aq-pid-routes__head span { display: block; color: var(--on-navy-muted); opacity: 0.8; }
.aq-pid-routes__ruler { display: block; width: 100%; height: 10px; margin-bottom: var(--space-4); }
.aq-pid-routes__ruler path { fill: none; stroke: color-mix(in srgb, var(--on-navy-muted) 45%, transparent); stroke-width: 1; }
.aq-pid-routes__list + .aq-pid-routes__ruler { margin: var(--space-4) 0 0; transform: scaleY(-1); }

.aq-pid-routes__list { list-style: none; margin: 0; padding: 0; }
.aq-pid-routes__route { display: contents; }
.aq-pid-routes__sit, .aq-pid-routes__node, .aq-pid-routes__run { position: relative; padding-block: var(--space-3); }
.aq-pid-routes__box { position: relative; height: 100%; display: flex; flex-direction: column; justify-content: center; box-sizing: border-box; }

/* Situation: a double-framed tag box with its path number on the frame */
.aq-pid-routes__sit .aq-pid-routes__box {
  min-height: calc(var(--space-16) + var(--space-2)); padding: var(--space-4) var(--space-4) var(--space-3);
  border: 1px solid var(--on-navy-muted);
  box-shadow: 0 0 0 3px var(--navy), 0 0 0 4px color-mix(in srgb, var(--on-navy-muted) 40%, transparent);
  background: var(--navy);
}
.aq-pid-routes__tag { position: absolute; top: calc(-1 * var(--space-2)); left: var(--space-3); right: var(--space-3); display: flex; justify-content: space-between; margin: 0; font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-pid-routes__tag span { padding: 0 var(--space-1); background: var(--navy); }
.aq-pid-routes__t { margin: 0; font: 400 16px/24px var(--font-sans); color: var(--on-navy); text-wrap: pretty; }

/* System and start: single-line boxes with a port dot on the inlet side */
.aq-pid-routes__node .aq-pid-routes__box { padding: var(--space-3) var(--space-4) var(--space-3) var(--space-8); border: 1px solid color-mix(in srgb, var(--on-navy-muted) 70%, transparent); background: var(--navy); }
.aq-pid-routes__node .aq-pid-routes__box::before {
  content: ""; position: absolute; left: var(--space-3); top: 50%; width: var(--space-2); height: var(--space-2); margin-top: calc(-1 * var(--space-1));
  border-radius: var(--radius-pill); border: 1.5px solid var(--on-navy-muted); box-sizing: border-box;
}
.aq-pid-routes__node--go .aq-pid-routes__box::before { background: var(--on-navy-muted); }
.aq-pid-routes__v { margin: 0; font: 400 15px/22px var(--font-sans); color: var(--on-navy); text-wrap: pretty; }
.aq-pid-routes__v a { color: var(--on-navy); text-decoration: none; }
.aq-pid-routes__node--go .aq-pid-routes__v a::after { content: "\a0\2192"; }
.aq-pid-routes__v a::before { content: ""; position: absolute; inset: 0; }
.aq-pid-routes__v a:hover { text-decoration: underline; text-underline-offset: 3px; }
.aq-pid-routes__v a:focus-visible { outline: none; }
.aq-pid-routes__node:has(a:focus-visible) .aq-pid-routes__box { outline: 2px solid var(--on-navy); outline-offset: 2px; }
.aq-pid-routes__node:has(a) .aq-pid-routes__box:hover { border-color: var(--on-navy); }
/* column labels: read by screen readers on desktop (the drawn heads are aria-hidden), shown on phones */
.aq-pid-routes__k { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; margin: 0; }

/* Runs: the pipe svg fills the cell; symbols sit on its centre line */
.aq-pid-routes__run { padding: 0; min-height: var(--space-16); }
.aq-pid-routes__pipe { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.aq-pid-routes__pipe line { vector-effect: non-scaling-stroke; fill: none; stroke-width: 1.5; stroke-linecap: round; }
.aq-pid-routes__ln { stroke: var(--on-navy-muted); }
.aq-pid-routes__ln--v { display: none; }
.aq-pid-routes__tie { stroke: color-mix(in srgb, var(--on-navy-muted) 75%, transparent); }
.aq-pid-routes__valve { position: absolute; left: 58%; top: 50%; width: 28px; height: 28px; margin: -14px 0 0 -14px; overflow: visible; }
.aq-pid-routes__run--b .aq-pid-routes__valve { left: 62%; }
.aq-pid-routes__vb { fill: var(--navy); stroke: var(--on-navy); stroke-width: 1.5; stroke-linejoin: round; }
.aq-pid-routes__vs { fill: none; stroke: var(--on-navy); stroke-width: 1.5; stroke-linecap: round; }
.aq-pid-routes__vf { fill: var(--on-navy); stroke: none; }
.aq-pid-routes__inst { position: absolute; left: 82%; bottom: 50%; width: 20px; height: 30px; margin-left: -10px; overflow: visible; }
.aq-pid-routes__inst path, .aq-pid-routes__inst circle { fill: var(--navy); stroke: var(--on-navy-muted); stroke-width: 1.25; }
.aq-pid-routes__port { position: absolute; left: 0; top: 50%; width: var(--space-2); height: var(--space-2); margin: calc(-1 * var(--space-1)) 0 0 calc(-1 * var(--space-1)); border-radius: var(--radius-pill); background: var(--on-navy); }
.aq-pid-routes__jn { position: absolute; top: 50%; width: 7px; height: 7px; margin: -3.5px 0 0 -3.5px; border-radius: var(--radius-pill); background: var(--on-navy-muted); }
.aq-pid-routes__arrow { position: absolute; right: 1px; top: 50%; width: 10px; height: 10px; margin-top: -5px; }
.aq-pid-routes__arrow path { fill: var(--on-navy); }

/* Drawing caption (decorative title block) */
.aq-pid-routes__cap { display: flex; justify-content: flex-end; gap: var(--space-3); margin: var(--space-3) 0 0; font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-pid-routes__cap span + span::before { content: "·"; content: "·" / ""; margin-right: var(--space-3); }

/* Hover or focus lights one route in water-blue; the others step back */
.aq-pid-routes [data-r], .aq-pid-routes [data-rs] { transition: opacity 200ms cubic-bezier(0.2, 0, 0, 1); }
.aq-pid-routes.has-hot [data-r]:not(.is-hot) { opacity: 0.38; }
.aq-pid-routes.has-hot .aq-pid-routes__tie:not(.is-hot), .aq-pid-routes.has-hot .aq-pid-routes__jn:not(.is-hot) { opacity: 0.3; }
.aq-pid-routes .is-hot .aq-pid-routes__ln, .aq-pid-routes .aq-pid-routes__tie.is-hot { stroke: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); stroke-width: 2; }
.aq-pid-routes .is-hot .aq-pid-routes__vb, .aq-pid-routes .is-hot .aq-pid-routes__vs { stroke: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-pid-routes .aq-pid-routes__jn.is-hot, .aq-pid-routes .is-hot .aq-pid-routes__port { background: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-pid-routes .is-hot .aq-pid-routes__arrow path { fill: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-pid-routes__node.is-hot .aq-pid-routes__box, .aq-pid-routes__node.is-lit .aq-pid-routes__box, .aq-pid-routes__sit.is-hot .aq-pid-routes__box { border-color: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-pid-routes__node.is-hot .aq-pid-routes__box::before, .aq-pid-routes__node.is-lit .aq-pid-routes__box::before { border-color: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); background: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-pid-routes__node .aq-pid-routes__box { transition: border-color 300ms cubic-bezier(0.2, 0, 0, 1); }
/* motion: the droplet that rides a run (created and removed by motion.js) */
.aq-pid-routes__drop { position: absolute; left: 0; top: 50%; width: var(--space-2); height: var(--space-2); margin: calc(-1 * var(--space-1)) 0 0 calc(-1 * var(--space-1)); border-radius: var(--radius-pill); background: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); pointer-events: none; }

/* Beam (motion only, ported from Subframe Motion "Animated beam"): the water running a pointed-at route; a bright head
   with a fading tail slides along the run's line, clipped to the run */
.aq-pid-routes__beam { position: absolute; left: 0; right: 0; top: 50%; height: 3px; margin-top: -1.5px; overflow: hidden; pointer-events: none; }
.aq-pid-routes__beam i { position: absolute; left: 0; top: 0; bottom: 0; width: 40%; transform: translateX(-100%);
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--flow) 60%, var(--on-navy)) 67.5%, var(--on-navy) 99%, transparent); }

@container (max-width: 860px) {
  .aq-pid-routes { padding: var(--space-4) var(--space-3) var(--space-3); }
  .aq-pid-routes__heads, .aq-pid-routes__ruler { display: none; }
  .aq-pid-routes__list { grid-template-columns: minmax(0, 1fr); }
  .aq-pid-routes__route { display: block; padding-bottom: var(--space-6); }
  .aq-pid-routes__route + .aq-pid-routes__route { padding-top: var(--space-4); border-top: 1px dashed color-mix(in srgb, var(--on-navy-muted) 40%, transparent); }
  .aq-pid-routes__sit, .aq-pid-routes__node { padding-block: 0; }
  .aq-pid-routes__sit .aq-pid-routes__box { min-height: 0; padding: var(--space-4) var(--space-3) var(--space-3); }
  .aq-pid-routes__node { margin-left: var(--space-6); }
  .aq-pid-routes__node .aq-pid-routes__box { padding: var(--space-2) var(--space-3) var(--space-2) var(--space-6); }
  .aq-pid-routes__k:not(.aq-pid-routes__k--sit) {
    position: static; width: auto; height: auto; overflow: visible; clip-path: none; white-space: normal;
    font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted);
  }
  /* the run turns vertical, down the left of the node it feeds */
  .aq-pid-routes__run { min-height: var(--space-12); margin-left: calc(var(--space-6) + var(--space-1)); width: var(--space-6); }
  .aq-pid-routes__ln--h, .aq-pid-routes__tie, .aq-pid-routes__jn, .aq-pid-routes__inst { display: none; }
  .aq-pid-routes__ln--v { display: inline; }
  .aq-pid-routes__valve, .aq-pid-routes__run--b .aq-pid-routes__valve { left: 50%; top: 50%; transform: rotate(90deg); }
  .aq-pid-routes__port { left: 50%; top: 0; margin-top: 0; }
  .aq-pid-routes__arrow { right: auto; left: 50%; top: auto; bottom: 1px; margin: 0 0 0 -5px; transform: rotate(90deg); }
  .aq-pid-routes__drop { left: 50%; top: 0; }
  .aq-pid-routes__cap { justify-content: flex-start; flex-wrap: wrap; }
}

/* ---------- PipeCollage: an evidence table as a Swiss poster (look "pipe-collage"). A geometric collage board of flat
   pieces (fills: navy, limestone, surface tokens; flow only as a line) beside asymmetric editorial blocks hung from
   hairline brackets. Piece shapes carry data-f (their fill or stroke role). The board is limestone paper
   (board and thumbs carry data-theme="light", so the poster keeps its light-paper fills in the dark theme). ---------- */
.aq-pipe-collage { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: var(--space-12); align-items: start; }
.aq-pipe-collage__board { position: sticky; top: calc(var(--space-16) + var(--space-8)); }
.aq-pipe-collage__board svg { display: block; width: 100%; height: auto; }
.aq-pipe-collage svg [data-f="ls"] { fill: var(--limestone); }
.aq-pipe-collage svg [data-f="lsf"] { fill: var(--limestone); }
.aq-pipe-collage svg [data-f="nv"] { fill: var(--navy); }
.aq-pipe-collage svg [data-f="sk"] { fill: var(--surface-sunken); }
.aq-pipe-collage svg [data-f="sf"] { fill: var(--surface-raised); }
.aq-pipe-collage svg [data-f="ln"] { fill: none; stroke: var(--line-strong); stroke-width: 1.5; }
.aq-pipe-collage svg [data-f="lnb"] { fill: none; stroke: var(--navy); stroke-width: 3; stroke-linecap: square; }
.aq-pipe-collage svg [data-f="nvl"] { fill: none; stroke: var(--navy); stroke-width: 1.5; }
.aq-pipe-collage svg [data-f="fl"] { fill: none; stroke: var(--flow); stroke-width: 1.5; stroke-linecap: round; }
.aq-pipe-collage svg [data-f="flb"] { fill: none; stroke: var(--flow); stroke-width: 1.5; }
.aq-pipe-collage svg [data-f="flo"] { fill: none; stroke: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); stroke-width: 1.5; stroke-dasharray: 6 5; }
.aq-pipe-collage svg [data-f="pipe"] { fill: none; stroke: var(--navy); stroke-width: 22; }
.aq-pipe-collage svg [data-f="ring"] { fill: var(--limestone); }
.aq-pipe-collage svg [data-f="dot"] { fill: var(--flow); }
.aq-pipe-collage svg [data-f="bead"] { fill: var(--navy); stroke: var(--limestone); stroke-width: 1.5; }
/* the sunken tiles need an edge on the light ground */
.aq-pipe-collage svg [data-f="sk"], .aq-pipe-collage svg [data-f="sf"] { stroke: var(--line); stroke-width: 1; }
.aq-pipe-collage__n { font: 500 12px/1 var(--font-mono); letter-spacing: 0.08em; fill: var(--ink-subtle); }
.aq-pipe-collage__cell.is-piece .aq-pipe-collage__n { fill: var(--on-limestone); }
.aq-pipe-collage__cell[data-pc] .aq-pipe-collage__n { paint-order: stroke; stroke: var(--limestone); stroke-width: 6px; stroke-linejoin: round; }
.aq-pipe-collage__frame { fill: none; stroke: var(--flow); stroke-width: 3; stroke-opacity: 0; }
.aq-pipe-collage__cell.is-on .aq-pipe-collage__frame { stroke-opacity: 1; }
.aq-pipe-collage.is-focus .aq-pipe-collage__cell:not(.is-on) { opacity: 0.55; }
@media (prefers-reduced-motion: no-preference) {
  .aq-pipe-collage__cell { transition: opacity 200ms; }
  .aq-pipe-collage__frame { transition: stroke-opacity 200ms; }
  .aq-pipe-collage__block { transition: border-color 200ms; }
}

/* Editorial blocks, stepped on a six-column field */
.aq-pipe-collage__blocks { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: var(--space-12) var(--space-6); }
.aq-pipe-collage__block { position: relative; display: flex; flex-direction: column; gap: var(--space-3); padding: var(--space-1) 0 0 var(--space-6); border-left: 1px solid var(--line-strong); min-width: 0; }
.aq-pipe-collage__block::before { content: ""; position: absolute; left: 0; top: 0; width: var(--space-4); height: 1px; background: var(--line-strong); }
.aq-pipe-collage__block:nth-child(5n+1) { grid-column: 1 / span 4; }
.aq-pipe-collage__block:nth-child(5n+2) { grid-column: 3 / span 4; }
.aq-pipe-collage__block:nth-child(5n+3) { grid-column: 1 / span 3; }
