.aq-pipe-collage__block:hover, .aq-pipe-collage__block:focus-within { border-left-color: var(--flow); }
.aq-pipe-collage__head { display: flex; align-items: baseline; gap: var(--space-3); }
.aq-pipe-collage__block > .aq-index { margin-bottom: calc(-1 * var(--space-2)); }
.aq-pipe-collage__std { margin: 0; font: 300 32px/38px var(--font-sans); letter-spacing: -0.02em; color: var(--ink); text-wrap: balance; }
.aq-pipe-collage__std .aq-ph { font-size: 22px; line-height: 30px; }
.aq-pipe-collage__how { margin: 0; font: 400 16px/25px var(--font-sans); color: var(--ink); text-wrap: pretty; }
.aq-pipe-collage__proof { margin: 0; font: 400 13px/20px var(--font-mono); color: var(--ink-muted); }
.aq-pipe-collage__k { display: block; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-pipe-collage__go { margin: 0; }
.aq-pipe-collage__go .aq-pipe-collage__k { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.aq-pipe-collage__go a { display: inline-flex; align-items: center; min-height: 44px; color: var(--flow); font: 500 15px/22px var(--font-sans); text-decoration: none; }
.aq-pipe-collage__go a::after { content: "\a0\2192"; }
.aq-pipe-collage__go a:hover { text-decoration: underline; text-underline-offset: 3px; }
.aq-pipe-collage__go a:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-pipe-collage__thumb { display: none; }
/* desktop: every block shows beside the whole board; the fold is for phones */
.aq-pipe-collage .aq-fold:not(.is-open) .aq-pipe-collage__block.aq-fold-x { display: flex; }
.aq-pipe-collage .aq-fold__btn { display: none; }
.aq-pipe-collage__block.aq-standards-map-hit { border-left-color: var(--flow); }

.aq-pipe-collage-sec .aq-sec-head { margin-bottom: var(--space-4); }
.aq-pipe-collage__text { min-width: 0; }

@container (max-width: 860px) {
  .aq-pipe-collage { grid-template-columns: minmax(0, 1fr); gap: var(--space-6); }
  .aq-pipe-collage__board { display: none; }
  .aq-pipe-collage__blocks { grid-template-columns: minmax(0, 1fr); gap: var(--space-8); }
  .aq-pipe-collage__block:nth-child(n) { grid-column: 1; padding-left: var(--space-4); }
  .aq-pipe-collage__block:nth-child(even) { margin-left: var(--space-6); }
  .aq-pipe-collage__thumb { display: block; width: var(--space-24); margin-bottom: var(--space-2); }
  .aq-pipe-collage__thumb svg { display: block; width: 100%; height: auto; max-height: var(--space-24); }
  .aq-pipe-collage__std { font-size: 26px; line-height: 32px; }
  .aq-pipe-collage .aq-fold:not(.is-open) .aq-pipe-collage__block.aq-fold-x { display: none; }
  .aq-pipe-collage .aq-fold__btn { display: flex; margin-top: var(--space-6); }
}

/* ---------- PlanChecker: service plans as a checker of navy and limestone tiles (look "plan-checker") ----------
   Limestone band (data-theme light). One column per plan, columns alternate navy and a lighter limestone tile with a
   hairline edge; each column is a head tile (slash numeral 300 at up to 112 px, name, who it suits) and a terms tile
   whose rows line up across columns through subgrid. No table rules: tiles and gaps separate. Navy tiles remap the ink
   tokens to their on-navy values. Phones: numeral tabs pick one plan. */
.aq-plan-checker-sec .aq-sec-head .aq-h1 { font-weight: 300; letter-spacing: -0.03em; }
.aq-plan-checker__tabs { display: none; }
.aq-plan-checker__plans {
  list-style: none; margin: 0; padding: 0; display: grid; column-gap: var(--space-1);
  grid-template-columns: repeat(var(--n, 4), minmax(0, 1fr));
  grid-template-rows: auto repeat(var(--rows, 3), auto) auto;
}
.aq-plan-checker__plan { grid-row: 1 / -1; display: grid; grid-template-rows: subgrid; min-width: 0; }
.aq-plan-checker .is-navy {
  background: var(--navy); color: var(--on-navy);
  --ink: var(--on-navy); --ink-muted: var(--on-navy-muted); --line-strong: color-mix(in srgb, var(--on-navy) 45%, transparent);
}
.aq-plan-checker .is-lime {
  background: color-mix(in srgb, var(--surface) 55%, var(--limestone)); color: var(--on-limestone);
  box-shadow: inset 1px 0 var(--line-strong), inset -1px 0 var(--line-strong);
}
.aq-plan-checker .is-navy .aq-ph { background: transparent; color: var(--on-navy); outline: 1px dashed var(--on-navy-muted); outline-offset: -1px; }

.aq-plan-checker__head { display: flex; flex-direction: column; gap: var(--space-3); padding: var(--space-6); margin-bottom: var(--space-1); min-height: 19rem; }
.aq-plan-checker__head.is-lime { box-shadow: inset 0 0 0 1px var(--line-strong); }
.aq-plan-checker__no { margin: 0 0 auto; font: 300 clamp(72px, 8.4vw, 112px)/0.9 var(--font-sans); letter-spacing: -0.05em; font-variant-numeric: tabular-nums; }
.aq-plan-checker__sl { opacity: 0.55; margin-left: 0.04em; }
.aq-plan-checker__mark { margin: 0; font: 500 12px/16px var(--font-mono); color: var(--flow); }
.aq-plan-checker__name { margin: var(--space-4) 0 0; font: 400 13px/20px var(--font-mono); }
.aq-plan-checker__suits { margin: 0; font: 300 20px/26px var(--font-sans); letter-spacing: -0.01em; }
.aq-plan-checker__sk { display: block; font: 400 12px/18px var(--font-mono); color: var(--on-limestone-muted); }
.is-navy .aq-plan-checker__sk { color: var(--on-navy-muted); }

.aq-plan-checker__term { padding: var(--space-3) var(--space-6); transition: background-color 160ms ease; }
.aq-plan-checker__term.is-first { padding-top: var(--space-6); }
.aq-plan-checker__term.is-first.is-lime { box-shadow: inset 1px 0 var(--line-strong), inset -1px 0 var(--line-strong), inset 0 1px var(--line-strong); }
.aq-plan-checker__v { margin: 0; font-size: 16px; line-height: 23px; overflow-wrap: anywhere; }
.aq-plan-checker__term.is-first .aq-plan-checker__v { font: 300 22px/28px var(--font-sans); letter-spacing: -0.01em; }
.aq-plan-checker__k { margin: var(--space-1) 0 0; font: 400 12px/17px var(--font-mono); color: var(--on-limestone-muted); }
.is-navy .aq-plan-checker__k { color: var(--on-navy-muted); }
.aq-plan-checker__term.is-lit.is-lime { background: var(--flow-tint); }
.aq-plan-checker__term.is-lit.is-navy { background: color-mix(in srgb, var(--on-navy) 12%, var(--navy)); }
.aq-plan-checker__act { padding: var(--space-4) var(--space-6) var(--space-6); }
.aq-plan-checker__act.is-lime { box-shadow: inset 1px 0 var(--line-strong), inset -1px 0 var(--line-strong), inset 0 -1px var(--line-strong); }
.aq-plan-checker__act .aq-btn { width: 100%; justify-content: center; text-align: center; }
.aq-plan-checker-sec .aq-fold__btn { margin-top: var(--space-6); }
.aq-fold:not(.is-open) .aq-plan-checker__term.aq-fold-x { display: none; }

@container (max-width: 860px) {
  .aq-plan-checker__tabs { display: grid; grid-template-columns: repeat(var(--n, 4), minmax(0, 1fr)); gap: var(--space-1); margin-bottom: var(--space-1); }
  .aq-plan-checker__tab {
    display: flex; flex-direction: column; align-items: flex-start; gap: var(--space-1); min-height: 72px; min-width: 0;
    padding: var(--space-2); border: 0; border-radius: 0; font: inherit; text-align: left; cursor: pointer;
  }
  .aq-plan-checker__tabno { font: 300 28px/1 var(--font-sans); letter-spacing: -0.04em; }
  .aq-plan-checker__tabn { font: 400 11px/14px var(--font-mono); overflow-wrap: anywhere; }
  .aq-plan-checker__tab .aq-ph { font-size: 11px; }
  .aq-plan-checker__tab[aria-pressed="true"] { outline: 2px solid var(--flow); outline-offset: -2px; }
  .aq-plan-checker__tab:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
  .aq-plan-checker__plans { grid-template-columns: minmax(0, 1fr); }
  .aq-plan-checker[data-show="1"] .aq-plan-checker__plan:not(.t1),
  .aq-plan-checker[data-show="2"] .aq-plan-checker__plan:not(.t2),
  .aq-plan-checker[data-show="3"] .aq-plan-checker__plan:not(.t3),
  .aq-plan-checker[data-show="4"] .aq-plan-checker__plan:not(.t4),
  .aq-plan-checker[data-show="5"] .aq-plan-checker__plan:not(.t5) { display: none; }
  .aq-plan-checker__head { min-height: 0; padding: var(--space-4); }
  .aq-plan-checker__no { font-size: 64px; margin-bottom: var(--space-4); }
  .aq-plan-checker__term { padding-inline: var(--space-4); }
  .aq-plan-checker__act { padding-inline: var(--space-4); }
}

/* ---------- PqCalendar: PQ phases beside one instrument readout (look "pq-calendar") ----------
   Section on the limestone band; the figure carries data-theme="light" so navy and flow keep their light values on
   limestone in both themes. Desktop: the phases as a ruled stack (5 of 12; mono "01 /" numerals, a key in the
   phase's fill), the readout panel beside it (7 of 12) on a lighter sheet with a navy foot rule: the giant light
   count, unit and sum, the sampling grid, then the year's tick scale (solid ticks for the daily phases, short ticks for
   the routine plan) with month numbers and the year tag. The region marker (flow tint, flow edges with handles)
   glides to the pointed phase's span: --g0/--g1 on the grid, --y0/--y1 on the scale. */
.aq-pq-calendar { --pq-p1: var(--navy); --pq-p2: var(--flow); display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: var(--space-12); align-items: start; color: var(--on-limestone); }
.aq-pq-calendar__phases { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--on-limestone); }
.aq-pq-calendar__ph { display: grid; grid-template-columns: var(--space-24) minmax(0, 1fr); column-gap: var(--space-4); padding: var(--space-6) var(--space-2) var(--space-6) 0; border-bottom: 1px solid color-mix(in srgb, var(--on-limestone) 35%, transparent); outline: none; cursor: default; transition: background-color 180ms; }
.aq-pq-calendar__ph:hover, .aq-pq-calendar__ph:focus-visible { background: color-mix(in srgb, var(--surface-raised) 45%, transparent); }
.aq-pq-calendar__ph:focus-visible { outline: 2px solid var(--focus); outline-offset: -2px; }
.aq-pq-calendar__n { font: 300 34px/1 var(--font-mono); letter-spacing: -0.04em; color: var(--on-limestone); padding-left: var(--space-2); }
.aq-pq-calendar__n i { font-style: normal; color: var(--on-limestone-muted); margin-left: 0.1em; }
.aq-pq-calendar__t { margin: 0; display: flex; align-items: center; gap: var(--space-2); font: 400 20px/26px var(--font-sans); color: var(--on-limestone); }
.aq-pq-calendar__key { width: var(--space-3); height: var(--space-3); flex: none; background: var(--pq-p1, var(--navy)); border-radius: 50%; }
.is-p2 > .aq-pq-calendar__txt .aq-pq-calendar__key { background: var(--pq-p2, var(--flow)); }
.is-rest > .aq-pq-calendar__txt .aq-pq-calendar__key { border-radius: 0; width: 2px; height: var(--space-4); background: var(--pq-p1, var(--navy)); }
.aq-pq-calendar__d { margin: var(--space-2) 0 0; font: 400 15px/23px var(--font-sans); color: var(--on-limestone-muted); }
.aq-pq-calendar__hold { margin: var(--space-3) 0 0; display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); font: 400 14px/20px var(--font-sans); color: var(--on-limestone); }
.aq-pq-calendar__hold span { padding: 0 var(--space-2); border: 1px solid var(--on-limestone); font: 500 12px/20px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; }

.aq-pq-calendar__panel { display: flex; flex-direction: column; gap: var(--space-8); padding: var(--space-8) var(--space-8) var(--space-6); background: color-mix(in srgb, var(--surface-raised) 55%, transparent); border-bottom: 2px solid var(--navy); }
.aq-pq-calendar__total { margin: 0; display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--space-1) var(--space-4); }
.aq-pq-calendar__num { flex-basis: 100%; font: 300 168px/0.9 var(--font-sans); letter-spacing: -0.05em; color: var(--on-limestone); font-variant-numeric: tabular-nums; }
.aq-pq-calendar__unit { font: 400 13px/18px var(--font-mono); letter-spacing: 0.12em; text-transform: uppercase; color: var(--on-limestone); }
.aq-pq-calendar__eq { font: 400 13px/18px var(--font-mono); letter-spacing: 0.04em; color: var(--on-limestone-muted); }
.aq-pq-calendar__zoomed, .aq-pq-calendar__scale { position: relative; }
.aq-pq-calendar__grid { display: block; width: 100%; height: auto; overflow: visible; }
.aq-pq-calendar__dot.is-p1 { fill: var(--pq-p1, var(--navy)); }
.aq-pq-calendar__dot.is-p2 { fill: var(--pq-p2, var(--flow)); }
.aq-pq-calendar__hl { stroke: var(--on-limestone); stroke-width: 1.5; stroke-dasharray: 4 3; }
.aq-pq-calendar__year { display: block; width: 100%; height: var(--space-8); }
.aq-pq-calendar__wk.is-p1 { fill: var(--pq-p1, var(--navy)); }
.aq-pq-calendar__wk.is-p2 { fill: var(--pq-p2, var(--flow)); }
.aq-pq-calendar__wk.is-rest { fill: var(--on-limestone-muted); }
.aq-pq-calendar__strip { position: relative; margin-top: var(--space-4); }
.aq-pq-calendar__months { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); margin-top: var(--space-1); border-top: 1px solid var(--on-limestone); }
.aq-pq-calendar__months span { padding: var(--space-1) 0 0 var(--space-1); border-left: 1px solid color-mix(in srgb, var(--on-limestone) 35%, transparent); font: 400 12px/16px var(--font-mono); color: var(--on-limestone-muted); }
.aq-pq-calendar__ylab { position: absolute; right: 0; top: calc(-1 * var(--space-6)); padding: 0 var(--space-2); border: 1px solid var(--on-limestone); font: 500 12px/20px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-limestone); background: var(--limestone); }

/* the region marker: not drawn until a phase is pointed at; then glides between spans */
.aq-pq-calendar__reg { position: absolute; top: calc(-1 * var(--space-1)); bottom: calc(-1 * var(--space-1)); left: var(--g0, 0%); width: var(--g1, 0%); background: color-mix(in srgb, var(--flow) 14%, transparent); border-left: 1px solid var(--flow); border-right: 1px solid var(--flow); display: none; pointer-events: none;
  transition: left 240ms cubic-bezier(0.2, 0, 0, 1), width 240ms cubic-bezier(0.2, 0, 0, 1); }
.aq-pq-calendar__reg i { position: absolute; top: 50%; width: var(--space-1); height: var(--space-4); margin-top: calc(-1 * var(--space-2)); background: var(--flow); }
.aq-pq-calendar__reg i:first-child { left: calc(-1 * var(--space-1) / 2); } .aq-pq-calendar__reg i:last-child { right: calc(-1 * var(--space-1) / 2); }
.aq-pq-calendar__scale .aq-pq-calendar__reg { left: var(--y0, 0%); width: var(--y1, 0%); }
.aq-pq-calendar[data-on] .aq-pq-calendar__scale .aq-pq-calendar__reg, .aq-pq-calendar[data-on="grid"] .aq-pq-calendar__zoomed .aq-pq-calendar__reg { display: block; }
@media (prefers-reduced-motion: reduce) { .aq-pq-calendar__reg { transition: none; } }

@container (max-width: 860px) {
  .aq-pq-calendar { grid-template-columns: minmax(0, 1fr); gap: var(--space-8); }
  .aq-pq-calendar__ph { grid-template-columns: var(--space-16) minmax(0, 1fr); padding: var(--space-4) 0; }
  .aq-pq-calendar__n { font-size: 26px; padding-left: 0; }
  .aq-pq-calendar__t { font-size: 18px; line-height: 24px; }
  .aq-pq-calendar__d { font-size: 14px; line-height: 22px; }
  .aq-pq-calendar__panel { padding: var(--space-6) var(--space-4) var(--space-4); gap: var(--space-6); }
  .aq-pq-calendar__num { font-size: 104px; }
  .aq-pq-calendar__months span:nth-child(even) { color: transparent; }
}

/* section hook */
.aq-pq-calendar-sec { position: relative; }

/* ---------- ProcessDiagram: a treatment train as an interactive piping flow in a Plate ----------
   Single-weight line art: one row of stations (Spot vignette in a `line` frame, index, name) on a double-hairline flow
   pipe with arrows; each station is a toggle button. The pressed station's run and the runs before it tint flow-tint
   (water has reached here), and its detail opens under the row, below a `line` hairline, with a flow leader up to it.
   Phone: one vertical pipe through the vignettes; the pressed station's detail opens inline under it, beside the pipe.
   Without the page script (no is-live) every detail shows: under its column on desktop, inline on phones.
   Geometry: --fh vignette box height, --fw its width (phone), --g column gap; the pipe is --space-3 high, 1.5 px walls. */
.aq-diagram__plate { padding-top: var(--space-8); }
.aq-diagram { --fh: calc(var(--space-24) + var(--space-6)); --g: var(--space-6); --pw: var(--space-3); min-width: 0; }
.aq-diagram--base { border: 1px dashed var(--line-strong); padding: var(--space-6) var(--space-6) var(--space-4); }
.aq-diagram__line { display: grid; grid-template-columns: repeat(var(--n, 6), minmax(0, 1fr)); column-gap: var(--g, var(--space-6)); }

/* Pipe-end labels (WaterPath "City feed" / "Point of use"). Child spans only: a [placeholder] or µ inside a label is a
   span of its own and takes no arrow */
.aq-diagram__ends { display: flex; justify-content: space-between; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
/* the end labels are a <p>: the extra class beats the page reset (.aq-page p { margin: 0 }) */
.aq-diagram .aq-diagram__ends { margin: 0 0 var(--space-6); }
.aq-diagram__ends > span::after { color: var(--flow); }
.aq-diagram__ends > span:first-child::after { content: "\a0\2192"; }
.aq-diagram__ends > span:last-child::after { content: "\a0\2192"; }

/* Station: a reset button holding the run, the vignette box, the index and the name */
.aq-diagram__st {
  grid-row: 1; position: relative; display: flex; flex-direction: column; align-items: center; gap: var(--space-3); min-width: 0;
  margin: 0; padding: 0 0 var(--space-2); border: 0; background: none; color: var(--ink); font: inherit; text-align: center; cursor: pointer;
}
.aq-diagram__st:focus-visible { outline: 2px solid var(--focus); outline-offset: var(--space-1); border-radius: var(--radius-sm); }
.aq-diagram__fig { position: relative; z-index: 1; display: grid; place-items: center; width: min(100%, var(--space-32)); height: var(--fh, var(--space-32)); border: 1px solid var(--line); background: var(--surface); }
.aq-diagram__fig .aq-diagram__spot { background-color: var(--ink-muted); }
.aq-diagram__n {
  position: absolute; z-index: 2; top: var(--space-1); left: calc(50% - min(50%, var(--space-16)) + var(--space-2));
  font: 400 12px/16px var(--font-mono); font-variant-numeric: tabular-nums; letter-spacing: 0.02em; color: var(--ink-subtle);
}
.aq-diagram__t { padding: 0 var(--space-1); font: 500 14px/20px var(--font-sans); letter-spacing: 0; color: var(--ink); overflow-wrap: anywhere; text-wrap: balance; }

/* The pipe run into each station: from the previous station's centre (first: from the edge), two hairline walls, arrow mid-run */
.aq-diagram__run { position: absolute; z-index: 0; top: calc(var(--fh, var(--space-32)) / 2 - var(--pw, var(--space-4)) / 2); right: 50%; width: calc(100% + var(--g, var(--space-6))); height: var(--pw, var(--space-4)); border-block: 1.5px solid var(--flow); overflow: hidden; }
.aq-diagram__st:first-child .aq-diagram__run { width: calc(50% + var(--space-8)); }
.aq-diagram__fill { position: absolute; inset: 0; background: var(--flow-tint); transform: scaleX(0); transform-origin: left center; }
.aq-diagram__run::after, .aq-diagram__st.is-last::after { content: ""; position: absolute; z-index: 1; top: 50%; left: 50%; transform: translate(-50%, -50%); border-block: 4px solid transparent; border-left: 6px solid var(--flow); }
/* The outlet after the last station, with its arrow */
.aq-diagram__st.is-last::before { content: ""; position: absolute; z-index: 0; top: calc(var(--fh, var(--space-32)) / 2 - var(--pw, var(--space-4)) / 2); left: 50%; width: calc(50% + var(--space-6)); height: var(--pw, var(--space-4)); border-block: 1.5px solid var(--flow); }
.aq-diagram__st.is-last::after { top: calc(var(--fh, var(--space-32)) / 2); left: auto; right: calc(-1 * var(--space-6)); transform: translateY(-50%); border-left-width: 8px; border-block-width: 5px; }

/* Pressed: its run and every run upstream tint (water has reached here); the box edge, index and name take flow */
.aq-diagram__st[aria-pressed="true"] .aq-diagram__fill, .aq-diagram__st:has(~ .aq-diagram__st[aria-pressed="true"]) .aq-diagram__fill { transform: none; }
.aq-diagram__st[aria-pressed="true"] .aq-diagram__fig { border-color: var(--flow); }
.aq-diagram__st[aria-pressed="true"] .aq-diagram__fig .aq-diagram__spot { background-color: var(--flow); }
.aq-diagram__st[aria-pressed="true"] .aq-diagram__n { color: var(--flow); }
.aq-diagram__st[aria-pressed="true"] .aq-diagram__t { color: var(--flow); }
.aq-diagram__st:not([aria-pressed="true"]):hover .aq-diagram__t { color: var(--flow); }
.aq-diagram__st:not([aria-pressed="true"]):hover .aq-diagram__fig .aq-diagram__spot { background-color: var(--ink); }
@media (prefers-reduced-motion: no-preference) { .aq-diagram__fig, .aq-diagram__t, .aq-diagram__spot { transition: color 200ms, background-color 200ms, border-color 200ms; } }

/* Detail: with the script, one panel under the row (the pressed station's) below a hairline, a leader up to its column */
.aq-diagram__d[hidden] { display: none; }
.aq-diagram__d { grid-row: 2; min-width: 0; }
.aq-diagram.is-live .aq-diagram__d {
  grid-column: 1 / -1; position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; column-gap: var(--space-8); align-items: start;
  margin-top: var(--space-8); padding: var(--space-6) 0 0; border-top: 1px solid var(--line);
}
.aq-diagram.is-live .aq-diagram__d::before {
  content: ""; position: absolute; bottom: 100%; height: calc(var(--space-8) - var(--space-1)); width: 0; border-left: 1px solid var(--flow);
  left: calc((100% - (var(--n, 6) - 1) * var(--g, var(--space-6))) / var(--n, 6) * (var(--i, 0) + 0.5) + var(--i, 0) * var(--g, var(--space-6)) - 1px);
}
.aq-diagram__dn { font: 300 32px/36px var(--font-mono); letter-spacing: -0.02em; color: var(--ink); font-variant-numeric: tabular-nums; }
.aq-diagram__dn small { font-size: 14px; color: var(--ink-subtle); letter-spacing: 0; }
.aq-diagram__db { display: flex; flex-direction: column; gap: var(--space-2); min-width: 0; }
.aq-diagram__dt { margin: 0; font: 500 20px/28px var(--font-sans); color: var(--ink); }
.aq-diagram__dd { margin: 0; max-width: var(--text-max); font: 400 16px/24px var(--font-sans); color: var(--ink-muted); text-wrap: pretty; }
.aq-diagram__dx { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-4); margin: var(--space-1) 0 0; }
.aq-diagram__dx a { color: var(--ink); font: 500 15px/24px var(--font-sans); text-decoration: none; }
.aq-diagram__dx a::after { content: "\a0\2192"; color: var(--flow); }
.aq-diagram__dx a:hover { color: var(--flow); text-decoration: underline; }
.aq-diagram__io { display: flex; flex-direction: column; gap: var(--space-2); margin: 0; font: 400 14px/22px var(--font-sans); color: var(--ink); }
.aq-diagram__io b { display: inline-block; min-width: var(--space-8); margin-right: var(--space-2); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
/* Without the script: each column's line under its station, small; number, title and in/out left to the stations */
.aq-diagram:not(.is-live) .aq-diagram__d { padding: var(--space-2) var(--space-1) 0; text-align: center; }
.aq-diagram:not(.is-live) .aq-diagram__dn, .aq-diagram:not(.is-live) .aq-diagram__dt, .aq-diagram:not(.is-live) .aq-diagram__io { display: none; }
.aq-diagram:not(.is-live) .aq-diagram__dd { font-size: 14px; line-height: 20px; }
.aq-diagram:not(.is-live) .aq-diagram__dx { justify-content: center; }

/* What spans every stage: the dashed control boundary round the train, labelled at its foot */
.aq-diagram__base { display: flex; align-items: center; gap: var(--space-3); margin: var(--space-6) 0 0; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-diagram__base svg { flex: none; width: var(--space-6); height: var(--space-6); fill: none; stroke: var(--ink-muted); stroke-width: 1.5; }

/* Phone: one vertical pipe down through the vignettes; name beside each; the detail opens inline under its station */
/* Selecting a station further down: the water shows in full Flow in the runs it passes through (script, < 1 s) */
.aq-diagram__st.is-flowing .aq-diagram__fill { background: var(--flow); }
@media (prefers-reduced-motion: no-preference) {
  .aq-diagram__fig { transition: color 120ms, background-color 120ms, border-color 120ms, transform 200ms; }
  /* hover lifts the box a hair; press sets it down */
  .aq-diagram__st:not([aria-pressed="true"]):hover .aq-diagram__fig { transform: translateY(calc(-1 * var(--space-1))); }
  .aq-diagram__st:active .aq-diagram__fig { transform: scale(0.97); transition-duration: 80ms; }
}

@container (max-width: 860px) {
  .aq-diagram__plate { padding: var(--space-3); }
  .aq-diagram__plate .aq-plate__block { display: none; }
  .aq-diagram { --fh: calc(var(--space-12) + var(--space-2)); --fw: calc(var(--space-12) + var(--space-2)); --g: var(--space-1); --pw: var(--space-3); }
  /* compact vignettes: 56 px boxes, the drawing at 48 px (icons 36 px), glyph scaled to fit */
  .aq-diagram__fig .aq-spot, .aq-diagram__fig .aq-spot--s { width: var(--space-12); height: var(--space-12); }
  .aq-diagram__fig .aq-spot.aq-spot--icon { width: calc(var(--space-8) + var(--space-1)); height: calc(var(--space-8) + var(--space-1)); }
  .aq-diagram--base { padding: var(--space-4) var(--space-3) var(--space-3); }
  .aq-diagram__ends { display: none; }
  .aq-diagram__line { grid-template-columns: minmax(0, 1fr); row-gap: var(--g, var(--space-6)); padding-top: var(--space-3); }
  .aq-diagram__st { grid-row: auto; display: grid; grid-template-columns: var(--fw, var(--space-24)) minmax(0, 1fr); column-gap: var(--space-3); align-items: center; padding: 0; text-align: left; }
  .aq-diagram__fig { width: var(--fw, var(--space-24)); }
  .aq-diagram__n { top: 0; left: 0; padding: 0 var(--space-1); background: var(--surface); font-size: 12px; line-height: 16px; }
  .aq-diagram__t { padding: 0; font-size: 14px; line-height: 20px; text-wrap: pretty; }
  /* runs are vertical: the incoming half from above, the outgoing half below the box */
  .aq-diagram__run { top: calc(-1 * var(--g, var(--space-6))); bottom: 50%; right: auto; left: calc(var(--fw, var(--space-24)) / 2 - var(--pw, var(--space-4)) / 2); width: var(--pw, var(--space-4)); height: auto; border: 0; border-inline: 1.5px solid var(--flow); }
  .aq-diagram__st:first-child .aq-diagram__run { top: calc(-1 * var(--space-3)); width: var(--pw, var(--space-4)); }
  .aq-diagram__fill { transform: scaleY(0); transform-origin: center top; }
  .aq-diagram__run::after { display: none; }
  .aq-diagram__st::before, .aq-diagram__st.is-last::before { content: ""; position: absolute; z-index: 0; top: 50%; bottom: 0; left: calc(var(--fw, var(--space-24)) / 2 - var(--pw, var(--space-4)) / 2); width: var(--pw, var(--space-4)); height: auto; border: 0; border-inline: 1.5px solid var(--flow); }
  .aq-diagram__st.is-last::before { bottom: calc(-1 * var(--space-4)); }
  .aq-diagram__st.is-last::after { top: auto; bottom: calc(-1 * var(--space-4)); right: auto; left: calc(var(--fw, var(--space-24)) / 2); transform: translate(-50%, 100%); border: 0; border-inline: 5px solid transparent; border-top: 8px solid var(--flow); }
  .aq-diagram__line { padding-bottom: var(--space-6); }
  .aq-diagram__line > .aq-diagram__d:last-child::after { display: none; }
  /* the detail: tucked under the station's name, beside the box (it rises into the row by --fh less one name line);
     the pipe continues down past whatever runs below the box */
  .aq-diagram__st { align-items: start; }
  .aq-diagram__st .aq-diagram__t { padding-top: var(--space-1); }
  .aq-diagram__d, .aq-diagram.is-live .aq-diagram__d {
    grid-row: auto; grid-column: 1; position: relative; display: block; margin: calc(var(--space-6) + var(--space-1) - var(--fh, var(--space-24))) 0 0 calc(var(--fw, var(--space-24)) + var(--space-3)); padding: 0;
    border: 0; border-radius: 0; background: none; text-align: left;
  }
  .aq-diagram__d::after { content: ""; position: absolute; top: calc(var(--fh, var(--space-24)) - var(--space-6) - var(--space-1)); bottom: calc(-1 * var(--space-1)); left: calc(-1 * var(--space-3) - var(--fw, var(--space-24)) / 2 - var(--pw, var(--space-4)) / 2); width: var(--pw, var(--space-4)); border-inline: 1.5px solid var(--flow); }
  .aq-diagram.is-live .aq-diagram__d::before { display: none; }
  .aq-diagram__dn, .aq-diagram__dt { display: none; }
  .aq-diagram__db { gap: var(--space-1); }
  .aq-diagram__dd, .aq-diagram:not(.is-live) .aq-diagram__dd { font-size: 13px; line-height: 20px; }
  /* on the phone the neighbours sit right above and below: In/Out only where there is no line to show */
  .aq-diagram .aq-diagram__db:has(.aq-diagram__dd) + .aq-diagram__io { display: none; }
  .aq-diagram__dx { gap: var(--space-3); }
  .aq-diagram__io, .aq-diagram:not(.is-live) .aq-diagram__io { display: flex; flex-direction: row; flex-wrap: wrap; gap: var(--space-1) var(--space-4); margin-top: var(--space-2); }
  .aq-diagram__io:first-child { margin-top: 0; }
  .aq-diagram__base { margin-top: var(--space-4); }
}

/* ---------- ProcessSteps: a real sequence as rows of the shared list grammar ---------- */
/* Layout from .aq-rows (base.css): index | step name | what happens. The index already carries the order, so a plain
   list has no pipe, spine or stair: hairlines between steps are the only structure. */
.aq-steps { min-width: 0; }

/* ---------- Hold-point flow (.aq-steps--hold, inside a Plate) ----------
   Steps with at least one hold draw as a process flow in single-weight line art: numbered stations in a grid (--cols per
   row, set by steps.js), joined by 1.5 px line-strong pipes with small arrowheads, rows returning under each other
   through rounded elbows, and a closed flow valve (P&ID symbol) on the run into every hold station. Stations have no
   ground or frame: the number, the name and what happens sit on the section, and a hold adds one line, "Hold" in
   flow and who signs.
   Geometry: space-8 gutter beside the grid (the return pipe runs in it), space-12 gap between stations (the runs),
   pipe centre line at space-3 + 24px (the middle of the station number). Pipes, valves and arrows are aria-hidden. */
.aq-steps--hold {
  display: grid; grid-template-columns: repeat(var(--cols, 4), minmax(0, 1fr)); column-gap: var(--space-12); row-gap: 0;
  list-style: none; margin: 0; padding: 0 var(--space-8);
}
.aq-steps__st { position: relative; display: flex; flex-direction: column; gap: var(--space-2); padding: var(--space-3); min-width: 0; }
.aq-steps__n { font: 300 32px/48px var(--font-mono); letter-spacing: -0.02em; font-variant-numeric: tabular-nums; color: var(--ink); }
.aq-steps__body { display: flex; flex-direction: column; gap: var(--space-2); }
.aq-steps__t { margin: 0; font: 500 16px/24px var(--font-sans); letter-spacing: -0.005em; color: var(--ink); text-wrap: balance; }
/* Station link (item link): the title is the link, as a row's: ink, ending in a flow arrow, flow on hover */
.aq-steps__go { color: inherit; text-decoration: none; }
.aq-steps__go::after { content: "\a0\2192"; content: "\a0\2192" / ""; color: var(--flow); }
.aq-steps__go:hover { color: var(--flow); }
.aq-steps__go:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-steps__d { margin: 0; font: 400 14px/22px var(--font-sans); color: var(--ink-muted); overflow-wrap: break-word; text-wrap: pretty; }

/* The hold: one line under the step's text, "Hold" in flow (a word) and who signs in ink-muted */
.aq-steps .aq-steps__hold { margin: var(--space-2) 0 0; }
.aq-steps__stamp { display: inline-flex; flex-wrap: wrap; align-items: baseline; column-gap: var(--space-2); max-width: 100%; font: 400 14px/20px var(--font-sans); color: var(--ink-muted); }
.aq-steps__stamp-k { flex: none; font-weight: 500; color: var(--flow); }
.aq-steps__who { min-width: 0; text-wrap: balance; }

/* Run: the pipe from a station to the next, in the gap between them, with a small arrowhead into the next station */
.aq-steps__run { position: absolute; left: 100%; top: calc(var(--space-3) + 24px - 0.75px); width: var(--space-12); height: 1.5px; background: var(--line-strong); }
.aq-steps__run::after { content: ""; position: absolute; right: 0; top: 50%; transform: translateY(-50%); border-left: 6px solid var(--line-strong); border-block: 4px solid transparent; }
.aq-steps__valve { position: absolute; left: 50%; top: 50%; width: var(--space-6); height: var(--space-6); transform: translate(-60%, -50%); overflow: visible; }
.aq-steps__valve path:first-child { fill: var(--flow); stroke: var(--flow); stroke-width: 1.5; stroke-linejoin: round; }
.aq-steps__valve path + path { fill: none; stroke: var(--flow); stroke-width: 1.5; }
.aq-steps__st.is-eol > .aq-steps__run { display: none; }
/* The pipe leaves just after the station number, so it reads as one run between stations */
.aq-steps__st > .aq-steps__run { left: var(--space-24); width: calc(100% - var(--space-24) + var(--space-12)); }
.aq-steps__st.is-eol > .aq-steps__turn:not(.aq-steps__turn--in) { left: var(--space-24); width: calc(100% - var(--space-24) + var(--space-8) / 2 + 0.75px); }
/* Return: out of the row's last station into the right gutter, down, back along under the row, down the left gutter
   and into the next row's first station, in the same 1.5 px line with rounded elbows. */
.aq-steps__turn { position: absolute; left: 100%; top: calc(var(--space-3) + 24px - 0.75px); bottom: 0; width: calc(var(--space-8) / 2 + 0.75px); box-sizing: border-box; border-top: 1.5px solid var(--line-strong); border-right: 1.5px solid var(--line-strong); border-top-right-radius: var(--space-4); }
.aq-steps__turn--in { left: auto; right: 100%; top: 0; bottom: auto; height: calc(var(--space-3) + 24px + 0.75px); border: 0; border-left: 1.5px solid var(--line-strong); border-bottom: 1.5px solid var(--line-strong); border-radius: 0 0 0 var(--space-4); }
.aq-steps__turn--in::after { content: ""; position: absolute; right: -2px; bottom: calc(-0.75px - 4px); border-left: 6px solid var(--line-strong); border-block: 4px solid transparent; }
.aq-steps__ret { position: relative; grid-column: 1 / -1; height: var(--space-12); }
.aq-steps__ret::before { content: ""; position: absolute; top: 0; height: calc(50% + 0.75px); left: calc(var(--space-4) - var(--space-8) / 2); right: calc(var(--space-8) / -2 - 0.75px); box-sizing: border-box; border-right: 1.5px solid var(--line-strong); border-bottom: 1.5px solid var(--line-strong); border-bottom-right-radius: var(--space-4); }
.aq-steps__ret::after { content: ""; position: absolute; top: calc(50% - 0.75px); bottom: 0; left: calc(var(--space-8) / -2 - 0.75px); width: var(--space-6); box-sizing: border-box; border-left: 1.5px solid var(--line-strong); border-top: 1.5px solid var(--line-strong); border-top-left-radius: var(--space-4); }
.aq-steps__ret-arrow { display: none; }
.aq-steps__ret > .aq-steps__valve { left: 25%; }

/* Motion (ProcessSteps/motion.js): the drop of water that runs each pipe as it is laid; made and removed by the motion layer */
.aq-steps--hold { position: relative; }
.aq-steps__drop { position: absolute; left: 0; top: 0; z-index: 2; width: var(--space-2); height: var(--space-2); margin: calc(var(--space-2) / -2) 0 0 calc(var(--space-2) / -2); border-radius: var(--radius-pill); background: var(--flow); pointer-events: none; }

/* ---------- Row (as: "row"): a short sequence read across, as the site first drew it ----------
   A line-strong rule on top, then one column per step: flow number (eyebrow mono), name (h3), one sentence (small). */
.aq-steps-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--line-strong); }
.aq-steps-row > li { display: flex; flex-direction: column; gap: var(--space-2); min-width: 0; padding: var(--space-6) var(--space-6) 0 0; }
.aq-steps-row__n { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; color: var(--flow); font-variant-numeric: tabular-nums; }
.aq-steps-row__t { margin: 0; font: 500 20px/28px var(--font-sans); letter-spacing: -0.005em; color: var(--ink); }
.aq-steps-row__d { margin: 0; font: 400 14px/22px var(--font-sans); color: var(--ink-muted); text-wrap: pretty; }

@container (max-width: 860px) {
  /* Phone: one vertical 1.5 px pipe down the number column, stations along it, no frames */
  .aq-steps--hold { grid-template-columns: minmax(0, 1fr); padding: 0; }
  .aq-steps__st { display: grid; grid-template-columns: var(--space-12) minmax(0, 1fr); align-items: start; column-gap: var(--space-3); padding: 0 0 var(--space-6); }
  .aq-steps__n { justify-self: center; position: relative; z-index: 1; padding-block: var(--space-1); background: var(--surface); font-size: 24px; line-height: 32px; }
  .aq-plate .aq-steps__n { background: var(--surface-raised); }
  .aq-steps__body { padding-top: var(--space-2); }
  .aq-steps__go { padding-block: calc(var(--space-2) + var(--space-1) / 2); }
  .aq-steps__run, .aq-steps__st.is-eol > .aq-steps__run, .aq-steps__st > .aq-steps__run { display: block; left: calc(var(--space-12) / 2 - 0.75px); top: var(--space-8); bottom: 0; width: 1.5px; height: auto; }
  .aq-steps__run::after { top: auto; right: auto; bottom: 0; left: 50%; transform: translateX(-50%); border-top: 6px solid var(--line-strong); border-left: 4px solid transparent; border-right: 4px solid transparent; border-bottom: 0; }
  .aq-steps__valve { transform: translate(-50%, -50%) rotate(90deg); }
  .aq-steps__turn, .aq-steps__ret { display: none; }
}

/* ---------- ProjectRun: ordered steps told as one run you scroll along ---------- */
/* Two states. Static (default: no script, reduced motion, phones): the steps stack down a vertical twin-wall pipe,
   a numbered node per step, the step's drawing beside its text. Live (motion adds is-live on wide screens): the
   steps scroll on the left at large size while a sticky stage on the right shows the current step's drawing, its
   number set huge, and a horizontal run whose water fills stop by stop. Drawings are Illustration masks in ink. */
.aq-project-run { --pipe: var(--space-3); --node: var(--space-12); position: relative; }
.aq-project-run__stage { display: none; }

/* Static: vertical run */
/* each step but the last carries the run down to the next node: twin wall, water (--w, 0 to 1, set by motion; full without it) */
.aq-project-run__step { --w: 1; position: relative; }
.aq-project-run__step:not(:last-child)::before, .aq-project-run__step:not(:last-child)::after { content: ""; position: absolute; top: calc(var(--node, var(--space-12)) / 2); height: calc(100% + var(--space-12)); }
.aq-project-run__step:not(:last-child)::before { left: calc(var(--node, var(--space-12)) / 2 - var(--pipe, var(--space-3)) / 2); width: var(--pipe, var(--space-3)); border-inline: 1px solid var(--line-strong); box-sizing: border-box; }
.aq-project-run__step:not(:last-child)::after { left: calc(var(--node, var(--space-12)) / 2 - 1px); width: 2px; background: var(--flow); transform: scaleY(var(--w, 1)); transform-origin: 50% 0; }
.aq-project-run__steps { list-style: none; margin: 0; padding: 0; position: relative; display: flex; flex-direction: column; gap: var(--space-12); }
.aq-project-run__step { display: grid; grid-template-columns: var(--node, var(--space-12)) minmax(0, 240px) minmax(0, 1fr); column-gap: var(--space-8); align-items: start; }
.aq-project-run__node { width: var(--node, var(--space-12)); height: var(--node, var(--space-12)); display: grid; place-items: center; border-radius: var(--radius-pill); box-sizing: border-box;
  border: 2px solid var(--flow); background: var(--surface); font: 500 13px/16px var(--font-mono); color: var(--ink); font-variant-numeric: tabular-nums; position: relative; z-index: 1; }
.aq-project-run__pic { aspect-ratio: 4 / 3; -webkit-mask-size: contain; mask-size: contain; }
.aq-project-run__text { display: flex; flex-direction: column; gap: var(--space-3); padding-top: var(--space-2); }
.aq-project-run__code { margin: 0; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; color: var(--ink-subtle); }
.aq-project-run__t { margin: 0; font: 400 32px/38px var(--font-sans); letter-spacing: -0.02em; }
.aq-project-run__t a { color: var(--ink); text-decoration: none; }
.aq-project-run__t a::after { content: "\00a0\2192"; display: inline-block; color: var(--flow); transition: transform 200ms; }
.aq-project-run__t a:hover { text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 0.16em; text-decoration-color: var(--flow); }
.aq-project-run__t a:hover::after { transform: translateX(var(--space-1)); }
.aq-project-run__t a:focus-visible { outline: 2px solid var(--focus); outline-offset: var(--space-1); }
.aq-project-run__d { margin: 0; font: 400 18px/28px var(--font-sans); color: var(--ink-muted); max-width: 46ch; }

/* Live: sticky stage on the right, steps scroll on the left */
.aq-project-run.is-live { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); column-gap: var(--space-16); }
.is-live .aq-project-run__node, .is-live .aq-project-run__pic, .is-live .aq-project-run__step::before, .is-live .aq-project-run__step::after { display: none; }
.is-live .aq-project-run__steps { grid-column: 1; grid-row: 1; gap: 0; padding-block: 8vh 24vh; }
.is-live .aq-project-run__step { display: flex; align-items: center; min-height: 64vh; }
.is-live .aq-project-run__text { opacity: 0.28; transition: opacity 500ms cubic-bezier(0.2, 0, 0, 1); }
.is-live .aq-project-run__step.is-on .aq-project-run__text { opacity: 1; }
.is-live .aq-project-run__t { font: 300 48px/52px var(--font-sans); letter-spacing: -0.025em; }
.is-live .aq-project-run__d { font-size: 20px; line-height: 30px; }
.is-live .aq-project-run__code { font-size: 13px; }

.is-live .aq-project-run__stage { display: flex; flex-direction: column; grid-column: 2; grid-row: 1; position: sticky; top: 12vh; height: 76vh; align-self: start;
  border: 1px solid var(--line); background: var(--surface-raised); padding: var(--space-8); box-sizing: border-box; }
.aq-project-run__num { position: absolute; left: var(--space-8); top: var(--space-6); margin: 0; display: flex; align-items: baseline; gap: var(--space-3); z-index: 1; }
.aq-project-run__cur { font: 300 140px/1 var(--font-sans); letter-spacing: -0.05em; color: var(--ink); font-variant-numeric: tabular-nums; }
.aq-project-run__of { font: 500 14px/16px var(--font-mono); letter-spacing: 0.08em; color: var(--ink-subtle); }
.aq-project-run__arts { position: relative; flex: 1; min-height: 0; margin: var(--space-16) 0 var(--space-6) var(--space-16); }
.aq-project-run__art { position: absolute; inset: 0; width: auto; aspect-ratio: auto; -webkit-mask-size: contain; mask-size: contain;
  clip-path: inset(0 0 100% 0); transition: clip-path 800ms cubic-bezier(0.65, 0, 0.35, 1); }
/* the current drawing prints up from the bottom while the last one lifts away */
.aq-project-run__art.is-on { clip-path: inset(0 0 0 0); }
.aq-project-run__art.is-on ~ .aq-project-run__art { clip-path: inset(100% 0 0 0); }

/* The run: a twin-wall pipe through one stop per step; the water fills to the current stop (--f, 0 to 1) */
.aq-project-run__run { --f: 0; position: relative; display: grid; grid-template-columns: repeat(var(--n, 5), minmax(0, 1fr)); padding-top: var(--space-2); }
.aq-project-run__pipe { position: absolute; top: calc(var(--space-2) + var(--space-4) - var(--pipe, var(--space-3)) / 2); height: var(--pipe, var(--space-3)); left: calc(50% / var(--n, 5)); right: calc(50% / var(--n, 5));
  border-block: 1px solid var(--line-strong); box-sizing: border-box; }
.aq-project-run__water { position: absolute; left: 0; right: 0; top: 50%; height: 2px; margin-top: -1px; background: var(--flow); transform: scaleX(var(--f, 0)); transform-origin: 0 50%; }
.aq-project-run__drop { position: absolute; top: 50%; left: calc(var(--f, 0) * 100%); width: var(--space-3); height: var(--space-3); margin: calc(var(--space-3) / -2) 0 0 calc(var(--space-3) / -2);
  border-radius: var(--radius-pill); background: var(--flow); border: 2px solid var(--surface-raised); }
.aq-project-run__stop { position: relative; display: flex; flex-direction: column; align-items: center; gap: var(--space-3); }
.aq-project-run__dot { width: var(--space-8); height: var(--space-8); border-radius: var(--radius-pill); box-sizing: border-box; border: 2px solid var(--line-strong); background: var(--surface-raised);
  transition: border-color 300ms, background-color 300ms, transform 300ms cubic-bezier(0.2, 0, 0, 1); }
.aq-project-run__lab { font: 500 12px/16px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-subtle); text-align: center; transition: color 300ms; }
.aq-project-run__stop.is-past .aq-project-run__dot { border-color: var(--flow); }
.aq-project-run__stop.is-on .aq-project-run__dot { border-color: var(--flow); background: var(--flow); transform: scale(1.15); }
.aq-project-run__stop.is-on .aq-project-run__lab, .aq-project-run__stop.is-past .aq-project-run__lab { color: var(--ink); }

@container (max-width: 1100px) {
  .aq-project-run.is-live { column-gap: var(--space-8); }
  .is-live .aq-project-run__t { font-size: 40px; line-height: 44px; }
  .aq-project-run__cur { font-size: 104px; }
  .aq-project-run__lab { font-size: 11px; letter-spacing: 0.02em; }
}

/* Phones: always static; the drawing sits over its text */
@container (max-width: 860px) {
  .aq-project-run { --node: var(--space-8); }
  .aq-project-run__step { grid-template-columns: var(--node, var(--space-12)) minmax(0, 1fr); column-gap: var(--space-4); }
  .aq-project-run__pic { grid-column: 2; grid-row: 1; max-width: 260px; width: 100%; }
  .aq-project-run__text { grid-column: 2; grid-row: 2; padding-top: var(--space-3); }
  .aq-project-run__node { grid-column: 1; grid-row: 1; font-size: 12px; }
  .aq-project-run__steps { gap: var(--space-12); }
  .aq-project-run__t { font-size: 26px; line-height: 32px; }
  .aq-project-run__d { font-size: 16px; line-height: 26px; }
}
/* Phones: a node the water has passed fills with the flow tint */
.aq-project-run__node.is-wet { background: var(--flow-tint); }

/* ---------- ProofFolders: an evidence table as a drawer of manila folders (look "proof-folders"). Each row is the
   standard set on the ground plus its folder (limestone, data-theme="light" so the paper keeps light-theme contrast in
   the dark theme): a tab with the code, a typed slip, clipped proof sheets struck with a stamp, a navy index label.
   Folders overlap upward so each tab sits over the folder before it; the tab steps right row by row. ---------- */
.aq-proof-folders { position: relative; }
.aq-proof-folders__cols, .aq-proof-folders__row { display: grid; grid-template-columns: minmax(0, 0.9fr) minmax(0, 3.1fr); column-gap: var(--space-6); }
.aq-proof-folders__cols { padding-bottom: var(--space-6); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-proof-folders__cols { grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.25fr) minmax(0, 1.1fr) minmax(0, 0.75fr); }
.aq-proof-folders__cols span:nth-child(n+2) { padding-left: var(--space-6); }
.aq-proof-folders__list { list-style: none; margin: 0; padding: var(--space-8) 0 0; }
.aq-proof-folders__row { position: relative; align-items: start; }
.aq-proof-folders__row + .aq-proof-folders__row { margin-top: calc(-1 * var(--space-3)); }

/* The standard, on the ground */
/* the index is the row's own first child (so a standards-map chip matches the standard's cell alone) */
.aq-proof-folders__row > .aq-index { position: absolute; left: 0; top: var(--space-6); }
.aq-proof-folders__std { display: flex; flex-direction: column; gap: var(--space-2); padding-top: var(--space-12); }
.aq-proof-folders__name { margin: 0; display: flex; flex-direction: column; gap: var(--space-1); }
.aq-proof-folders__code { font: 300 30px/36px var(--font-sans); letter-spacing: -0.02em; color: var(--ink); }
.aq-proof-folders__title { font: 400 15px/22px var(--font-sans); color: var(--ink-muted); text-wrap: pretty; }

/* The folder */
.aq-proof-folders__folder {
  position: relative; display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1.1fr) minmax(0, 0.75fr); align-items: start;
  min-height: var(--space-32); padding: var(--space-6) 0 var(--space-8);
  background: var(--limestone); color: var(--on-limestone);
  border-top: 1px solid color-mix(in srgb, var(--on-limestone) 22%, transparent);
  box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--on-limestone) 10%, transparent);
}
.aq-proof-folders__folder > div { padding: 0 var(--space-6); min-width: 0; }
.aq-proof-folders__tab {
  position: absolute; bottom: 100%; left: calc(var(--space-6) + var(--i, 0) * 13%); height: var(--space-8); padding: 0 var(--space-6) 0 var(--space-4);
  display: flex; align-items: center; background: var(--limestone); color: var(--on-limestone);
  border: 1px solid color-mix(in srgb, var(--on-limestone) 22%, transparent); border-bottom: 0;
  clip-path: polygon(0 0, calc(100% - var(--space-3)) 0, 100% 100%, 0 100%);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.06em; white-space: nowrap;
}
/* every second folder a shade deeper, so the files read apart */
.aq-proof-folders__row:nth-child(even) .aq-proof-folders__folder, .aq-proof-folders__row:nth-child(even) .aq-proof-folders__tab { background: color-mix(in srgb, var(--limestone) 93%, var(--on-limestone)); }
/* the slip: typed, set slightly off square */
.aq-proof-folders__slip {
  margin: 0; padding: var(--space-4) var(--space-4) var(--space-6); background: var(--surface-raised); color: var(--ink);
  border: 1px solid var(--line); font: 400 15px/23px var(--font-mono); letter-spacing: -0.01em; transform: rotate(-0.6deg); text-wrap: pretty;
}
.aq-proof-folders__row:nth-child(even) .aq-proof-folders__slip { transform: rotate(0.5deg); }
/* the proof: sheets fanned under a clip */
.aq-proof-folders__proof { position: relative; padding-top: var(--space-2) !important; padding-bottom: var(--space-8) !important; }
.aq-proof-folders__sheets { list-style: none; margin: 0; padding: 0; display: grid; }
.aq-proof-folders__sheet {
  grid-area: auto; position: relative; margin-top: calc(-1 * var(--space-1)); padding: var(--space-3) var(--space-4);
  background: var(--surface-raised); color: var(--ink); border: 1px solid var(--line);
  font: 400 14px/20px var(--font-sans); transform: rotate(calc(1.2deg - var(--j, 0) * 1.6deg)) translateX(calc(var(--j, 0) * var(--space-2)));
}
.aq-proof-folders__sheet:first-child { margin-top: 0; }
.aq-proof-folders__clip {
  position: absolute; z-index: 1; top: calc(-1 * var(--space-2)); left: calc(var(--space-6) + var(--space-8)); width: var(--space-3); height: var(--space-8);
  border: 1.5px solid var(--line-strong); border-radius: var(--radius-pill);
}
.aq-proof-folders__clip::after { content: ""; position: absolute; inset: var(--space-1) calc(var(--space-1) / 2) var(--space-2); border: 1.5px solid var(--line-strong); border-radius: var(--radius-pill); }
/* the stamp, struck over the sheets */
.aq-proof-folders__stamp {
  position: absolute; right: var(--space-2); bottom: 0; z-index: 2; display: flex; flex-direction: column; align-items: center;
  padding: var(--space-1) var(--space-3); border: 3px double var(--flow); color: var(--flow);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; transform: rotate(-7deg); opacity: 0.88; pointer-events: none;
  mix-blend-mode: multiply;
}
.aq-proof-folders__stamp span + span { font-size: 12px; line-height: 14px; letter-spacing: 0.16em; }
.aq-proof-folders__row:nth-child(even) .aq-proof-folders__stamp { transform: rotate(5deg); right: auto; left: 45%; }
/* the index label: navy, the row's link */
.aq-proof-folders__label { margin: 0; padding: var(--space-3) var(--space-4); background: var(--navy); color: var(--on-navy); font: 400 15px/22px var(--font-sans); }
.aq-proof-folders__label a { color: inherit; text-decoration: none; display: block; }
.aq-proof-folders__label a::after { content: "\a0\2192"; }
.aq-proof-folders__label a:hover { text-decoration: underline; text-underline-offset: 3px; }
.aq-proof-folders__label:has(a) { position: relative; min-height: var(--space-12); box-sizing: border-box; }
.aq-proof-folders__label a::before { content: ""; position: absolute; inset: 0; }
.aq-proof-folders__label:has(a:focus-visible) { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-proof-folders__label a:focus-visible { outline: none; }
/* cell names: read by screen readers on desktop (the column heads are drawn), shown on phones */
.aq-proof-folders__k { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; margin: 0; }
.aq-proof-folders .aq-fold__btn { margin-top: var(--space-8); }
.aq-proof-folders__row.aq-standards-map-hit .aq-proof-folders__folder { outline: 2px solid var(--flow); outline-offset: 2px; }

.aq-proof-folders-sec .aq-sec-head { margin-bottom: var(--space-2); }
.aq-proof-folders__how, .aq-proof-folders__go { position: relative; z-index: 1; }

/* motion slides parts in from the side; never let them widen the page */
.aq-section.aq-proof-folders-sec { overflow-x: clip; }

@container (max-width: 860px) {
  .aq-proof-folders__cols { display: none; }
  .aq-proof-folders__list { padding-top: var(--space-6); }
  .aq-proof-folders__row { grid-template-columns: minmax(0, 1fr); }
  .aq-proof-folders__row + .aq-proof-folders__row { margin-top: var(--space-6); }
  .aq-proof-folders__row > .aq-index { top: var(--space-1); }
  .aq-proof-folders__std { padding: 0 0 var(--space-8) var(--space-8); flex-direction: row; align-items: baseline; gap: var(--space-3); }
  .aq-proof-folders__code { font-size: 24px; line-height: 30px; }
  .aq-proof-folders__folder { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-6); padding: var(--space-4) 0 var(--space-6); min-height: 0; }
  .aq-proof-folders__folder > div { padding: 0 var(--space-4); }
  .aq-proof-folders__tab { left: calc(var(--space-4) + var(--i, 0) * 8%); }
  .aq-proof-folders__k { position: static; width: auto; height: auto; overflow: visible; clip-path: none; margin: 0 0 var(--space-2); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-limestone-muted); }
  .aq-proof-folders__clip { left: auto; right: var(--space-8); }
  .aq-proof-folders__stamp, .aq-proof-folders__row:nth-child(even) .aq-proof-folders__stamp { bottom: 0; right: var(--space-6); left: auto; }
}

/* ---------- Prose ---------- */
/* Plain: a few paragraphs within text-max (also used for captions). */
.aq-prose { max-width: var(--text-max); }
.aq-prose p + p { margin-top: var(--space-4); }

/* Sheet (the site's prose block): the first sentence as a large light lead in ink, then the paragraphs in body size in
   ink-muted. White space does the work: no grid, frame, rule, tags or leaders.
   ".aq-prose.aq-prose--sheet" selectors match SplitSection's ".aq-split-section__body .aq-prose p:first-child"
   specificity and win by coming later in bundle.css, so the lead and body keep their own type inside a split. */
.aq-prose--sheet { display: flex; flex-direction: column; gap: var(--space-4); }
.aq-prose.aq-prose--sheet > p { margin: 0; font: 400 16px/26px var(--font-sans); color: var(--ink-muted); text-wrap: pretty; overflow-wrap: break-word; }
.aq-prose.aq-prose--sheet > p.aq-prose__lead {
  margin-bottom: var(--space-2); font: 300 28px/36px var(--font-sans); letter-spacing: -0.01em; color: var(--ink);
  text-wrap: balance;
}

@container (max-width: 860px) {
  .aq-prose.aq-prose--sheet > p.aq-prose__lead { font-size: 22px; line-height: 30px; }
}

/* ---------- ReaderSplit: readers on the navy half, what they read on the limestone half, row against row across a seam ---------- */
.aq-reader-split-sec { position: relative; overflow: hidden; background: var(--limestone); color: var(--on-limestone); }
.aq-reader-split__ground { position: absolute; left: 0; top: 0; bottom: 0; width: 50%; background: var(--navy); transform-origin: 0 50%; }
.aq-reader-split-sec > .aq-in { position: relative; }
.aq-reader-split { --gap: var(--space-16); display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); column-gap: var(--gap, 64px); }
.aq-reader-split__head { grid-column: 1; color: var(--on-navy); padding-right: var(--space-8); }
.aq-reader-split__head .aq-h1 { color: var(--on-navy); }
.aq-reader-split__head .aq-lead { color: var(--on-navy-muted); }
.aq-reader-split__colh { grid-column: 1 / -1; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); column-gap: var(--gap, 64px); margin: 0 0 var(--space-3); padding-top: var(--space-12);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; }
.aq-reader-split__colh span:first-child { color: var(--on-navy-muted); }
.aq-reader-split__colh span + span { color: var(--on-limestone-muted); }
.aq-reader-split > .aq-fold, .aq-reader-split > .aq-reader-split__rows { grid-column: 1 / -1; }
.aq-reader-split-sec .aq-fold__btn { color: var(--on-limestone); border-bottom-color: color-mix(in srgb, var(--on-limestone) 25%, transparent); padding-left: calc(50% + var(--gap, 64px) / 2); }

.aq-reader-split__rows { position: relative; list-style: none; margin: 0; padding: 0; }
.aq-reader-split__rows::before { content: ""; position: absolute; left: 50%; top: 0; bottom: 0; width: 1.5px; margin-left: -0.75px; background: var(--limestone); }
.aq-reader-split__row { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); column-gap: var(--gap, 64px); }
.aq-reader-split__who { display: flex; gap: var(--space-4); align-items: baseline; padding: var(--space-8) var(--space-8) var(--space-8) 0;
  border-top: 1px solid color-mix(in srgb, var(--on-navy-muted) 35%, transparent); color: var(--on-navy); }
.aq-reader-split__who .aq-index { color: var(--on-navy-muted); }
.aq-reader-split__t { margin: 0; font: 300 28px/34px var(--font-sans); letter-spacing: -0.02em; }
.aq-reader-split__what { display: flex; flex-direction: column; gap: var(--space-4); padding: var(--space-8) 0; border-top: 1px solid color-mix(in srgb, var(--on-limestone) 22%, transparent); }
.aq-reader-split__read { margin: 0; font: 400 17px/27px var(--font-mono); letter-spacing: -0.01em; color: var(--on-limestone); }
.aq-reader-split__k { display: block; font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-limestone-muted); }
.aq-reader-split__go { align-self: flex-start; display: flex; flex-direction: column; gap: var(--space-1); min-height: 44px; margin: 0; color: var(--on-limestone); text-decoration: none; font: 400 16px/22px var(--font-sans); }
a.aq-reader-split__go span + span::after { content: " →"; color: var(--flow); }
a.aq-reader-split__go:hover span + span { text-decoration: underline; text-decoration-color: var(--flow); text-underline-offset: 4px; }
a.aq-reader-split__go:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }

/* The tie: a node on the seam at the row's first line, and a short tie across it that draws on hover */
.aq-reader-split__tie { position: absolute; left: calc(50% - var(--gap, 64px) / 2); width: var(--gap, 64px); top: calc(var(--space-8) + var(--space-4)); height: 1.5px; pointer-events: none; }
.aq-reader-split__tie::before { content: ""; position: absolute; inset: 0; background: var(--limestone); transform: scaleX(0.3); transition: transform 400ms cubic-bezier(0.2, 0, 0, 1); }
.aq-reader-split__node { position: absolute; left: 50%; top: 50%; width: var(--space-3); height: var(--space-3); margin: calc(var(--space-3) * -0.5) 0 0 calc(var(--space-3) * -0.5);
  background: var(--navy); border: 1.5px solid var(--limestone); transition: background-color 300ms; }
.aq-reader-split__row:hover .aq-reader-split__tie::before, .aq-reader-split__row:focus-within .aq-reader-split__tie::before { transform: scaleX(1); }
.aq-reader-split__row:hover .aq-reader-split__node, .aq-reader-split__row:focus-within .aq-reader-split__node { background: var(--limestone); }

@container (max-width: 1100px) {
  .aq-reader-split { --gap: var(--space-12); }
  .aq-reader-split__t { font-size: 24px; line-height: 30px; }
}

/* Phones: one column on limestone; each reader is a navy bar over its reading, the seam turns into the bar's edge */
@container (max-width: 860px) {
  .aq-reader-split__ground { display: none; }
  .aq-reader-split__head, .aq-reader-split__head .aq-h1 { color: var(--on-limestone); }
  .aq-reader-split__head .aq-lead { color: var(--on-limestone-muted); }
  .aq-reader-split { grid-template-columns: minmax(0, 1fr); }
  .aq-reader-split__head { padding: 0 0 var(--space-8); }
  .aq-reader-split__colh { display: none; }
  .aq-reader-split__rows::before { display: none; }
  .aq-reader-split__row { grid-template-columns: minmax(0, 1fr); margin-bottom: var(--space-4); }
  .aq-reader-split__who { padding: var(--space-4); background: var(--navy); border-top: 0; }
  .aq-reader-split__t { font-size: 21px; line-height: 27px; }
  .aq-reader-split__what { padding: var(--space-4) var(--space-4) var(--space-4) var(--space-4); border: 1px solid color-mix(in srgb, var(--on-limestone) 22%, transparent); border-top: 0; }
  .aq-reader-split__read { font-size: 15px; line-height: 24px; }
  .aq-reader-split__tie { display: none; }
  .aq-reader-split-sec .aq-fold__btn { padding-left: 0; }
}

/* ---------- Readout: the page's one highlighted figure ---------- */
/* The brand's "proof in numbers": one measurement set large in Geist Mono Light in flow, its unit beside it,
   the method on a limit tag (the StandardTag look), and a one-sentence caption. No frame: white space carries it.
   A limit (--limit) adds a 1 px flow rule under the reading. */
.aq-readout {
  display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
  column-gap: var(--space-12); row-gap: var(--space-6); align-items: end;
}

/* Head: reading on the left, the method tag on the right; font-size here sets the figure */
.aq-readout__head { display: contents; }

.aq-readout__reading {
  grid-column: 1; grid-row: 1 / span 2; align-self: end;
  margin: 0; min-width: 0; padding-bottom: var(--space-4);
  display: flex; flex-wrap: wrap; align-items: baseline;
  font: 300 clamp(64px, 10cqi, 128px)/1 var(--font-mono); letter-spacing: -0.04em; font-variant-numeric: tabular-nums;
  color: var(--flow);
}
.aq-readout--limit .aq-readout__reading { border-bottom: 1px solid var(--flow); }
.aq-readout__figure { min-width: 0; overflow-wrap: anywhere; }
.aq-readout__figure .aq-ph { letter-spacing: -0.02em; }
/* Comparator (<, ≤): smaller, in ink-muted */
.aq-readout__cmp { font-size: 0.45em; letter-spacing: 0; color: var(--ink-muted); }
/* Unit: on the baseline beside the figure */
.aq-readout__unit { margin-left: var(--space-2); font: 400 28px/34px var(--font-mono); letter-spacing: 0; color: var(--ink); }
/* Condition ("@ 25 °C"): small, on its own line under the figure; -1ch cancels the leading no-break space */
.aq-readout__cond {
  flex-basis: 100%; margin: var(--space-3) 0 0 -1ch;
  font: 400 14px/22px var(--font-mono); letter-spacing: 0; color: var(--ink-muted);
}

/* Method: the limit tag, as StandardTag draws it */
.aq-readout__ref { grid-column: 2; grid-row: 1; display: flex; min-width: 0; }
.aq-readout__tag {
  display: inline-flex; align-items: center; min-height: 28px; max-width: 100%; padding: var(--space-1) var(--space-3);
  border: 1px solid var(--line-strong); border-radius: var(--radius-pill);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.04em; color: var(--ink);
  overflow-wrap: anywhere;
}

.aq-readout__caption { grid-column: 2; grid-row: 2; margin: 0; min-width: 0; }

@container (max-width: 860px) {
  .aq-readout { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-4); }
  .aq-readout__reading { grid-column: 1; grid-row: auto; font-size: clamp(48px, 16cqi, 88px); }
  /* Unit drops under the figure */
  .aq-readout__unit { flex-basis: 100%; margin: var(--space-2) 0 0 -1ch; font-size: 24px; line-height: 30px; }
  .aq-readout__ref, .aq-readout__caption { grid-column: 1; grid-row: auto; }
}

/* ---------- RecordAnatomy: one specimen record drawn in zones, each zone's number led to the point it explains ---------- */
.aq-record-anatomy-sec { }
.aq-record-anatomy__stamp { transform-box: view-box; }
/* The sheet is limestone in both themes; the zones are its rows, so it reads as one paper with hairline zone rules. */
.aq-record-anatomy { margin-top: var(--space-4); }
.aq-record-anatomy__rows { list-style: none; margin: 0; padding: 0; }
.aq-record-anatomy__row { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 1fr) minmax(0, 5fr); align-items: center; }
.aq-record-anatomy__zone { position: relative; align-self: stretch; display: flex; align-items: center; padding: var(--space-6) var(--space-8) var(--space-6) var(--space-16);
  background: var(--limestone); color: var(--on-limestone); border-inline: 1px solid color-mix(in srgb, var(--navy) 30%, transparent);
  border-bottom: 1px dashed color-mix(in srgb, var(--navy) 22%, transparent); }
.aq-record-anatomy__row:first-child .aq-record-anatomy__zone { border-top: 1px solid color-mix(in srgb, var(--navy) 30%, transparent); padding-top: var(--space-12); }
.aq-record-anatomy__row:first-child .aq-record-anatomy__zone::before { content: ""; position: absolute; left: var(--space-16); right: var(--space-8); top: var(--space-4); height: var(--space-3);
  border-top: 2px solid var(--navy); border-bottom: 1px solid color-mix(in srgb, var(--navy) 30%, transparent); }
.aq-record-anatomy__row:last-child .aq-record-anatomy__zone { border-bottom: 1px solid color-mix(in srgb, var(--navy) 30%, transparent); padding-bottom: var(--space-12); }
.aq-record-anatomy__mark { position: absolute; left: var(--space-4); top: 50%; transform: translateY(-50%); display: grid; place-items: center; width: var(--space-8); height: var(--space-8);
  border: 1px solid var(--navy); color: var(--navy); font: 500 12px/1 var(--font-mono); transition: background-color 250ms, color 250ms; }
.aq-record-anatomy__row:hover .aq-record-anatomy__mark { background: var(--navy); color: var(--limestone); }
.aq-record-anatomy__svg { display: block; width: 100%; max-width: 420px; height: auto; overflow: visible; }
.aq-record-anatomy__svg path, .aq-record-anatomy__svg circle { fill: none; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.aq-record-anatomy__ln { stroke: var(--navy); stroke-width: 1.5px; }
.aq-record-anatomy__thin { stroke: color-mix(in srgb, var(--navy) 55%, transparent); stroke-width: 1px; }
.aq-record-anatomy__hid { stroke: var(--navy); stroke-width: 1px; stroke-dasharray: 4 4; }
.aq-record-anatomy__limit { stroke: var(--navy); stroke-width: 1.5px; stroke-dasharray: 8 5; }
.aq-record-anatomy__tick { stroke: var(--navy); stroke-width: 1.5px; }
.aq-record-anatomy__flow { stroke: var(--flow); stroke-width: 1.5px; }
.aq-record-anatomy__svg .aq-record-anatomy__fill { fill: var(--navy); stroke: var(--navy); stroke-width: 1.5px; }
.aq-record-anatomy__svg .aq-record-anatomy__sheet { fill: var(--surface-raised); stroke: var(--navy); stroke-width: 1.5px; }
.aq-record-anatomy__svg .aq-record-anatomy__pt { fill: var(--limestone); stroke: var(--flow); stroke-width: 1.5px; }
.aq-record-anatomy__br { font: 300 96px/1 var(--font-sans); fill: var(--navy); }
.aq-record-anatomy__no { font: 500 11px/1 var(--font-mono); fill: var(--navy); }

/* leader: from the zone's edge across the gutter to the point, a dot at the point's end */
.aq-record-anatomy__lead { position: relative; height: 1px; background: var(--line-strong); transform-origin: 0 50%; }
.aq-record-anatomy__lead i { position: absolute; right: 0; top: 50%; width: var(--space-2); height: var(--space-2); margin-top: calc(var(--space-2) / -2); background: var(--ink); }
.aq-record-anatomy__row:hover .aq-record-anatomy__lead { background: var(--flow); }
.aq-record-anatomy__pt-t { padding: var(--space-6) 0 var(--space-6) var(--space-4); }
.aq-record-anatomy__t { margin: 0; display: flex; align-items: baseline; gap: var(--space-3); font: 300 32px/38px var(--font-sans); letter-spacing: -0.02em; color: var(--ink); }
.aq-record-anatomy__n { font: 400 12px/16px var(--font-mono); color: var(--ink-subtle); transform: translateY(-4px); }
.aq-record-anatomy__d { margin: var(--space-2) 0 0; font: 400 16px/26px var(--font-sans); color: var(--ink-muted); max-width: 40ch; }

@container (max-width: 1100px) {
  .aq-record-anatomy__zone { padding-left: var(--space-12); padding-right: var(--space-4); }
  .aq-record-anatomy__mark { left: var(--space-2); }
  .aq-record-anatomy__row:first-child .aq-record-anatomy__zone::before { left: var(--space-12); right: var(--space-4); }
  .aq-record-anatomy__t { font-size: 26px; line-height: 32px; }
}
/* Phones: each zone of the sheet above its point; the leader drops down from the zone to the point */
@container (max-width: 860px) {
  .aq-record-anatomy__row { grid-template-columns: minmax(0, 1fr); }
  .aq-record-anatomy__zone { padding: var(--space-4) var(--space-4) var(--space-4) var(--space-12); border-bottom-style: solid; }
  .aq-record-anatomy__row:first-child .aq-record-anatomy__zone { padding-top: var(--space-8); }
  .aq-record-anatomy__row:last-child .aq-record-anatomy__zone { padding-bottom: var(--space-4); }
  .aq-record-anatomy__row:first-child .aq-record-anatomy__zone::before { left: var(--space-12); right: var(--space-4); top: var(--space-3); }
  .aq-record-anatomy__lead { width: 1px; height: var(--space-6); margin-left: calc(var(--space-6) - 0.5px); transform-origin: 50% 0; }
  .aq-record-anatomy__lead i { right: auto; left: 50%; top: auto; bottom: 0; margin: 0 0 0 calc(var(--space-2) / -2); }
  .aq-record-anatomy__pt-t { padding: var(--space-2) 0 var(--space-8); }
  .aq-record-anatomy__t { font-size: 24px; line-height: 30px; }
}

/* ---------- RecordSlips: each process and the record it leaves (look "record-slips"). Process in light display type on
   the ground; a navy slot at its right edge; the record as a paper slip (surface-raised, data-theme="light") fed out of
   the slot, square, with an empty tick box per record. One flow accent: the slip's top edge. ---------- */
.aq-record-slips-sec { position: relative; }
.aq-record-slips { position: relative; }
.aq-record-slips__cols { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); padding-bottom: var(--space-3); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-record-slips__cols span:first-child { padding-left: calc(var(--space-12) + var(--space-4)); }
.aq-record-slips__cols span + span { padding-left: var(--space-8); }
.aq-record-slips__list { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line-strong); }
.aq-record-slips__row {
  display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); column-gap: 0; align-items: center;
  padding: var(--space-4) 0; border-bottom: 1px solid var(--line);
}
.aq-record-slips__proc { display: grid; grid-template-columns: var(--space-12) minmax(0, 1fr); column-gap: var(--space-4); padding-right: var(--space-12); }
.aq-record-slips__proc > .aq-index { grid-row: 1 / span 3; padding-top: var(--space-2); }
.aq-record-slips__name { margin: 0 0 var(--space-3); font: 300 32px/38px var(--font-sans); letter-spacing: -0.025em; color: var(--ink); text-wrap: balance; transition: color 240ms cubic-bezier(0.2, 0, 0, 1); }
.aq-record-slips__name a { color: inherit; }
.aq-record-slips__k { display: none; margin: 0 0 var(--space-1); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-record-slips__ctl { margin: 0; max-width: 52ch; font: 400 15px/24px var(--font-sans); color: var(--ink-muted); text-wrap: pretty; }

/* the feed: slot and slip */
.aq-record-slips__feed { position: relative; display: flex; align-items: center; min-height: 100%; }
.aq-record-slips__slot {
  flex: none; align-self: stretch; width: var(--space-3); margin: calc(-1 * var(--space-2)) 0; background: var(--navy);
  box-shadow: inset calc(-1 * var(--space-1)) 0 0 color-mix(in srgb, var(--on-navy) 18%, transparent);
}
.aq-record-slips__slip {
  position: relative; flex: 1 1 auto; margin-left: calc(-1 * var(--space-1)); padding: var(--space-4) var(--space-6) var(--space-4) var(--space-8);
  background: var(--surface-raised); color: var(--ink); border: 1px solid var(--line); border-left: 0; border-top: 2px solid var(--flow);
  transform-origin: 0 50%; transition: transform 320ms cubic-bezier(0.2, 0, 0, 1);
}
/* perforation where the slip leaves the slot */
.aq-record-slips__slip::before { content: ""; position: absolute; left: var(--space-3); top: var(--space-2); bottom: var(--space-2); border-left: 1.5px dotted var(--line-strong); }
.aq-record-slips__recs { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--space-2); }
.aq-record-slips__recs li { display: grid; grid-template-columns: var(--space-4) minmax(0, 1fr); column-gap: var(--space-3); align-items: baseline; font: 400 16px/24px var(--font-sans); color: var(--ink); text-wrap: pretty; }
.aq-record-slips__box { width: var(--space-3); height: var(--space-3); border: 1.5px solid var(--line-strong); transform: translateY(1px); }
.aq-record-slips__row:hover .aq-record-slips__slip { transform: translateX(var(--space-3)); }
.aq-record-slips__row:hover .aq-record-slips__name { color: var(--flow); }

/* Fold: desktop shows every process; the fold works on phones only */
.aq-fold:not(.is-open) .aq-record-slips__row.aq-fold-x { display: grid; }
.aq-fold:has(> .aq-record-slips__list) > .aq-fold__btn { display: none; }

@media (prefers-reduced-motion: reduce) { .aq-record-slips__slip, .aq-record-slips__name { transition: none; } }

@container (max-width: 860px) {
  .aq-record-slips__cols { display: none; }
  .aq-record-slips__k { display: block; }
  .aq-record-slips__row { grid-template-columns: minmax(0, 1fr); row-gap: 0; padding: var(--space-6) 0 var(--space-8); }
  .aq-record-slips__proc { grid-template-columns: var(--space-8) minmax(0, 1fr); column-gap: var(--space-3); padding-right: 0; padding-bottom: var(--space-4); }
  .aq-record-slips__name { font-size: 26px; line-height: 32px; margin-bottom: var(--space-2); }
  .aq-record-slips__feed { flex-direction: column; align-items: stretch; padding-left: calc(var(--space-8) + var(--space-3)); }
  .aq-record-slips__slot { width: auto; height: var(--space-2); margin: 0 calc(-1 * var(--space-2)); }
  .aq-record-slips__slip { margin: calc(-1 * var(--space-1)) 0 0; padding: var(--space-6) var(--space-4) var(--space-4); border-left: 1px solid var(--line); border-top: 0; border-bottom: 2px solid var(--flow); transform-origin: 50% 0; }
  .aq-record-slips__slip::before { left: var(--space-2); right: var(--space-2); top: var(--space-2); bottom: auto; border-left: 0; border-top: 1.5px dotted var(--line-strong); }
  .aq-record-slips__recs li { font-size: 15px; line-height: 22px; }
  .aq-record-slips__row:hover .aq-record-slips__slip { transform: translateY(var(--space-1)); }
  .aq-fold:not(.is-open) .aq-record-slips__row.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-record-slips__list) > .aq-fold__btn { display: flex; }
}

/* ---------- RedlineSheet: qualification failures as design-review markups on one limestone drawing sheet (look
   "redline-sheet"). The sheet is data-theme="light" paper so it keeps light-theme contrast in the dark theme. Each
   column: revision triangle + what fails (fail ink: qualification status, always with its words), the figure with the
   mistake clouded in fail and the correction drawn in flow, the mistake struck through, the fix as the flow note. ---------- */
.aq-redline-sheet {
  position: relative; background: var(--limestone); color: var(--on-limestone);
  padding: var(--space-12) var(--space-8) var(--space-16);
  border: 1px solid color-mix(in srgb, var(--on-limestone) 26%, transparent);
  outline: 1px solid color-mix(in srgb, var(--on-limestone) 14%, transparent); outline-offset: calc(-1 * var(--space-3));
}
/* zone numbers along the top border, as on a drawing sheet */
.aq-redline-sheet__zones { position: absolute; top: var(--space-3); left: var(--space-3); right: var(--space-3); display: flex; pointer-events: none; }
.aq-redline-sheet__zones span {
  flex: 1; padding: var(--space-1) 0; text-align: center; font: 400 12px/16px var(--font-mono); color: var(--on-limestone-muted);
  border-left: 1px solid color-mix(in srgb, var(--on-limestone) 14%, transparent);
}
.aq-redline-sheet__zones span:first-child { border-left: 0; }
.aq-redline-sheet__list { list-style: none; margin: 0; padding: var(--space-8) 0 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); }
.aq-redline-sheet__list { grid-template-rows: repeat(4, auto); row-gap: var(--space-4); }
.aq-redline-sheet__item { display: grid; grid-row: span 4; grid-template-rows: subgrid; align-content: start; padding: 0 var(--space-6); min-width: 0; }
.aq-redline-sheet__item + .aq-redline-sheet__item { border-left: 1px solid color-mix(in srgb, var(--on-limestone) 16%, transparent); }

/* what fails, with its revision triangle */
.aq-redline-sheet__head { position: relative; padding-left: var(--space-12); min-height: var(--space-24); }
.aq-redline-sheet__rev {
  position: absolute; left: 0; top: 0; width: var(--space-8); height: var(--space-8); display: grid; place-items: end center;
  padding-bottom: var(--space-1); box-sizing: border-box; font: 500 12px/16px var(--font-mono); color: var(--fail);
  background: var(--fail); clip-path: polygon(50% 0, 100% 100%, 0 100%);
}
.aq-redline-sheet__rev::before { content: ""; position: absolute; inset: 0; background: var(--limestone); clip-path: polygon(50% 9%, 93% 95%, 7% 95%); }
.aq-redline-sheet__rev { isolation: isolate; }
.aq-redline-sheet__rev::before { z-index: -1; }
.aq-redline-sheet__k { margin: 0 0 var(--space-2); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-limestone-muted); }
.aq-redline-sheet__k--fail { color: var(--fail); }
.aq-redline-sheet__k--flow { color: var(--flow); }
.aq-redline-sheet__fail { margin: 0; font: 300 24px/30px var(--font-sans); letter-spacing: -0.015em; color: var(--on-limestone); text-wrap: balance; }

/* the figure: the design as drawn, marked up */
.aq-redline-sheet__fig { margin: 0; padding: var(--space-3); background: color-mix(in srgb, var(--limestone) 70%, var(--surface-raised)); border: 1px solid color-mix(in srgb, var(--on-limestone) 14%, transparent); }
.aq-redline-sheet__fig svg { display: block; width: 100%; height: auto; overflow: visible; }
.aq-redline-sheet__fig * { vector-effect: non-scaling-stroke; stroke-linecap: round; stroke-linejoin: round; }
.aq-redline-sheet__ln { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1.5; }
.aq-redline-sheet__thin { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1; }
.aq-redline-sheet__txt { fill: none; stroke: color-mix(in srgb, var(--on-limestone) 30%, transparent); stroke-width: 4; stroke-linecap: butt; }
.aq-redline-sheet__gap { fill: none; stroke: var(--fail); stroke-width: 1; stroke-dasharray: 3 3; }
.aq-redline-sheet__paper { fill: var(--surface-raised); stroke: color-mix(in srgb, var(--on-limestone) 22%, transparent); stroke-width: 1; }
.aq-redline-sheet__bar { fill: color-mix(in srgb, var(--on-limestone) 18%, transparent); }
.aq-redline-sheet__avg { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1; stroke-dasharray: 5 4; }
.aq-redline-sheet__flw { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1.5; }
.aq-redline-sheet__cl { fill: none; stroke: var(--fail); stroke-width: 1.5; }
.aq-redline-sheet__tri .aq-redline-sheet__cl { fill: var(--limestone); }
.aq-redline-sheet__fixln { fill: none; stroke: var(--flow); stroke-width: 2; }
.aq-redline-sheet__lbl { font: 400 11px/1 var(--font-mono); fill: var(--on-limestone-muted); stroke: none; letter-spacing: 0.04em; }
.aq-redline-sheet__lbl--fail { fill: var(--fail); font-weight: 500; }
.aq-redline-sheet__lbl--flow { fill: var(--flow); font-weight: 500; }

/* the mistake, struck through in fail; the fix, a flow markup note */
.aq-redline-sheet__err { padding-left: var(--space-3); border-left: 2px solid var(--fail); }
.aq-redline-sheet__mistake { margin: 0; font: 400 16px/24px var(--font-sans); color: var(--on-limestone); text-decoration: line-through; text-decoration-color: var(--fail); text-decoration-thickness: 1.5px; text-wrap: pretty; }
.aq-redline-sheet__fix { padding-left: var(--space-3); border-left: 2px solid var(--flow); }
.aq-redline-sheet__note { margin: 0; font: 400 16px/24px var(--font-sans); color: var(--on-limestone); text-wrap: pretty; }

/* title block, bottom right */
.aq-redline-sheet__block {
  position: absolute; right: var(--space-3); bottom: var(--space-3); display: flex;
  border: 1px solid color-mix(in srgb, var(--on-limestone) 22%, transparent); font: 400 12px/16px var(--font-mono); color: var(--on-limestone-muted);
}
.aq-redline-sheet__block span { padding: var(--space-1) var(--space-3); }
.aq-redline-sheet__block span + span { border-left: 1px solid color-mix(in srgb, var(--on-limestone) 22%, transparent); }

/* hover: the markup being read inks harder */
.aq-redline-sheet__item:hover .aq-redline-sheet__cl { stroke-width: 2.25; }
.aq-redline-sheet__item:hover .aq-redline-sheet__fixln { stroke-width: 2.75; }

@container (max-width: 860px) {
  .aq-redline-sheet { padding: var(--space-12) var(--space-4) var(--space-16); }
  .aq-redline-sheet__zones span:nth-child(n+4) { display: none; }
  .aq-redline-sheet__list { grid-template-columns: minmax(0, 1fr); padding-top: var(--space-4); }
  .aq-redline-sheet__item { grid-row: auto; grid-template-rows: none; row-gap: var(--space-4); padding: var(--space-8) 0; }
  .aq-redline-sheet__item:first-child { padding-top: var(--space-4); }
  .aq-redline-sheet__item + .aq-redline-sheet__item { border-left: 0; border-top: 1px solid color-mix(in srgb, var(--on-limestone) 16%, transparent); }
  .aq-redline-sheet__head { min-height: 0; }
  .aq-redline-sheet__fail { font-size: 22px; line-height: 28px; }
  .aq-redline-sheet__block span:nth-child(2) { display: none; }
}
.aq-section.aq-redline-sheet-sec { overflow-x: clip; }
.aq-redline-sheet__mark, .aq-redline-sheet__fixg { transform-box: fill-box; }

/* pass 9b, concept svc-design.0: the plant's P&ID as a navy band across the head of the sheet (data-theme dark, so
   the fail and flow inks stay readable on navy in both themes), each failure pinned where it happens. The camera
   (__cam) zooms onto a pin while a markup column is pointed at; a spotlight (__dim) dims the rest. */
.aq-redline-sheet__band { position: relative; margin: var(--space-8) 0 var(--space-4); background: var(--navy); overflow: hidden; }
.aq-redline-sheet__band svg { display: block; width: 100%; height: auto; }
.aq-redline-sheet__cam { transform-box: view-box; transform-origin: 0 0; transition: transform 550ms cubic-bezier(0.22, 0.75, 0.22, 1); }
.aq-redline-sheet__band * { vector-effect: non-scaling-stroke; }
.aq-redline-sheet__grid { fill: none; stroke: var(--on-navy-muted); stroke-width: 1; opacity: 0.1; }
.aq-redline-sheet__p { fill: none; stroke: var(--on-navy-muted); stroke-width: 1.25; stroke-linejoin: round; stroke-linecap: round; }
.aq-redline-sheet__p--w { stroke: var(--flow); stroke-width: 1.75; }
.aq-redline-sheet__p--chev { stroke: var(--flow); stroke-width: 1.5; }
.aq-redline-sheet__pl { font: 400 11px var(--font-mono); fill: var(--on-navy-muted); letter-spacing: 0.04em; }
.aq-redline-sheet__ring { fill: none; stroke: var(--fail); stroke-width: 1.25; stroke-dasharray: 4 3; }
.aq-redline-sheet__ptri { fill: var(--navy); stroke: var(--fail); stroke-width: 1.5; stroke-linejoin: round; }
.aq-redline-sheet__pn { font: 500 12px var(--font-mono); fill: var(--fail); }
.aq-redline-sheet__pin.is-on .aq-redline-sheet__ring { stroke-dasharray: none; stroke-width: 2; }
