.aq-response-lanes__num {
  font: 300 88px/72px var(--font-sans); letter-spacing: -0.05em; font-variant-numeric: tabular-nums;
  color: transparent; -webkit-text-stroke: 1.5px var(--line-strong);
}
.aq-response-lanes__row.is-first .aq-response-lanes__num { color: var(--flow); -webkit-text-stroke-color: var(--flow); }
.aq-response-lanes__t { grid-column: 2; margin: 0; display: flex; flex-direction: column; gap: var(--space-1); font: 300 22px/28px var(--font-sans); letter-spacing: -0.01em; color: var(--ink); text-wrap: balance; }
.aq-response-lanes__row:not(.is-sev) .aq-response-lanes__t { grid-column: 1 / -1; padding-left: calc(var(--space-16) + var(--space-4)); }
.aq-response-lanes__sev { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-response-lanes__row.is-first .aq-response-lanes__sev { color: var(--flow); }
.aq-response-lanes__sr, .aq-response-lanes__zk { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* The lane: one line from the start mark through both zones */
.aq-response-lanes__lane { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); padding-top: var(--space-2); }
.aq-response-lanes__line { position: absolute; left: 0; right: 0; top: calc(var(--space-2) + 6px); height: 0; border-top: 1.5px solid var(--line-strong);
  transform: scaleX(var(--aq-line, 1)); transform-origin: left center; }
