  .aq-response-lanes__stops > li { position: relative; }
  .aq-response-lanes__node { position: absolute; left: calc(-1 * var(--space-8)); top: var(--space-1); }
  .aq-response-lanes__lane .aq-response-lanes__node { left: calc(-1 * var(--space-8) - 1px); }
}
.aq-response-lanes-sec .aq-sec-head .aq-lead { max-width: 52ch; }
.aq-response-lanes { display: block; }
.aq-response-lanes__what { display: block; }

/* ---------- RetrofitPlant: upgrades on the running plant, existing faint and new bold (look "retrofit-plant") ----------
   A navy band; the ink tokens take on-navy values inside. The sheet: IsoKit on navy (aq-iso--navy) with the existing
   plant dropped to 40 % and the picked upgrade's stages lit (is-lit, flow lines), a legend under it. Below, 5/7: the
   tab list (huge light index, upgrade name; the selected tab carries a limestone rule and full-strength text) and the
   panel (terms as a three-column definition list with mono keys, then where to start as a link). Phones: tabs hidden,
   every panel shown as a card with its stage drawn small. */
.aq-retrofit-plant-sec {
  --ink: var(--on-navy); --ink-muted: var(--on-navy-muted); --ink-subtle: var(--on-navy-muted);
  --line: color-mix(in srgb, var(--on-navy) 18%, transparent); --line-strong: color-mix(in srgb, var(--on-navy) 45%, transparent);
  --rp-flow: color-mix(in srgb, var(--flow) 40%, var(--on-navy));
}
.aq-retrofit-plant-sec .aq-sec-head .aq-h1 { font: 300 56px/60px var(--font-sans); letter-spacing: -0.03em; color: var(--on-navy); max-width: 20ch; }
.aq-retrofit-plant-sec .aq-ph { background: transparent; color: var(--on-navy); outline: 1px dashed var(--on-navy-muted); outline-offset: -1px; }
.aq-retrofit-plant { position: relative; }
.aq-retrofit-plant__sheet { position: relative; border: 1px solid var(--line); }
.aq-retrofit-plant__svg { display: block; width: 100%; height: auto; }
.aq-retrofit-plant__svg.is-retro .aq-iso__part, .aq-retrofit-plant__svg.is-retro .aq-iso__pipe { transition: opacity 400ms cubic-bezier(0.2, 0, 0, 1); }
.aq-retrofit-plant__svg.is-retro .aq-iso__part:not(.is-lit), .aq-retrofit-plant__svg.is-retro .aq-iso__pipe:not(.is-lit) { opacity: 0.28; }
.aq-retrofit-plant__svg .aq-iso__part.is-lit .aq-iso__eq, .aq-retrofit-plant__svg .aq-iso__part.is-lit .aq-iso__ln { stroke-width: 2; }
.aq-retrofit-plant__cam { transition: transform 900ms cubic-bezier(0.65, 0, 0.35, 1); }
.aq-retrofit-plant__kbox { fill: var(--navy); stroke: var(--line-strong); stroke-width: 1; vector-effect: non-scaling-stroke; }
.aq-retrofit-plant__kplant use { fill: var(--navy); stroke: var(--on-navy-muted); }
/* the clone does not match the navy-sheet rules (their ancestor is outside its shadow tree): it inherits these */
.aq-retrofit-plant__kwin { fill: color-mix(in srgb, var(--rp-flow, var(--flow)) 12%, transparent); stroke: var(--rp-flow, var(--flow)); stroke-width: 1.5; transition: transform 900ms cubic-bezier(0.65, 0, 0.35, 1); }
@media (prefers-reduced-motion: reduce) { .aq-retrofit-plant__cam, .aq-retrofit-plant__kwin { transition: none; } }
.aq-retrofit-plant__legend { position: absolute; right: 0; top: 100%; margin: var(--space-2) 0 0; display: flex; align-items: center; gap: var(--space-2); font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-retrofit-plant__sw { display: inline-block; width: var(--space-6); border-top: 1.5px solid var(--on-navy-muted); opacity: 0.5; }
.aq-retrofit-plant__sw--new { border-top: 2px solid var(--rp-flow, var(--flow)); opacity: 1; margin-left: var(--space-4); }
.aq-retrofit-plant__pick { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: var(--space-12); margin-top: var(--space-8); }
.aq-retrofit-plant__tabs { display: flex; flex-direction: column; border-top: 1px solid var(--line-strong); }
.aq-retrofit-plant__tab { display: grid; grid-template-columns: var(--space-12) minmax(0, 1fr); align-items: baseline; gap: var(--space-3); min-height: 44px; padding: var(--space-4) var(--space-4) var(--space-4) 0; background: none; border: 0; border-bottom: 1px solid var(--line); border-left: 2px solid transparent; color: var(--on-navy-muted); text-align: left; cursor: pointer; transition: color 200ms ease, border-color 200ms ease, padding 200ms ease; }
.aq-retrofit-plant__tab:hover { color: var(--on-navy); }
.aq-retrofit-plant__tab:focus-visible { outline: 2px solid var(--focus); outline-offset: -2px; }
.aq-retrofit-plant__tab[aria-selected="true"] { color: var(--on-navy); border-left-color: var(--limestone); padding-left: var(--space-4); }
.aq-retrofit-plant__tn { font: 500 12px/16px var(--font-mono); color: var(--on-navy-muted); }
.aq-retrofit-plant__tt { font: 300 22px/28px var(--font-sans); letter-spacing: -0.01em; text-wrap: balance; }
.aq-retrofit-plant__panel { padding-top: var(--space-2); }
.aq-retrofit-plant__panel.is-off { display: none; }
.aq-retrofit-plant__mfig { display: none; }
.aq-retrofit-plant__pt { display: none; }
.aq-retrofit-plant__terms { margin: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-6); border-top: 1px solid var(--line-strong); padding-top: var(--space-4); }
.aq-retrofit-plant__term dt { font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-retrofit-plant__term dd { margin: var(--space-2) 0 0; font: 400 16px/24px var(--font-sans); color: var(--on-navy); text-wrap: pretty; }
.aq-retrofit-plant__term--3 dd { font: 300 24px/30px var(--font-sans); letter-spacing: -0.01em; }
.aq-retrofit-plant .aq-retrofit-plant__go { margin: var(--space-8) 0 0; display: flex; flex-direction: column; gap: var(--space-2); }
.aq-retrofit-plant__gk { font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-retrofit-plant__go a { font: 300 28px/34px var(--font-sans); letter-spacing: -0.015em; color: var(--on-navy); text-decoration: none; }
.aq-retrofit-plant__go a::after { content: " →"; color: var(--rp-flow, var(--flow)); }
.aq-retrofit-plant__go a:hover { color: var(--rp-flow, var(--flow)); }

@container (max-width: 860px) {
  .aq-retrofit-plant-sec .aq-sec-head .aq-h1 { font: 300 36px/42px var(--font-sans); }
  .aq-retrofit-plant__sheet, .aq-retrofit-plant__tabs { display: none; }
  .aq-retrofit-plant__pick { display: block; margin: 0; }
  .aq-retrofit-plant__panel, .aq-retrofit-plant__panel.is-off { display: grid; grid-template-columns: minmax(0, 1fr) calc(var(--space-16) + var(--space-8)); column-gap: var(--space-3); padding: var(--space-6) 0; border-top: 1px solid var(--line-strong); }
  .aq-retrofit-plant__mfig { display: block; grid-column: 2; grid-row: 1; align-self: start; }
  .aq-retrofit-plant__mini { display: block; width: 100%; height: auto; }
  .aq-retrofit-plant__mini .aq-iso__part { opacity: 1; }
  .aq-retrofit-plant__pt { display: flex; flex-direction: column; gap: var(--space-1); grid-column: 1; grid-row: 1; margin: 0; font: 300 22px/28px var(--font-sans); color: var(--on-navy); }
  .aq-retrofit-plant__terms { grid-column: 1 / -1; grid-template-columns: minmax(0, 1fr); gap: var(--space-3); margin-top: var(--space-4); }
  .aq-retrofit-plant__term--3 dd { font-size: 20px; line-height: 26px; }
  .aq-retrofit-plant .aq-retrofit-plant__go { grid-column: 1 / -1; margin-top: var(--space-6); padding-top: var(--space-4); border-top: 1px solid var(--line); }
  .aq-retrofit-plant__go a { font-size: 22px; line-height: 28px; }
}

/* ---------- ReturnSlips: what each request returns, as an exchange of paper slips on a limestone band ----------
   A row per situation: what you have, large and light, on the left; a pipe with its arrow across the gutter; what comes
   back on the right as paper slips (one per returned item) with "When" and "Cost" fields. The wrapper carries
   data-theme="light" so the slips keep light tokens on the limestone ground in both themes. */
.aq-return-slips-wrap { display: flex; flex-direction: column; gap: var(--space-12); color: var(--on-limestone); }
.aq-return-slips { --rs-gut: var(--space-16); }
.aq-return-slips__cols {
  margin: 0 0 var(--space-4); display: grid; grid-template-columns: minmax(0, 3fr) var(--rs-gut, var(--space-16)) minmax(0, 9fr);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-limestone-muted);
}
.aq-return-slips__cols > span + span { grid-column: 3; }
.aq-return-slips__rows { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line-strong); }
.aq-return-slips__row {
  position: relative; display: grid; grid-template-columns: minmax(0, 3fr) var(--rs-gut, var(--space-16)) minmax(0, 9fr); align-items: start;
  padding-block: var(--space-8); border-bottom: 1px solid var(--line-strong);
}

/* What you have: index and the situation, large and light */
.aq-return-slips__have { display: grid; grid-template-columns: var(--space-12) minmax(0, 1fr); align-items: baseline; padding-right: var(--space-4); }
.aq-return-slips__i { font: 400 13px/20px var(--font-mono); font-variant-numeric: tabular-nums; color: var(--on-limestone-muted); }
.aq-return-slips__s { margin: 0; font: 300 32px/38px var(--font-sans); letter-spacing: -0.02em; color: var(--on-limestone); text-wrap: balance; }
.aq-return-slips__s a { color: inherit; text-decoration-thickness: 1px; text-underline-offset: 4px; }

/* The pipe: twin wall with the water arrow, from what you have to what comes back */
.aq-return-slips__pipe { position: relative; align-self: start; margin-top: var(--space-4); height: var(--space-3);
  border-block: 1.5px solid var(--line-strong); transform: scaleX(var(--aq-pipe, 1)); transform-origin: left center; }
.aq-return-slips__pipe i { position: absolute; left: 0; right: var(--space-2); top: 50%; height: 0; border-top: 1.5px solid var(--flow);
  transform: scaleX(var(--aq-water, 1)); transform-origin: left center; }
.aq-return-slips__pipe::after { content: ""; position: absolute; right: calc(-1 * var(--space-1)); top: 50%; width: var(--space-3); height: var(--space-3);
  border-top: 1.5px solid var(--flow); border-right: 1.5px solid var(--flow); transform: translateY(-50%) rotate(45deg); }

/* The slips: paper with a folded corner and a ruled header, the returned item, then When and Cost */
.aq-return-slips__slips { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-4); row-gap: 0; }
.aq-return-slips__slip:nth-child(n+5) { margin-top: var(--space-4); }
.aq-return-slips__slip:only-child { grid-column: span 2; }
.aq-return-slips__slip {
  position: relative; display: grid; grid-row: span 3; grid-template-rows: subgrid; row-gap: var(--space-3); min-width: 0;
  padding: var(--space-4);
  background: var(--surface-raised); color: var(--ink); border: 1px solid var(--line);
  clip-path: polygon(0 0, calc(100% - var(--space-6)) 0, 100% var(--space-6), 100% 100%, 0 100%);
}
.aq-return-slips__slip::after { content: ""; position: absolute; right: 0; top: 0; width: var(--space-6); height: var(--space-6);
  background: var(--line-strong); clip-path: polygon(0 0, 100% 100%, 0 100%); }
.aq-return-slips__ruling { display: flex; gap: var(--space-1); }
.aq-return-slips__ruling i { display: block; height: 3px; width: var(--space-6); background: var(--line-strong); }
.aq-return-slips__ruling i.is-k { background: var(--flow); }
.aq-return-slips__t { margin: 0; font: 400 17px/24px var(--font-sans); color: var(--ink); text-wrap: pretty; }
.aq-return-slips__t a { color: var(--flow); text-underline-offset: 4px; text-decoration-thickness: 1px; }
.aq-return-slips__f { margin: 0; display: flex; flex-direction: column; gap: var(--space-2); padding-top: var(--space-3); border-top: 1px dashed var(--line-strong); }
.aq-return-slips__f > div { display: flex; flex-direction: column; gap: var(--space-1); }
.aq-return-slips__f dt { display: inline-flex; align-items: center; gap: var(--space-1); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-return-slips__f dd { margin: 0; font: 400 14px/22px var(--font-sans); color: var(--ink); overflow-wrap: break-word; }
.aq-return-slips__ic { width: 12px; height: 12px; background-color: var(--ink-muted); }
.aq-return-slips .aq-fold__btn { color: var(--on-limestone-muted); }

@media (prefers-reduced-motion: no-preference) {
  .aq-return-slips__slip { transition: transform 240ms cubic-bezier(0.2, 0, 0, 1), border-color 240ms; }
  .aq-return-slips__pipe { transition: border-color 240ms; }
  .aq-return-slips__row:hover .aq-return-slips__slip, .aq-return-slips__row:focus-within .aq-return-slips__slip { transform: translateY(calc(-1 * var(--space-1))); border-color: var(--line-strong); }
  .aq-return-slips__row:hover .aq-return-slips__pipe, .aq-return-slips__row:focus-within .aq-return-slips__pipe { border-color: var(--flow); }
}

@container (max-width: 860px) {
  .aq-return-slips-wrap { gap: var(--space-8); }
  .aq-return-slips__cols { display: none; }
  .aq-return-slips__row { grid-template-columns: minmax(0, 1fr); padding-block: var(--space-6); row-gap: var(--space-3); }
  .aq-return-slips__have { grid-template-columns: var(--space-8) minmax(0, 1fr); padding-right: 0; }
  .aq-return-slips__s { font-size: 24px; line-height: 30px; }
  /* the pipe turns down: from the situation into its slips */
  .aq-return-slips__pipe { justify-self: start; margin: 0 0 0 calc(var(--space-8) + var(--space-2)); width: var(--space-3); height: var(--space-8);
    border-block: 0; border-inline: 1.5px solid var(--line-strong); transform: scaleY(var(--aq-pipe, 1)); transform-origin: center top; }
  .aq-return-slips__pipe i { left: 50%; right: auto; top: 0; bottom: var(--space-2); height: auto; border-top: 0; border-left: 1.5px solid var(--flow);
    transform: scaleY(var(--aq-water, 1)); transform-origin: center top; }
  .aq-return-slips__pipe::after { right: auto; left: 50%; top: auto; bottom: calc(-1 * var(--space-1)); transform: translateX(-50%) rotate(135deg); }
  .aq-return-slips__slips { grid-template-columns: minmax(0, 1fr); gap: var(--space-3); }
  .aq-return-slips__slip { display: flex; flex-direction: column; gap: var(--space-3); }
  .aq-return-slips__slip:nth-child(n+5) { margin-top: 0; }
  .aq-return-slips__slip:only-child { grid-column: auto; }
  .aq-return-slips__f > div { display: grid; grid-template-columns: minmax(0, 4.5rem) minmax(0, 1fr); column-gap: var(--space-3); align-items: baseline; }
  .aq-return-slips__t { font-size: 16px; line-height: 24px; }
}
.aq-return-slips-sec .aq-sec-head .aq-h1 { color: var(--on-limestone); }

/* ---------- ReviewReticles: assessment areas as a drawing register with one viewfinder (look "review-reticles") ----------
   A limestone band (data-theme="light" on the section: paper in both themes). The sheet: an outer navy hairline frame,
   a zone band with numbers (top, bottom) and letters (sides), an inner frame. Inside, the register (7 of 12) and the
   viewer (5 of 12) split by a hairline. Register rows: number and area code in mono, the name light 32 px (the
   control), the line 15 px; the picked row has a flow rule on its left and its number in flow. The viewer: a square
   viewfinder (navy corner brackets, faint crosshair, "01 / 06" in mono) whose window holds a vertical reel of the
   drawings, slid to the picked one (240 ms cubic-bezier(.2,.85,.25,1), instant for keyboard and reduced motion); in the sheet's
   bottom right corner a title block (Aquemi, the section's nav name, the area, its number). The scan line is a flow hairline the
   motion sweeps once. Phones: no zones and no viewer; each row has its own small square viewfinder. */
.aq-review-reticles-sec .aq-sec-head .aq-h1 { font: 300 56px/60px var(--font-sans); letter-spacing: -0.03em; }
.aq-review-reticles { --rr-line: color-mix(in srgb, var(--navy) 45%, transparent); --rr-faint: color-mix(in srgb, var(--on-limestone-muted) 25%, transparent); position: relative; padding: var(--space-8); border: 1px solid var(--rr-line, var(--line-strong)); color: var(--on-limestone); }
.aq-review-reticles__z { position: absolute; display: flex; font: 500 11px/16px var(--font-mono); letter-spacing: 0.06em; color: var(--on-limestone-muted); }
.aq-review-reticles__z span { flex: 1; display: grid; place-items: center; }
.aq-review-reticles__z--t, .aq-review-reticles__z--b { left: var(--space-8); right: var(--space-8); height: var(--space-8); }
.aq-review-reticles__z--t { top: 0; }
.aq-review-reticles__z--b { bottom: 0; }
.aq-review-reticles__z--t span + span, .aq-review-reticles__z--b span + span { border-left: 1px solid var(--rr-line, var(--line-strong)); }
.aq-review-reticles__z--l, .aq-review-reticles__z--r { top: var(--space-8); bottom: var(--space-8); width: var(--space-8); flex-direction: column; }
.aq-review-reticles__z--l { left: 0; }
.aq-review-reticles__z--r { right: 0; }
.aq-review-reticles__z--l span + span, .aq-review-reticles__z--r span + span { border-top: 1px solid var(--rr-line, var(--line-strong)); }
.aq-review-reticles__sheet { display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); border: 1px solid var(--rr-line, var(--line-strong)); }

/* the register */
.aq-review-reticles__reg { list-style: none; margin: 0; padding: var(--space-6) var(--space-8) var(--space-8); }
.aq-review-reticles__item { position: relative; display: grid; grid-template-columns: var(--space-12) var(--space-16) minmax(0, 1fr); column-gap: var(--space-2); padding: var(--space-4) 0; border-bottom: 1px solid var(--rr-faint, var(--line)); }
.aq-review-reticles__item::before { content: ""; position: absolute; left: calc(-1 * var(--space-8)); top: -1px; bottom: -1px; border-left: 3px solid var(--flow); transform: scaleY(0); transform-origin: 50% 0; transition: transform 240ms cubic-bezier(0.2, 0.85, 0.25, 1); }
.aq-review-reticles__item.is-on::before { transform: none; }
.aq-review-reticles__no2, .aq-review-reticles__code { grid-row: 1; padding-top: var(--space-3); font: 500 13px/16px var(--font-mono); letter-spacing: 0.04em; color: var(--on-limestone-muted); transition: color 160ms ease; }
.aq-review-reticles__no2 { grid-column: 1; }
.aq-review-reticles__code { grid-column: 2; font-size: 12px; letter-spacing: 0.08em; }
.aq-review-reticles__item.is-on .aq-review-reticles__no2, .aq-review-reticles__item.is-on .aq-review-reticles__code { color: var(--flow); }
.aq-review-reticles__t { grid-column: 3; grid-row: 1; margin: 0; font: 300 32px/40px var(--font-sans); letter-spacing: -0.02em; }
.aq-review-reticles__pick { display: block; width: 100%; min-height: var(--space-12); margin: 0; padding: 0; border: 0; background: none; font: inherit; letter-spacing: inherit; color: var(--on-limestone); text-align: left; text-decoration: none; cursor: pointer; }
.aq-review-reticles__pick:focus-visible { outline: 2px solid var(--flow); outline-offset: var(--space-1); }
a.aq-review-reticles__pick:hover { color: var(--flow); }
.aq-review-reticles__d { grid-column: 3; grid-row: 2; margin: 0; max-width: 46ch; font: 400 15px/22px var(--font-sans); color: var(--on-limestone-muted); text-wrap: pretty; }

/* viewfinders (the big one in the viewer, the small ones on phones) */
.aq-review-reticles__vf { --in: var(--space-3); position: relative; display: block; border: 1px solid var(--rr-faint, var(--line)); overflow: hidden; }
.aq-review-reticles__br { position: absolute; width: var(--space-8); height: var(--space-8); border: 0 solid var(--navy); transition: transform 300ms cubic-bezier(0.2, 0, 0, 1); }
.aq-review-reticles__br--tl { left: var(--in, var(--space-3)); top: var(--in, var(--space-3)); border-left-width: 2px; border-top-width: 2px; }
.aq-review-reticles__br--tr { right: var(--in, var(--space-3)); top: var(--in, var(--space-3)); border-right-width: 2px; border-top-width: 2px; }
.aq-review-reticles__br--bl { left: var(--in, var(--space-3)); bottom: var(--in, var(--space-3)); border-left-width: 2px; border-bottom-width: 2px; }
.aq-review-reticles__br--br { right: var(--in, var(--space-3)); bottom: var(--in, var(--space-3)); border-right-width: 2px; border-bottom-width: 2px; }
.aq-review-reticles__sheet:hover .aq-review-reticles__big .aq-review-reticles__br--tl { transform: translate(var(--space-2), var(--space-2)); }
.aq-review-reticles__sheet:hover .aq-review-reticles__big .aq-review-reticles__br--tr { transform: translate(calc(-1 * var(--space-2)), var(--space-2)); }
.aq-review-reticles__sheet:hover .aq-review-reticles__big .aq-review-reticles__br--bl { transform: translate(var(--space-2), calc(-1 * var(--space-2))); }
.aq-review-reticles__sheet:hover .aq-review-reticles__big .aq-review-reticles__br--br { transform: translate(calc(-1 * var(--space-2)), calc(-1 * var(--space-2))); }
.aq-review-reticles__cross { position: absolute; inset: 0; }
.aq-review-reticles__cross::before, .aq-review-reticles__cross::after { content: ""; position: absolute; background: color-mix(in srgb, var(--on-limestone-muted) 22%, transparent); }
.aq-review-reticles__cross::before { left: 50%; top: var(--space-6); bottom: var(--space-6); width: 1px; }
.aq-review-reticles__cross::after { top: 50%; left: var(--space-6); right: var(--space-6); height: 1px; }
.aq-review-reticles__no { position: absolute; left: calc(var(--in, var(--space-3)) + var(--space-3)); top: calc(var(--in, var(--space-3)) + var(--space-2)); font: 500 12px/16px var(--font-mono); letter-spacing: 0.06em; color: var(--on-limestone-muted); }
.aq-review-reticles__sel { color: var(--flow); }
