.aq-review-reticles__tb { display: grid; grid-template-columns: auto auto minmax(0, 1fr) auto; margin: auto calc(-1 * var(--space-8)) 0; border-top: 1px solid var(--rr-line, var(--line-strong)); }
.aq-review-reticles__tb span { padding: var(--space-2) var(--space-3); font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-limestone-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
