.aq-roles__key .aq-roles__stamp { flex: none; padding-block: 0; font-size: 14px; line-height: 20px; }
.aq-roles__rows { list-style: none; margin: 0; padding: 0; border-bottom: 1px solid var(--line); }
.aq-roles__row { display: grid; grid-template-columns: var(--space-12) minmax(0, 4fr) minmax(0, 8fr); column-gap: var(--space-4); align-items: start; padding-block: var(--space-4); border-top: 1px solid var(--line); }
.aq-roles__row > .aq-index { line-height: 28px; }
.aq-roles__t { margin: 0; font: 400 20px/28px var(--font-sans); letter-spacing: -0.005em; color: var(--ink); overflow-wrap: break-word; text-wrap: pretty; }
.aq-roles__stamps { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); column-gap: var(--space-6); }
.aq-roles__cell { display: flex; flex-direction: column; gap: var(--space-1); min-width: 0; }
.aq-roles__k { margin: 0; font: 500 14px/20px var(--font-sans); color: var(--ink-muted); }
.aq-roles__stamp { margin: 0; padding: var(--space-1) 0 var(--space-1) var(--space-3); border-left: 2px solid var(--line-strong); font: 400 16px/24px var(--font-sans); color: var(--ink); overflow-wrap: break-word; }
.aq-roles__stamp.is-ours { border-left-color: var(--flow); }
.aq-roles__stamp.is-yours { border-left-color: var(--ink-muted); }
.aq-roles__stamp.is-shared { border-left-style: dashed; }

@container (max-width: 860px) {
  .aq-roles__key { gap: var(--space-2) var(--space-4); }
  .aq-roles__row { grid-template-columns: var(--space-8) minmax(0, 1fr); column-gap: var(--space-2); row-gap: var(--space-3); }
  .aq-roles__row > .aq-index { line-height: 24px; }
  .aq-roles__t { font-size: 18px; line-height: 24px; }
  .aq-roles__stamps { grid-column: 1 / -1; column-gap: var(--space-3); }
  .aq-roles__k { font-size: 12px; line-height: 16px; }
  .aq-roles__stamp { padding-left: var(--space-2); font-size: 14px; line-height: 20px; }
}

/* ---------- Router: pick your situation, see one route (table block with as: "router", blocks/router.js) ----------
   On a plate (wPlate). Desktop: situations as rows on hairlines on the left, each with the shared mono index; the
   chosen one is the plate's one flow-tint row with a 2 px flow line on its left and a flow line with an arrowhead into
   the route. The open route on the right spans every row in a line frame: stations, each with a "Station 0N" eyebrow,
   its column name and value, joined by flow lines with arrowheads (the water path); the linked end station is tinted.
   Phones: one column; the route opens under its situation and its stations run down with arrowed risers between them. */
.aq-router { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); column-gap: var(--space-12); align-items: start; }
.aq-router__opt {
  grid-column: 1; position: relative; display: grid; grid-template-columns: var(--space-12) minmax(0, 1fr); align-items: baseline;
  width: 100%; min-height: 56px; margin: 0; padding: var(--space-4) var(--space-4) var(--space-4) var(--space-3);
  background: none; border: 0; border-left: 2px solid transparent; border-bottom: 1px solid var(--line); cursor: pointer; text-align: left;
  font: 500 16px/24px var(--font-sans); color: var(--ink-muted);
}
.aq-router__opt .aq-index { line-height: 24px; }
.aq-router__t { min-width: 0; text-wrap: pretty; overflow-wrap: break-word; }
.aq-router__opt:hover { color: var(--ink); }
.aq-router__opt:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-router__opt[aria-expanded="true"] { color: var(--ink); background: var(--flow-tint); border-left-color: var(--flow); }
.aq-router__opt[aria-expanded="true"] .aq-index { color: var(--flow); }
/* the flow line from the chosen situation into the route frame, ending in an arrowhead */
.aq-router__opt[aria-expanded="true"]::after {
  content: ""; position: absolute; top: calc(50% - 4px); right: calc(-1 * var(--space-12) - 1px); width: var(--space-12); height: 9px;
  background: var(--flow); clip-path: polygon(0 4px, calc(100% - 7px) 4px, calc(100% - 7px) 0, 100% 50%, calc(100% - 7px) 100%, calc(100% - 7px) 5px, 0 5px);
}
/* The route frame spans every situation row; its station chain sits centred in it (not stranded at the top) */
.aq-router__route { grid-column: 2; position: relative; align-self: stretch; display: flex; flex-direction: column; justify-content: center; padding: var(--space-6); border: 1px solid var(--line); background: var(--surface); }
.aq-router__route[hidden] { display: none; }
.aq-router__hit { position: absolute; inset: 0; z-index: 0; }
.aq-router__route.is-link:hover { border-color: var(--line-strong); }
.aq-router__stations { position: relative; z-index: 1; pointer-events: none; list-style: none; margin: 0; padding: 0; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); column-gap: var(--space-8); align-items: start; counter-reset: aq-station; }
.aq-router__stations a { pointer-events: auto; }
.aq-router__stations > li { position: relative; min-width: 0; padding-top: var(--space-6); counter-increment: aq-station; }
.aq-router__stations > li::before {
  content: "Station 0" counter(aq-station); position: absolute; top: 0; left: 0;
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted);
}
/* a flow line with an arrowhead in the gap to the next station, clear of both texts (space-2 each side) */
.aq-router__stations > li:not(:last-child)::after {
  content: ""; position: absolute; top: calc(var(--space-6) + var(--space-3) + 6px); right: calc(-1 * var(--space-8) + var(--space-2)); width: var(--space-4); height: 9px;
  background: var(--flow); clip-path: polygon(0 4px, calc(100% - 7px) 4px, calc(100% - 7px) 0, 100% 50%, calc(100% - 7px) 100%, calc(100% - 7px) 5px, 0 5px);
}
/* Four or more stations: two per row (a 2 x 2 for four), so each keeps a readable measure; the flow line runs along
   each row and the station numbers carry the order across the turn */
.aq-router__stations:has(> li:nth-child(4)) { grid-auto-flow: row; grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: var(--space-6); }
.aq-router__stations:has(> li:nth-child(4)) > li:nth-child(2n)::after { display: none; }
.aq-router__k {
  margin: 0; padding: var(--space-3) 0 var(--space-1); border-top: 1px solid var(--line-strong);
  font: 500 14px/20px var(--font-sans); color: var(--ink-muted);
}
.aq-router__v {
  margin: 0; padding: 0 0 var(--space-2);
  font: 400 16px/24px var(--font-sans); color: var(--ink); overflow-wrap: break-word; text-wrap: pretty;
}
.aq-router__stations > li.is-go .aq-router__k { border-top-color: var(--flow); color: var(--flow); padding-inline: var(--space-3); background: var(--flow-tint); }
.aq-router__stations > li.is-go .aq-router__v { padding: 0 var(--space-3) var(--space-3); background: var(--flow-tint); }
.aq-router__v a { font-weight: 500; text-decoration: none; }
.aq-router__v a::after { content: "\a0\2192"; }
.aq-router__v a:hover, .aq-router__route.is-link:hover li.is-go a { text-decoration: underline; }
/* Pending station: the value opens with a [placeholder]; a dashed top line and a "To confirm" eyebrow */
.aq-router__stations > li.is-pending .aq-router__k { border-top-style: dashed; }
.aq-router__stations > li.is-pending .aq-router__v { color: var(--ink-muted); }
.aq-router__tbc {
  display: flex; align-items: center; gap: var(--space-2); margin-top: var(--space-1);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted);
}
.aq-router__tbc::before { content: ""; flex: none; width: var(--space-2); height: var(--space-2); border: 1px dashed var(--ink-muted); border-radius: var(--radius-pill); }

/* Motion hooks (Router/motion.js): --aq-pipe grows the runs in the flow direction, --aq-node pops the chosen marker.
   Both default to 1, so the drawing is complete without motion. */
.aq-router__opt[aria-expanded="true"]::after, .aq-router__stations > li:not(:last-child)::after { transform: scaleX(var(--aq-pipe, 1)); transform-origin: left center; }
.aq-router__opt[aria-expanded="true"]::before { transform: scale(var(--aq-node, 1)); }
@media (prefers-reduced-motion: no-preference) {
  .aq-router__opt .aq-index { transition: color 120ms, transform 160ms cubic-bezier(0.2, 0, 0, 1); }
  .aq-router__opt:not([aria-expanded="true"]):hover .aq-index { transform: translateX(var(--space-1)); }
}

@container (max-width: 860px) {
  .aq-router { grid-template-columns: minmax(0, 1fr); }
  .aq-router__opt { grid-template-columns: var(--space-8) minmax(0, 1fr); padding: var(--space-3) var(--space-3) var(--space-3) var(--space-2); font-size: 15px; line-height: 22px; }
  .aq-router__opt .aq-index { line-height: 22px; }
  .aq-router__opt[aria-expanded="true"]::after { top: auto; bottom: calc(-1 * var(--space-3) - 1px); right: auto; left: calc(var(--space-6) - 4px); width: 9px; height: var(--space-3); clip-path: polygon(4px 0, 5px 0, 5px calc(100% - 7px), 100% calc(100% - 7px), 50% 100%, 0 calc(100% - 7px), 4px calc(100% - 7px)); }
  .aq-router__route { grid-column: 1; grid-row: auto !important; margin: var(--space-3) 0 var(--space-3); padding: var(--space-4) var(--space-3); }
  .aq-router__stations, .aq-router__stations:has(> li:nth-child(4)) { grid-auto-flow: row; grid-template-columns: minmax(0, 1fr); row-gap: var(--space-4); }
  .aq-router__stations:has(> li:nth-child(4)) > li:nth-child(2n):not(:last-child)::after { display: block; }
  .aq-router__stations > li { padding-top: 0; }
  .aq-router__stations > li::before { display: none; }
  .aq-router__k::before { content: "0" counter(aq-station) "  "; white-space: pre; font-family: var(--font-mono); color: var(--ink-subtle); }
  .aq-router__stations > li:not(:last-child)::after {
    top: auto; bottom: calc(-1 * var(--space-4)); right: auto; left: calc(var(--space-6) - 4px); width: 9px; height: var(--space-4);
    clip-path: polygon(4px 0, 5px 0, 5px calc(100% - 7px), 100% calc(100% - 7px), 50% 100%, 0 calc(100% - 7px), 4px calc(100% - 7px));
  }
  .aq-router__v { font-size: 15px; line-height: 22px; }
  /* 44 px hit area on the inline link without moving the line */
  .aq-router__v a { padding-block: calc(var(--space-3) + var(--space-1) / 2); }
}
@container (max-width: 860px) { .aq-router__opt[aria-expanded="true"]::after, .aq-router__stations > li:not(:last-child)::after { transform: scaleY(var(--aq-pipe, 1)); transform-origin: center top; } }

/* ---------- RuleFigures: design rules as a Swiss sheet of small engineering figures ---------- */
.aq-rule-figures-sec { overflow: hidden; }
.aq-rule-figures { position: relative; display: flex; flex-direction: column; gap: var(--space-16); }
.aq-rule-figures__cap { position: absolute; right: 0; top: calc(-1 * var(--space-12)); margin: 0; font: 400 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }

/* Shared drawing strokes (line art, round joins; figures scale with their box, so strokes are set in user units) */
.aq-rule-figures svg path, .aq-rule-figures svg circle { fill: none; stroke-linecap: round; stroke-linejoin: round; }
.aq-rule-figures__ln, .aq-rule-figures__wall { stroke: var(--line-strong); stroke-width: 1.5; }
.aq-rule-figures__wall { stroke: var(--ink); stroke-width: 2; }
.aq-rule-figures svg .aq-rule-figures__fill { fill: var(--surface); stroke: var(--line-strong); stroke-width: 1.5; }
.aq-rule-figures__th { stroke: var(--line-strong); stroke-width: 1; }
.aq-rule-figures__dim { stroke: var(--ink-subtle); stroke-width: 1; }
.aq-rule-figures__fl { stroke: var(--flow); stroke-width: 1.5; }
.aq-rule-figures__fl.fl-hid { stroke-dasharray: 3 4; }
.aq-rule-figures__ring { stroke: var(--flow); stroke-width: 1.5; }
.aq-rule-figures__bub { stroke: var(--line-strong); stroke-width: 1.5; }
.aq-rule-figures svg .aq-rule-figures__bub { fill: var(--surface); }
.aq-rule-figures__bub.is-opt { stroke-dasharray: 4 3; }
.aq-rule-figures__tx { fill: var(--ink-muted); font: 500 11px/1 var(--font-mono); }
.aq-rule-figures__tx.is-mid { text-anchor: middle; font-size: 10px; }

/* Lead rule: text left, the pipe cut lengthways running off the right edge of the page */
.aq-rule-figures__lead { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: var(--space-12); align-items: center;
  padding-block: var(--space-8); border-top: 1px solid var(--ink); border-bottom: 1px solid var(--line); }
.aq-rule-figures__lead-text { display: flex; flex-direction: column; gap: var(--space-4); }
.aq-rule-figures__no { margin: 0; font: 300 64px/1 var(--font-mono); letter-spacing: -0.04em; color: var(--flow); }
.aq-rule-figures__lead-p { margin: 0; font: 300 40px/44px var(--font-sans); letter-spacing: -0.02em; }
.aq-rule-figures__lead-art { position: relative; margin-right: calc(-1 * var(--space-32) * 2); aspect-ratio: 4 / 1; }
.aq-rule-figures__pipe { position: absolute; inset: 0; width: 100%; height: 100%; }
.aq-rule-figures__streak { stroke: var(--flow); stroke-width: 1.2; opacity: 0.85; }
.aq-rule-figures__eddy { stroke: var(--flow); stroke-width: 1; opacity: 0.7; }
.aq-rule-figures__arrow { stroke: var(--ink); stroke-width: 1.5; }
.aq-rule-figures__env { stroke: var(--ink); stroke-width: 1; stroke-dasharray: 4 4; }

/* Rule figure in mono: the number (or its placeholder) that the rule is held to */
.aq-rule-figures__rule { margin: 0; font: 400 18px/26px var(--font-mono); color: var(--ink); font-variant-numeric: tabular-nums; }
.aq-rule-figures__rule--lead { font-size: 24px; line-height: 34px; }

.aq-rule-figures__dl { margin: 0; display: grid; gap: var(--space-3); }
.aq-rule-figures__dl div { display: grid; gap: var(--space-1); }
.aq-rule-figures__dl dt { font: 400 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-rule-figures__dl dd { margin: 0; }
.aq-rule-figures__v { font: 400 16px/24px var(--font-sans); color: var(--ink); }
.aq-rule-figures__m { font: 400 13px/20px var(--font-mono); color: var(--ink-muted); }
.aq-rule-figures__link { color: var(--flow); }

/* The other rules: a three-column grid of figure cards, hairlines between */
.aq-rule-figures__grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); column-gap: var(--space-8); row-gap: var(--space-12); }
.aq-rule-figures__card { display: flex; flex-direction: column; gap: var(--space-4); padding-top: var(--space-4); border-top: 1px solid var(--line-strong); }
.aq-rule-figures__figbox { aspect-ratio: 2 / 1; background: var(--surface-sunken); border: 1px solid var(--line); padding: var(--space-3); }
.aq-section--alt .aq-rule-figures__figbox { background: var(--surface); }
.aq-rule-figures__fig { display: block; width: 100%; height: 100%; overflow: visible; }
.aq-rule-figures__head { margin: 0; display: flex; align-items: baseline; gap: var(--space-3); }
.aq-rule-figures__n { font: 400 28px/1 var(--font-mono); letter-spacing: -0.03em; color: var(--ink-subtle); }
.aq-rule-figures__p { font: 500 20px/28px var(--font-sans); letter-spacing: -0.005em; }
.aq-rule-figures__card:hover .aq-rule-figures__n { color: var(--flow); }
.aq-rule-figures__card:hover .aq-rule-figures__figbox { border-color: var(--line-strong); }
.aq-rule-figures__card:hover .aq-rule-figures__fl { stroke-width: 2.5; }

/* Desktop shows every rule; the fold is for phones */
.aq-fold:not(.is-open) .aq-rule-figures__card.aq-fold-x { display: flex; }
.aq-fold:has(> .aq-rule-figures__grid) > .aq-fold__btn { display: none; }

.aq-rule-figures__streaks, .aq-rule-figures__eddies, .aq-rule-figures__prof { pointer-events: none; }

@container (max-width: 1100px) {
  .aq-rule-figures__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@container (max-width: 860px) {
  .aq-rule-figures { gap: var(--space-8); }
  .aq-rule-figures__cap { position: static; }
  .aq-rule-figures__lead { grid-template-columns: minmax(0, 1fr); gap: var(--space-6); }
  .aq-rule-figures__lead-art { margin-right: calc(-1 * var(--space-4)); margin-left: calc(-1 * var(--space-4)); aspect-ratio: 10 / 3; }
  .aq-rule-figures__no { font-size: 48px; }
  .aq-rule-figures__lead-p { font-size: 32px; line-height: 38px; }
  .aq-rule-figures__rule--lead { font-size: 20px; line-height: 28px; }
  .aq-rule-figures__grid { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-8); }
  .aq-fold:not(.is-open) .aq-rule-figures__card.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-rule-figures__grid) > .aq-fold__btn { display: flex; }
}

/* ---------- SectionTrain: a pretreatment train as one sectional elevation, each bed holding what it caught ---------- */
/* Limestone sheet (the component sets data-theme="light" so flow keeps its light value on the fixed limestone ground).
   The svg spans the content width; the stage columns under it share its 200-unit column grid. */
.aq-section-train-sec .aq-sec-head .aq-h1 { color: var(--on-limestone); }
.aq-section-train { position: relative; display: flex; flex-direction: column; gap: var(--space-6); color: var(--on-limestone); background: transparent; }
.aq-section-train__defs { position: absolute; width: 0; height: 0; overflow: hidden; }
.aq-section-train__svg { display: block; width: 100%; height: auto; overflow: visible; }
.aq-section-train svg * { vector-effect: non-scaling-stroke; stroke-linejoin: round; stroke-linecap: round; }

/* Drawing: walls cut and hatched, interiors on the raised paper, beds in fine marks */
.aq-section-train__hatch-bg { fill: var(--limestone); }
.aq-section-train__hatch { stroke: var(--on-limestone-muted); stroke-width: 0.75; vector-effect: none; }
.aq-section-train__wall { stroke: var(--on-limestone); stroke-width: 1.5; }
.aq-section-train__in { fill: var(--surface-raised); stroke: var(--on-limestone-muted); stroke-width: 1; }
.aq-section-train__head { fill: var(--surface-raised); stroke: var(--on-limestone); stroke-width: 1.5; }
.aq-section-train__level { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1; stroke-dasharray: 4 3; }
.aq-section-train__ripple { fill: none; stroke: var(--flow); stroke-width: 1; opacity: 0.55; }
.aq-section-train__gap { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1; }
.aq-section-train__valve { fill: var(--surface-raised); stroke: var(--on-limestone); stroke-width: 1.5; }
.aq-section-train__sand { fill: var(--on-limestone-muted); }
.aq-section-train__pebble, .aq-section-train__bead, .aq-section-train__grain { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1; }
.aq-section-train__grain { fill: var(--limestone); }
.aq-section-train__bed--idle { opacity: 0.45; }
.aq-section-train__regen { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1.25; }
.aq-section-train__pleat, .aq-section-train__core, .aq-section-train__drain { fill: none; stroke: var(--on-limestone); stroke-width: 1; }

/* The pipe: a twin wall (a wide dark stroke under a narrower paper one) and the water as a flow line */
.aq-section-train__pipe { fill: none; stroke: var(--on-limestone); stroke-width: 12; vector-effect: none; stroke-linejoin: round; }
.aq-section-train__bore { fill: none; stroke: var(--surface-raised); stroke-width: 9; vector-effect: none; stroke-linejoin: round; }
.aq-section-train__flow { fill: none; stroke: var(--flow); stroke-width: 2; }
.aq-section-train__drop { fill: var(--flow); opacity: 0; }
.aq-section-train__arrow { fill: none; stroke: var(--flow); stroke-width: 2; }
.aq-section-train__swarm { display: none; }

/* What the water carries: particles solid, hardness hexagons, chlorine crosses, fines dust */
.aq-section-train__g--p, .aq-section-train__g--f { fill: var(--on-limestone); }
.aq-section-train__g--h { fill: var(--surface-raised); stroke: var(--on-limestone); stroke-width: 1.25; }
.aq-section-train__g--c { fill: none; stroke: var(--on-limestone); stroke-width: 1.5; }

/* Lenses: a magnified sample of the water, at the feed and at the RO */
.aq-section-train__lens-rim { fill: var(--limestone); stroke: var(--on-limestone); stroke-width: 1.5; }
.aq-section-train__lens-face { fill: var(--surface-raised); stroke: var(--on-limestone-muted); stroke-width: 1; }
.aq-section-train__lens-water { fill: none; stroke: var(--flow); stroke-width: 1; opacity: 0.6; }
.aq-section-train__lead { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1; stroke-dasharray: 2 3; }
.aq-section-train__dot { fill: var(--on-limestone); }

/* Monitoring bus: a dashed signal line with instrument bubbles tapped off the pipe */
.aq-section-train__bus { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1; stroke-dasharray: 6 3 1 3; }
.aq-section-train__tap { fill: none; stroke: var(--on-limestone-muted); stroke-width: 1; }
.aq-section-train__bubble { fill: var(--surface-raised); stroke: var(--on-limestone); stroke-width: 1.25; }

/* Stage columns under the drawing */
.aq-section-train__stages { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(var(--n, 7), minmax(0, 1fr)); }
.aq-section-train__stage { position: relative; padding: var(--space-4) var(--space-3) 0; border-top: 1px solid var(--on-limestone-muted); }
.aq-section-train__stage + .aq-section-train__stage { border-left: 1px solid color-mix(in srgb, var(--on-limestone-muted) 35%, transparent); }
.aq-section-train__mini { display: none; }
.aq-section-train__text { display: flex; flex-direction: column; gap: var(--space-2); }
.aq-section-train__no { margin: 0; font: 400 12px/16px var(--font-mono); color: var(--on-limestone-muted); }
.aq-section-train__stage.is-on .aq-section-train__no .aq-index { color: var(--flow); }
.aq-section-train__t { margin: 0; font: 500 16px/22px var(--font-sans); letter-spacing: -0.005em; color: var(--on-limestone); }
.aq-section-train__t a { color: var(--flow); text-decoration: underline; text-underline-offset: 3px; }
.aq-section-train__t a::after { content: " \2192"; }
.aq-section-train__d { margin: 0; font: 400 14px/21px var(--font-sans); color: var(--on-limestone-muted); }
.aq-section-train__catch { display: inline-flex; align-self: flex-start; align-items: center; gap: var(--space-2); margin: var(--space-1) 0 0;
  padding: var(--space-1) var(--space-2); border: 1px solid var(--on-limestone); background: var(--surface-raised);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.04em; text-transform: uppercase; color: var(--on-limestone); }
.aq-section-train__cg { width: 14px; height: 14px; flex: none; overflow: visible; }
.aq-section-train__base { margin: 0; display: flex; align-items: center; gap: var(--space-3); padding-top: var(--space-3);
  font: 400 13px/20px var(--font-mono); color: var(--on-limestone-muted); }
.aq-section-train__base-mark { flex: none; width: var(--space-12); height: 0; border-top: 1px dashed var(--on-limestone-muted); }

/* Phones: one frame of the elevation per stage, run down the page on a pipe rail at the left */
@container (max-width: 860px) {
  .aq-section-train__svg { display: none; }
  .aq-section-train__stages { grid-template-columns: minmax(0, 1fr); }
  .aq-section-train__stage { display: grid; grid-template-columns: 104px minmax(0, 1fr); column-gap: var(--space-4); align-items: start;
    padding: 0 0 var(--space-6); border: 0; }
  .aq-section-train__stage + .aq-section-train__stage { border-left: 0; }
  .aq-section-train__stage::before { content: ""; position: absolute; left: 52px; top: 0; bottom: 0; width: 3px; transform: translateX(-50%);
    border-inline: 1px solid var(--on-limestone); background: var(--surface-raised); z-index: 0; }
  /* the rail is the pipe: it starts at the feed lens, runs behind every vessel (their walls and beds are filled, the
     paper round them is not) and ends at the outlet lens */
  .aq-section-train__stage:first-child::before { top: 78px; }
  .aq-section-train__stage:last-child::before { bottom: auto; height: 78px; }
  .aq-section-train__mini { display: block; position: relative; z-index: 1; width: 104px; height: auto; background: transparent; }
  /* the backflow preventer turns onto the rail; the outlet's arrowhead is the rail's end, so it goes */
  .aq-section-train__mini .aq-section-train__valve { transform-box: fill-box; transform-origin: center; transform: translate(52px, 0) rotate(90deg); }
  .aq-section-train__mini .aq-section-train__arrow, .aq-section-train__mini .aq-section-train__dot { display: none; }
  .aq-section-train__mini .aq-section-train__lead { display: none; }
  .aq-section-train__text { padding-top: var(--space-4); }
  .aq-section-train__t { font-size: 17px; line-height: 24px; }
  .aq-section-train__base { align-items: flex-start; }
  .aq-section-train__base-mark { width: var(--space-6); margin-top: var(--space-3); }
}
.aq-section-train__seep { fill: none; stroke: var(--flow); stroke-width: 1.25; stroke-dasharray: 2 5; opacity: 0.7; }

/* ---------- SheetStack: documents as an exploded stack of isometric drawing sheets ---------- */
.aq-sheet-stack { position: relative; display: flex; flex-direction: column; gap: var(--space-8); }
.aq-sheet-stack__axis { position: absolute; left: calc(100% * 5 / 24); top: 0; bottom: var(--space-16); border-left: 1px dashed var(--line-strong); }
.aq-sheet-stack__rows { list-style: none; margin: 0; padding: 0; position: relative; display: flex; flex-direction: column; }
.aq-sheet-stack__row { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); align-items: center; min-height: calc(var(--space-32) + var(--space-12)); }
.aq-sheet-stack__slot { position: relative; display: grid; place-items: center; height: calc(var(--space-32) + var(--space-12)); perspective: none; }
.aq-sheet-stack__sheet { display: block; width: min(100%, calc(var(--space-32) * 2 + var(--space-12))); aspect-ratio: 280 / 198; background: var(--surface-raised);
  border-right: 3px solid var(--line-strong); border-bottom: 3px solid var(--line-strong);
  transform: rotateX(60deg) rotateZ(-45deg); transition: transform 350ms cubic-bezier(0.2, 0, 0, 1); }
.aq-sheet-stack__row:hover .aq-sheet-stack__sheet, .aq-sheet-stack__row:focus-within .aq-sheet-stack__sheet { transform: translateY(calc(-1 * var(--space-4))) rotateX(60deg) rotateZ(-45deg); }
.aq-sheet-stack__sheet svg { display: block; width: 100%; height: 100%; }
.aq-sheet-stack__sheet path, .aq-sheet-stack__sheet circle { fill: none; stroke-linecap: round; stroke-linejoin: round; }
.aq-sheet-stack__frame { stroke: var(--line-strong); stroke-width: 1.5; }
.aq-sheet-stack__tb { stroke: var(--line-strong); stroke-width: 1; }
.aq-sheet-stack__sheet text { fill: var(--ink); font: 500 13px/1 var(--font-mono); text-anchor: middle; }
.aq-sheet-stack__ln { stroke: var(--ink-muted); stroke-width: 1.5; }
.aq-sheet-stack__th { stroke: var(--line-strong); stroke-width: 1; }
.aq-sheet-stack__bar { stroke: var(--flow); stroke-width: 7; stroke-linecap: butt; }
.aq-sheet-stack__lim { stroke: var(--ink); stroke-width: 1.2; stroke-dasharray: 4 4; }
.aq-sheet-stack__flow { stroke: var(--flow); stroke-width: 1.5; stroke-dasharray: 5 5; }
.aq-sheet-stack__sheet .aq-sheet-stack__fl { fill: var(--flow); stroke: none; }
.aq-sheet-stack__seal { stroke: var(--flow); stroke-width: 1.5; }
.aq-sheet-stack__row:hover .aq-sheet-stack__frame { stroke: var(--flow); }

/* The row beside its sheet, a hairline leader running in from the sheet */
.aq-sheet-stack__text { position: relative; display: flex; flex-direction: column; gap: var(--space-2); padding-left: var(--space-6); }
.aq-sheet-stack__text::before { content: ""; position: absolute; right: 100%; top: var(--space-3); width: var(--space-16); border-top: 1px solid var(--line-strong); }
.aq-sheet-stack__code { margin: 0; display: flex; gap: var(--space-4); font: 500 14px/20px var(--font-mono); letter-spacing: 0.04em; color: var(--ink-muted); }
.aq-sheet-stack__i { color: var(--ink-subtle); font-weight: 400; }
.is-key .aq-sheet-stack__code { color: var(--flow); }
.aq-sheet-stack__t { margin: 0; font: 300 30px/36px var(--font-sans); letter-spacing: -0.015em; }
.aq-sheet-stack__d { margin: 0; max-width: var(--text-max); font: 400 16px/26px var(--font-sans); color: var(--ink-muted); }
.aq-sheet-stack__more { margin: 0; padding-left: calc(100% * 5 / 12 + var(--space-6)); }

/* Desktop shows every sheet; the fold is for phones */
.aq-fold:not(.is-open) .aq-sheet-stack__row.aq-fold-x { display: grid; }
.aq-fold:has(> .aq-sheet-stack__rows) > .aq-fold__btn { display: none; }

.aq-sheet-stack-sec { overflow: hidden; }
.aq-sheet-stack__k { display: inline-block; }

@container (max-width: 860px) {
  .aq-sheet-stack__axis { left: calc(var(--space-16) + var(--space-2)); }
  .aq-sheet-stack__row { grid-template-columns: calc(var(--space-32) + var(--space-4)) minmax(0, 1fr); min-height: 0; align-items: start; padding-block: var(--space-4); }
  .aq-sheet-stack__slot { height: var(--space-24); }
  .aq-sheet-stack__sheet { width: calc(var(--space-24) + var(--space-8)); border-right-width: 2px; border-bottom-width: 2px; }
  .aq-sheet-stack__text { padding-left: var(--space-2); }
  .aq-sheet-stack__text::before { display: none; }
  .aq-sheet-stack__t { font-size: 22px; line-height: 28px; }
  .aq-sheet-stack__d { font-size: 14px; line-height: 22px; }
  .aq-sheet-stack__more { padding-left: 0; }
  .aq-fold:not(.is-open) .aq-sheet-stack__row.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-sheet-stack__rows) > .aq-fold__btn { display: flex; }
}

/* ---------- ShopFloor: people or roles placed at their stations on one isometric plan of the shop ---------- */
.aq-shop-floor-sec { }
.aq-shop-floor__body { min-width: 0; }
/* Navy band. Wide: the plan on the left (sticky when the cards run long), the cards on the right on a hairline rail.
   Pins are square mono tags over the plan; the lit station and its walking leg turn flow, its pin fills limestone. */
.aq-shop-floor { display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); gap: var(--space-12); align-items: start; margin-top: var(--space-4); }
.aq-shop-floor.is-long { grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: var(--space-8); }
.aq-shop-floor__fig { margin: 0; position: sticky; top: var(--space-24); }
.aq-shop-floor__plan { position: relative; }
.aq-shop-floor__svg { display: block; width: 100%; height: auto; }
.aq-shop-floor__st { transition: opacity 300ms; }
.aq-shop-floor__st.is-idle { opacity: 0.42; }
.aq-shop-floor__st.is-lit { opacity: 1; }
.aq-shop-floor__st.is-lit .aq-iso__eq, .aq-shop-floor__st.is-lit .aq-iso__ln, .aq-shop-floor__st.is-lit .aq-iso__thin { stroke: var(--on-navy); }
/* the walking route: a bold dashed line in full on-navy, so it reads apart from the muted walls and room lines */
.aq-shop-floor .aq-shop-floor__walk .aq-iso__pipe-line { stroke: var(--on-navy); stroke-width: 3px; stroke-dasharray: 8 6; stroke-linecap: butt; }
.aq-shop-floor__walk .aq-iso__flow { stroke: transparent; transition: stroke 300ms; }
.aq-shop-floor__walk.is-lit .aq-iso__flow, .aq-shop-floor.is-walking .aq-shop-floor__walk .aq-iso__flow { stroke: var(--on-navy); }
.aq-shop-floor__svg .aq-iso__flow--line { stroke-width: 2px; }
.aq-shop-floor__door { stroke: var(--on-navy); stroke-width: 3px; }

.aq-shop-floor__pin { position: absolute; transform: translate(-50%, -100%); display: grid; place-items: center; min-width: var(--space-8); height: var(--space-6);
  padding: 0 var(--space-1); background: var(--navy); color: var(--on-navy); border: 1px solid var(--on-navy-muted);
  font: 500 12px/1 var(--font-mono); letter-spacing: 0.04em; transition: background-color 250ms, color 250ms, border-color 250ms; }
.aq-shop-floor__pin::after { content: ""; position: absolute; left: 50%; top: 100%; width: 1px; height: var(--space-3); background: var(--on-navy-muted); }
.aq-shop-floor__pin.is-on { background: var(--limestone); color: var(--on-limestone); border-color: var(--limestone); }

/* Cards: index, title, nameplate or labelled fields */
.aq-shop-floor__cards { list-style: none; margin: 0; padding: 0; border-top: 1px solid color-mix(in srgb, var(--on-navy) 22%, transparent); }
.aq-shop-floor__card { position: relative; display: grid; grid-template-columns: var(--space-12) minmax(0, 1fr); gap: var(--space-4);
  padding: var(--space-6) 0; border-bottom: 1px solid color-mix(in srgb, var(--on-navy) 22%, transparent); transition: background-color 300ms; }
.aq-shop-floor__card::before { content: ""; position: absolute; left: 0; top: -1px; height: 1px; width: 100%; background: var(--on-navy);
  transform: scaleX(0); transform-origin: 0 50%; transition: transform 400ms cubic-bezier(0.2, 0, 0, 1); }
.aq-shop-floor__card.is-on::before { transform: scaleX(1); }
.aq-shop-floor__n { font: 300 32px/1 var(--font-sans); letter-spacing: -0.03em; color: var(--on-navy-muted); font-variant-numeric: tabular-nums; transition: color 300ms; }
.aq-shop-floor__card.is-on .aq-shop-floor__n { color: var(--on-navy); }
.aq-shop-floor__t { margin: 0; font: 300 26px/32px var(--font-sans); letter-spacing: -0.015em; color: var(--on-navy); text-wrap: balance; }
.aq-shop-floor .aq-shop-floor__name { margin: var(--space-3) 0 0; font: 400 15px/24px var(--font-sans); color: var(--on-navy); }
.aq-shop-floor .aq-shop-floor__d { margin: var(--space-2) 0 0; font: 400 16px/26px var(--font-sans); color: var(--on-navy-muted); max-width: 46ch; }
.aq-shop-floor .aq-shop-floor__go { margin: var(--space-2) 0 0; }
.aq-shop-floor__go a { display: inline-flex; align-items: center; min-height: var(--space-12); color: var(--on-navy); font: 500 14px/20px var(--font-sans); text-decoration: none;
  box-shadow: inset 0 -1px 0 var(--on-navy-muted); }
.aq-shop-floor__go a::after { content: "→"; margin-left: var(--space-2); transition: transform 200ms; }
.aq-shop-floor__go a:hover::after { transform: translateX(var(--space-1)); }
.aq-shop-floor a:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-shop-floor__dl { margin: var(--space-4) 0 0; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--space-4) var(--space-6); }
.aq-shop-floor__f { min-width: 0; }
.aq-shop-floor__f:first-child { grid-column: 1 / -1; }
.aq-shop-floor.is-long .aq-shop-floor__dl { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.aq-shop-floor__f dt { font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-shop-floor__f dd { margin: var(--space-1) 0 0; font: 400 15px/24px var(--font-sans); color: var(--on-navy); overflow-wrap: anywhere; }
.aq-shop-floor__f:first-child dd { font-size: 17px; line-height: 27px; }
.aq-shop-floor .aq-ph { background: color-mix(in srgb, var(--limestone) 22%, transparent); color: var(--on-navy); }

@container (max-width: 1100px) {
  .aq-shop-floor, .aq-shop-floor.is-long { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--space-8); }
  .aq-shop-floor__dl, .aq-shop-floor.is-long .aq-shop-floor__dl { grid-template-columns: minmax(0, 1fr); }
}
/* Phones: the plan is a band above the cards (not sticky), pins smaller */
@container (max-width: 860px) {
  .aq-shop-floor, .aq-shop-floor.is-long { grid-template-columns: minmax(0, 1fr); gap: var(--space-6); }
  .aq-shop-floor__fig { position: relative; top: auto; margin-inline: calc(var(--space-2) * -1); }
  .aq-shop-floor__pin { min-width: var(--space-6); height: var(--space-4); font-size: 11px; }
  .aq-shop-floor__card { grid-template-columns: var(--space-8) minmax(0, 1fr); gap: var(--space-3); padding: var(--space-4) 0 var(--space-6); }
  .aq-shop-floor__n { font-size: 24px; }
  .aq-shop-floor__t { font-size: 22px; line-height: 28px; }
}

/* ---------- SignalDial: an instrument schedule beside one multi-channel transmitter dial (look "signal-dial") ---------- */
/* Desktop: the table (left) and the dial (right) side by side; the dial's bezel turns (--sd-a, degrees) to bring the
   chosen channel under the index. Phones: the dial first, smaller; the rows stack under it. */
.aq-signal-dial {
  display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(320px, 0.8fr); grid-template-areas: "table fig";
  column-gap: var(--space-16); align-items: center;
}
.aq-signal-dial__fig { grid-area: fig; display: flex; flex-direction: column; align-items: center; gap: var(--space-4); }
.aq-signal-dial__table { grid-area: table; }

/* the dial */
.aq-signal-dial__dial {
  position: relative; width: 100%; max-width: 460px; aspect-ratio: 1; border-radius: 50%;
  background: var(--surface-raised); cursor: ew-resize; touch-action: pan-y; user-select: none; -webkit-user-select: none;
}
.aq-signal-dial__dial:focus-visible { outline: 2px solid var(--focus); outline-offset: var(--space-2); }
.aq-signal-dial__dial.is-drag { cursor: grabbing; }
.aq-signal-dial__svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.aq-signal-dial__rim { fill: none; stroke: var(--line-strong); stroke-width: 1; }
.aq-signal-dial__rim2 { fill: var(--surface); stroke: var(--line); stroke-width: 1; }
.aq-signal-dial__ring {
  transform: rotate(calc(var(--sd-a, 0) * 1deg)); transform-box: view-box; transform-origin: 200px 200px;
  transition: transform 600ms cubic-bezier(0.22, 1, 0.36, 1);
}
.aq-signal-dial__dial.is-drag .aq-signal-dial__ring { transition: none; }
.aq-signal-dial__tk { stroke: var(--line-strong); stroke-width: 1; opacity: 0.6; }
.aq-signal-dial__tk--mid { opacity: 1; }
.aq-signal-dial__tk--stop { stroke: var(--ink); stroke-width: 1.5; opacity: 1; }
.aq-signal-dial__tk--stop.is-on { stroke: var(--flow); stroke-width: 2.5; }
.aq-signal-dial__sn { font: 400 12px var(--font-mono); fill: var(--ink-subtle); text-anchor: middle; transition: fill 200ms ease; }
.aq-signal-dial__sn.is-on { fill: var(--flow); }
.aq-signal-dial__fine { fill: none; stroke: var(--line-strong); stroke-width: 1; opacity: 0.5; }
.aq-signal-dial__index { fill: var(--flow); stroke: var(--flow); stroke-width: 1.5; }

/* the readout on the face */
.aq-signal-dial__read {
  position: absolute; left: 50%; top: 50%; width: 58%; transform: translate(-50%, -50%);
  display: flex; flex-direction: column; align-items: center; text-align: center; pointer-events: none;
}
.aq-signal-dial__ch { font: 400 12px/16px var(--font-mono); letter-spacing: 0.08em; color: var(--ink-subtle); }
.aq-signal-dial__num { display: flex; align-items: baseline; gap: var(--space-2); color: var(--ink); }
.aq-signal-dial__digits { font: 300 clamp(56px, 7vw, 96px)/1 var(--font-mono); letter-spacing: -0.04em; font-variant-numeric: tabular-nums; }
.aq-signal-dial__of { font: 400 13px/1 var(--font-mono); color: var(--ink-subtle); }
.aq-signal-dial__name { margin-top: var(--space-2); font: 400 18px/24px var(--font-sans); letter-spacing: -0.01em; color: var(--ink); text-wrap: balance; }
.aq-signal-dial__lim { align-self: stretch; height: 1px; margin: var(--space-3) calc(-1 * var(--space-4)) var(--space-2); background: var(--flow); }
.aq-signal-dial__val { font: 400 13px/18px var(--font-sans); color: var(--ink-muted); text-wrap: balance; }
.aq-signal-dial__tag {
  margin-top: var(--space-2); padding: 0 var(--space-2); border: 1px solid var(--line-strong);
  font: 400 11px/18px var(--font-mono); color: var(--ink-muted); white-space: normal;
}
.aq-signal-dial__tag[hidden] { display: none; }
.aq-signal-dial__read.is-tick > * { animation: aq-sd-tick 220ms cubic-bezier(0.2, 0.8, 0.2, 1); }
@keyframes aq-sd-tick { from { opacity: 0.2; transform: translateY(var(--sd-dir, 8px)); } to { opacity: 1; transform: none; } }
.aq-signal-dial__hint { margin: 0; font: 400 12px/16px var(--font-mono); color: var(--ink-subtle); }

/* the schedule */
.aq-signal-dial__table { width: 100%; border-collapse: collapse; }
.aq-signal-dial__table thead th {
  padding: 0 var(--space-3) var(--space-3); text-align: left; border-bottom: 1px solid var(--line-strong);
  font: 400 12px/16px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-subtle);
}
.aq-signal-dial__row > * { padding: var(--space-3); vertical-align: top; border-bottom: 1px solid var(--line); text-align: left; transition: background-color 200ms ease; }
.aq-signal-dial__row > th { padding: 0; width: 34%; font-weight: 400; }
.aq-signal-dial__pick {
  display: grid; grid-template-columns: var(--space-8) 1fr; align-items: baseline; width: 100%; min-height: 44px;
  padding: var(--space-3); border: 0; border-left: 2px solid transparent; background: none; text-align: left; cursor: pointer;
  font: 500 15px/22px var(--font-sans); color: var(--ink);
}
.aq-signal-dial__pick:focus-visible { outline: 2px solid var(--focus); outline-offset: -2px; }
.aq-signal-dial__n { font: 400 12px/22px var(--font-mono); color: var(--ink-subtle); }
.aq-signal-dial__v { font: 400 15px/22px var(--font-sans); color: var(--ink); text-wrap: pretty; }
.aq-signal-dial__m { font: 400 13px/22px var(--font-mono); color: var(--ink-muted); }
.aq-signal-dial__go { display: block; font-family: var(--font-sans); }
.aq-signal-dial__row.is-on > * { background: var(--flow-tint); }
.aq-signal-dial__row.is-on .aq-signal-dial__pick { border-left-color: var(--flow); }
.aq-signal-dial__row.is-on .aq-signal-dial__n { color: var(--flow); }
.aq-fold:not(.is-open) .aq-signal-dial__row.aq-fold-x { display: table-row; }
.aq-fold:has(> .aq-signal-dial) > .aq-fold__btn { display: none; }
.aq-signal-dial__note { margin: 0; padding-left: var(--space-4); border-left: 2px solid var(--flow); font: 400 14px/22px var(--font-sans); color: var(--ink-muted); max-width: var(--text-max); }

@media (prefers-reduced-motion: reduce) {
  .aq-signal-dial__ring { transition: none; }
  .aq-signal-dial__read.is-tick > * { animation: none; }
}

@container (max-width: 860px) {
  .aq-signal-dial { grid-template-columns: minmax(0, 1fr); grid-template-areas: "fig" "table"; row-gap: var(--space-8); }
  .aq-signal-dial__dial { max-width: 320px; }
  .aq-signal-dial__digits { font-size: 56px; }
  .aq-signal-dial__name { font-size: 16px; line-height: 22px; }
  .aq-signal-dial__val { font-size: 12px; line-height: 16px; }
  .aq-signal-dial__lim { margin-top: var(--space-2); }
  .aq-signal-dial__table thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
  .aq-signal-dial__table, .aq-signal-dial__table tbody { display: block; }
  .aq-signal-dial__row, .aq-fold:not(.is-open) .aq-signal-dial__row.aq-fold-x { display: grid; grid-template-columns: var(--space-12) minmax(0, 1fr); border-bottom: 1px solid var(--line); }
  .aq-fold:not(.is-open) .aq-signal-dial__row.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-signal-dial) > .aq-fold__btn { display: flex; }
  .aq-signal-dial__row > * { border-bottom: 0; }
  .aq-signal-dial__row > th { grid-column: 1 / -1; width: auto; }
  .aq-signal-dial__v, .aq-signal-dial__m { grid-column: 2; padding: 0 var(--space-3) var(--space-2) 0; }
  .aq-signal-dial__m { padding-bottom: var(--space-4); }
}
.aq-signal-dial-sec { position: relative; }
.aq-signal-dial__p { min-width: 0; }

/* ---------- SignatureBlocks: who writes and who reviews, as each document's signature block (look "signature-blocks") ----------
   A dark section on navy (data-theme="dark" on the section, background navy, so flow reads light on it in both
   themes). Desktop: a key strip, then the blocks two to a row, each a ruled frame (line-strong): its index and name
   over the two fields (an odd last block runs the full width). A field is a mono label, the party typed into a box and a signature line under it marked
   with a cross. Box styles name the party: Aquemi in a flow rule, your side in a double limestone rule, shared in a
   dashed rule. Phones: one column; the fold applies here only. */
.aq-signature-blocks-sec, .aq-section--alt.aq-signature-blocks-sec { background: var(--navy); color: var(--ink); }
.aq-signature-blocks { display: flex; flex-direction: column; gap: var(--space-6); }
.aq-signature-blocks__key { display: flex; flex-wrap: wrap; gap: var(--space-3); margin: 0; padding-bottom: var(--space-4); border-bottom: 1px solid var(--line); }
.aq-signature-blocks__key span { padding: var(--space-1) var(--space-3); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink); }
.aq-signature-blocks__key .is-us { border: 1.5px solid var(--flow); color: var(--flow); }
.aq-signature-blocks__key .is-you { border: 3px double var(--limestone); }
.aq-signature-blocks__key .is-both { border: 1.5px dashed var(--ink-muted); }
.aq-signature-blocks__list { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-4); }
.aq-signature-blocks__b { position: relative; border: 1px solid var(--line-strong); padding: var(--space-6); display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-4); align-items: start;
  background: color-mix(in srgb, var(--navy) 85%, var(--surface)); }
/* an odd last block runs the full width: name at the left, its fields beside it */
.aq-signature-blocks__b:last-child:nth-child(odd) { grid-column: 1 / -1; grid-template-columns: minmax(0, 4fr) minmax(0, 8fr); gap: var(--space-8); }
.aq-signature-blocks__b::after { content: ""; position: absolute; inset: var(--space-1); border: 1px solid var(--line); pointer-events: none; }
.aq-signature-blocks__head { display: flex; flex-direction: column; gap: var(--space-1); }
.aq-signature-blocks__n { font: 400 12px/16px var(--font-mono); letter-spacing: 0.08em; color: var(--ink-subtle); }
.aq-signature-blocks__t { margin: 0; font: 300 24px/30px var(--font-sans); letter-spacing: -0.015em; color: var(--ink); }
.aq-signature-blocks__fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-6); }
.aq-signature-blocks__f { display: flex; flex-direction: column; gap: var(--space-2); min-width: 0; }
.aq-signature-blocks__lab { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-signature-blocks__v { display: block; min-height: var(--space-12); padding: var(--space-3); font: 400 15px/22px var(--font-sans); color: var(--ink); }
.is-us > .aq-signature-blocks__v { border: 1.5px solid var(--flow); color: var(--flow); }
.is-you > .aq-signature-blocks__v { border: 3px double var(--limestone); }
.is-both > .aq-signature-blocks__v { border: 1.5px dashed var(--ink-muted); }
.aq-signature-blocks__line { position: relative; display: block; height: var(--space-8); border-bottom: 1px solid var(--ink-muted); transform-origin: 0 50%; }
.aq-signature-blocks__sig { position: absolute; left: var(--space-6); bottom: var(--space-1); width: var(--space-24); height: var(--space-8); overflow: visible; }
.aq-signature-blocks__sig path { fill: none; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.aq-signature-blocks__imp { stroke: var(--ink-subtle); opacity: 0.35; transform: translate(1px, 1px); }
.aq-signature-blocks__ink { stroke: var(--ink); }
.aq-signature-blocks__line::before { content: "\00d7"; position: absolute; left: 0; bottom: 0; font: 400 16px/20px var(--font-mono); color: var(--ink-subtle); }
.aq-signature-blocks__b:hover { border-color: var(--flow); }

/* the fold is for phones only: desktop shows every block */
.aq-fold:not(.is-open) .aq-signature-blocks__b.aq-fold-x { display: grid; }
.aq-fold:has(> .aq-signature-blocks__list) > .aq-fold__btn { display: none; }

@container (max-width: 860px) {
  .aq-signature-blocks__list { grid-template-columns: minmax(0, 1fr); gap: var(--space-4); }
  .aq-signature-blocks__b, .aq-signature-blocks__b:last-child:nth-child(odd) { grid-column: auto; padding: var(--space-4); gap: var(--space-4); grid-template-columns: minmax(0, 1fr); }
  .aq-signature-blocks__t { font-size: 20px; line-height: 26px; }
  .aq-signature-blocks__fields { gap: var(--space-3); }
  .aq-signature-blocks__v { min-height: var(--space-12); padding: var(--space-2); font-size: 14px; line-height: 20px; }
  .aq-fold:not(.is-open) .aq-signature-blocks__b.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-signature-blocks__list) > .aq-fold__btn { display: flex; margin-top: var(--space-4); }
}

/* ---------- SitePlates: sites as figure plates, two to a row (look site-plates) ----------
   Each plate: an isometric drawing of what stands there on a limestone panel (IsoKit, aq-iso--limestone) beside the
   site's index and place, its kind set large and light, and what happens here, the address and the contact lines.
   Plates sit on hairlines; phones stack the drawing above the words. */
.aq-site-plates { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: var(--space-8); row-gap: var(--space-8); }
.aq-site-plates__plate {
  display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); column-gap: var(--space-6); align-items: start; min-width: 0;
  padding-top: var(--space-6); border-top: 1px solid var(--line-strong);
}
.aq-site-plates__fig { position: relative; display: grid; place-items: center; aspect-ratio: 4 / 3; padding: var(--space-4); background: var(--limestone); overflow: hidden; }
/* a faint ground grid on the panel, the drawing set on it */
.aq-site-plates__fig::before { content: ""; position: absolute; inset: var(--space-2); border: 1px solid color-mix(in srgb, var(--on-limestone-muted) 25%, transparent); }
.aq-site-plates__svg { position: relative; width: 100%; height: 100%; max-height: calc(var(--space-32) + var(--space-16)); }
.aq-site-plates__text { display: flex; flex-direction: column; gap: var(--space-3); min-width: 0; }
.aq-site-plates__at { margin: 0; display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--space-2) var(--space-3); font: 500 12px/18px var(--font-mono); letter-spacing: 0.04em; color: var(--ink-muted); }
.aq-site-plates__i { font-variant-numeric: tabular-nums; color: var(--flow); letter-spacing: 0.08em; }
.aq-site-plates__t { margin: 0; font: 300 32px/38px var(--font-sans); letter-spacing: -0.02em; color: var(--ink); text-wrap: balance; }
.aq-site-plates__t a { color: inherit; text-decoration-thickness: 1px; text-underline-offset: 5px; text-decoration-color: var(--flow); }
.aq-site-plates__t a:hover { color: var(--flow); }
.aq-site-plates__dl { margin: var(--space-2) 0 0; display: flex; flex-direction: column; }
.aq-site-plates__dl > div { display: grid; grid-template-columns: minmax(0, 1fr); row-gap: var(--space-1); padding-block: var(--space-3); border-top: 1px solid var(--line); }
.aq-site-plates__dl dt { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-site-plates__dl dd { margin: 0; display: flex; flex-direction: column; gap: var(--space-1); font: 400 15px/22px var(--font-sans); color: var(--ink); overflow-wrap: break-word; }
.aq-site-plates-sec .aq-fold__btn { margin-top: var(--space-6); }

@media (prefers-reduced-motion: no-preference) {
  .aq-site-plates__svg { transition: transform 400ms cubic-bezier(0.2, 0, 0, 1); }
  .aq-site-plates__plate:hover .aq-site-plates__svg, .aq-site-plates__plate:focus-within .aq-site-plates__svg { transform: translateY(calc(-1 * var(--space-1))); }
}

@container (max-width: 860px) {
  .aq-site-plates { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-6); }
  .aq-site-plates__plate { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-4); padding-top: var(--space-4); }
  .aq-site-plates__fig { aspect-ratio: 16 / 9; }
  .aq-site-plates__t { font-size: 26px; line-height: 32px; }
}

/* ---------- SiteTiles: a Swiss row of tiles, each opened by a flat figure plate that draws the change ---------- */
.aq-site-tiles-sec { }
.aq-site-tiles__needle, .aq-site-tiles__imprint { transform-box: view-box; }
.aq-site-tiles { list-style: none; margin: var(--space-4) 0 0; padding: 0; display: grid; grid-template-columns: repeat(var(--n, 4), minmax(0, 1fr)); gap: 1px;
  background: var(--line); border: 1px solid var(--line); }
.aq-site-tiles__tile { position: relative; display: flex; flex-direction: column; gap: var(--space-3); min-width: 0; padding: 0 0 var(--space-6); background: var(--surface); }
.aq-section--alt .aq-site-tiles__tile { background: var(--surface-sunken); }
.aq-site-tiles__plate { display: grid; place-items: center; height: calc(var(--space-32) + var(--space-8)); margin-bottom: var(--space-3); padding: var(--space-4);
  border-bottom: 1px solid var(--line); background: var(--surface-raised); overflow: hidden; }
.aq-site-tiles__svg { width: auto; height: var(--space-32); max-width: 100%; overflow: visible; }
.aq-site-tiles__svg path, .aq-site-tiles__svg circle, .aq-site-tiles__svg rect { fill: none; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.aq-site-tiles__ln { stroke: var(--line-strong); stroke-width: 1.5px; }
.aq-site-tiles__thin { stroke: var(--line-strong); stroke-width: 1px; }
.aq-site-tiles__hid { stroke: var(--line-strong); stroke-width: 1px; stroke-dasharray: 3 4; }
.aq-site-tiles__limit { stroke: var(--ink-subtle); stroke-width: 1px; stroke-dasharray: 6 4; }
.aq-site-tiles__flow { stroke: var(--flow); stroke-width: 2px; }
.aq-site-tiles__svg .aq-site-tiles__dot { fill: var(--flow); stroke: var(--flow); stroke-width: 1.5px; }
.aq-site-tiles__spot { color: var(--ink-muted); }
.aq-site-tiles__n, .aq-site-tiles__t, .aq-site-tiles__d, .aq-site-tiles__go { margin: 0; padding-inline: var(--space-6); }
.aq-site-tiles__n { display: block; overflow: hidden; font: 300 56px/56px var(--font-sans); letter-spacing: -0.04em; color: var(--ink); font-variant-numeric: tabular-nums; transition: color 300ms; }
.aq-site-tiles__n > span { display: block; }
.aq-site-tiles__tile:hover .aq-site-tiles__n { color: var(--flow); }
.aq-site-tiles__t { font: 400 20px/28px var(--font-sans); letter-spacing: -0.01em; color: var(--ink); text-wrap: balance; }
.aq-site-tiles__d { font: 400 15px/24px var(--font-sans); color: var(--ink-muted); }
/* links sit on one line across the row (the page reset .aq-page p would cancel a single-class margin) */
.aq-site-tiles .aq-site-tiles__go { margin-top: auto; padding-top: var(--space-2); }
.aq-site-tiles__go a { display: inline-block; padding-block: var(--space-3); color: var(--flow); text-decoration: none; font: 500 14px/20px var(--font-sans); }
.aq-site-tiles__go a::after { content: "→"; margin-left: var(--space-1); transition: transform 200ms; }
.aq-site-tiles__go a:hover::after { transform: translateX(var(--space-1)); }
.aq-site-tiles__go a:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }

@container (max-width: 1100px) {
  .aq-site-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
/* Phones: one tile per row, the plate a short band beside the number */
@container (max-width: 860px) {
  .aq-site-tiles { grid-template-columns: minmax(0, 1fr); }
  /* the plate is a square figure beside the number and title; the line and link run full width under them */
  .aq-site-tiles__tile { display: grid; grid-template-columns: minmax(0, 1fr) var(--space-32); column-gap: 0; align-content: start; }
  .aq-site-tiles__plate { grid-column: 2; grid-row: 1 / span 2; align-self: start; height: var(--space-32); margin: 0; padding: var(--space-3); border-left: 1px solid var(--line); }
  .aq-site-tiles__svg { width: 100%; height: auto; }
  .aq-site-tiles__n { grid-column: 1; grid-row: 1; padding-top: var(--space-4); font-size: 40px; line-height: 44px; }
  .aq-site-tiles__t { grid-column: 1; grid-row: 2; align-self: start; padding-right: var(--space-3); }
  .aq-site-tiles__d, .aq-site-tiles .aq-site-tiles__go { grid-column: 1 / -1; }
  .aq-site-tiles__d { margin-top: var(--space-1); }
  .aq-site-tiles__n, .aq-site-tiles__t, .aq-site-tiles__d, .aq-site-tiles__go { padding-inline: var(--space-4); }
}

/* ---------- SpareSheet: like-for-like rules on a limestone drawing sheet (look "spare-sheet") ----------
   A limestone sheet (data-theme light) on the section ground: double border (outer line-strong, inner hairline), the
   title and intro top left, the dimensioned part drawing top right (equipment 1.5 px line-strong, centre line
   dash-dot, dimensions and balloon in hairline ink-muted, drawing letters mono), the four-column table under them on
   hairlines with numbered column notes, a title block bottom right. The chosen row carries a flow rule at its left. */
.aq-spare-sheet {
  position: relative; background: var(--limestone); color: var(--on-limestone);
  border: 1px solid var(--line-strong); outline: 1px solid var(--line); outline-offset: calc(-1 * var(--space-2));
  padding: var(--space-12) var(--space-12) var(--space-24);
}
.aq-spare-sheet__top { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: var(--space-8); align-items: center; }
.aq-spare-sheet .aq-sec-head .aq-h1 { font-weight: 300; font-size: 56px; line-height: 60px; letter-spacing: -0.03em; }
.aq-spare-sheet .aq-sec-head .aq-lead { color: var(--on-limestone-muted); }
.aq-spare-sheet__fig { margin: 0; }
.aq-spare-sheet__svg { display: block; width: 100%; height: auto; overflow: visible; }
.aq-spare-sheet__cross { fill: none; stroke: var(--line-strong); stroke-width: 1; }
.aq-spare-sheet__part { display: none; }
.aq-spare-sheet__part.is-on { display: inline; }
.aq-spare-sheet__art * { fill: none; stroke: var(--line-strong); stroke-width: 1.5; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.aq-spare-sheet__art .k-t { stroke: var(--ink-muted); stroke-width: 1; }
.aq-spare-sheet__art .k-a { stroke: var(--flow); }
.aq-spare-sheet__cl { fill: none; stroke: var(--ink-muted); stroke-width: 1; stroke-dasharray: 14 3 2 3; }
.aq-spare-sheet__dim { fill: none; stroke: var(--ink-muted); stroke-width: 1; }
.aq-spare-sheet__dot { fill: var(--ink-muted); }
.aq-spare-sheet__ball { fill: var(--limestone); stroke: var(--line-strong); stroke-width: 1; }
.aq-spare-sheet__dt, .aq-spare-sheet__bt { font: 400 12px/1 var(--font-mono); fill: var(--ink-muted); text-anchor: middle; }
.aq-spare-sheet__bt { fill: var(--on-limestone); }

.aq-spare-sheet .aq-fold { margin-top: var(--space-8); }
.aq-spare-sheet__table { width: 100%; border-collapse: collapse; table-layout: fixed; }
.aq-spare-sheet__table thead th {
  padding: 0 var(--space-4) var(--space-3) 0; text-align: left; vertical-align: bottom;
  font: 400 12px/17px var(--font-mono); color: var(--on-limestone-muted); border-bottom: 1px solid var(--line-strong);
}
.aq-spare-sheet__table thead th:first-child { width: 26%; }
.aq-spare-sheet__hn {
  display: inline-grid; place-items: center; width: var(--space-6); height: var(--space-6); margin-right: var(--space-2);
  border: 1px solid var(--line-strong); color: var(--on-limestone);
}
.aq-spare-sheet__row th, .aq-spare-sheet__row td {
  padding: var(--space-3) var(--space-4) var(--space-3) 0; vertical-align: top; text-align: left;
  border-bottom: 1px solid var(--line); font-size: 15px; line-height: 22px;
}
.aq-spare-sheet__row th { font-weight: 400; padding: 0; }
.aq-spare-sheet__k { display: none; }
.aq-spare-sheet__pick {
  display: flex; gap: var(--space-3); align-items: baseline; width: 100%; min-height: 44px; margin: 0;
  padding: var(--space-3) var(--space-4) var(--space-3) var(--space-3); border: 0; border-left: 2px solid transparent;
  background: transparent; color: var(--on-limestone); font: 400 16px/22px var(--font-sans); text-align: left; cursor: pointer;
  transition: border-color 160ms ease, background-color 160ms ease;
}
.aq-spare-sheet__pick:focus-visible { outline: 2px solid var(--focus); outline-offset: -2px; }
.aq-spare-sheet__n { font: 400 12px/22px var(--font-mono); color: var(--on-limestone-muted); }
.aq-spare-sheet__row.is-on .aq-spare-sheet__pick { border-left-color: var(--flow); background: var(--flow-tint); }
.aq-spare-sheet__row.is-on .aq-spare-sheet__n { color: var(--flow); }
.aq-fold:not(.is-open) .aq-spare-sheet__row.aq-fold-x { display: table-row; }
.aq-fold:has(> .aq-spare-sheet__table) > .aq-fold__btn { display: none; }

.aq-spare-sheet__tb {
  position: absolute; right: var(--space-2); bottom: var(--space-2); display: grid; grid-template-columns: auto auto;
  border-top: 1px solid var(--line-strong); border-left: 1px solid var(--line-strong);
}
.aq-spare-sheet__tb > span { padding: var(--space-2) var(--space-4); font: 400 12px/17px var(--font-mono); color: var(--on-limestone-muted); }
.aq-spare-sheet__tbn { border-right: 1px solid var(--line-strong); color: var(--on-limestone); min-width: 14rem; }
.aq-spare-sheet__tbi { font-variant-numeric: tabular-nums; }
.aq-spare-sheet__tbp { display: none; }
.aq-spare-sheet__tbp.is-on { display: inline; }

@container (max-width: 860px) {
  .aq-spare-sheet { padding: var(--space-8) var(--space-4) var(--space-16); }
  .aq-spare-sheet__top { grid-template-columns: minmax(0, 1fr); gap: var(--space-4); }
  .aq-spare-sheet .aq-sec-head .aq-h1 { font-size: 34px; line-height: 40px; }
  .aq-spare-sheet__table, .aq-spare-sheet__table tbody { display: block; }
  .aq-spare-sheet__table thead { display: none; }
  .aq-spare-sheet__row, .aq-fold:not(.is-open) .aq-spare-sheet__row.aq-fold-x { display: block; padding-bottom: var(--space-3); border-bottom: 1px solid var(--line-strong); }
  .aq-fold:not(.is-open) .aq-spare-sheet__row.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-spare-sheet__table) > .aq-fold__btn { display: flex; }
  .aq-spare-sheet__row th, .aq-spare-sheet__row td { display: block; border: 0; padding: var(--space-1) 0 var(--space-1) var(--space-3); }
  .aq-spare-sheet__row th { padding: 0; }
  .aq-spare-sheet__k { display: block; font: 400 12px/17px var(--font-mono); color: var(--on-limestone-muted); }
  .aq-spare-sheet__tbn { min-width: 0; }
}

/* ---------- SpineShelf: the turnover package as binder spines on one shelf beside its index that opens (look
   "spine-shelf"). Spines are limestone (every third a shade apart), the key section navy; a spine's width follows how
   many documents its section holds. Opening a section pulls its spine up off the shelf with a flow edge. ---------- */
.aq-spine-shelf-sec { position: relative; }
.aq-spine-shelf__index { min-width: 0; }
.aq-spine-shelf { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); column-gap: var(--space-16); align-items: start; }

/* The shelf (decoration; the index is the content) */
.aq-spine-shelf__shelf { position: sticky; top: var(--space-24); padding-top: var(--space-12); }
.aq-spine-shelf__row { display: flex; align-items: flex-end; gap: calc(var(--space-1) / 2); height: calc(var(--space-32) * 3.25); padding: 0 var(--space-2); }
.aq-spine-shelf__spine { position: relative; flex: var(--w, 4) 1 0; min-width: calc(var(--space-6) + var(--space-2)); height: 100%; cursor: pointer; }
.aq-spine-shelf__body {
  position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; gap: var(--space-3);
  padding: var(--space-3) 0 var(--space-4); background: var(--limestone); color: var(--on-limestone);
  border: 1px solid color-mix(in srgb, var(--on-limestone) 26%, transparent);
  transition: transform 320ms cubic-bezier(0.2, 0, 0, 1), box-shadow 320ms cubic-bezier(0.2, 0, 0, 1);
}
.aq-spine-shelf__spine:nth-child(3n+2) .aq-spine-shelf__body { background: color-mix(in srgb, var(--limestone) 90%, var(--on-limestone)); }
.aq-spine-shelf__spine:nth-child(3n) .aq-spine-shelf__body { background: color-mix(in srgb, var(--limestone) 60%, var(--on-navy)); }
/* binding bands near top and foot */
.aq-spine-shelf__body::before, .aq-spine-shelf__body::after { content: ""; position: absolute; left: 0; right: 0; height: 0; border-top: 1px solid color-mix(in srgb, var(--on-limestone) 30%, transparent); }
.aq-spine-shelf__body::before { top: var(--space-8); }
.aq-spine-shelf__body::after { bottom: var(--space-12); }
.aq-spine-shelf__no { font: 500 12px/16px var(--font-mono); letter-spacing: 0.02em; font-variant-numeric: tabular-nums; }
.aq-spine-shelf__holder {
  flex: 1 1 auto; min-height: 0; display: flex; justify-content: center; width: calc(100% - var(--space-2) * 2); max-width: var(--space-8);
  margin-top: var(--space-3); padding: var(--space-3) 0; background: color-mix(in srgb, var(--limestone) 30%, var(--on-navy)); border: 1px solid color-mix(in srgb, var(--on-limestone) 30%, transparent); overflow: hidden;
}
.aq-spine-shelf__name { writing-mode: vertical-rl; transform: rotate(180deg); font: 400 13px/16px var(--font-sans); color: var(--on-limestone); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-height: 100%; }
.aq-spine-shelf__ring { flex: none; width: var(--space-3); height: var(--space-3); margin-bottom: var(--space-1); border: 1.5px solid color-mix(in srgb, var(--on-limestone) 55%, transparent); border-radius: var(--radius-pill); }
/* the key section: the navy spine */
.aq-spine-shelf__spine.is-key .aq-spine-shelf__body { background: var(--navy); color: var(--on-navy); border-color: var(--navy); }
.aq-spine-shelf__spine.is-key .aq-spine-shelf__body::before, .aq-spine-shelf__spine.is-key .aq-spine-shelf__body::after { border-top-color: color-mix(in srgb, var(--on-navy) 30%, transparent); }
.aq-spine-shelf__spine.is-key .aq-spine-shelf__holder { background: color-mix(in srgb, var(--navy) 80%, var(--on-navy)); border-color: color-mix(in srgb, var(--on-navy) 35%, transparent); }
.aq-spine-shelf__spine.is-key .aq-spine-shelf__name { color: var(--on-navy); }
.aq-spine-shelf__spine.is-key .aq-spine-shelf__ring { border-color: var(--on-navy-muted); }
/* lifted (pointing at its row) and pulled (its section open) */
.aq-spine-shelf__spine.is-hover .aq-spine-shelf__body { transform: translateY(calc(-1 * var(--space-3))); }
.aq-spine-shelf__spine.is-open .aq-spine-shelf__body { transform: translateY(calc(-1 * var(--space-8))); box-shadow: inset 0 2px 0 var(--flow); }
.aq-spine-shelf__board { display: block; height: var(--space-3); border-top: 1.5px solid var(--line-strong); border-bottom: 1px solid var(--line); background: var(--surface-sunken); }
.aq-spine-shelf__cap { margin: var(--space-3) 0 0; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }

/* The index */
.aq-spine-shelf__list { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line-strong); }
.aq-spine-shelf__item { border-bottom: 1px solid var(--line); }
.aq-spine-shelf__sum {
  list-style: none; display: grid; grid-template-columns: var(--space-12) auto minmax(var(--space-8), 1fr) var(--space-8); align-items: center; column-gap: var(--space-4);
  min-height: calc(var(--space-12) + var(--space-3)); cursor: pointer; transition: background 200ms cubic-bezier(0.2, 0, 0, 1);
}
.aq-spine-shelf__sum::-webkit-details-marker { display: none; }
.aq-spine-shelf__sum:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-spine-shelf__item.is-hover .aq-spine-shelf__sum { background: color-mix(in srgb, var(--flow-tint) 55%, transparent); }
.aq-spine-shelf__n { font: 400 13px/24px var(--font-mono); font-variant-numeric: tabular-nums; color: var(--ink-subtle); padding-left: var(--space-2); }
.aq-spine-shelf__t { margin: 0; font: 300 24px/30px var(--font-sans); letter-spacing: -0.015em; color: var(--ink); text-wrap: balance; }
.aq-spine-shelf__lead { align-self: center; height: 0; margin-top: var(--space-2); border-bottom: 1.5px dotted var(--line-strong); }
.aq-spine-shelf__mark { position: relative; justify-self: end; width: var(--space-6); height: var(--space-6); margin-right: var(--space-2); }
.aq-spine-shelf__mark::before, .aq-spine-shelf__mark::after { content: ""; position: absolute; left: 50%; top: 50%; width: var(--space-4); height: 0; border-top: 1.5px solid var(--ink-muted); transform: translate(-50%, -50%); transition: transform 240ms cubic-bezier(0.2, 0, 0, 1); }
.aq-spine-shelf__mark::after { transform: translate(-50%, -50%) rotate(90deg); }
details[open] > .aq-spine-shelf__sum .aq-spine-shelf__mark::after { transform: translate(-50%, -50%) rotate(0deg); }
details[open] > .aq-spine-shelf__sum .aq-spine-shelf__n, .aq-spine-shelf__item.is-key .aq-spine-shelf__n { color: var(--flow); }
details[open] > .aq-spine-shelf__sum .aq-spine-shelf__t { font-weight: 400; }
.aq-spine-shelf__docs {
  list-style: none; margin: 0; padding: var(--space-1) var(--space-8) var(--space-6) calc(var(--space-12) + var(--space-4));
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: var(--space-8); row-gap: var(--space-3);
}
.aq-spine-shelf__docs li { position: relative; padding-left: var(--space-6); font: 400 15px/22px var(--font-sans); color: var(--ink-muted); text-wrap: pretty; }
/* each document a small sheet with a folded corner */
.aq-spine-shelf__docs li::before {
  content: ""; position: absolute; left: 0; top: var(--space-1); width: var(--space-3); height: var(--space-4);
  border: 1px solid var(--line-strong); background: var(--surface-raised); clip-path: polygon(0 0, 66% 0, 100% 28%, 100% 100%, 0 100%);
}
.aq-spine-shelf__item.is-key .aq-spine-shelf__docs li::before { border-color: var(--flow); }

/* Fold: desktop shows the whole index; the fold works on phones only */
.aq-fold:not(.is-open) .aq-spine-shelf__item.aq-fold-x { display: block; }
.aq-fold:has(> .aq-spine-shelf__list) > .aq-fold__btn { display: none; }

@media (prefers-reduced-motion: reduce) { .aq-spine-shelf__body, .aq-spine-shelf__mark::before, .aq-spine-shelf__mark::after { transition: none; } }

@container (max-width: 860px) {
  .aq-spine-shelf { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-8); }
  .aq-spine-shelf__shelf { position: relative; top: auto; padding-top: var(--space-8); }
  .aq-spine-shelf__row { height: calc(var(--space-32) + var(--space-8)); padding: 0; gap: 1px; }
  .aq-spine-shelf__spine { min-width: 0; }
  .aq-spine-shelf__holder { display: none; }
  .aq-spine-shelf__body { padding-top: var(--space-2); }
  .aq-spine-shelf__body::before { top: var(--space-6); }
  .aq-spine-shelf__body::after { bottom: var(--space-8); }
  .aq-spine-shelf__no { writing-mode: vertical-rl; transform: rotate(180deg); }
  .aq-spine-shelf__ring { margin-top: auto; }
  .aq-spine-shelf__spine.is-open .aq-spine-shelf__body { transform: translateY(calc(-1 * var(--space-6))); }
  .aq-spine-shelf__sum { grid-template-columns: var(--space-8) minmax(0, 1fr) var(--space-8); column-gap: var(--space-3); min-height: var(--space-12); padding-block: var(--space-2); }
  .aq-spine-shelf__lead { display: none; }
  .aq-spine-shelf__n { padding-left: 0; font-size: 12px; }
  .aq-spine-shelf__t { font-size: 19px; line-height: 26px; }
  .aq-spine-shelf__docs { grid-template-columns: minmax(0, 1fr); padding: 0 0 var(--space-4) calc(var(--space-8) + var(--space-3)); row-gap: var(--space-2); }
  .aq-spine-shelf__docs li { font-size: 14px; line-height: 21px; }
  .aq-fold:not(.is-open) .aq-spine-shelf__item.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-spine-shelf__list) > .aq-fold__btn { display: flex; }
}

/* ---------- SpoolDossier: a dossier beside the as-built isometric it indexes, on the limestone band (look
   "spool-dossier"). Title huge and light at the top left, the spool (IsoKit, aq-iso--limestone) at the right, the
   parts in a hairline grid underneath. The figure's data-layer (joints, lots, quals, test) shows what the pointed part
   records; layers change in 240 ms. ---------- */
.aq-spool-dossier {
  --sd-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  display: grid; grid-template-columns: minmax(0, 0.75fr) minmax(0, 1.25fr); column-gap: var(--space-8); align-items: center;
}
.aq-spool-dossier__head .aq-h1 { font: 300 80px/82px var(--font-sans); letter-spacing: -0.035em; max-width: 9ch; color: var(--on-limestone); }
.aq-spool-dossier__head .aq-lead { color: var(--on-limestone-muted); }
.aq-spool-dossier__fig { position: relative; }
.aq-spool-dossier__fig .aq-iso { max-height: 520px; }

/* drawing labels */
.aq-spool-dossier__j text, .aq-spool-dossier__lot text { font: 500 10px/1 var(--font-mono); letter-spacing: 0.06em; fill: var(--on-limestone-muted); transition: fill 240ms var(--sd-ease, ease-out); }
.aq-spool-dossier__dot { fill: var(--on-limestone); transition: fill 240ms var(--sd-ease, ease-out), r 240ms var(--sd-ease, ease-out); }
.aq-spool-dossier__ring { fill: none; stroke: var(--flow); stroke-width: 1.5; stroke-opacity: 0; transform-box: fill-box; transform-origin: 50% 50%; transform: scale(0.4); transition: stroke-opacity 240ms var(--sd-ease, ease-out), transform 240ms var(--sd-ease, ease-out); }
.aq-spool-dossier__lot text { font-size: 11px; }
.aq-spool-dossier__svg .aq-iso__flow { transition: stroke-width 240ms var(--sd-ease, ease-out), opacity 240ms var(--sd-ease, ease-out); opacity: 0.45; }
.aq-spool-dossier__svg .aq-iso__pipe-wall { transition: stroke 240ms var(--sd-ease, ease-out); }

/* layers */
.aq-spool-dossier__fig[data-layer="joints"] .aq-spool-dossier__dot { fill: var(--flow); r: 6px; }
.aq-spool-dossier__fig[data-layer="joints"] .aq-spool-dossier__j text { fill: var(--flow); }
.aq-spool-dossier__fig[data-layer="quals"] .aq-spool-dossier__ring { stroke-opacity: 1; transform: scale(1); }
.aq-spool-dossier__fig[data-layer="quals"] .aq-spool-dossier__dot { fill: var(--flow); }
.aq-spool-dossier__fig[data-layer="lots"] .aq-spool-dossier__len .aq-iso__pipe-wall { stroke: var(--flow); }
.aq-spool-dossier__fig[data-layer="lots"] .aq-spool-dossier__lot text { fill: var(--flow); }
.aq-spool-dossier__fig[data-layer="test"] .aq-iso__flow { stroke-width: 4; opacity: 1; }
.aq-spool-dossier__fig[data-layer="test"] [data-iso-id="cap"] .aq-iso__eq, .aq-spool-dossier__fig[data-layer="test"] [data-iso-id="cap"] .aq-iso__ln { stroke: var(--flow); }

/* the parts: a hairline grid */
.aq-spool-dossier__parts { grid-column: 1 / -1; margin-top: var(--space-12); }
.aq-spool-dossier__list { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(min(var(--n, 4), 4), minmax(0, 1fr)); column-gap: var(--space-8); row-gap: var(--space-8); }
.aq-spool-dossier__item {
  display: flex; flex-direction: column; gap: var(--space-2); padding-top: var(--space-4); border-top: 1px solid var(--on-limestone-muted);
  outline-offset: var(--space-2); transition: border-color 240ms var(--sd-ease, ease-out);
}
.aq-spool-dossier__item[data-layer] { cursor: default; }
.aq-spool-dossier__item:focus-visible { outline: 2px solid var(--focus); }
.aq-spool-dossier__item.is-on { border-top-color: var(--flow); box-shadow: inset 0 1px 0 var(--flow); }
.aq-spool-dossier__n { font: 400 32px/36px var(--font-sans); letter-spacing: -0.02em; color: var(--on-limestone); }
.aq-spool-dossier__item.is-key .aq-spool-dossier__n, .aq-spool-dossier__item.is-on .aq-spool-dossier__n { color: var(--flow); }
.aq-spool-dossier__t { margin: var(--space-2) 0 0; font: 500 13px/18px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--on-limestone); text-wrap: balance; }
.aq-spool-dossier__t a { color: inherit; text-decoration: underline; text-decoration-color: var(--flow); text-underline-offset: 0.2em; }
.aq-spool-dossier__t a::after { content: " \2192"; }
.aq-spool-dossier__d { margin: 0; font: 400 16px/24px var(--font-sans); color: var(--on-limestone-muted); text-wrap: pretty; }
.aq-spool-dossier__more { margin: var(--space-8) 0 0; }

@media (prefers-reduced-motion: reduce) {
  .aq-spool-dossier * { transition: none !important; }
}
@container (max-width: 860px) {
  .aq-spool-dossier { grid-template-columns: minmax(0, 1fr); }
  .aq-spool-dossier__head .aq-h1 { font: 300 44px/48px var(--font-sans); }
  .aq-spool-dossier__fig { margin-top: var(--space-6); }
  .aq-spool-dossier__parts { margin-top: var(--space-8); }
  .aq-spool-dossier__list { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-6); }
}
.aq-spool-dossier-sec .aq-spool-dossier { position: relative; }
.aq-spool-dossier__fit .aq-iso__pipe-wall { stroke-width: 1.5; }
@container (max-width: 860px) {
  .aq-spool-dossier__j text, .aq-spool-dossier__lot text { font-size: 12px; }
}

/* ---------- StageStacks: what each stage issues, as the turnover package building up along the project axis (look
   "stage-stacks"). Navy ground (aq-band--navy). Stages share one grid (subgrid rows: stack, axis, stage, step), so
   every stack stands on the same axis line and every name and step line up across. Sheets are limestone paper, one
   per document, stacked bottom up. The axis is the only flow line. ---------- */
.aq-stage-stacks-sec { position: relative; }
.aq-stage-stacks { position: relative; padding-left: calc(var(--space-32) + var(--space-6)); }
.aq-stage-stacks__list {
  list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(var(--n, 6), minmax(0, 1fr));
  grid-template-rows: auto var(--space-8) auto auto; column-gap: 0;
}
.aq-stage-stacks__stage { position: relative; display: grid; grid-row: 1 / span 4; grid-template-rows: subgrid; min-width: 0; }
.aq-stage-stacks__head { grid-row: 3; position: relative; padding: var(--space-4) var(--space-3) 0 var(--space-2); }
.aq-stage-stacks__pile { grid-row: 1; position: relative; align-self: end; padding: var(--space-12) var(--space-3) var(--space-3) var(--space-2); }
.aq-stage-stacks__axis { grid-row: 2; position: relative; }
.aq-stage-stacks__who { grid-row: 4; position: relative; padding: var(--space-4) var(--space-3) 0 var(--space-2); }

/* the axis: one flow run through a node per stage */
.aq-stage-stacks__axis::before { content: ""; position: absolute; left: 0; right: 0; top: 50%; border-top: 1px solid color-mix(in srgb, var(--on-navy-muted) 35%, transparent); }
.aq-stage-stacks__run { position: absolute; left: 0; right: 0; top: 50%; margin-top: -1px; border-top: 2px solid var(--flow); }
.aq-stage-stacks__stage:last-child .aq-stage-stacks__run { right: var(--space-6); }
.aq-stage-stacks__stage:last-child .aq-stage-stacks__axis::after {
  content: ""; position: absolute; right: var(--space-4); top: 50%; width: var(--space-3); height: var(--space-3);
  border-top: 2px solid var(--flow); border-right: 2px solid var(--flow); transform: translateY(-50%) rotate(45deg);
}
.aq-stage-stacks__node {
  position: absolute; left: var(--space-2); top: 50%; width: var(--space-3); height: var(--space-3); transform: translateY(-50%);
  background: var(--navy); border: 2px solid var(--flow); transition: background 200ms cubic-bezier(0.2, 0, 0, 1);
}
.aq-stage-stacks__stage:hover .aq-stage-stacks__node { background: var(--flow); }

/* the stage */
.aq-stage-stacks__name { margin: 0; display: flex; flex-direction: column; gap: var(--space-1); }
.aq-stage-stacks__no { font: 500 12px/16px var(--font-mono); letter-spacing: 0.04em; color: var(--on-navy-muted); }
.aq-stage-stacks__nm { font: 300 22px/28px var(--font-sans); letter-spacing: -0.015em; color: var(--on-navy); text-wrap: balance; }
.aq-stage-stacks__nm a { color: inherit; }
.aq-stage-stacks__ref { font: 400 12px/18px var(--font-mono); color: var(--on-navy-muted); }
.aq-stage-stacks__step { margin: 0; padding-top: var(--space-3); border-top: 1px dashed color-mix(in srgb, var(--on-navy-muted) 45%, transparent); font: 400 14px/21px var(--font-sans); color: var(--on-navy-muted); text-wrap: pretty; }

/* the stack: sheets bottom up */
.aq-stage-stacks__docs { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column-reverse; gap: 2px; }
.aq-stage-stacks__doc {
  position: relative; padding: var(--space-2) var(--space-3); background: var(--limestone); color: var(--on-limestone);
  font: 400 13px/18px var(--font-sans); text-wrap: pretty; transition: transform 240ms cubic-bezier(0.2, 0, 0, 1);
  box-shadow: inset 2px 0 0 color-mix(in srgb, var(--on-limestone) 18%, transparent);
}
.aq-stage-stacks__doc:nth-child(even) { transform: translateX(var(--space-1)); background: color-mix(in srgb, var(--limestone) 70%, var(--on-navy)); }
.aq-stage-stacks__doc:last-child { clip-path: polygon(0 0, calc(100% - var(--space-3)) 0, 100% var(--space-3), 100% 100%, 0 100%); }
.aq-stage-stacks__stage:hover .aq-stage-stacks__doc { transform: translateY(calc(-1 * var(--space-1))); }
.aq-stage-stacks__stage:hover .aq-stage-stacks__doc:nth-child(even) { transform: translate(var(--space-1), calc(-1 * var(--space-1))); }

/* band labels: the table's column names, once, in the margin left of the first stage */
.aq-stage-stacks__k { display: none; margin: 0; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-stage-stacks__stage:first-child .aq-stage-stacks__k { display: block; position: absolute; right: calc(100% + var(--space-6)); width: var(--space-32); text-align: right; text-wrap: balance; }
.aq-stage-stacks__stage:first-child .aq-stage-stacks__pile > .aq-stage-stacks__k { bottom: var(--space-3); }
.aq-stage-stacks__stage:first-child .aq-stage-stacks__head > .aq-stage-stacks__k { top: var(--space-4); }
.aq-stage-stacks__stage:first-child .aq-stage-stacks__who > .aq-stage-stacks__k { top: calc(var(--space-4) + var(--space-3)); }

/* Fold: desktop shows the whole axis; the fold works on phones only */
.aq-fold:not(.is-open) .aq-stage-stacks__stage.aq-fold-x { display: grid; }
.aq-fold:has(> .aq-stage-stacks__list) > .aq-fold__btn { display: none; }

@media (prefers-reduced-motion: reduce) { .aq-stage-stacks__doc { transition: none; } }

/* mid widths: the band labels turn to read up the margin (bottom to top), so every band stays named */
@container (max-width: 1100px) {
  .aq-stage-stacks { padding-left: var(--space-12); }
  .aq-stage-stacks__stage:first-child .aq-stage-stacks__k {
    right: calc(100% + var(--space-4)); width: auto; max-inline-size: var(--space-32); writing-mode: vertical-rl; transform: rotate(180deg); text-align: start;
  }
  .aq-stage-stacks__stage:first-child .aq-stage-stacks__head > .aq-stage-stacks__k { top: var(--space-4); }
  .aq-stage-stacks__nm { font-size: 19px; line-height: 25px; }
}
@container (max-width: 860px) {
  .aq-stage-stacks__list { display: block; }
  .aq-stage-stacks__stage { grid-template-columns: var(--space-8) minmax(0, 1fr); grid-template-rows: none; grid-row: auto; padding-bottom: var(--space-8); }
  .aq-stage-stacks__head, .aq-stage-stacks__pile, .aq-stage-stacks__who { grid-column: 2; grid-row: auto; padding: 0; }
  .aq-stage-stacks__pile { padding-top: var(--space-4); align-self: start; }
  .aq-stage-stacks__who { padding-top: var(--space-4); }
  .aq-stage-stacks__axis { grid-column: 1; grid-row: 1 / span 3; position: absolute; left: 0; top: 0; bottom: 0; width: var(--space-8); }
  .aq-stage-stacks__axis::before { left: var(--space-2); right: auto; top: 0; bottom: 0; border-top: 0; border-left: 1px solid color-mix(in srgb, var(--on-navy-muted) 35%, transparent); }
  .aq-stage-stacks__run { left: var(--space-2); right: auto; top: 0; bottom: 0; margin: 0 0 0 calc(-1 * 1px / 2); border-top: 0; border-left: 2px solid var(--flow); }
  .aq-stage-stacks__stage:last-child .aq-stage-stacks__run { right: auto; bottom: var(--space-8); }
  .aq-stage-stacks__stage:last-child .aq-stage-stacks__axis::after { right: auto; top: auto; left: calc(var(--space-2) - var(--space-3) / 2 + 1px); bottom: var(--space-6); border-top: 0; border-left: 0; border-right: 2px solid var(--flow); border-bottom: 2px solid var(--flow); transform: rotate(45deg); }
  .aq-stage-stacks__node { left: calc(var(--space-2) - var(--space-3) / 2 + 1px); top: var(--space-2); transform: none; }
  .aq-stage-stacks { padding-left: 0; }
  .aq-stage-stacks__nm { font-size: 20px; line-height: 26px; }
  .aq-stage-stacks__docs { flex-direction: row; flex-wrap: wrap; gap: var(--space-1); }
  .aq-stage-stacks__doc, .aq-stage-stacks__doc:nth-child(even) { transform: none; }
  .aq-stage-stacks__doc:last-child { clip-path: none; }
  .aq-stage-stacks__k.is-ph, .aq-stage-stacks__stage:first-child .aq-stage-stacks__k { display: block; position: static; width: auto; max-inline-size: none; writing-mode: horizontal-tb; transform: none; text-align: left; margin-bottom: var(--space-2); }
  .aq-stage-stacks__head > .aq-stage-stacks__k, .aq-stage-stacks__stage:first-child .aq-stage-stacks__head > .aq-stage-stacks__k { display: none; }
  .aq-stage-stacks__step { border-top: 0; padding-top: 0; }
  .aq-fold:not(.is-open) .aq-stage-stacks__stage.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-stage-stacks__list) > .aq-fold__btn { display: flex; color: var(--on-navy-muted); margin-top: var(--space-2); }
}

/* ---------- StageTiles: ordered stages as a Swiss row of navy and limestone tiles (look "stage-tiles") ----------
   Desktop (six stages): a five-column grid. Row 1: the heading in a navy band across four columns, stage 05 at the
   right. Row 2: stages 01 to 04, stage 06 under 05. The list is one subgrid over both rows, so tiles sit in the
   wrapper's columns while the heading stays outside the list. Every tile leads with a huge light mono numeral and a
   lighter slash; the words sit at the tile's foot. Tones run limestone, navy, navy, so no two limestone tiles meet.
   The art tile (IQ) carries the pipe-run blueprint above a smaller numeral. */
.aq-stage-tiles { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); }
.aq-stage-tiles__head { grid-column: 1 / -1; background: var(--navy); color: var(--on-navy); padding: var(--space-12) var(--space-8); }
.aq-stage-tiles__head .aq-sec-head { display: flex; flex-wrap: wrap; align-items: flex-end; gap: var(--space-4) var(--space-8); margin: 0; max-width: none; }
.aq-stage-tiles__head .aq-h1 { margin: 0; color: var(--on-navy); font: 300 64px/68px var(--font-sans); letter-spacing: -0.03em; }
.aq-stage-tiles__head .aq-lead { margin: 0 0 var(--space-2); max-width: 32ch; padding: var(--space-1) var(--space-2); border: 1px solid color-mix(in srgb, var(--on-navy-muted) 55%, transparent); color: var(--on-navy-muted); font: 400 14px/20px var(--font-sans); }
.aq-stage-tiles__list { grid-column: 1 / -1; list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); }

.aq-stage-tiles__tile { position: relative; display: flex; flex-direction: column; gap: var(--space-6); min-height: calc(var(--space-32) * 2.6); padding: var(--space-8) var(--space-6); }
.aq-stage-tiles__tile::before { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 2px; background: var(--flow); transform: scaleX(0); transform-origin: 0 50%; transition: transform 180ms cubic-bezier(0.2, 0, 0, 1); }
.aq-stage-tiles__tile:hover::before, .aq-stage-tiles__tile:focus-within::before { transform: scaleX(1); }
.aq-stage-tiles__tile.is-lime { background: var(--limestone); color: var(--on-limestone); }
.aq-stage-tiles__tile.is-navy { background: var(--navy); color: var(--on-navy); }
.aq-stage-tiles__tile.is-navy + .is-navy, .aq-stage-tiles__head + .aq-stage-tiles__list .is-navy { border-left: 1px solid color-mix(in srgb, var(--on-navy-muted) 28%, transparent); }

.aq-stage-tiles__n { display: block; font: 300 96px/1 var(--font-mono); letter-spacing: -0.06em; white-space: nowrap; }
.aq-stage-tiles__n i { font-style: normal; margin-left: 0.04em; }
.is-lime .aq-stage-tiles__n i { color: var(--on-limestone-muted); }
.is-navy .aq-stage-tiles__n i { color: var(--on-navy-muted); }
.aq-stage-tiles__body { margin-top: auto; display: flex; flex-direction: column; gap: var(--space-2); }
.aq-stage-tiles__lab { font: 300 22px/28px var(--font-sans); }
.is-lime .aq-stage-tiles__lab { color: var(--on-limestone-muted); }
.is-navy .aq-stage-tiles__lab { color: var(--on-navy-muted); }
.aq-stage-tiles__t { margin: 0; font: 400 21px/27px var(--font-sans); letter-spacing: -0.01em; color: inherit; }
.aq-stage-tiles__t a { color: inherit; text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 0.2em; }
.is-navy .aq-stage-tiles__t a { text-decoration-color: var(--on-navy-muted); }
.aq-stage-tiles__t a:hover { text-decoration-color: currentColor; }
.aq-stage-tiles__t a:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-stage-tiles__d { margin: 0; font: 400 14px/21px var(--font-sans); }
.is-lime .aq-stage-tiles__d { color: var(--on-limestone-muted); }
.is-navy .aq-stage-tiles__d { color: var(--on-navy-muted); }

/* the art tile: the pipe-run blueprint in place of the big numeral */
.aq-stage-tiles__tile.has-art { gap: var(--space-4); }
.has-art .aq-stage-tiles__n { font-size: 40px; }
.aq-stage-tiles__art { margin: calc(-1 * var(--space-2)) calc(-1 * var(--space-2)) 0; border: 1px solid color-mix(in srgb, var(--on-navy-muted) 40%, transparent); }
.aq-stage-tiles__svg { display: block; width: 100%; height: auto; aspect-ratio: 3 / 2; }
.aq-stage-tiles__grid { fill: none; stroke: color-mix(in srgb, var(--on-navy-muted) 14%, transparent); stroke-width: 1; }
.aq-stage-tiles__pw { fill: none; stroke: var(--on-navy-muted); stroke-width: 9; stroke-linejoin: round; }
.aq-stage-tiles__pi { fill: none; stroke: var(--navy); stroke-width: 6; stroke-linejoin: round; }
.aq-stage-tiles__water { fill: none; stroke: color-mix(in srgb, var(--flow) 55%, var(--on-navy)); stroke-width: 1.5; stroke-dasharray: 5 5; }
.aq-stage-tiles__jt { fill: none; stroke: var(--on-navy); stroke-width: 2; }
.aq-stage-tiles__ar { fill: none; stroke: color-mix(in srgb, var(--flow) 55%, var(--on-navy)); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.aq-stage-tiles__tb { fill: none; stroke: color-mix(in srgb, var(--on-navy-muted) 55%, transparent); stroke-width: 1; }

/* roll faces (motion.js builds them; the numeral reads the same without them) */
.aq-stage-tiles__ch { position: relative; display: inline-block; perspective: 10000px; transform-style: preserve-3d; }
.aq-stage-tiles__ch > span { display: inline-block; backface-visibility: hidden; }
.aq-stage-tiles__ch > span + span { position: absolute; left: 0; top: 0; }

/* six stages, wide: the concept's composition */
@container (min-width: 1081px) {
  .aq-stage-tiles.is-six { grid-template-columns: repeat(5, minmax(0, 1fr)); grid-template-rows: auto auto; }
  .is-six .aq-stage-tiles__head { grid-column: 1 / 5; grid-row: 1; display: flex; align-items: flex-end; }
  .is-six .aq-stage-tiles__list { grid-column: 1 / -1; grid-row: 1 / 3; grid-template-columns: subgrid; grid-template-rows: subgrid; pointer-events: none; }
  .is-six .aq-stage-tiles__tile { pointer-events: auto; grid-row: 2; }
  .is-six .aq-stage-tiles__tile:nth-child(5) { grid-column: 5; grid-row: 1; min-height: 0; border-left: 1px solid color-mix(in srgb, var(--on-navy-muted) 28%, transparent); }
  .is-six .aq-stage-tiles__tile:nth-child(6) { grid-column: 5; grid-row: 2; border-top: 1px solid color-mix(in srgb, var(--on-navy-muted) 28%, transparent); }
  .is-six .aq-stage-tiles__tile:nth-child(5) .aq-stage-tiles__n { font-size: 80px; }
}

@container (max-width: 860px) {
  .aq-stage-tiles, .aq-stage-tiles__list { grid-template-columns: minmax(0, 1fr); }
  .aq-stage-tiles__head { padding: var(--space-8) var(--space-4); }
  .aq-stage-tiles__head .aq-h1 { font-size: 40px; line-height: 44px; }
  .aq-stage-tiles__tile { display: grid; grid-template-columns: var(--space-24) minmax(0, 1fr); align-items: start; column-gap: var(--space-4); min-height: 0; padding: var(--space-6) var(--space-4); }
  .aq-stage-tiles__tile.is-navy + .is-navy, .aq-stage-tiles__head + .aq-stage-tiles__list .is-navy { border-left: 0; border-top: 1px solid color-mix(in srgb, var(--on-navy-muted) 28%, transparent); }
  .aq-stage-tiles__n { font-size: 48px; }
  .aq-stage-tiles__body { margin-top: 0; }
  .aq-stage-tiles__lab { font-size: 17px; line-height: 24px; }
  .aq-stage-tiles__t { font-size: 18px; line-height: 24px; }
  .aq-stage-tiles__art { grid-column: 1 / -1; margin: 0 0 var(--space-2); }
  .has-art .aq-stage-tiles__n { font-size: 32px; }
}

/* section hook (the look marks its section) */
.aq-stage-tiles-sec { position: relative; }

/* ---------- StairRouter: situations as a rising staircase of cards over huge cropped outline type (look "stair-router") ----------
   Navy ground with a limestone wedge bottom right (a hard diagonal, no gradient). Behind everything, the block's
   kinetic word runs as outline type cropped by the section edges; it is drawn twice, clipped to each side of the
   diagonal, so its ink turns from on-navy to navy where it crosses onto the limestone. The end word sits solid on
   the wedge. Desktop: one column per situation, each card on a tread one rise higher than the last; treads and
   risers make one continuous stair line. The heading sits in the empty top-left corner above the low steps. */
.aq-stair-router-sec, .aq-section--alt.aq-stair-router-sec {
  --rise: var(--space-12);
  --stair: color-mix(in srgb, var(--flow) 45%, var(--on-navy));
  position: relative; overflow: clip; background: var(--navy); color: var(--on-navy);
}
.aq-stair-router-sec > .aq-in { position: relative; z-index: 2; }
.aq-stair-router__wedge { position: absolute; inset: 0; z-index: 0; background: var(--limestone); clip-path: polygon(100% 16%, 100% 100%, 56% 100%); }
.aq-stair-router__type { position: absolute; inset: 0; z-index: 1; pointer-events: none; }
.aq-stair-router__words { position: absolute; inset: 0; }
.aq-stair-router__words--navy { clip-path: polygon(0 0, 100% 0, 100% 16%, 56% 100%, 0 100%); opacity: 0.46; }
.aq-stair-router__words--lime { clip-path: polygon(100% 16%, 100% 100%, 56% 100%); opacity: 0.3; }
.aq-stair-router__w {
  position: absolute; white-space: nowrap; font: 500 24cqw/0.8 var(--font-sans); letter-spacing: -0.05em; color: transparent;
  -webkit-text-stroke: 1.5px var(--on-navy-muted);
}
.aq-stair-router__words--lime .aq-stair-router__w { -webkit-text-stroke-color: var(--navy); }
.aq-stair-router__w--a { top: -0.16em; right: -0.08em; }
.aq-stair-router__w--b { left: -0.1em; top: 50%; }
.aq-stair-router__w--c { left: -0.1em; top: calc(50% + 0.82em); }
.aq-stair-router__go {
  position: absolute; right: -0.03em; bottom: -0.2em; z-index: 1; margin: 0; pointer-events: none;
  font: 500 25cqw/1 var(--font-sans); letter-spacing: -0.06em; color: var(--navy);
}

.aq-stair-router { position: relative; display: grid; }
.aq-stair-router > .aq-sec-head { grid-area: 1 / 1; align-self: start; position: relative; z-index: 3; max-width: 40%; }
.aq-stair-router .aq-sec-head .aq-h1 { font: 300 64px/68px var(--font-sans); letter-spacing: -0.035em; color: var(--on-navy); max-width: none; }
.aq-stair-router .aq-sec-head .aq-eyebrow, .aq-stair-router .aq-sec-head .aq-lead { color: var(--on-navy-muted); }

.aq-stair-router__flight {
  grid-area: 1 / 1; list-style: none; margin: 0; padding: 0;
  display: grid; grid-template-columns: repeat(var(--n, 6), minmax(0, 1fr)); align-items: start;
}
.aq-stair-router__step { position: relative; min-width: 0; margin-top: calc((var(--n, 6) - 1 - var(--i, 0)) * var(--rise, var(--space-12))); padding-top: var(--rise, var(--space-12)); }
.aq-stair-router__n {
  position: absolute; top: 0; left: 0; height: var(--rise, var(--space-12)); display: flex; align-items: center; gap: var(--space-2);
  font: 400 22px/1 var(--font-mono); font-variant-numeric: tabular-nums; letter-spacing: 0.02em; color: var(--on-navy);
}
.aq-stair-router__num { display: inline-block; min-width: 2ch; }
.aq-stair-router__arrow {
  display: block; width: var(--space-6); height: 9px; background: var(--stair, var(--on-navy-muted));
  clip-path: polygon(0 4px, calc(100% - 7px) 4px, calc(100% - 7px) 0, 100% 50%, calc(100% - 7px) 100%, calc(100% - 7px) 5px, 0 5px);
}
.aq-stair-router__tread { position: absolute; top: var(--rise, var(--space-12)); left: 0; right: 0; height: 2px; margin-top: -1px; background: var(--stair, var(--on-navy-muted)); transform-origin: 0 50%; }
.aq-stair-router__riser { position: absolute; top: var(--rise, var(--space-12)); left: 0; width: 2px; height: var(--rise, var(--space-12)); margin-left: -1px; background: var(--stair, var(--on-navy-muted)); transform-origin: 50% 100%; }
.aq-stair-router__card {
  position: relative; margin: var(--space-2) var(--space-2) 0 var(--space-2); padding: var(--space-4) var(--space-3) var(--space-4);
  background: var(--surface-raised); color: var(--ink); border: 1px solid var(--line);
  transition: transform 200ms cubic-bezier(0.2, 0, 0, 1), border-color 200ms;
}
.aq-stair-router__step:first-child .aq-stair-router__card { margin-left: 0; }
.aq-stair-router__hit { position: absolute; inset: 0; z-index: 0; }
.aq-stair-router__t, .aq-stair-router__dl { position: relative; z-index: 1; pointer-events: none; }
.aq-stair-router__dl a { pointer-events: auto; }
.aq-stair-router__t { margin: 0 0 var(--space-3); font: 500 17px/22px var(--font-sans); letter-spacing: -0.005em; color: var(--ink); text-wrap: balance; }
.aq-stair-router__dl { margin: 0; display: flex; flex-direction: column; gap: var(--space-3); }
.aq-stair-router__f dt {
  padding-top: var(--space-2); border-top: 1px solid var(--line);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-muted);
}
.aq-stair-router__f dd { margin: var(--space-1) 0 0; font: 400 14px/20px var(--font-sans); color: var(--ink); overflow-wrap: break-word; text-wrap: pretty; }
/* the situation under its short title: a subtitle, its term ("Your situation") kept for screen readers only */
.aq-stair-router__f.is-sit dt { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; padding: 0; border: 0; }
.aq-stair-router__f.is-sit dd { margin: 0; color: var(--ink-muted); }
.aq-stair-router__t:has(+ .aq-stair-router__dl > .is-sit:first-child) { margin-bottom: var(--space-1); }
.aq-stair-router__f.is-go dt { border-top: 2px solid var(--flow); color: var(--flow); }
.aq-stair-router__f.is-go dd a { font-weight: 500; text-decoration: none; }
.aq-stair-router__f.is-go dd a::after { content: "\a0\2192"; }
.aq-stair-router__f.is-pending dt { border-top-style: dashed; }
.aq-stair-router__tbc { display: block; margin-top: var(--space-1); font: 500 12px/16px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-muted); }
/* the water: one flow dot at the top of the stair (motion climbs it there) */
.aq-stair-router__drop {
  position: absolute; top: var(--rise, var(--space-12)); right: 0; width: 10px; height: 10px; margin: -5px -5px 0 0; z-index: 2;
  border-radius: var(--radius-pill); background: var(--limestone); pointer-events: none;
}
/* hover or focus on a step: the card lifts off its tread, the tread and riser light */
.aq-stair-router__step:hover .aq-stair-router__card, .aq-stair-router__step:focus-within .aq-stair-router__card { transform: translateY(calc(-1 * var(--space-1))); border-color: var(--line-strong); }
.aq-stair-router__step:hover .aq-stair-router__tread, .aq-stair-router__step:hover .aq-stair-router__riser,
.aq-stair-router__step:focus-within .aq-stair-router__tread, .aq-stair-router__step:focus-within .aq-stair-router__riser { background: var(--limestone); }
.aq-stair-router__step.is-link:hover .is-go a { text-decoration: underline; }
.aq-stair-router__step:hover .aq-stair-router__arrow { background: var(--limestone); }

/* Narrower than the seven-column stair: the flight runs down the page, each step indented one notch further, its
   tread and riser drawing the stair along the cards' left edges */
@container (max-width: 1180px) {
  .aq-stair-router { display: block; }
  .aq-stair-router > .aq-sec-head { max-width: none; margin-bottom: var(--space-4); }
  .aq-stair-router__flight { display: flex; flex-direction: column; }
  .aq-stair-router__step { margin-top: 0; margin-left: calc(var(--i, 0) * var(--space-3)); }
  .aq-stair-router__riser { top: 0; height: var(--rise, var(--space-12)); }
  .aq-stair-router__tread { left: calc(-1 * var(--space-3)); }
  .aq-stair-router__step:first-child .aq-stair-router__tread { left: 0; }
  .aq-stair-router__card { margin: 0; }
  .aq-stair-router__dl { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-3) var(--space-6); }
  .aq-stair-router__drop { top: auto; bottom: 0; right: auto; left: calc((var(--n, 6) - 1) * var(--space-3)); margin: 0 0 -5px -5px; }
  .aq-stair-router-sec { padding-bottom: calc(var(--space-32) + var(--space-12)); }
  .aq-stair-router__wedge { clip-path: polygon(0 93%, 100% 84%, 100% 100%, 0 100%); }
  .aq-stair-router__words--navy { clip-path: polygon(0 0, 100% 0, 100% 84%, 0 93%); }
  .aq-stair-router__words--lime { clip-path: polygon(0 93%, 100% 84%, 100% 100%, 0 100%); }
  .aq-stair-router__w { font-size: 30cqw; }
  .aq-stair-router__w--b { top: 34%; }
  .aq-stair-router__w--c { top: calc(34% + 0.82em); }
  .aq-stair-router__go { font-size: 34cqw; bottom: -0.22em; }
}
@container (max-width: 860px) {
  .aq-stair-router-sec, .aq-section--alt.aq-stair-router-sec { --rise: var(--space-12); }
  .aq-stair-router .aq-sec-head .aq-h1 { font: 300 44px/48px var(--font-sans); letter-spacing: -0.03em; }
  .aq-stair-router__step { margin-left: calc(var(--i, 0) * var(--space-2)); }
  .aq-stair-router__tread { left: calc(-1 * var(--space-2)); }
  .aq-stair-router__drop { left: calc((var(--n, 6) - 1) * var(--space-2)); }
  .aq-stair-router__dl { display: flex; }
  .aq-stair-router__n { font-size: 20px; }
  .aq-stair-router__w { font-size: 44cqw; }
  .aq-stair-router__w--a { top: -0.12em; }
  .aq-stair-router__go { font-size: 46cqw; }
  .aq-stair-router-sec { padding-bottom: calc(var(--space-32) + var(--space-8)); }
}

/* ---------- StandardTiles: a Swiss row of tall linked tiles, the standard tag set as the hero ---------- */
.aq-standard-tiles-sec { position: relative; }
.aq-standard-tiles { list-style: none; margin: var(--space-8) 0 0; padding: 0; display: grid; grid-template-columns: repeat(var(--n, 4), minmax(0, 1fr)); gap: 1px;
  background: var(--line-strong); border: 1px solid var(--line-strong); }
/* Each tile spans four shared rows (count, tag, body, arrow) as a subgrid, so the hairlines line up across the row */
.aq-standard-tiles__tile { display: grid; grid-row: span 4; grid-template-rows: subgrid; row-gap: 0; min-width: 0; background: var(--surface-raised); }
.aq-standard-tiles__in { position: relative; display: grid; grid-row: span 4; grid-template-rows: subgrid; row-gap: var(--space-6); width: 100%; padding: var(--space-6);
  color: var(--ink); text-decoration: none; overflow: hidden; transition: background-color 300ms cubic-bezier(0.2, 0, 0, 1); }
.aq-standard-tiles__top { display: flex; align-items: flex-start; justify-content: space-between; }
.aq-standard-tiles__no { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; color: var(--ink-subtle); }
.aq-standard-tiles__ic { width: var(--space-16); height: var(--space-16); background-color: var(--ink-muted); transition: background-color 300ms, transform 500ms cubic-bezier(0.2, 0, 0, 1); }
.aq-standard-tiles__tag { display: block; font: 300 40px/44px var(--font-mono); letter-spacing: -0.04em; color: var(--ink); overflow-wrap: anywhere; text-wrap: balance; min-height: var(--space-32); }
.aq-standard-tiles__tag.is-word { font-family: var(--font-sans); letter-spacing: -0.03em; }
.aq-standard-tiles__body { display: flex; flex-direction: column; gap: var(--space-2); align-self: start; padding-top: var(--space-4); border-top: 1px solid var(--line); }
.aq-standard-tiles__t { margin: 0; font: 400 20px/26px var(--font-sans); letter-spacing: -0.01em; }
.aq-standard-tiles__d { font: 400 15px/23px var(--font-sans); color: var(--ink-muted); }
.aq-standard-tiles__arrow { position: relative; display: block; width: var(--space-12); height: var(--space-4); color: var(--flow); }
.aq-standard-tiles__arrow::before { content: ""; position: absolute; left: 0; right: 1px; top: 50%; height: 1.5px; background: currentColor; transform: scaleX(0.4); transform-origin: 0 50%;
  transition: transform 400ms cubic-bezier(0.2, 0, 0, 1); }
.aq-standard-tiles__arrow::after { content: ""; position: absolute; left: calc(40% - var(--space-2)); top: 50%; width: var(--space-2); height: var(--space-2); border-top: 1.5px solid currentColor;
  border-right: 1.5px solid currentColor; transform: translateY(-50%) rotate(45deg); transition: left 400ms cubic-bezier(0.2, 0, 0, 1); }

/* Lead tile: navy */
.aq-standard-tiles__tile.is-lead { background: var(--navy); }
.is-lead .aq-standard-tiles__in { color: var(--on-navy); }
.is-lead .aq-standard-tiles__no { color: var(--on-navy-muted); }
.is-lead .aq-standard-tiles__ic { background-color: var(--limestone); }
.is-lead .aq-standard-tiles__tag { color: var(--limestone); }
.is-lead .aq-standard-tiles__body { border-top-color: color-mix(in srgb, var(--on-navy-muted) 40%, transparent); }
.is-lead .aq-standard-tiles__d { color: var(--on-navy-muted); }
.is-lead .aq-standard-tiles__arrow { color: var(--limestone); }

/* Hover and focus: the tile tints, the tag turns flow, the icon rises, the arrow runs out */
a.aq-standard-tiles__in:hover, a.aq-standard-tiles__in:focus-visible { background: var(--flow-tint); }
a.aq-standard-tiles__in:hover .aq-standard-tiles__tag, a.aq-standard-tiles__in:focus-visible .aq-standard-tiles__tag { color: var(--flow); }
.is-lead a.aq-standard-tiles__in:hover, .is-lead a.aq-standard-tiles__in:focus-visible { background: color-mix(in srgb, var(--navy) 85%, var(--on-navy)); }
.is-lead a.aq-standard-tiles__in:hover .aq-standard-tiles__tag { color: var(--on-navy); }
a.aq-standard-tiles__in:hover .aq-standard-tiles__ic { transform: translateY(calc(var(--space-1) * -1)); }
a.aq-standard-tiles__in:hover .aq-standard-tiles__arrow::before, a.aq-standard-tiles__in:focus-visible .aq-standard-tiles__arrow::before { transform: scaleX(1); }
a.aq-standard-tiles__in:hover .aq-standard-tiles__arrow::after, a.aq-standard-tiles__in:focus-visible .aq-standard-tiles__arrow::after { left: calc(100% - var(--space-2) - 1px); }
a.aq-standard-tiles__in:focus-visible { outline: 2px solid var(--focus); outline-offset: -2px; }

@container (max-width: 1100px) {
  .aq-standard-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .aq-standard-tiles__tag { min-height: var(--space-24); }
}

/* Phones: one column, compact tiles, the tag still the largest thing in each */
@container (max-width: 860px) {
  .aq-standard-tiles { grid-template-columns: minmax(0, 1fr); margin-top: var(--space-4); }
  .aq-standard-tiles__in { row-gap: var(--space-4); padding: var(--space-4) var(--space-4) var(--space-6); }
  .aq-standard-tiles__ic { width: var(--space-12); height: var(--space-12); }
  .aq-standard-tiles__tag { font-size: 32px; line-height: 36px; min-height: 0; }
  .aq-standard-tiles__t { font-size: 18px; line-height: 24px; }
}

/* ---------- StandardWires: standards wired to the equipment that answers them (look "standard-wires") ----------
   Navy blueprint band. Desktop: one grid of five tracks shared by the header and every row (standard | asks | answer
   chip | wire run | drawing cell). The drawing cells stack into one plate (a framed column with a title block); the
   run is a hairline from the chip to the plate edge, where the svg's own wire picks it up at mid height and steps to the
   part. Phones: each row stacks (standard, asks, then the chip beside its drawing); the run and header go. */
.aq-standard-wires-sec .aq-sec-head .aq-h1 { color: var(--on-navy); }
.aq-standard-wires { color: var(--on-navy); position: relative; }
.aq-standard-wires__heads, .aq-standard-wires__row { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1.2fr) minmax(0, 0.9fr) minmax(var(--space-6), 0.35fr) minmax(0, 1.15fr); column-gap: var(--space-6); }
.aq-standard-wires__heads { padding-bottom: var(--space-3); border-bottom: 1px solid color-mix(in srgb, var(--on-navy-muted) 40%, transparent); }
.aq-standard-wires__heads p { margin: 0; font: 400 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-standard-wires__heads p span { opacity: 0.7; }
.aq-standard-wires__heads p:last-child { padding-left: var(--space-4); }
.aq-standard-wires__list { list-style: none; margin: 0; padding: 0; }
.aq-standard-wires__row { align-items: center; border-bottom: 1px solid color-mix(in srgb, var(--on-navy-muted) 25%, transparent); position: relative; }
.aq-standard-wires__std { position: relative; padding: var(--space-6) 0 var(--space-6) var(--space-12); }
.aq-standard-wires__n {
  position: absolute; left: 0; top: var(--space-6); min-width: var(--space-8); padding: 0 var(--space-1);
  border: 1px solid color-mix(in srgb, var(--on-navy-muted) 50%, transparent);
  font: 400 11px/20px var(--font-mono); text-align: center; color: var(--on-navy-muted);
}
.aq-standard-wires__k { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }
.aq-standard-wires__s { margin: 0; font: 400 26px/34px var(--font-mono); letter-spacing: -0.02em; color: var(--on-navy); }
.aq-standard-wires__s > span:not(.aq-standard-wires__semi) { display: inline; }
.aq-standard-wires__semi { color: var(--on-navy-muted); }
.aq-standard-wires__a { margin: 0; font: 400 15px/22px var(--font-sans); color: var(--on-navy-muted); }
.aq-standard-wires__chip { margin: 0; }
.aq-standard-wires__chip a, .aq-standard-wires__chip > span {
  display: inline-flex; align-items: center; min-height: 44px; padding: var(--space-2) var(--space-3);
  border: 1px solid color-mix(in srgb, var(--on-navy-muted) 55%, transparent);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy); text-decoration: none;
  transition: background-color 200ms ease, border-color 200ms ease, color 200ms ease;
}
.aq-standard-wires__chip a:focus-visible { outline: 2px solid var(--limestone); outline-offset: 2px; }
.aq-standard-wires__run { align-self: center; height: 0; border-top: 1px solid var(--on-navy-muted); transform-origin: left center; margin-left: calc(-1 * var(--space-6)); margin-right: calc(-1 * var(--space-6)); position: relative; }
.aq-standard-wires__run::before { content: ""; position: absolute; left: 0; top: -3.5px; width: 6px; height: 6px; border-radius: 50%; background: var(--on-navy-muted); }
/* the drawing plate: one framed column, a cell per row */
.aq-standard-wires__cell {
  align-self: stretch; display: flex; min-height: calc(var(--space-32) + var(--space-8));
  border-left: 1px solid color-mix(in srgb, var(--on-navy-muted) 45%, transparent); border-right: 1px solid color-mix(in srgb, var(--on-navy-muted) 45%, transparent);
}
.aq-standard-wires__svg { width: 100%; height: 100%; flex: 1; overflow: visible; }
.aq-standard-wires__wire { fill: none; stroke: var(--on-navy-muted); stroke-width: 1; vector-effect: non-scaling-stroke; transition: stroke 200ms ease; }
.aq-standard-wires__end { fill: var(--on-navy-muted); transition: fill 200ms ease; }
.aq-standard-wires__foot { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1.2fr) minmax(0, 0.9fr) minmax(var(--space-6), 0.35fr) minmax(0, 1.15fr); column-gap: var(--space-6); }
.aq-standard-wires__title {
  grid-column: 5; display: grid; grid-template-columns: auto 1fr auto; margin: 0;
  border: 1px solid color-mix(in srgb, var(--on-navy-muted) 45%, transparent); border-top: 0;
  font: 400 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted);
}
.aq-standard-wires__title span { padding: var(--space-2) var(--space-3); }
.aq-standard-wires__title span + span { border-left: 1px solid color-mix(in srgb, var(--on-navy-muted) 45%, transparent); }
/* hover or focus: the chip fills, its wire and part turn flow */
.aq-standard-wires__row.is-hot .aq-standard-wires__chip a { background: color-mix(in srgb, var(--flow) 35%, var(--navy)); border-color: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-standard-wires__row.is-hot .aq-standard-wires__run { border-top-color: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-standard-wires__row.is-hot .aq-standard-wires__wire { stroke: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-standard-wires__row.is-hot .aq-standard-wires__end { fill: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-standard-wires .aq-fold__btn { color: var(--on-navy-muted); }
.aq-standard-wires .aq-fold__btn:hover { color: var(--on-navy); }

@container (max-width: 860px) {
  .aq-standard-wires__heads, .aq-standard-wires__run, .aq-standard-wires__foot, .aq-standard-wires__wire, .aq-standard-wires__end { display: none; }
  .aq-standard-wires__row { grid-template-columns: minmax(0, 1fr) minmax(0, 0.8fr); column-gap: var(--space-4); padding-bottom: var(--space-4); }
  .aq-standard-wires__std, .aq-standard-wires__ask { grid-column: 1 / -1; }
  .aq-standard-wires__std { padding: var(--space-6) 0 var(--space-3) var(--space-12); }
  .aq-standard-wires__ask { padding-bottom: var(--space-2); }
  .aq-standard-wires__s { font-size: 20px; line-height: 28px; }
  .aq-standard-wires__ans { align-self: center; }
  .aq-standard-wires__cell { border: 0; min-height: var(--space-24); }
}

/* ---------- StandardsGrid: numbered standards in a three-column grid, each opening on a line hairline ---------- */
/* Desktop: three items to a row, no cards, frames or connectors: each item is the shared mono index and the code on a
   hairline, the plain-language name under it. Phones: compact hairline rows, two to a row for code-only standards. */
.aq-standards-grid {
  counter-reset: aq-standards;
  list-style: none; margin: 0; padding: 0;
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-8) var(--space-6);
}
.aq-standards-grid__item { counter-increment: aq-standards; position: relative; min-width: 0; display: flex; }

/* Item: a link to Compliance when that page exists, otherwise a plain block */
.aq-standards-grid__card {
  flex: 1; display: flex; flex-wrap: wrap; align-items: baseline; align-content: flex-start;
  column-gap: var(--space-3); row-gap: var(--space-2);
  padding: var(--space-4) 0 0;
  border-top: 1px solid var(--line);
  color: var(--ink); text-decoration: none;
}
.aq-standards-grid__card::before {
  content: counter(aq-standards, decimal-leading-zero);
  content: counter(aq-standards, decimal-leading-zero) / "";
  font: 400 13px/16px var(--font-mono); letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums; color: var(--ink-subtle);
}
a.aq-standards-grid__card:hover { border-top-color: var(--flow); }
a.aq-standards-grid__card:hover::before { color: var(--flow); }
a.aq-standards-grid__card:hover .aq-standards-grid__name { text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1px; }
a.aq-standards-grid__card:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }

/* Code line: the standard's published short name, in mono beside the number */
.aq-standards-grid__code {
  min-width: 0; overflow-wrap: anywhere;
  font: 400 13px/16px var(--font-mono); color: var(--ink);
}
/* Plain-language name, below the code line */
.aq-standards-grid__name {
  flex-basis: 100%; min-width: 0; overflow-wrap: break-word; text-wrap: balance;
  font: 400 22px/28px var(--font-sans); letter-spacing: -0.01em; color: var(--ink);
}
/* Code only (no name supplied): the code itself takes the large line */
.aq-standards-grid__item--code .aq-standards-grid__code {
  flex-basis: 100%; overflow-wrap: break-word; text-wrap: balance;
  font: 400 22px/28px var(--font-sans); letter-spacing: -0.01em;
}

/* Motion hooks: connectors draw through custom properties (motion.js); unset they are 1, fully drawn */
.aq-standards-grid__item::after { transform: scaleX(var(--aq-cn, 1)); transform-origin: left center; }
.aq-standards-grid__item::before { transform: scaleY(var(--aq-cn, 1)); transform-origin: center top; }
@media (prefers-reduced-motion: no-preference) {
  a.aq-standards-grid__card { transition: border-color 120ms, box-shadow 120ms, transform 120ms; }
  a.aq-standards-grid__card:active { transform: translateY(1px); }
}

@container (max-width: 860px) {
  /* Phones: compact hairline rows, two to a row for code-only standards (one when a plain-language name is given) */
  .aq-standards-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: var(--space-4); row-gap: 0; }
  .aq-standards-grid:has(.aq-standards-grid__name) { grid-template-columns: minmax(0, 1fr); }
  .aq-standards-grid__card { flex-wrap: nowrap; padding: var(--space-3) 0; min-height: 44px; }
  .aq-standards-grid:has(.aq-standards-grid__name) .aq-standards-grid__card { flex-wrap: wrap; }
  .aq-standards-grid__name,
  .aq-standards-grid__item--code .aq-standards-grid__code { font-size: 16px; line-height: 22px; }
  .aq-standards-grid__name { padding-left: calc(2ch + var(--space-3)); }
}

/* ---------- StandardsMap: a plant map of the water system, each zone labelled with the standards that govern it ----------
   Desktop: zones as hairline-framed areas in two rows, a 1 px flow line (the water main) between them, a flow branch
   from each zone to it. Phones: zones stacked as compact rows on a vertical flow line at the left, codes as pill tags. */
.aq-standards-map { min-width: 0; }
.aq-standards-map__zones {
  position: relative; list-style: none; margin: 0; padding: 0;
  display: grid; grid-template-columns: repeat(var(--cols, 3), minmax(0, 1fr)); grid-template-rows: auto var(--space-16) auto;
  column-gap: var(--space-8);
}
/* the main: one flow line across the middle row, an arrow at its end */
.aq-standards-map__zones::before {
  content: ""; grid-row: 2; grid-column: 1 / -1; align-self: center; height: 0;
  border-top: 1px solid var(--flow);
}
.aq-standards-map__zones::after {
  content: ""; grid-row: 2; grid-column: -2 / -1; justify-self: end; align-self: center; margin-right: -1px;
  width: 0; height: 0; border-left: var(--space-2) solid var(--flow); border-block: 4px solid transparent;
}
.aq-standards-map__zone {
  position: relative; display: flex; flex-direction: column; gap: var(--space-4); min-width: 0;
  padding: var(--space-6); border: 1px solid var(--line);
}
/* branch from each zone to the main, with a small node where it joins */
.aq-standards-map__zone::after {
  content: ""; position: absolute; left: var(--space-12); height: calc(var(--space-8) - 1px); border-left: 1px solid var(--flow);
}
.aq-standards-map__zone.is-up::after { top: 100%; }
.aq-standards-map__zone.is-down::after { bottom: 100%; }
.aq-standards-map__zone::before {
  content: ""; position: absolute; left: calc(var(--space-12) - 2px); width: 5px; height: 5px;
  border-radius: var(--radius-pill); background: var(--flow);
}
.aq-standards-map__zone.is-up::before { top: calc(100% + var(--space-8) - 3px); }
.aq-standards-map__zone.is-down::before { bottom: calc(100% + var(--space-8) - 3px); }
.aq-standards-map__label { display: flex; flex-direction: column; gap: var(--space-4); min-width: 0; }
.aq-standards-map__head { display: flex; align-items: center; gap: var(--space-3); min-width: 0; }
.aq-standards-map__head .aq-index { flex: none; }
.aq-standards-map__icon { flex: none; background-color: var(--ink-muted); }
.aq-standards-map__t { margin: 0; font: 500 18px/26px var(--font-sans); color: var(--ink); text-wrap: balance; }
.aq-standards-map__t a { color: inherit; text-decoration: none; }
.aq-standards-map__t a:hover { color: var(--flow); text-decoration: underline; }
.aq-standards-map__codes { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: var(--space-2); }
/* Codes are standard tags: pills in a line frame, mono */
.aq-standards-map__code {
  display: inline-block; padding: 1px var(--space-3); border: 1px solid var(--line-strong); border-radius: var(--radius-pill);
  font: 400 13px/22px var(--font-mono); color: var(--ink); text-decoration: none; white-space: nowrap;
  max-width: 100%; box-sizing: border-box;
}
/* A code longer than its zone (a [placeholder] standard) wraps inside the pill instead of running past the frame */
.aq-standards-map__codes li { max-width: 100%; }
@supports (overflow-wrap: anywhere) { .aq-standards-map__code { white-space: normal; overflow-wrap: anywhere; } }
.aq-standards-map__code::after { content: "\a0\2193"; color: var(--ink-subtle); }
.aq-standards-map__code:hover { border-color: var(--flow); color: var(--flow); }
.aq-standards-map__code:hover::after { color: var(--flow); }
.aq-standards-map__code:focus-visible, .aq-standards-map__t a:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
/* the row a code jumped to flashes once */
.aq-standards-map-hit { outline: 2px solid var(--flow); outline-offset: var(--space-1); animation: aq-standards-map-hit 2.4s ease-out forwards; }
.aq-standards-map-hit:focus { outline: 2px solid var(--flow); }
@keyframes aq-standards-map-hit { 0%, 60% { outline-color: var(--flow); } 100% { outline-color: transparent; } }
@media (prefers-reduced-motion: reduce) { .aq-standards-map-hit { animation: none; } }

/* ---------- With spots (every zone has a Spot): the same map on a plate. Each zone shows its equipment vignette
   beside the name and codes; no grid, corner marks or dashed leaders. ---------- */
.aq-standards-map__plate { min-width: 0; }
.aq-standards-map--spots .aq-standards-map__zone {
  display: grid; grid-template-columns: var(--space-16) minmax(0, 1fr); column-gap: var(--space-6); align-items: start;
  padding: var(--space-6) var(--space-6) var(--space-6) var(--space-4); background: var(--surface-raised);
}
.aq-standards-map--spots .aq-standards-map__zone::after { left: calc(var(--space-4) + var(--space-8)); }
.aq-standards-map--spots .aq-standards-map__zone::before { left: calc(var(--space-4) + var(--space-8) - 2px); }
/* The figure column fits the icon (56 px in a 64 px column), so the codes keep the rest of the zone */
.aq-standards-map__fig { position: relative; display: grid; place-items: center; width: var(--space-16); height: var(--space-16); }
.aq-standards-map__spot { background-color: var(--ink-muted); }
.aq-standards-map--spots .aq-standards-map__zone:hover .aq-standards-map__spot { background-color: var(--flow); }
.aq-standards-map--spots .aq-standards-map__label { gap: var(--space-3); padding-top: var(--space-1); }
@media (prefers-reduced-motion: no-preference) { .aq-standards-map__spot { transition: background-color 120ms; } }

/* Motion hooks: the pipe, branches, nodes and leaders are pseudo-elements, so motion.js draws them through custom
   properties on their element (transform and opacity only). Unset (no JS, reduced motion) they are 1: fully drawn. */
.aq-standards-map__zones::before { transform: scaleX(var(--aq-pipe, 1)); transform-origin: left center; }
.aq-standards-map__zones::after { opacity: var(--aq-arrow, 1); }
.aq-standards-map__zone::after { transform: scaleY(var(--aq-branch, 1)); }
.aq-standards-map__zone.is-up::after { transform-origin: center bottom; }
.aq-standards-map__zone.is-down::after { transform-origin: center top; }
.aq-standards-map__zone::before { transform: scale(var(--aq-node, 1)); }
.aq-standards-map--spots .aq-standards-map__head::before { transform: scaleX(var(--aq-lead, 1)); transform-origin: left center; }
.aq-standards-map--spots .aq-standards-map__head::after { transform: scale(var(--aq-lead, 1)); }
/* Press feedback on the chips the visitor drives */
@media (prefers-reduced-motion: no-preference) {
  .aq-standards-map__code { transition: border-color 120ms, color 120ms, transform 120ms; }
  .aq-standards-map__code:active { transform: translateY(1px); }
}

@container (max-width: 860px) {
  .aq-standards-map__zones { display: flex; flex-direction: column; gap: var(--space-3); padding-left: var(--space-6); }
  .aq-standards-map__zones::before { position: absolute; align-self: auto; left: var(--space-1); top: var(--space-4); bottom: var(--space-4); height: auto; border-top: 0; border-left: 1px solid var(--flow); }
  .aq-standards-map__zones::after { display: none; }
  .aq-standards-map__zone { gap: var(--space-2); padding: var(--space-3) var(--space-4); }
  .aq-standards-map__zone.is-up::after, .aq-standards-map__zone.is-down::after {
    top: calc(var(--space-6) - 1px); bottom: auto; left: calc(-1 * var(--space-6) + var(--space-1)); width: calc(var(--space-6) - var(--space-1)); height: 0;
    border-left: 0; border-top: 1px solid var(--flow);
  }
  .aq-standards-map__zone.is-up::before, .aq-standards-map__zone.is-down::before { top: calc(var(--space-6) - 3px); bottom: auto; left: calc(-1 * var(--space-6) + 2px); }
  .aq-standards-map__t { font-size: 16px; line-height: 24px; }
  .aq-standards-map__code { position: relative; padding-block: var(--space-1); font-size: 12px; line-height: 20px; }
  /* 44 px hit area on each tag and zone link */
  .aq-standards-map__code::before { content: ""; position: absolute; inset: calc(-1 * var(--space-2)) 0; }
  .aq-standards-map__t a { padding-block: calc(var(--space-3) + var(--space-1) / 2); }
  .aq-standards-map__codes { row-gap: var(--space-3); }
  /* with spots: the vignette floats at the zone's right, the name and codes run beside and under it */
  .aq-standards-map--spots .aq-standards-map__zone { display: block; padding: var(--space-3) var(--space-3) var(--space-3) var(--space-4); }
  .aq-standards-map--spots .aq-standards-map__zone::after { left: calc(-1 * var(--space-6) + var(--space-1)); }
  .aq-standards-map--spots .aq-standards-map__zone::before { left: calc(-1 * var(--space-6) + 2px); }
  .aq-standards-map__fig { float: right; width: var(--space-24); height: var(--space-24); margin: 0 0 var(--space-1) var(--space-2); }
  .aq-standards-map--spots .aq-standards-map__label { display: block; padding: 0; }
  .aq-standards-map--spots .aq-standards-map__head { margin-bottom: var(--space-2); }
  .aq-standards-map--spots .aq-standards-map__codes { display: block; }
  .aq-standards-map--spots .aq-standards-map__codes li { display: inline-block; margin: 0 var(--space-1) var(--space-3) 0; }
  /* motion hooks on phones: the main runs top to bottom, branches reach right to each zone */
  .aq-standards-map__zones::before { transform: scaleY(var(--aq-pipe, 1)); transform-origin: center top; }
  .aq-standards-map__zone.is-up::after, .aq-standards-map__zone.is-down::after { transform: scaleX(var(--aq-branch, 1)); transform-origin: left center; }
}

/* ---------- StandardsOrbit: standards as nodes on orbit rings round the plant, arcs touching the part they govern
   (look "standards-orbit"). A navy blueprint band. The stage keeps the orbit svg's aspect (--sw / --sh); the plant and
   the zone labels are placed over it in percentages, so nodes, arcs and labels stay together at any width. ---------- */
.aq-standards-orbit-sec .aq-sec-head .aq-h1 { color: var(--on-navy); max-width: 26ch; }
.aq-standards-orbit { position: relative; color: var(--on-navy); }
.aq-standards-orbit__stage { position: relative; aspect-ratio: var(--sw, 1200) / var(--sh, 720); }
.aq-standards-orbit__orbits { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.aq-standards-orbit__ring { fill: none; stroke: color-mix(in srgb, var(--on-navy-muted) 42%, transparent); stroke-width: 1; vector-effect: non-scaling-stroke; }
.aq-standards-orbit__ring--in { stroke: color-mix(in srgb, var(--on-navy-muted) 24%, transparent); stroke-dasharray: 2 6; }
.aq-standards-orbit__ring--far { stroke: color-mix(in srgb, var(--on-navy-muted) 14%, transparent); }
.aq-standards-orbit__tick { stroke: color-mix(in srgb, var(--on-navy-muted) 45%, transparent); stroke-width: 1; vector-effect: non-scaling-stroke; }
.aq-standards-orbit__arc { fill: none; stroke: color-mix(in srgb, var(--on-navy-muted) 55%, transparent); stroke-width: 1.5; vector-effect: non-scaling-stroke; stroke-linecap: round; }
.aq-standards-orbit__end { fill: var(--navy); stroke: color-mix(in srgb, var(--on-navy-muted) 70%, transparent); stroke-width: 1.5; vector-effect: non-scaling-stroke; }
.aq-standards-orbit__halo { fill: none; stroke: color-mix(in srgb, var(--on-navy-muted) 35%, transparent); stroke-width: 1; vector-effect: non-scaling-stroke; }
.aq-standards-orbit__dot { fill: var(--on-navy); }
/* lit: the zone under the pointer or focus */
.aq-standards-orbit__arc.is-on { stroke: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); stroke-width: 2; }
.aq-standards-orbit__end.is-on { stroke: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); fill: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-standards-orbit__node.is-on .aq-standards-orbit__halo { stroke: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); }
.aq-standards-orbit.is-focus .aq-standards-orbit__arc:not(.is-on) { stroke: color-mix(in srgb, var(--on-navy-muted) 22%, transparent); }
@media (prefers-reduced-motion: no-preference) {
  .aq-standards-orbit__arc, .aq-standards-orbit__end, .aq-standards-orbit__halo, .aq-standards-orbit__zone { transition: stroke 160ms, fill 160ms, opacity 160ms; }
}

.aq-standards-orbit__plant { position: absolute; }
.aq-standards-orbit__svg { display: block; width: 100%; height: auto; }

/* Zone labels beside their nodes */
.aq-standards-orbit__zones { list-style: none; margin: 0; padding: 0; }
.aq-standards-orbit__zone { position: absolute; top: var(--y, 50%); width: 21%; max-width: calc(var(--space-32) * 2.4); transform: translateY(-50%); display: flex; flex-direction: column; gap: var(--space-2); }
.aq-standards-orbit__zone.is-l { right: calc(100% - var(--x, 50%) + var(--space-6)); width: min(21%, calc(var(--x, 50%) - var(--space-6))); align-items: flex-end; text-align: right; }
.aq-standards-orbit__zone.is-r { left: calc(var(--x, 50%) + var(--space-6)); width: min(21%, calc(100% - var(--x, 50%) - var(--space-6))); }
.aq-standards-orbit__zone.is-b { left: calc(var(--x, 50%) + var(--space-6)); transform: translateY(-20%); width: 30%; max-width: none; }
.aq-standards-orbit__head { display: flex; align-items: baseline; gap: var(--space-2); }
.aq-standards-orbit__zone.is-l .aq-standards-orbit__head { flex-direction: row-reverse; }
.aq-standards-orbit .aq-index { color: var(--on-navy-muted); }
.aq-standards-orbit__t { margin: 0; font: 400 22px/28px var(--font-sans); letter-spacing: -0.01em; color: var(--on-navy); }
.aq-standards-orbit__t a { color: inherit; text-decoration: none; }
.aq-standards-orbit__t a:hover { text-decoration: underline; text-underline-offset: 4px; }
.aq-standards-orbit__codes { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: var(--space-3) var(--space-2); }
.aq-standards-orbit__zone.is-l .aq-standards-orbit__codes { justify-content: flex-end; }
.aq-standards-orbit__code {
  position: relative; display: inline-flex; align-items: center; gap: var(--space-1); min-height: var(--space-8); padding: 0 var(--space-3);
  border: 1px solid color-mix(in srgb, var(--on-navy-muted) 45%, transparent); color: var(--on-navy); text-decoration: none;
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.04em; white-space: nowrap;
}
.aq-standards-orbit__code::after { content: "\2193"; color: var(--on-navy-muted); }
/* 44 px target: the hit area reaches into the row gap */
.aq-standards-orbit__code::before { content: ""; position: absolute; inset: calc(-1 * var(--space-1) - 2px) 0; }
.aq-standards-orbit__code:hover { border-color: var(--on-navy); background: color-mix(in srgb, var(--on-navy) 8%, transparent); }
.aq-standards-orbit__code:focus-visible, .aq-standards-orbit__t a:focus-visible { outline: 2px solid var(--on-navy); outline-offset: 2px; }

/* motion slides parts in from the side; never let them widen the page */
.aq-section.aq-standards-orbit-sec { overflow-x: clip; }

@container (max-width: 1180px) {
  /* Below about 1180 px the labels no longer fit beside the rings: the plant stands alone, the zones in a grid under it */
  .aq-standards-orbit__stage { aspect-ratio: auto; }
  .aq-standards-orbit__orbits { display: none; }
  .aq-standards-orbit__plant { position: relative; left: auto !important; top: auto !important; width: auto !important; max-width: calc(var(--space-32) * 4); margin: 0 auto var(--space-8); }
  .aq-standards-orbit__zones { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-8) var(--space-6); }
  .aq-standards-orbit__zone, .aq-standards-orbit__zone.is-l, .aq-standards-orbit__zone.is-r, .aq-standards-orbit__zone.is-b {
    position: relative; left: auto; right: auto; top: auto; width: auto; max-width: none; transform: none; align-items: flex-start; text-align: left;
    padding-top: var(--space-4); border-top: 1px solid color-mix(in srgb, var(--on-navy-muted) 40%, transparent);
  }
  .aq-standards-orbit__zone.is-l .aq-standards-orbit__head { flex-direction: row; }
  .aq-standards-orbit__zone.is-l .aq-standards-orbit__codes { justify-content: flex-start; }
  .aq-standards-orbit__t { font-size: 20px; line-height: 26px; }
}
@container (max-width: 860px) {
  /* Phones: the plant on top, the zones strung down a vertical orbit line */
  .aq-standards-orbit__plant { margin: 0 calc(-1 * var(--space-2)) var(--space-6); max-width: none; }
  .aq-standards-orbit__zones { position: relative; display: flex; flex-direction: column; gap: var(--space-8); padding-left: var(--space-8); }
  .aq-standards-orbit__zones::before { content: ""; position: absolute; left: var(--space-2); top: var(--space-2); bottom: var(--space-2); width: 1px; background: color-mix(in srgb, var(--on-navy-muted) 45%, transparent); }
  .aq-standards-orbit__zone, .aq-standards-orbit__zone.is-l, .aq-standards-orbit__zone.is-r, .aq-standards-orbit__zone.is-b { padding-top: 0; border-top: 0; }
  .aq-standards-orbit__zone::before { content: ""; position: absolute; left: calc(-1 * var(--space-8) + var(--space-1)); top: var(--space-2); width: var(--space-2); height: var(--space-2); border-radius: var(--radius-pill); background: var(--on-navy); box-shadow: 0 0 0 4px var(--navy), 0 0 0 5px color-mix(in srgb, var(--on-navy-muted) 40%, transparent); }
}

/* the signal (AQbeam) that runs a zone's arc while the visitor points at the zone: on navy, the water's lightened flow */
.aq-standards-orbit { --beam: var(--on-navy); --beam-tail: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); --beam-w: 3; }

/* ---------- StrataRun: one water run stepping down a terrace of paper slabs (look "strata-run") ----------
   Desktop: the stage labels in a row of equal columns over the drawing; each label's left hairline is the top of its
   leader, which the svg carries on down to the part (the svg is as wide as the row, one column per stage). Slabs are
   stacked sheets: raised tops, sunken sides, a hairline at every sheet edge. Behind them, a cut-paper stream in
   flow-tint with its own thickness edge. Phones: labels stack down a vertical pipe, each with its own slab drawing. */
.aq-strata-run-sec { overflow: hidden; }
.aq-strata-run { position: relative; display: grid; gap: 0; }
.aq-strata-run__stack { pointer-events: none; }
.aq-strata-run__stages {
  list-style: none; margin: 0; padding: 0; position: relative; z-index: 1;
  display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr);
}
.aq-strata-run__stage {
  position: relative; display: grid; align-content: start; gap: var(--space-1);
  padding: 0 var(--space-4) var(--space-4) var(--space-3);
  border-left: 1px solid var(--line-strong);
  transition: border-color 200ms ease;
}
.aq-strata-run__stage .aq-index { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; color: var(--flow); }
.aq-strata-run__t { margin: 0; font: 500 17px/24px var(--font-sans); letter-spacing: -0.005em; color: var(--ink); }
.aq-strata-run__t a { color: inherit; text-decoration: none; padding-block: 10px; }
.aq-strata-run__t a::after { content: "→"; display: inline-block; margin-left: var(--space-2); color: var(--flow); transition: transform 200ms ease; }
.aq-strata-run__t a:hover::after, .aq-strata-run__t a:focus-visible::after { transform: translateX(3px); }
.aq-strata-run__t a:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-strata-run__d { margin: 0; font: 400 14px/21px var(--font-sans); color: var(--ink-muted); max-width: 24ch; }
.aq-strata-run__thumb { display: none; }
.aq-strata-run__stage.is-hot, .aq-strata-run__stage:hover { border-left-color: var(--flow); }

.aq-strata-run__fig { position: relative; margin-top: calc(-1 * var(--space-1)); }
.aq-strata-run__svg { display: block; width: 100%; height: auto; }
/* the slabs: stacked sheets */
.aq-strata-run__slab { fill: var(--surface-sunken); stroke: var(--line-strong); stroke-width: 1; stroke-linejoin: round; }
.aq-strata-run__slab.is-top { fill: var(--surface-raised); }
/* the stream behind, with its paper edge */
.aq-strata-run__stream { fill: var(--flow-tint); }
.aq-strata-run__edge { fill: var(--line); }
/* leaders and the monitoring bus */
.aq-strata-run__lead { fill: none; stroke: var(--line-strong); stroke-width: 1; transition: stroke 200ms ease; }
.aq-strata-run__dot { fill: var(--line-strong); transition: fill 200ms ease; }
.aq-strata-run__lead.is-hot { stroke: var(--flow); }
.aq-strata-run__dot.is-hot { fill: var(--flow); }
.aq-strata-run__bus { fill: none; stroke: var(--line-strong); stroke-width: 1; stroke-dasharray: 4 3; }
.aq-strata-run__node { fill: var(--surface); stroke: var(--line-strong); stroke-width: 1; }
.aq-strata-run__bus-g.is-hot .aq-strata-run__bus, .aq-strata-run__bus-g.is-hot .aq-strata-run__node { stroke: var(--flow); }
.aq-strata-run__svg .aq-iso__part.is-hot .aq-iso__eq, .aq-strata-run__svg .aq-iso__part.is-hot .aq-iso__ln, .aq-strata-run__svg .aq-iso__part.is-hot .aq-iso__thin { stroke: var(--flow); }
.aq-strata-run__return .aq-iso__pipe-wall { stroke-dasharray: none; }

.aq-strata-run__base {
  display: flex; align-items: center; gap: var(--space-3); margin: var(--space-2) 0 0;
  font: 400 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted);
}
.aq-strata-run__base a { color: inherit; display: inline-flex; align-items: center; min-height: 44px; text-decoration: none; border-bottom: 1px solid transparent; }
.aq-strata-run__base a::after { content: "→"; margin-left: var(--space-2); color: var(--flow); }
.aq-strata-run__base a:hover { color: var(--ink); }
.aq-strata-run__base a:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-strata-run__bus-key { width: var(--space-12); height: 0; border-top: 1px dashed var(--line-strong); flex: none; }

@container (max-width: 860px) {
  .aq-strata-run__fig { display: none; }
  .aq-strata-run__stages { grid-auto-flow: row; grid-template-columns: minmax(0, 1fr); }
  /* the vertical pipe: twin walls with the water line down the middle, one stage per joint */
  .aq-strata-run__stage {
    grid-template-columns: minmax(0, 1fr) 112px; grid-template-rows: auto auto 1fr; column-gap: var(--space-3); row-gap: var(--space-1); align-items: start;
    border-left: 0; padding: 0 0 var(--space-6) var(--space-8);
  }
  .aq-strata-run__stage::before {
    content: ""; position: absolute; left: calc(var(--space-2) + 1px); top: 0; bottom: 0; box-sizing: border-box; width: 11px; padding: 0 3.25px;
    border-left: 1.5px solid var(--line-strong); border-right: 1.5px solid var(--line-strong);
    background: var(--flow); background-clip: content-box;
  }
  .aq-strata-run__stage::after {
    content: ""; position: absolute; left: calc(var(--space-2) - 3px); top: var(--space-1); width: 13px; height: 13px;
    border: 1.5px solid var(--line-strong); background: var(--surface); border-radius: 50%;
  }
  .aq-strata-run__stage:last-child::before { bottom: auto; height: var(--space-2); }
  .aq-strata-run__stage > * { grid-column: 1; }
  .aq-strata-run__thumb { display: block; grid-column: 2; grid-row: 1 / span 3; }
  .aq-strata-run__mini { width: 100%; height: auto; }
  .aq-strata-run__d { max-width: none; }
  .aq-strata-run__base { padding-left: var(--space-8); }
}

/* the moving water (AQbeam) while the visitor points at a stage: flow on the light sheet */
.aq-strata-run { --beam: var(--flow); --beam-tail: var(--flow); --beam-w: 4.5; }

/* ---------- StrikeGaps: before struck, after set (look "strike-gaps") ----------
   Rows on hairlines in a 12-column split: index, the gap (5 columns, light 26 px in ink-muted, struck through with
   an ink rule), the requirement (3 columns, mono 13 px over an arrow in flow), the fix (4 columns, light
   26 px in ink). Column names in mono over the rows; inside rows they are visually hidden labels for screen readers. */
.aq-strike-gaps { position: relative; }
.aq-strike-gaps__heads, .aq-strike-gaps__row { display: grid; grid-template-columns: var(--space-8) minmax(0, 5fr) minmax(0, 3fr) minmax(0, 4fr); column-gap: var(--space-6); }
.aq-strike-gaps__heads { padding-bottom: var(--space-2); border-bottom: 1px solid var(--line-strong); }
.aq-strike-gaps__heads span { font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-strike-gaps__heads span:first-child { grid-column: 2; }
.aq-strike-gaps__rows { list-style: none; margin: 0; padding: 0; }
.aq-strike-gaps__row { align-items: start; padding: var(--space-8) 0; border-bottom: 1px solid var(--line); }
.aq-strike-gaps__row > .aq-index { line-height: 32px; }
.aq-strike-gaps__k { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.aq-strike-gaps__was, .aq-strike-gaps__now { margin: 0; font: 300 28px/34px var(--font-sans); letter-spacing: -0.02em; text-wrap: balance; }
.aq-strike-gaps__was { color: var(--ink-muted); }
.aq-strike-gaps__wt { text-decoration: line-through; text-decoration-thickness: 1.5px; text-decoration-color: var(--ink); }
.aq-strike-gaps__now { color: var(--ink); }
.aq-strike-gaps__req { position: relative; margin: 0; padding-top: var(--space-1); }
.aq-strike-gaps__rt { display: block; font: 400 13px/18px var(--font-mono); color: var(--ink); }
.aq-strike-gaps__arrow { position: relative; display: block; height: var(--space-4); margin-top: var(--space-2); }
.aq-strike-gaps__shaft { position: absolute; left: 0; right: var(--space-1); top: 50%; border-top: 1.5px solid var(--flow); transform-origin: 0 50%; }
.aq-strike-gaps__tip { position: absolute; right: 1px; top: 50%; width: var(--space-2); height: var(--space-2); border-top: 1.5px solid var(--flow); border-right: 1.5px solid var(--flow); transform: translateY(-50%) rotate(45deg); }
.aq-strike-gaps__row:hover .aq-strike-gaps__was { color: var(--ink-subtle); }
.aq-strike-gaps__row:hover .aq-strike-gaps__now { color: var(--flow); }

@container (max-width: 860px) {
  .aq-strike-gaps__heads { display: none; }
  .aq-strike-gaps__row { grid-template-columns: var(--space-8) minmax(0, 1fr); row-gap: var(--space-3); padding: var(--space-6) 0; }
  .aq-strike-gaps__was, .aq-strike-gaps__req, .aq-strike-gaps__now { grid-column: 2; }
  .aq-strike-gaps__was, .aq-strike-gaps__now { font-size: 22px; line-height: 28px; }
  .aq-strike-gaps__req { display: flex; align-items: center; gap: var(--space-3); }
  .aq-strike-gaps__arrow { order: -1; flex: none; width: var(--space-4); height: var(--space-8); margin: 0; }
  .aq-strike-gaps__shaft { left: 50%; right: auto; top: 0; bottom: var(--space-1); border-top: 0; border-left: 1.5px solid var(--flow); transform-origin: 50% 0; }
  .aq-strike-gaps__tip { right: auto; left: 50%; top: auto; bottom: 1px; transform: translateX(-50%) rotate(135deg); }
}
/* the head (pass 9b concept svc-upgrades.2): the intro, which names the discontinued controllers, set as a mono side
   note beside the headline's last line, on a flow hairline, like a note on a drawing */
.aq-strike-gaps-sec .aq-sec-head { display: grid; grid-template-columns: auto minmax(0, 30ch); align-items: end; justify-content: start; column-gap: var(--space-12); max-width: none; }
.aq-strike-gaps-sec .aq-sec-head .aq-h1 { font: 300 56px/60px var(--font-sans); letter-spacing: -0.03em; max-width: 13ch; }
.aq-strike-gaps-sec .aq-sec-head .aq-lead { margin: 0 0 var(--space-2); padding-left: var(--space-4); border-left: 1.5px solid var(--flow); max-width: none; font: 400 13px/20px var(--font-mono); color: var(--ink-muted); }
@container (max-width: 860px) {
  .aq-strike-gaps-sec .aq-sec-head { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-4); }
  .aq-strike-gaps-sec .aq-sec-head .aq-h1 { font: 300 36px/42px var(--font-sans); }
  .aq-strike-gaps-sec .aq-sec-head .aq-lead { margin: 0; }
}

/* ---------- SuiteLoop: a router as a plan of one shared loop feeding a row of suites ---------- */
.aq-suite-loop-sec { position: relative; }
.aq-suite-loop { --wall: color-mix(in srgb, var(--on-limestone) 55%, transparent); --pipe: color-mix(in srgb, var(--on-limestone) 70%, transparent);
  --run: var(--space-8); --bore: var(--space-3); position: relative; margin-top: var(--space-8); padding: var(--space-24) var(--space-8) var(--space-12); color: var(--on-limestone); }

/* The loop: twin walls round the sheet, the water on its centre line, one flow chevron on the supply run */
.aq-suite-loop__loop { position: absolute; left: 0; right: 0; top: var(--run, 32px); bottom: 0; border: 1.5px solid var(--pipe, currentColor); pointer-events: none; }
.aq-suite-loop__loop::before { content: ""; position: absolute; inset: calc(var(--bore, 12px) - 1.5px); border: 1.5px solid var(--pipe, currentColor); }
.aq-suite-loop__water { position: absolute; inset: calc(var(--bore, 12px) / 2 - 1.5px); border: 1.5px solid var(--flow); }
.aq-suite-loop__arrow { position: absolute; top: calc(var(--bore, 12px) / 2 - var(--space-2) / 2 - 1px); left: var(--space-16); width: var(--space-2); height: var(--space-2);
  border-top: 1.5px solid var(--flow); border-right: 1.5px solid var(--flow); transform: rotate(45deg); }

.aq-suite-loop__suites { position: relative; list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(var(--n, 5), minmax(0, 1fr)); gap: var(--space-4); }

/* A suite: walls in plan, a door swing in the lower wall, its drop and valve off the loop */
.aq-suite-loop__suite { position: relative; display: flex; flex-direction: column; gap: var(--space-4); min-width: 0; padding: var(--space-6) var(--space-4) 0;
  border: 1.5px solid var(--wall, currentColor); background: color-mix(in srgb, var(--on-navy) 40%, transparent); transition: background-color 300ms cubic-bezier(0.2, 0, 0, 1); }
.aq-suite-loop__drop { position: absolute; left: 50%; bottom: 100%; width: var(--bore, 12px); margin-left: calc(var(--bore, 12px) / -2); height: calc(var(--space-24) - var(--run, 32px) - var(--bore, 12px) / 2 + 1.5px);
  border-inline: 1.5px solid var(--pipe, currentColor); transform-origin: 50% 0; }
.aq-suite-loop__dw { position: absolute; left: 50%; top: 0; bottom: 0; width: 1.5px; margin-left: -0.75px; background: var(--flow); transform-origin: 50% 0; transform: scaleY(0.001);
  transition: transform 500ms cubic-bezier(0.2, 0, 0, 1); }
.aq-suite-loop__valve { position: absolute; left: 50%; top: 50%; width: var(--space-6); height: var(--space-8); margin: calc(var(--space-8) / -2) 0 0 calc(var(--space-6) / -2); }
.aq-suite-loop__valve svg { width: 100%; height: 100%; overflow: visible; }
.aq-suite-loop__vb { fill: var(--limestone); stroke: var(--on-limestone); stroke-width: 1.5; stroke-linejoin: round; transition: fill 300ms; }
.aq-suite-loop__vs { stroke: var(--on-limestone); stroke-width: 1.5; stroke-linecap: round; }
.aq-suite-loop__door { position: absolute; left: var(--space-4); bottom: -1.5px; width: var(--space-12); height: var(--space-12); border-right: 1.5px solid var(--wall, currentColor);
  border-top: 1px dashed var(--wall, currentColor); border-top-right-radius: 100%; pointer-events: none; }
.aq-suite-loop__door::after { content: ""; position: absolute; left: 0; right: -1.5px; bottom: 0; height: 2px; background: var(--limestone); }

.aq-suite-loop__tag { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; color: var(--on-limestone-muted); }
.aq-suite-loop__t { margin: 0; font: 300 22px/28px var(--font-sans); letter-spacing: -0.015em; }
.aq-suite-loop__dl { display: flex; flex-direction: column; gap: var(--space-3); margin: 0; }
.aq-suite-loop__f { display: flex; flex-direction: column; gap: var(--space-1); padding-top: var(--space-3); border-top: 1px solid color-mix(in srgb, var(--on-limestone) 18%, transparent); }
.aq-suite-loop__f dt, .aq-suite-loop__k { font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-limestone-muted); }
.aq-suite-loop__f dd { margin: 0; font: 400 15px/22px var(--font-sans); color: var(--on-limestone); }
.aq-suite-loop__f a { color: var(--on-limestone); text-decoration: underline; text-decoration-color: var(--flow); text-underline-offset: 3px; display: inline-flex; min-height: 44px; align-items: center; }
.aq-suite-loop__f a:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }

/* The way out: the start page, in the lower wall beside the door */
.aq-suite-loop__go { position: relative; display: flex; flex-direction: column; gap: var(--space-1); margin: auto calc(var(--space-4) * -1) 0; padding: var(--space-4) var(--space-4) var(--space-6) calc(var(--space-16) + var(--space-2));
  min-height: calc(var(--space-16) + var(--space-4)); color: var(--on-limestone); text-decoration: none; border-top: 1px solid color-mix(in srgb, var(--on-limestone) 18%, transparent);
  transition: background-color 300ms cubic-bezier(0.2, 0, 0, 1), color 300ms; }
.aq-suite-loop__to { font: 400 16px/22px var(--font-sans); }
a.aq-suite-loop__go .aq-suite-loop__to::after { content: " →"; color: var(--flow); }
a.aq-suite-loop__go:hover, a.aq-suite-loop__go:focus-visible { background: var(--navy); color: var(--on-navy); }
a.aq-suite-loop__go:hover .aq-suite-loop__k, a.aq-suite-loop__go:focus-visible .aq-suite-loop__k { color: var(--on-navy-muted); }
a.aq-suite-loop__go:hover .aq-suite-loop__to::after, a.aq-suite-loop__go:focus-visible .aq-suite-loop__to::after { color: var(--limestone); }
a.aq-suite-loop__go:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }

/* Hover or focus a suite: water runs down its drop, the valve fills, the room brightens */
.aq-suite-loop__suite:hover, .aq-suite-loop__suite:focus-within { background: color-mix(in srgb, var(--on-navy) 75%, transparent); }
.aq-suite-loop__suite:hover .aq-suite-loop__dw, .aq-suite-loop__suite:focus-within .aq-suite-loop__dw { transform: scaleY(1); }
.aq-suite-loop__suite:hover .aq-suite-loop__vb, .aq-suite-loop__suite:focus-within .aq-suite-loop__vb { fill: var(--flow); }

/* Wide: every suite spans the same shared rows (number, situation, each field, way out) as a subgrid, so the rules
   inside the rooms line up across the plan */
@container (min-width: 1101px) {
  .aq-suite-loop__suite { display: grid; grid-row: span var(--rows, 5); grid-template-rows: subgrid; align-content: start; }
  .aq-suite-loop__dl { display: contents; }
  .aq-suite-loop__go { margin-top: 0; }
}

@container (max-width: 1100px) {
  .aq-suite-loop { padding-inline: var(--space-6); }
  .aq-suite-loop__suites { grid-template-columns: repeat(3, minmax(0, 1fr)); row-gap: var(--space-24); }
  .aq-suite-loop__suites > :nth-child(n+4) .aq-suite-loop__drop { display: none; }
}

/* Phones: the loop runs down the left as one riser; each suite branches off it to the right */
@container (max-width: 860px) {
  .aq-suite-loop { padding: var(--space-6) 0 var(--space-6) var(--space-16); margin-top: var(--space-4); }
  .aq-suite-loop__loop { top: 0; bottom: 0; left: var(--space-2); right: auto; width: calc(var(--bore, 12px) + 3px); border-block: 0; }
  .aq-suite-loop__loop::before { display: none; }
  .aq-suite-loop__water { inset: 0; left: 50%; width: 1.5px; margin-left: -0.75px; border: 0; background: var(--flow); }
  .aq-suite-loop__arrow { left: 50%; top: var(--space-12); margin-left: calc(var(--space-2) / -2 - 0.5px); transform: rotate(135deg); }
  .aq-suite-loop__suites, .aq-suite-loop__suites:nth-child(n) { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-6); }
  .aq-suite-loop__suites > :nth-child(n+4) .aq-suite-loop__drop { display: block; }
  .aq-suite-loop__suite { padding: var(--space-4) var(--space-4) 0; gap: var(--space-3); }
  .aq-suite-loop__drop { left: auto; right: 100%; bottom: auto; top: var(--space-8); margin: 0; width: calc(var(--space-16) - var(--space-2) - var(--bore, 12px) / 2); height: var(--bore, 12px);
    border-inline: 0; border-block: 1.5px solid var(--pipe, currentColor); transform-origin: 0 50%; }
  .aq-suite-loop__dw { left: 0; right: 0; top: 50%; bottom: auto; width: auto; height: 1.5px; margin: -0.75px 0 0; transform: scaleX(1); transform-origin: 0 50%; }
  .aq-suite-loop__valve { transform: rotate(90deg); }
  .aq-suite-loop__t { font-size: 20px; line-height: 26px; }
}

/* ---------- SystemRun: the package as one continuous water line, a navy blueprint of the four systems ---------- */
/* The drawing spans the content width (IsoKit, aq-iso--navy) with a bracket over each system; one column per system
   under it. Water on navy is flow lightened towards on-navy (the IsoKit navy rule), kept in --sr-flow. */
.aq-system-run { --sr-flow: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); --sr-rule: color-mix(in srgb, var(--on-navy-muted) 35%, transparent);
  position: relative; display: flex; flex-direction: column; gap: var(--space-8); }
.aq-system-run__fig { position: relative; margin-inline: calc(-1 * var(--space-4)); }
.aq-system-run__svg { width: 100%; }

/* Brackets over each system: index and name on a hairline with end ticks */
.aq-system-run__brackets { position: absolute; inset: 0; pointer-events: none; }
.aq-system-run__bracket { position: absolute; top: 7%; display: flex; gap: var(--space-2); align-items: baseline; justify-content: center;
  padding-top: var(--space-3); border-top: 1px solid var(--sr-rule, var(--line));
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); white-space: nowrap;
  transition: color 300ms, border-color 300ms; }
.aq-system-run__bracket::before, .aq-system-run__bracket::after { content: ""; position: absolute; top: calc(-1 * var(--space-2)); width: 1px; height: var(--space-4); background: var(--sr-rule, var(--line)); }
.aq-system-run__bracket::before { left: 0; }
.aq-system-run__bracket::after { right: 0; }
.aq-system-run__bn { color: var(--on-navy); }
.aq-system-run__bracket.is-on { color: var(--on-navy); border-top-color: var(--sr-flow, var(--flow)); }
.aq-system-run__bracket.is-on .aq-system-run__bn { color: var(--sr-flow, var(--flow)); }

/* Ends of the run: where drinking water enters, where Purified Water leaves */
.aq-system-run__end { position: absolute; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); white-space: nowrap; }
.aq-system-run__end--in { transform: translate(0, calc(-100% - var(--space-3))); }
.aq-system-run__end--out { right: var(--space-4); bottom: 8%; color: var(--sr-flow, var(--flow)); }
.aq-system-run__end--in::after, .aq-system-run__end--out::after { content: "\00a0\2192"; }

/* Columns: one per system, a hairline on top that fills with water when the system lights */
.aq-system-run__stages { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); column-gap: var(--space-6); }
.aq-system-run__item { min-width: 0; display: flex; }
.aq-system-run__stage { position: relative; display: flex; flex-direction: column; gap: var(--space-3); width: 100%; min-height: 44px;
  padding-top: var(--space-6); border-top: 1px solid var(--sr-rule, var(--line)); color: var(--on-navy); text-decoration: none; }
.aq-system-run__mark { position: absolute; left: 0; right: 0; top: -1px; height: 2px; background: var(--sr-flow, var(--flow)); transform: scaleX(0); transform-origin: 0 50%; transition: transform 500ms cubic-bezier(0.2, 0, 0, 1); }
.aq-system-run__stage.is-on .aq-system-run__mark, .aq-system-run__stage:hover .aq-system-run__mark, .aq-system-run__stage:focus-visible .aq-system-run__mark { transform: scaleX(1); }
.aq-system-run__stage:focus-visible { outline: 2px solid var(--on-navy); outline-offset: var(--space-2); }
.aq-system-run__mini-wrap { display: none; }
.aq-system-run__code { margin: 0; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; color: var(--on-navy-muted); }
.aq-system-run__t { margin: 0; font: 400 24px/30px var(--font-sans); letter-spacing: -0.015em; color: var(--on-navy); }
.aq-system-run__d { margin: 0; font: 400 15px/24px var(--font-sans); color: var(--on-navy-muted); }
.aq-system-run__foot { margin: auto 0 0; padding-top: var(--space-2); display: flex; flex-wrap: wrap; gap: var(--space-3); align-items: center; }
.aq-system-run .aq-tag { color: var(--on-navy); border-color: var(--on-navy-muted); }
.aq-system-run__go { font: 500 14px/20px var(--font-sans); color: var(--sr-flow, var(--flow)); }
.aq-system-run__go::after { content: "\00a0\2192"; display: inline-block; transition: transform 200ms; }
.aq-system-run__stage:hover .aq-system-run__go::after { transform: translateX(var(--space-1)); }
.aq-system-run__stage:hover .aq-system-run__t { text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 0.18em; text-decoration-color: var(--sr-flow, var(--flow)); }

@container (max-width: 1100px) {
  .aq-system-run__bracket { font-size: 11px; letter-spacing: 0.04em; }
  .aq-system-run__t { font-size: 20px; line-height: 26px; }
  .aq-system-run__d { font-size: 14px; line-height: 22px; }
}

/* Phones: one drawing per system, stacked down a vertical water line at the left */
@container (max-width: 860px) {
  .aq-system-run { gap: 0; }
  .aq-system-run__fig { display: none; }
  .aq-system-run__stages { grid-template-columns: minmax(0, 1fr); row-gap: 0; border-left: 2px solid var(--sr-rule, var(--line)); margin-left: var(--space-2); }
  .aq-system-run__stage { border-top: 0; padding: var(--space-6) 0 var(--space-8) var(--space-6); }
  .aq-system-run__mark { left: -2px; right: auto; top: 0; bottom: 0; width: 2px; height: auto; transform: scaleY(0); transform-origin: 50% 0; }
  .aq-system-run__stage.is-on .aq-system-run__mark, .aq-system-run__stage:hover .aq-system-run__mark { transform: scaleY(1); }
  .aq-system-run__stage::before { content: ""; position: absolute; left: calc(-1 * var(--space-2) - 1px); top: var(--space-8); width: var(--space-3); height: var(--space-3); border-radius: var(--radius-pill); background: var(--navy); border: 2px solid var(--sr-flow, var(--flow)); }
  .aq-system-run__mini-wrap { display: block; margin-bottom: var(--space-2); }
  .aq-system-run__mini { width: 100%; max-height: 180px; }
  .aq-system-run__t { font-size: 22px; line-height: 28px; }
}

/* the drawing may run a step past the content width: the band clips it */
.aq-system-run-sec { overflow-x: clip; }

/* Animated beam (AQbeam, ported from Subframe Motion "Animated beam"; shared by SystemRun, BatteryLimit, PidRoutes):
   the moving highlight that traces a water line while the visitor points at it. A hard bright head, a fading tail. */
.aq-beam, .aq-iso .aq-beam { stroke-width: var(--beam-w, 4); stroke-linecap: round; fill: none; pointer-events: none; vector-effect: none; }
.aq-beam__stop { stop-color: var(--beam, var(--flow)); }
.aq-beam__stop--0, .aq-beam__stop--3 { stop-opacity: 0; }
.aq-beam__stop--2, .aq-beam__stop--3 { stop-color: var(--beam-tail, var(--beam, var(--flow))); }
.aq-system-run { --beam: var(--on-navy); --beam-tail: var(--sr-flow, var(--flow)); }
/* the column of the system the visitor is pointing at in the drawing */
.aq-system-run__stage.is-hot .aq-system-run__mark { transform: scaleX(1); }
.aq-system-run__stage.is-hot .aq-system-run__t { text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 0.18em; text-decoration-color: var(--sr-flow, var(--flow)); }
.aq-system-run__fig { cursor: crosshair; }

/* ---------- TankTiles: fabrication parameters on a navy and limestone checkerboard of square tiles ---------- */
/* Four columns of square tiles, no gutters (the checkerboard is the grid). The head sits in the first navy tile, the
   steel-blue blueprint of the tank in the third; each row is a tile led by a huge light slash numeral. */
.aq-tank-tiles { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-auto-rows: auto; }
.aq-tank-tiles__list { display: contents; list-style: none; margin: 0; padding: 0; }
.aq-tank-tiles__head, .aq-tank-tiles__tile, .aq-tank-tiles__bp { aspect-ratio: 1 / 1; min-width: 0; box-sizing: border-box; padding: var(--space-6); }
.aq-tank-tiles__head { grid-column: 1; grid-row: 1; background: var(--navy); display: flex; flex-direction: column; justify-content: flex-end; }
.aq-tank-tiles__head .aq-sec-head { margin: 0; }
.aq-tank-tiles__head .aq-eyebrow { color: var(--on-navy-muted); }
.aq-tank-tiles__head .aq-h1 { font: 300 44px/48px var(--font-sans); letter-spacing: -0.025em; color: var(--on-navy); max-width: none; }
.aq-tank-tiles__head .aq-lead, .aq-tank-tiles__head p { color: var(--on-navy-muted); }

/* the blueprint tile: steel blue ground, limestone hairlines, a fine drafting grid */
.aq-tank-tiles__bp { grid-column: 3; grid-row: 1; position: relative; padding: var(--space-4); overflow: hidden;
  background-color: color-mix(in srgb, var(--flow) 60%, var(--navy));
  background-image: linear-gradient(color-mix(in srgb, var(--limestone) 14%, transparent) 1px, transparent 1px), linear-gradient(90deg, color-mix(in srgb, var(--limestone) 14%, transparent) 1px, transparent 1px);
  background-size: var(--space-6) var(--space-6); background-position: -1px -1px; }
.aq-tank-tiles__svg { display: block; width: 100%; height: 100%; overflow: visible; }
.aq-tank-tiles__svg path, .aq-tank-tiles__svg circle { fill: none; stroke-linecap: round; stroke-linejoin: round; }
.aq-tank-tiles__ln { stroke: var(--limestone); stroke-width: 1.5; }
.aq-tank-tiles__thin, .aq-tank-tiles__dim { stroke: var(--limestone); stroke-width: 1; opacity: 0.75; }
.aq-tank-tiles__hl { stroke: var(--limestone); stroke-width: 1; opacity: 0.6; }
.aq-tank-tiles__svg .aq-tank-tiles__eq { fill: color-mix(in srgb, var(--flow) 60%, var(--navy)); stroke: var(--limestone); stroke-width: 1.5; }
.aq-tank-tiles__level { stroke: var(--limestone); stroke-width: 1.5; }
.aq-tank-tiles__water { stroke: var(--limestone); stroke-width: 1; opacity: 0.3; }
.aq-tank-tiles__jet { stroke: var(--limestone); stroke-width: 1; stroke-dasharray: 2 4; }
.aq-tank-tiles__tx { fill: var(--limestone); font: 400 11px/1 var(--font-mono); text-anchor: middle; }
.aq-tank-tiles__bpt { position: absolute; left: var(--space-4); bottom: var(--space-3); font: 400 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--limestone); }

/* row tiles */
.aq-tank-tiles__tile { display: flex; flex-direction: column; gap: var(--space-2); }
.aq-tank-tiles__tile.is-navy { background: var(--navy); color: var(--on-navy); }
.aq-tank-tiles__tile.is-stone { background: var(--limestone); color: var(--on-limestone); }
.aq-tank-tiles__n { margin: 0 0 auto; font: 300 72px/1 var(--font-sans); letter-spacing: -0.04em; font-variant-numeric: tabular-nums; }
.aq-tank-tiles__sl { margin-left: 0.04em; }
.is-navy .aq-tank-tiles__sl { color: var(--on-navy-muted); }
.is-stone .aq-tank-tiles__sl { color: var(--on-limestone-muted); }
.aq-tank-tiles__p { margin: var(--space-4) 0 0; font: 400 20px/26px var(--font-sans); letter-spacing: -0.01em; }
.aq-tank-tiles__v { margin: 0; font: 400 14px/22px var(--font-sans); }
.aq-tank-tiles__m { margin: var(--space-1) 0 0; padding-top: var(--space-2); display: flex; flex-direction: column; gap: var(--space-1); font: 400 13px/20px var(--font-sans); }
.is-navy .aq-tank-tiles__m { color: var(--on-navy-muted); border-top: 1px solid color-mix(in srgb, var(--on-navy) 25%, transparent); }
.is-stone .aq-tank-tiles__m { color: var(--on-limestone-muted); border-top: 1px solid color-mix(in srgb, var(--on-limestone) 25%, transparent); }
.aq-tank-tiles__link { color: inherit; text-decoration: underline; text-underline-offset: 3px; min-height: var(--space-6); display: inline-flex; align-items: center; }
.is-navy .aq-tank-tiles__link { color: var(--on-navy); }
.is-stone .aq-tank-tiles__link { color: var(--on-limestone); }
.aq-tank-tiles__tile:hover .aq-tank-tiles__sl { color: var(--flow); }
.is-navy:hover .aq-tank-tiles__sl { color: var(--limestone); }

/* Desktop shows every tile; the fold is for phones */
.aq-fold:not(.is-open) .aq-tank-tiles__tile.aq-fold-x { display: flex; }
.aq-fold:has(> .aq-tank-tiles) > .aq-fold__btn { display: none; }

@container (max-width: 1100px) {
  .aq-tank-tiles__head, .aq-tank-tiles__tile { padding: var(--space-4); }
  .aq-tank-tiles__n { font-size: 56px; }
  .aq-tank-tiles__head .aq-h1 { font-size: 36px; line-height: 42px; }
  .aq-tank-tiles__p { font-size: 18px; line-height: 24px; }
}
/* Phones: one column; head, blueprint band, then the tiles alternating navy and limestone, the fold back on */
@container (max-width: 860px) {
  .aq-tank-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .aq-tank-tiles__head { grid-column: 1 / -1; grid-row: auto; aspect-ratio: auto; padding: var(--space-6) var(--space-4); }
  .aq-tank-tiles__bp { grid-column: 1 / -1; grid-row: auto; aspect-ratio: 2 / 1; }
  .aq-tank-tiles__tile { grid-column: 1 / -1; aspect-ratio: auto; padding: var(--space-6) var(--space-4); }
  .aq-tank-tiles__tile:nth-child(odd) { background: var(--limestone); color: var(--on-limestone); }
  .aq-tank-tiles__tile:nth-child(even) { background: var(--navy); color: var(--on-navy); }
  .aq-tank-tiles__tile:nth-child(odd) .aq-tank-tiles__m { color: var(--on-limestone-muted); border-top-color: color-mix(in srgb, var(--on-limestone) 25%, transparent); }
  .aq-tank-tiles__tile:nth-child(even) .aq-tank-tiles__m { color: var(--on-navy-muted); border-top-color: color-mix(in srgb, var(--on-navy) 25%, transparent); }
  .aq-tank-tiles__tile:nth-child(odd) .aq-tank-tiles__sl { color: var(--on-limestone-muted); }
  .aq-tank-tiles__tile:nth-child(even) .aq-tank-tiles__sl { color: var(--on-navy-muted); }
  .aq-tank-tiles__tile:nth-child(odd) .aq-tank-tiles__link { color: var(--on-limestone); }
  .aq-tank-tiles__tile:nth-child(even) .aq-tank-tiles__link { color: var(--on-navy); }
  .aq-tank-tiles__n { font-size: 48px; }
  .aq-tank-tiles__bpt { display: none; }
  .aq-fold:not(.is-open) .aq-tank-tiles__tile.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-tank-tiles) > .aq-fold__btn { display: flex; }
}
/* Shutter slats (added by motion.js for the entrance, removed when it ends) */
.aq-tank-tiles__head, .aq-tank-tiles__tile, .aq-tank-tiles__bp { position: relative; }
.aq-tank-tiles__blinds { position: absolute; inset: 0; display: flex; pointer-events: none; z-index: 1; }
.aq-tank-tiles__blinds span { flex: 1; background: var(--navy); }
.aq-tank-tiles__blinds.is-on-navy span { background: var(--limestone); }

/* ---------- TermsSheet: commercial terms as a contract's terms sheet (look "terms-sheet"). One paper sheet
   (surface-raised on a limestone offset, data-theme="light") with a ruled mono head; clauses in two columns that read down, each with a
   large light number, the term, our values one per line, the note under a hairline. No flow except the clause rule. ---------- */
.aq-terms-sheet-sec { position: relative; }
.aq-terms-sheet__body { min-width: 0; }
.aq-terms-sheet__go { margin: var(--space-3) 0 0; }
.aq-terms-sheet {
  position: relative; padding: var(--space-8) var(--space-12) var(--space-12); background: var(--surface-raised); color: var(--ink); border: 1px solid var(--line);
  box-shadow: var(--space-3) var(--space-3) 0 var(--limestone);
}
.aq-terms-sheet__head {
  display: flex; justify-content: space-between; gap: var(--space-6); padding-bottom: var(--space-3); margin-bottom: var(--space-2);
  border-bottom: 1.5px solid var(--navy); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted);
}
.aq-terms-sheet__list {
  list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); grid-template-rows: repeat(var(--rows, 4), auto);
  grid-auto-flow: column; column-gap: var(--space-16);
}
.aq-terms-sheet__cl { display: grid; grid-template-columns: var(--space-16) minmax(0, 1fr); column-gap: var(--space-4); padding: var(--space-6) 0; border-bottom: 1px solid var(--line); }
.aq-terms-sheet__n { font: 300 40px/40px var(--font-sans); letter-spacing: -0.04em; font-variant-numeric: tabular-nums; color: var(--ink-muted); }
.aq-terms-sheet__t { margin: 0 0 var(--space-2); font: 500 17px/24px var(--font-sans); color: var(--ink); }
.aq-terms-sheet__v { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--space-1); }
.aq-terms-sheet__v li { position: relative; padding-left: var(--space-4); font: 400 15px/23px var(--font-sans); color: var(--ink); }
.aq-terms-sheet__v li::before { content: ""; position: absolute; left: 0; top: calc(var(--space-3) - 1px); width: var(--space-2); border-top: 1.5px solid var(--flow); }
.aq-terms-sheet__m { margin: var(--space-3) 0 0; padding-top: var(--space-2); border-top: 1px dashed var(--line); font: 400 14px/21px var(--font-sans); color: var(--ink-muted); }
.aq-terms-sheet__mk { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; }
.aq-terms-sheet__cl:hover .aq-terms-sheet__n { color: var(--flow); }

/* Fold: desktop shows every clause; the fold works on phones only */
.aq-fold:not(.is-open) .aq-terms-sheet__cl.aq-fold-x { display: grid; }
.aq-fold:has(> .aq-terms-sheet__list) > .aq-fold__btn { display: none; }

@container (max-width: 860px) {
  .aq-terms-sheet { padding: var(--space-6) var(--space-4) var(--space-6); }
  .aq-terms-sheet__list { grid-template-columns: minmax(0, 1fr); grid-template-rows: none; grid-auto-flow: row; }
  .aq-terms-sheet__cl { grid-template-columns: var(--space-12) minmax(0, 1fr); column-gap: var(--space-3); padding: var(--space-4) 0; }
  .aq-terms-sheet__n { font-size: 30px; line-height: 32px; }
  .aq-fold:not(.is-open) .aq-terms-sheet__cl.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-terms-sheet__list) > .aq-fold__btn { display: flex; color: var(--ink-muted); margin-top: var(--space-4); }
}

/* ---------- TestSheet: the protocol as a signed test sheet on a limestone table (look "test-sheet") ----------
   Section on the limestone band. Desktop: the heading on the table at the left (3 of 12), the sheet beside it. The
   sheet is surface-raised paper with two more sheets' edges showing under it (offset hairlines, no shadow); rows are
   ruled (line), the step number set large in mono, the sign-off cell at the right behind a vertical rule. Hold rows
   carry a signature (flow ink) on a line and the HOLD stamp (a navy-ruled box, set slightly askew like a struck stamp).
   The torn row sits below a perforation (a dashed rule over a strip of the table) as a separate slip. */
.aq-test-sheet { display: grid; grid-template-columns: minmax(0, 3fr) minmax(0, 9fr); gap: var(--space-12); align-items: start; isolation: isolate; }
.aq-test-sheet > .aq-sec-head { position: sticky; top: var(--space-24); }
.aq-test-sheet__paper { position: relative; background: var(--surface-raised); color: var(--ink); border: 1px solid color-mix(in srgb, var(--on-limestone) 18%, transparent); }
.aq-test-sheet__paper::before, .aq-test-sheet__paper::after { content: ""; position: absolute; z-index: -1; border: 1px solid color-mix(in srgb, var(--on-limestone) 22%, transparent); background: var(--surface); }
.aq-test-sheet__paper::before { inset: var(--space-2) calc(-1 * var(--space-2)) calc(-1 * var(--space-2)) var(--space-2); }
.aq-test-sheet__paper::after { inset: var(--space-4) calc(-1 * var(--space-4)) calc(-1 * var(--space-4)) var(--space-4); z-index: -2; }
.aq-test-sheet__strip { display: grid; grid-template-columns: var(--space-24) minmax(0, 1fr) minmax(0, 15rem); padding: var(--space-3) var(--space-6); border-bottom: 1.5px solid var(--ink);
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-test-sheet__rows { list-style: none; margin: 0; padding: 0 var(--space-6); }
.aq-test-sheet__row { display: grid; grid-template-columns: var(--space-24) minmax(0, 1fr) minmax(0, 15rem); align-items: stretch; border-bottom: 1px solid var(--line); position: relative; }
.aq-test-sheet__n { padding: var(--space-6) 0; font: 300 40px/40px var(--font-mono); letter-spacing: -0.04em; color: var(--ink-subtle); }
.aq-test-sheet__row.is-hold .aq-test-sheet__n { color: var(--flow); }
.aq-test-sheet__body { padding: var(--space-6) var(--space-6) var(--space-6) 0; }
.aq-test-sheet__t { margin: 0; font: 500 18px/26px var(--font-sans); color: var(--ink); }
.aq-test-sheet__d { margin: var(--space-1) 0 0; font: 400 15px/24px var(--font-sans); color: var(--ink-muted); max-width: 60ch; }
.aq-test-sheet__sign { position: relative; display: flex; align-items: center; justify-content: center; padding: var(--space-4) var(--space-6); border-left: 1px solid var(--line); }
.aq-test-sheet__box { width: var(--space-8); height: var(--space-8); border: 1.5px solid var(--line-strong); display: inline-flex; }
.aq-test-sheet__box svg { width: 100%; height: 100%; fill: none; stroke: var(--flow); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
.aq-test-sheet__hold { position: relative; width: 100%; display: flex; flex-direction: column; gap: var(--space-1); }
.aq-test-sheet__hk { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
