/* ---------- TraceLines: a traceability table as transit lines (look "trace-lines"). One grid: the documents down the
   first column (station names, drawn), then one column per requirement line (--col). The wrappers are display:
   contents so every head and stop sits on the shared rows, each row a hairline across like an interchange. Each line
   has its colour --lc (flow for the first, ink for the second); its rail runs down the left of its column. ---------- */
.aq-trace-lines {
  display: grid; grid-template-columns: minmax(0, 0.75fr) repeat(var(--k, 2), minmax(0, 1.5fr)); column-gap: var(--space-8);
  grid-template-rows: auto; position: relative;
}
.aq-trace-lines__docs, .aq-trace-lines__line, .aq-trace-lines__stops { display: contents; }
.aq-trace-lines__line { --lc: var(--flow); }
.aq-trace-lines__line[data-line="1"] { --lc: var(--ink); }
.aq-trace-lines__line[data-line="2"] { --lc: var(--line-strong); }
.aq-trace-lines__stops { list-style: none; }

/* station names */
.aq-trace-lines__dh, .aq-trace-lines__doc { grid-column: 1; }
.aq-trace-lines__dh { align-self: end; padding-bottom: var(--space-4); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-trace-lines__doc {
  display: flex; flex-direction: column; gap: var(--space-1); padding: var(--space-6) 0; border-top: 1px solid var(--line-strong);
  font: 400 20px/26px var(--font-sans); letter-spacing: -0.01em; color: var(--ink);
}
.aq-trace-lines__dn { font: 400 13px/16px var(--font-mono); color: var(--ink-subtle); }

/* the line's start: its code large, the requirement under it */
.aq-trace-lines__head { grid-column: var(--col, 2); position: relative; padding: 0 0 var(--space-8) var(--space-12); }
.aq-trace-lines__code { display: block; font: 300 44px/48px var(--font-mono); letter-spacing: -0.03em; color: var(--lc, var(--flow)); white-space: nowrap; }
.aq-trace-lines__req { margin: var(--space-2) 0 0; font: 400 17px/24px var(--font-sans); color: var(--ink); text-wrap: balance; }
.aq-trace-lines__head::before {
  content: ""; position: absolute; left: var(--space-4); top: var(--space-4); width: var(--space-4); height: var(--space-4); transform: translateX(-50%) translateX(1.5px);
  border-radius: 50%; border: 3px solid var(--lc, var(--flow)); background: var(--surface); box-sizing: border-box; z-index: 1;
}
.aq-trace-lines__head::after { content: ""; position: absolute; left: var(--space-4); top: var(--space-8); bottom: 0; border-left: 3px solid var(--lc, var(--flow)); }

/* stops */
.aq-trace-lines__st { grid-column: var(--col, 2); position: relative; padding: var(--space-6) 0 var(--space-6) var(--space-12); border-top: 1px solid var(--line-strong); min-width: 0; }
.aq-trace-lines__st::before { content: ""; position: absolute; left: var(--space-4); top: -1px; bottom: 0; border-left: 3px solid var(--lc, var(--flow)); }
.aq-trace-lines__st::after {
  content: ""; position: absolute; left: var(--space-4); top: calc(var(--space-6) + var(--space-1)); width: var(--space-4); height: var(--space-4);
  transform: translateX(-50%) translateX(1.5px); border-radius: 50%; border: 3px solid var(--lc, var(--flow)); background: var(--surface); box-sizing: border-box;
}
.aq-trace-lines__st.is-end::before { bottom: auto; height: calc(var(--space-6) + var(--space-3)); }
.aq-trace-lines__st.is-end::after { border-radius: 0; background: var(--lc, var(--flow)); width: var(--space-6); height: var(--space-3); top: calc(var(--space-6) + var(--space-2)); }
/* not answered here: the line passes dashed, no stop */
.aq-trace-lines__st.is-na::before { border-left-style: dashed; opacity: 0.6; }
.aq-trace-lines__st.is-na::after { display: none; }
.aq-trace-lines__st.is-na .aq-trace-lines__p { color: var(--ink-subtle); font-family: var(--font-mono); font-size: 13px; letter-spacing: 0.04em; }
.aq-trace-lines__p { margin: 0; font: 400 16px/25px var(--font-sans); color: var(--ink); text-wrap: pretty; max-width: 48ch; }
.aq-trace-lines__met {
  display: inline-block; margin-right: var(--space-1); padding: 0 var(--space-2); border: 1px solid var(--pass); color: var(--pass);
  font: 500 12px/20px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; vertical-align: 1px;
}
/* test steps branch off the line */
.aq-trace-lines__tests { list-style: none; margin: var(--space-3) 0 0; padding: 0; display: flex; flex-direction: column; gap: var(--space-3); }
.aq-trace-lines__tests li { position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--space-3); align-items: baseline; font: 400 16px/25px var(--font-sans); }
.aq-trace-lines__tests li::before { content: ""; position: absolute; right: 100%; top: var(--space-3); width: calc(var(--space-8) - var(--space-1)); border-top: 2px solid var(--lc, var(--flow)); }
.aq-trace-lines__step {
  padding: 0 var(--space-2); border: 2px solid var(--lc, var(--flow)); color: var(--ink); background: var(--surface); font: 500 12px/20px var(--font-mono); letter-spacing: 0.06em; white-space: nowrap;
}
/* station name inside each stop: read by screen readers on desktop (the left column draws them), shown on phones */
.aq-trace-lines__k { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* pointing at one line dims the other */
.aq-trace-lines__head, .aq-trace-lines__st { transition: opacity 300ms cubic-bezier(0.2, 0, 0, 1); }
.aq-trace-lines:has(.aq-trace-lines__line:hover) .aq-trace-lines__line:not(:hover) :is(.aq-trace-lines__head, .aq-trace-lines__st) { opacity: 0.4; }

@container (max-width: 860px) {
  .aq-trace-lines { display: block; }
  .aq-trace-lines__docs { display: none; }
  .aq-trace-lines__line { display: block; }
  .aq-trace-lines__line + .aq-trace-lines__line { margin-top: var(--space-12); }
  .aq-trace-lines__stops { display: block; margin: 0; padding: 0; }
  .aq-trace-lines__head { padding-bottom: var(--space-6); }
  .aq-trace-lines__code { font-size: 34px; line-height: 40px; }
  .aq-trace-lines__st { border-top: 0; padding: var(--space-3) 0 var(--space-6) var(--space-12); }
  .aq-trace-lines__st::after { top: calc(var(--space-3) + var(--space-1)); }
  .aq-trace-lines__st.is-end::after { top: calc(var(--space-3) + var(--space-2)); }
  .aq-trace-lines__st.is-end::before { height: calc(var(--space-3) + var(--space-3)); }
  .aq-trace-lines__k { position: static; width: auto; height: auto; overflow: visible; clip-path: none; white-space: normal; display: block; margin-bottom: var(--space-1); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
}
.aq-section.aq-trace-lines-sec { overflow-x: clip; }

/* pass 9b, concept svc-design.3: the readout tile beside the lines. The tile is data-theme light, so its flow ground
   and on-navy figure keep their contrast in both page themes; pipe ghosts (line hairlines) sit behind it. */
.aq-trace-lines-wrap.has-tile { display: grid; grid-template-columns: minmax(0, 1fr) minmax(280px, 340px); column-gap: var(--space-12); align-items: start; }
.aq-trace-lines__panel { position: relative; display: flex; flex-direction: column; gap: var(--space-3); padding-top: var(--space-16); }
.aq-trace-lines__ghost { position: absolute; inset: 0 calc(-1 * var(--space-8)) calc(-1 * var(--space-16)) calc(-1 * var(--space-8)); width: calc(100% + 2 * var(--space-8)); height: calc(100% + var(--space-16)); fill: none; stroke: var(--line-strong); stroke-width: 1; opacity: 0.45; pointer-events: none; }
.aq-trace-lines__tile { position: relative; background: var(--flow); color: var(--on-navy); padding: var(--space-6) var(--space-6) var(--space-8); min-height: 300px; }
.aq-trace-lines__face { display: flex; flex-direction: column; gap: var(--space-4); }
.aq-trace-lines__face[hidden] { display: none; }
.aq-trace-lines__face.is-tick > :not(.aq-trace-lines__meter) { animation: aq-tl-tick 220ms cubic-bezier(0.2, 0.8, 0.2, 1); }
@keyframes aq-tl-tick { from { opacity: 0.2; transform: translateY(var(--tl-dir, 8px)); } to { opacity: 1; transform: none; } }
.aq-trace-lines__rk { margin: 0; font: 400 12px/16px var(--font-mono); letter-spacing: 0.06em; color: var(--on-navy); }
.aq-trace-lines__fig { margin: var(--space-6) 0 0; display: flex; align-items: baseline; gap: var(--space-3); white-space: nowrap; }
.aq-trace-lines__num { font: 300 112px/0.9 var(--font-sans); letter-spacing: -0.05em; font-variant-numeric: tabular-nums; }
.aq-trace-lines__unit { font: 400 24px/1 var(--font-sans); letter-spacing: -0.01em; }
.aq-trace-lines__scale { display: flex; justify-content: space-between; align-items: end; height: var(--space-4); border-bottom: 1px solid var(--on-navy-muted); }
.aq-trace-lines__scale i { width: 1px; height: 30%; background: var(--on-navy-muted); }
.aq-trace-lines__scale i.is-major { height: 60%; }
.aq-trace-lines__scale i.is-lim { height: 100%; width: 2px; background: var(--on-navy); }
.aq-trace-lines__meter { position: relative; padding-bottom: var(--space-16); }
.aq-trace-lines__tag { position: absolute; top: calc(100% - var(--space-16) + var(--space-2)); left: 75%; margin: 0; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: var(--space-1); white-space: nowrap; }
.aq-trace-lines__tag > span:first-child { padding: 0 var(--space-2); border: 1px solid var(--on-navy); font: 400 13px/22px var(--font-mono); }
.aq-trace-lines__at { font: 400 12px/16px var(--font-mono); color: var(--on-navy); }
.aq-trace-lines__keys { position: relative; display: flex; gap: var(--space-2); }
.aq-trace-lines__key {
  min-height: 44px; padding: 0 var(--space-4); border: 1px solid var(--line-strong); background: var(--surface); color: var(--ink-muted);
  font: 400 13px/1 var(--font-mono); cursor: pointer; transition: background-color 150ms ease, color 150ms ease, border-color 150ms ease;
}
.aq-trace-lines__key:hover { border-color: var(--flow); color: var(--ink); }
.aq-trace-lines__key[aria-pressed="true"] { background: var(--flow-tint); border-color: var(--flow); color: var(--ink); }
.aq-trace-lines__key:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { .aq-trace-lines__face.is-tick > :not(.aq-trace-lines__meter) { animation: none; } }
@container (max-width: 860px) {
  .aq-trace-lines-wrap.has-tile { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-8); }
  .aq-trace-lines__panel { order: -1; padding-top: 0; }
  .aq-trace-lines__ghost { display: none; }
  .aq-trace-lines__tile { min-height: 0; }
  .aq-trace-lines__num { font-size: 88px; }
}

/* ---------- UrsGate: decisions along one project line that runs into a gate set as giant outline type ---------- */
.aq-urs-gate-sec { overflow: hidden; }
.aq-urs-gate { position: relative; display: grid; grid-template-columns: repeat(var(--cols, 11), minmax(0, 1fr)) minmax(0, 4fr);
  grid-template-rows: auto var(--space-16) auto; column-gap: var(--space-4); margin-top: var(--space-12); }
.aq-urs-gate__list { display: contents; list-style: none; }
.aq-fold:not(.is-open) .aq-urs-gate__item.aq-fold-x { display: flex; }
.aq-fold:has(> .aq-urs-gate) > .aq-fold__btn { display: none; }

/* The line: a hairline pair with the water inside, running from the left edge into the gate bar */
.aq-urs-gate__axis { grid-column: 1 / -2; grid-row: 2; align-self: center; position: relative; height: var(--space-2); margin-right: calc(var(--space-4) * -1);
  border-block: 1px solid var(--line-strong); transform-origin: 0 50%; }
.aq-urs-gate__water { position: absolute; left: 0; right: 0; top: 50%; height: 1.5px; margin-top: -0.75px; background: var(--flow); transform-origin: 0 50%; }

/* A decision: numeral, title, detail on a stem that reaches the line */
.aq-urs-gate__item { grid-column: var(--c, 1) / span 3; grid-row: 1; align-self: end; position: relative; display: flex; flex-direction: column; gap: var(--space-2);
  padding: 0 0 var(--space-6) var(--space-4); min-width: 0; }
.aq-urs-gate__item.is-low { grid-row: 3; align-self: start; padding: var(--space-6) 0 0 var(--space-4); }
.aq-urs-gate__stem { position: absolute; left: 0; top: 0; bottom: calc(var(--space-8) * -1); width: 1px; background: var(--line-strong); transform-origin: 50% 100%;
  transition: background-color 300ms cubic-bezier(0.2, 0, 0, 1); }
.aq-urs-gate__item.is-low .aq-urs-gate__stem { top: calc(var(--space-8) * -1); bottom: 0; transform-origin: 50% 0; }
.aq-urs-gate__node { position: absolute; left: 50%; bottom: calc(var(--space-2) * -0.5); width: var(--space-3); height: var(--space-3); margin-left: calc(var(--space-3) * -0.5);
  background: var(--surface); border: 1.5px solid var(--ink); transition: background-color 300ms, border-color 300ms; }
.aq-urs-gate__item.is-low .aq-urs-gate__node { bottom: auto; top: calc(var(--space-2) * -0.5); }
.aq-section--alt .aq-urs-gate__node { background: var(--surface-sunken); }
.aq-urs-gate__n { display: block; overflow: hidden; font: 300 72px/64px var(--font-sans); letter-spacing: -0.05em; color: var(--ink-subtle); font-variant-numeric: tabular-nums; }
.aq-urs-gate__n > span { display: block; transition: color 300ms; }
.aq-urs-gate__t { margin: 0; font: 400 21px/28px var(--font-sans); letter-spacing: -0.01em; color: var(--ink); }
.aq-urs-gate__d { margin: 0; font: 400 15px/23px var(--font-sans); color: var(--ink-muted); max-width: 30ch; }
.aq-urs-gate__link { align-self: flex-start; display: inline-flex; align-items: center; min-height: 44px; color: var(--flow); text-decoration: none; font: 500 14px/20px var(--font-sans); }
.aq-urs-gate__link::after { content: "→"; margin-left: var(--space-1); transition: transform 200ms; }
.aq-urs-gate__link:hover::after { transform: translateX(var(--space-1)); }
.aq-urs-gate__link:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-urs-gate__item:hover .aq-urs-gate__stem, .aq-urs-gate__item:focus-within .aq-urs-gate__stem { background: var(--flow); }
.aq-urs-gate__item:hover .aq-urs-gate__node, .aq-urs-gate__item:focus-within .aq-urs-gate__node { background: var(--flow); border-color: var(--flow); }
.aq-urs-gate__item:hover .aq-urs-gate__n > span, .aq-urs-gate__item:focus-within .aq-urs-gate__n > span { color: var(--flow); }

/* The gate: a bar across the line, its mark, and the word as giant outline type cut by the page edge */
.aq-urs-gate__gate { grid-column: -2 / -1; grid-row: 1 / -1; position: relative; min-width: 0; }
.aq-urs-gate__bar { position: absolute; left: 0; top: var(--space-8); bottom: var(--space-8); width: var(--space-1); background: var(--action); transform-origin: 50% 50%; }
.aq-urs-gate__mark { position: absolute; left: var(--space-4); top: var(--space-8); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--ink-muted); white-space: nowrap; }
.aq-urs-gate__word { position: absolute; left: var(--space-3); top: 50%; transform: translateY(-50%); font: 200 260px/1 var(--font-sans); letter-spacing: -0.06em; white-space: nowrap;
  color: transparent; -webkit-text-stroke: 1.5px var(--line-strong); pointer-events: none; }

@container (max-width: 1100px) {
  .aq-urs-gate { grid-template-columns: repeat(var(--cols, 11), minmax(0, 1fr)) minmax(0, 2fr); column-gap: var(--space-3); }
  .aq-urs-gate__n { font-size: 56px; line-height: 52px; }
  .aq-urs-gate__t { font-size: 18px; line-height: 24px; }
  .aq-urs-gate__d { font-size: 14px; line-height: 21px; }
  .aq-urs-gate__word { font-size: 180px; }
}

/* Phones: the line runs down the left, decisions hang off it to the right, the gate closes it at the bottom */
@container (max-width: 860px) {
  .aq-urs-gate { grid-template-columns: var(--space-8) minmax(0, 1fr); grid-template-rows: none; column-gap: 0; margin-top: var(--space-6); }
  .aq-urs-gate__axis { grid-column: 1; grid-row: 1 / span 6; justify-self: center; align-self: stretch; width: var(--space-2); height: auto; margin: 0;
    border-block: 0; border-inline: 1px solid var(--line-strong); transform-origin: 50% 0; }
  .aq-urs-gate__water { left: 50%; right: auto; top: 0; bottom: 0; width: 1.5px; height: auto; margin: 0 0 0 -0.75px; transform-origin: 50% 0; }
  .aq-urs-gate__item, .aq-urs-gate__item.is-low { grid-column: 2; grid-row: auto; align-self: start; padding: var(--space-4) 0 var(--space-6) var(--space-4); }
  .aq-urs-gate__stem, .aq-urs-gate__item.is-low .aq-urs-gate__stem { top: var(--space-12); bottom: auto; left: calc(var(--space-4) * -1); width: var(--space-6); height: 1px; transform-origin: 0 50%; }
  .aq-urs-gate__node, .aq-urs-gate__item.is-low .aq-urs-gate__node { left: 0; top: calc(var(--space-2) * -0.5 - 0.5px); bottom: auto; margin-left: calc(var(--space-3) * -0.5); }
  .aq-urs-gate__n { font-size: 52px; line-height: 60px; }
  .aq-urs-gate__d { max-width: none; }
  .aq-urs-gate__gate { grid-column: 1 / -1; grid-row: auto; height: calc(var(--space-32) + var(--space-8)); }
  .aq-urs-gate__bar { left: 0; right: 0; top: 0; bottom: auto; width: auto; height: var(--space-1); }
  .aq-urs-gate__mark { left: var(--space-8); top: var(--space-3); }
  .aq-urs-gate__word { left: var(--space-6); top: auto; bottom: calc(var(--space-6) * -1); transform: none; font-size: 160px; }
  .aq-fold:not(.is-open) .aq-urs-gate__item.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-urs-gate) > .aq-fold__btn { display: flex; }
}

/* ---------- Versus: two routes facing each other across a spine of factors (table block as "versus") ----------
   On a plate (surface-raised). Desktop: the two route names at h2 in sentence case, joined by a hairline to an "or"
   on the spine; each factor sits on the spine (mono index, Geist 500 label) with hairline leaders out to route A
   (right-aligned) and route B (left-aligned, flow leader); the verdict closes it as two columns under hairlines.
   Phones: the names on top, the verdict next, then the spine runs down the left edge with each factor's index on it
   and A and B under the factor, each tagged with its route. */
.aq-versus { display: flex; flex-direction: column; }
.aq-versus__head, .aq-versus__row { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 200px) minmax(0, 1fr); column-gap: var(--space-8); }
.aq-versus__head { position: relative; align-items: center; padding-bottom: var(--space-6); }
.aq-versus__name { margin: 0; font: 400 28px/34px var(--font-sans); letter-spacing: -0.01em; color: var(--ink); text-wrap: balance; }
.aq-versus__head .aq-versus__name:first-child { text-align: right; }
.aq-versus__head .aq-versus__name:last-child { color: var(--flow); }
.aq-versus__head::before { content: ""; position: absolute; top: 50%; left: calc(50% - 100px - var(--space-6)); right: calc(50% - 100px - var(--space-6)); border-top: 1px solid var(--line); }
.aq-versus__head::after { content: ""; position: absolute; left: 50%; top: calc(50% + var(--space-4)); bottom: 0; border-left: 1px solid var(--line); }
.aq-versus__vs {
  position: relative; justify-self: center; padding: 0 var(--space-3); background: var(--surface-raised);
  font: 400 16px/24px var(--font-sans); color: var(--ink-muted);
}
.aq-versus__rows { margin: 0; }
.aq-versus__row { position: relative; padding-block: var(--space-6); }
.aq-versus__row::before { content: ""; position: absolute; top: 0; bottom: 0; left: 50%; border-left: 1px solid var(--line); }
.aq-versus__row dt {
  grid-column: 2; grid-row: 1; position: relative; justify-self: center; align-self: start; display: flex; flex-direction: column; align-items: center; gap: var(--space-1);
  max-width: 100%; padding: var(--space-1) var(--space-2); background: var(--surface-raised); text-align: center;
  font: 500 16px/24px var(--font-sans); color: var(--ink);
}
.aq-versus__n { font: 400 13px/24px var(--font-mono); letter-spacing: 0.02em; font-variant-numeric: tabular-nums; color: var(--ink-subtle); }
.aq-versus__row dd { position: relative; grid-row: 1; margin: 0; padding-top: var(--space-6); font: 400 16px/26px var(--font-sans); color: var(--ink); overflow-wrap: break-word; text-wrap: pretty; }
/* leader lines from each answer to the spine, drawn inside the answer's own box: a space-6 padding on its spine side,
   taken back out of the column gap by an equal negative margin, so the text keeps its column and the box measures
   what it draws (a leader hung outside the box made each A answer 24 px wider than its box to an overflow check) */
.aq-versus__row dd::after { content: ""; position: absolute; top: calc(var(--space-6) + 13px); width: var(--space-6); border-top: 1px solid var(--line); }
.aq-versus__row dd:nth-of-type(1) { grid-column: 1; text-align: right; margin-right: calc(-1 * var(--space-6)); padding-right: var(--space-6); }
.aq-versus__row dd:nth-of-type(1)::after { right: 0; }
.aq-versus__row dd:nth-of-type(2) { grid-column: 3; margin-left: calc(-1 * var(--space-6)); padding-left: var(--space-6); }
.aq-versus__row dd:nth-of-type(2)::after { left: 0; border-top-color: var(--flow); }
/* Verdict: two columns, each opening on a hairline (B's in flow) */
.aq-versus__verdict { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-8); margin-top: var(--space-6); }
.aq-versus__verdict > div { display: flex; flex-direction: column; gap: var(--space-2); padding-top: var(--space-4); border-top: 1px solid var(--line-strong); }
.aq-versus__verdict > div:last-child { border-top-color: var(--flow); }
.aq-versus__verdict p:not(.aq-eyebrow) { margin: 0; font: 400 18px/28px var(--font-sans); color: var(--ink); text-wrap: pretty; }

/* Conclusion: a footer band across the plate, the closing line that is not a choice (what carries into IQ/OQ). The same
   three columns as the factors, on a surface-sunken band under a hairline, the label as an eyebrow on the spine. */
.aq-versus__end {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 200px) minmax(0, 1fr); column-gap: var(--space-8); align-items: center;
  margin: var(--space-8) calc(-1 * var(--space-8)) 0; padding: var(--space-6) var(--space-8);
  background: var(--surface-sunken); border-top: 1px solid var(--line);
}
.aq-versus__end-k { grid-column: 2; grid-row: 1; margin: 0; text-align: center; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-versus__end-v { grid-row: 1; margin: 0; font: 400 16px/24px var(--font-sans); color: var(--ink); text-wrap: pretty; }
.aq-versus__end-v:nth-of-type(2) { grid-column: 1; text-align: right; }
.aq-versus__end-v:nth-of-type(3) { grid-column: 3; }
.aq-versus__end.is-one .aq-versus__end-v { grid-column: 1 / -1; grid-row: 2; margin-top: var(--space-3); text-align: center; }
/* ground: "light" (kept for old content): the plate is already a light surface, so nothing changes */
.aq-versus-plate--light { min-width: 0; }

/* Folded factors: the fold button's rule already closes the rows, so the verdict drops its own */
.aq-fold:has(> .aq-versus__rows) + .aq-versus__verdict { padding-top: 0; border-top: 0; }

@container (max-width: 860px) {
  .aq-versus__head { grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); column-gap: var(--space-3); padding-bottom: var(--space-4); }
  .aq-versus__head::before { left: 0; right: 0; top: 50%; }
  .aq-versus__head::after { display: none; }
  .aq-versus__name { position: relative; font-size: 20px; line-height: 26px; background: var(--surface-raised); }
  .aq-versus__vs { padding: 0 var(--space-2); font-size: 14px; line-height: 20px; }
  .aq-versus__row { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-2); padding: var(--space-4) 0 var(--space-4) var(--space-8); }
  .aq-versus__row::before { left: var(--space-3); }
  .aq-versus__row dt { grid-column: 1; justify-self: start; flex-direction: row; align-items: baseline; gap: var(--space-2); padding: 0; background: none; text-align: left; font-size: 16px; line-height: 24px; }
  .aq-versus__n { position: absolute; left: calc(-1 * var(--space-8)); top: 0; width: var(--space-6); background: var(--surface-raised); text-align: center; font-size: 12px; }
  .aq-versus__row dd, .aq-versus__row dd:nth-of-type(1), .aq-versus__row dd:nth-of-type(2) { grid-column: 1; grid-row: auto; margin: 0; padding: 0 0 0 var(--space-3); text-align: left; font-size: 15px; line-height: 23px; border-left: 1px solid var(--line-strong); }
  .aq-versus__row dd:nth-of-type(2) { border-left-color: var(--flow); }
  .aq-versus__row dd::after, .aq-versus__row dd:nth-of-type(1)::after, .aq-versus__row dd:nth-of-type(2)::after { display: none; }
  .aq-versus__row dd::before { content: attr(data-k); display: block; font: 500 12px/18px var(--font-sans); color: var(--ink-muted); }
  .aq-versus__row dd:nth-of-type(2)::before { color: var(--flow); }
  .aq-versus__head { order: -2; }
  .aq-versus__verdict { order: -1; grid-template-columns: minmax(0, 1fr); gap: var(--space-4); margin: 0 0 var(--space-4); }
  .aq-versus__verdict > div { padding-top: var(--space-3); }
  .aq-versus__verdict p:not(.aq-eyebrow) { font-size: 16px; line-height: 24px; }
  .aq-versus__end { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-2); margin: var(--space-6) calc(-1 * var(--space-4)) 0; padding: var(--space-4); }
  .aq-versus__end-k, .aq-versus__end-v, .aq-versus__end-v:nth-of-type(2), .aq-versus__end-v:nth-of-type(3), .aq-versus__end.is-one .aq-versus__end-v { grid-column: 1; grid-row: auto; margin: 0; text-align: left; }
  .aq-versus__end-v { padding-left: var(--space-3); border-left: 1px solid var(--line-strong); font-size: 15px; line-height: 23px; }
  .aq-versus__end-v:nth-of-type(3) { border-left-color: var(--flow); }
  .aq-versus__end-v[data-k]::before { content: attr(data-k); display: block; font: 500 12px/18px var(--font-sans); color: var(--ink-muted); }
  .aq-versus__end-v:nth-of-type(3)::before { color: var(--flow); }
}

/* ---------- VersusSpread: FAT versus SAT as an editorial spread (look "versus-spread") ----------
   Desktop: a navy mast (8 of 12 columns) bleeds off the page's left edge from the section's top, the heading in it at
   display scale, light weight; the comparison table under it on the page ground; the line drawing of the installed
   system sticks beside the table (4 of 12) with its two boundaries (site: fine dots, test bay: long dashes) and a
   caption naming the test on show. Rows are hairline-ruled, numbered in mono; the conclusion row closes on a 1.5 px
   ink rule with the reuse label as a navy tile. Lit parts turn flow with a flow-tint fill; the rest of the drawing
   steps back. The reading lens (script) is a flow-tint band with a flow edge behind the row in focus. */
.aq-versus-spread-sec { overflow-x: clip; }
.aq-versus-spread { display: grid; grid-template-columns: minmax(0, 8fr) minmax(0, 4fr); grid-template-areas: "mast ." "body fig"; column-gap: var(--space-12); align-items: start; }

/* the mast */
.aq-versus-spread__mast { grid-area: mast; position: relative; margin-top: calc(-1 * var(--space-16)); padding: var(--space-8) var(--space-8) var(--space-12) 0; background: var(--navy); color: var(--on-navy); }
.aq-versus-spread__mast::before { content: ""; position: absolute; top: 0; bottom: 0; right: 100%; width: 100vmax; background: var(--navy); }
.aq-versus-spread__top { display: flex; justify-content: space-between; gap: var(--space-4); padding-bottom: var(--space-3); margin-bottom: var(--space-12);
  border-bottom: 1px solid color-mix(in srgb, var(--on-navy) 28%, transparent); font: 400 14px/20px var(--font-sans); color: var(--on-navy-muted); }
.aq-versus-spread__mast .aq-sec-head { margin: 0; }
.aq-versus-spread__mast .aq-h1 { max-width: none; margin: 0; font-size: clamp(52px, 6.6cqi, 92px); line-height: 0.98; font-weight: 300; letter-spacing: -0.035em; color: var(--on-navy); }
.aq-versus-spread__mast .aq-eyebrow, .aq-versus-spread__mast .aq-lead { color: var(--on-navy-muted); }

/* the table */
.aq-versus-spread__body { grid-area: body; padding-top: var(--space-12); }
.aq-versus-spread__hrow, .aq-versus-spread__row, .aq-versus-spread__end { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, 1fr); column-gap: var(--space-6); }
.aq-versus-spread__hrow { padding-bottom: var(--space-3); border-bottom: 1px solid var(--ink); }
.aq-versus-spread__h { font: 400 14px/20px var(--font-sans); color: var(--ink-muted); }
.aq-versus-spread__h:first-child { padding-left: var(--space-8); }
.aq-versus-spread__rows { position: relative; isolation: isolate; }
.aq-versus-spread__row { position: relative; padding: var(--space-4) 0; border-bottom: 1px solid var(--line); outline: none; transition: opacity 200ms; }
.aq-versus-spread__row:focus-visible, .aq-versus-spread__end:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.aq-versus-spread__row::before { content: ""; position: absolute; left: calc(-1 * var(--space-4)); top: -1px; bottom: -1px; width: 2px; background: var(--flow); opacity: 0; transition: opacity 150ms; }
.aq-versus-spread:not([data-lens]) .aq-versus-spread__row.is-on::before { opacity: 1; }
.aq-versus-spread__test { display: grid; grid-template-columns: var(--space-8) minmax(0, 1fr); align-items: baseline; }
.aq-versus-spread__n { font: 400 13px/24px var(--font-mono); letter-spacing: 0.02em; color: var(--ink-subtle); transition: color 150ms; }
.aq-versus-spread__row.is-on .aq-versus-spread__n { color: var(--flow); }
.aq-versus-spread__tn { font: 500 16px/24px var(--font-sans); color: var(--ink); }
.aq-versus-spread__c { font: 400 15px/23px var(--font-sans); color: var(--ink-muted); }
.aq-versus-spread__c.is-na { padding-left: var(--space-3); border-left: 1.5px dashed var(--line-strong); color: var(--ink-subtle); }
.aq-versus-spread__k { display: none; }
.aq-versus-spread__lens { position: absolute; z-index: -1; left: calc(-1 * var(--space-4)); right: calc(-1 * var(--space-4)); top: 0; height: 0; background: var(--flow-tint);
  border-left: 2px solid var(--flow); opacity: 0; pointer-events: none; transition: opacity 200ms; }
.aq-versus-spread[data-lens] .aq-versus-spread__lens.is-live { opacity: 1; }
/* the conclusion */
.aq-versus-spread__end { padding: var(--space-6) 0 var(--space-4); border-top: 1.5px solid var(--ink); margin-top: -1px; outline: none; }
.aq-versus-spread__end .aq-versus-spread__test { display: block; }
.aq-versus-spread__reuse { display: inline-block; padding: var(--space-2) var(--space-3); background: var(--navy); color: var(--on-navy); font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; }
.aq-versus-spread__end .aq-versus-spread__c { color: var(--ink); }
.aq-versus-spread__end.is-on .aq-versus-spread__reuse { box-shadow: 0 0 0 2px var(--surface), 0 0 0 3.5px var(--flow); }

/* the drawing */
.aq-versus-spread__fig { grid-area: fig; position: sticky; top: var(--space-24); margin: 0; padding-top: var(--space-12); }
.aq-versus-spread__art { position: relative; }
.aq-versus-spread__svg { display: block; width: 100%; height: auto; aspect-ratio: 400 / 600; overflow: visible; }
.aq-versus-spread__eq { fill: var(--surface); stroke: var(--line-strong); stroke-width: 1.5; stroke-linejoin: round; transition: fill 200ms, stroke 200ms; }
.aq-versus-spread__thin { fill: none; stroke: var(--line-strong); stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; transition: stroke 200ms; }
.aq-versus-spread__wall { fill: none; stroke: var(--line-strong); stroke-width: 7; stroke-linejoin: round; transition: stroke 200ms; }
.aq-versus-spread__bore { fill: none; stroke: var(--surface); stroke-width: 4; stroke-linejoin: round; }
.aq-versus-spread__water { fill: none; stroke: var(--flow); stroke-width: 2; stroke-linejoin: round; }
.aq-versus-spread__bound { fill: none; stroke: var(--line-strong); stroke-width: 1; transition: stroke 200ms, fill 200ms; }
.aq-versus-spread__bound--sat { stroke-dasharray: 1 4; stroke-linecap: round; stroke-width: 1.5; }
.aq-versus-spread__bound--fat { stroke-dasharray: 8 5; stroke: var(--ink-subtle); }
.aq-versus-spread__part { transition: opacity 200ms; }
.aq-versus-spread.has-on .aq-versus-spread__part:not(.is-on) { opacity: 0.32; }
.aq-versus-spread__part.is-on .aq-versus-spread__eq { stroke: var(--flow); fill: var(--flow-tint); }
.aq-versus-spread__part.is-on .aq-versus-spread__thin, .aq-versus-spread__part.is-on .aq-versus-spread__wall { stroke: var(--flow); }
.aq-versus-spread__bound--fat.is-on { stroke: var(--flow); stroke-width: 2; fill: var(--flow-tint); fill-opacity: 0.6; }
.aq-versus-spread__tag { position: absolute; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); white-space: nowrap; }
.aq-versus-spread__tag--sat { left: 2%; top: 0; }
.aq-versus-spread__tag--fat { left: 8.5%; top: 51.2%; }
.aq-versus-spread__now { display: flex; align-items: baseline; gap: var(--space-3); min-height: var(--space-12); margin-top: var(--space-4); padding-top: var(--space-3); border-top: 1px solid var(--line); }
.aq-versus-spread__count { flex: none; font: 400 13px/20px var(--font-mono); letter-spacing: 0.02em; color: var(--ink-subtle); }
.aq-versus-spread__now-t { font: 500 15px/20px var(--font-sans); color: var(--flow); }

/* the fold is for phones only: desktop shows every test */
.aq-fold:not(.is-open) .aq-versus-spread__row.aq-fold-x { display: grid; }
.aq-fold:has(> .aq-versus-spread__table) > .aq-fold__btn { display: none; }

@container (max-width: 860px) {
  .aq-versus-spread { grid-template-columns: minmax(0, 1fr); grid-template-areas: "mast" "fig" "body"; }
  .aq-versus-spread__mast { margin-top: calc(-1 * var(--space-12)); padding: var(--space-6) 0 var(--space-8); }
  .aq-versus-spread__mast::after { content: ""; position: absolute; top: 0; bottom: 0; left: 100%; width: 100vmax; background: var(--navy); }
  .aq-versus-spread__top { margin-bottom: var(--space-8); font-size: 13px; }
  .aq-versus-spread__mast .aq-h1 { font-size: 44px; line-height: 46px; }
  .aq-versus-spread__fig { position: static; padding-top: var(--space-8); }
  .aq-versus-spread__art { width: 100%; }
  .aq-versus-spread__tag { letter-spacing: 0.02em; }
  .aq-versus-spread__tag--fat { top: 50.6%; }
  .aq-versus-spread__now { display: none; }
  .aq-versus-spread__body { padding-top: var(--space-6); }
  .aq-versus-spread__hrow { display: none; }
  .aq-versus-spread__row, .aq-versus-spread__end { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-3); }
  .aq-versus-spread__row:first-child { border-top: 1px solid var(--ink); }
  .aq-versus-spread__row::before { display: none; }
  .aq-versus-spread__c { padding-left: var(--space-8); font-size: 14px; line-height: 22px; }
  .aq-versus-spread__c.is-na { margin-left: var(--space-8); padding-left: var(--space-3); }
  .aq-versus-spread__k { display: block; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
  .aq-versus-spread__end .aq-versus-spread__c { padding-left: 0; }
  .aq-fold:not(.is-open) .aq-versus-spread__row.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-versus-spread__table) > .aq-fold__btn { display: flex; }
}

/* ---------- VisitPlan: a service visit walked around the plant (look "visit-plan") ----------
   One navy band (the ink tokens take their on-navy values inside). The drawing (IsoKit, aq-iso--navy) carries the
   plant, the dashed walk on the floor and the numbered stops (pin, ring, number in mono; the sign-off stop a tick).
   Along the base of the band the captions: one column per stop on on-navy hairlines, numbered like the stops. The
   sign-off item closes the band as one limestone line across the full width. A lit caption (hover or focus) turns its
   stop and its parts flow. Phones: no big drawing; the walk runs down the left, each caption a row with its stage
   drawn small, the closing line last. */
.aq-visit-plan-sec {
  --ink: var(--on-navy); --ink-muted: var(--on-navy-muted);
  --vp-line: color-mix(in srgb, var(--on-navy) 22%, transparent); --vp-flow: color-mix(in srgb, var(--flow) 45%, var(--on-navy));
}
.aq-visit-plan-sec .aq-sec-head .aq-h1 { font: 300 64px/68px var(--font-sans); letter-spacing: -0.035em; max-width: 18ch; color: var(--on-navy); }
.aq-visit-plan-sec .aq-ph { background: transparent; color: var(--on-navy); outline: 1px dashed var(--on-navy-muted); outline-offset: -1px; }
.aq-visit-plan { position: relative; }
.aq-visit-plan__sheet { margin-inline: calc(-1 * var(--space-4)); }
.aq-visit-plan__svg { display: block; width: 100%; height: auto; }
.aq-visit-plan__walk { fill: none; stroke: var(--on-navy-muted); stroke-width: 1.5; stroke-dasharray: 5 5; stroke-linecap: round; }
.aq-visit-plan__pin { fill: none; stroke: var(--on-navy-muted); stroke-width: 1; }
.aq-visit-plan__mark circle { fill: var(--navy); stroke: var(--on-navy); stroke-width: 1.5; transition: fill 200ms ease, stroke 200ms ease; }
.aq-visit-plan__mark text { font: 500 11px/1 var(--font-mono); fill: var(--on-navy); text-anchor: middle; }
.aq-visit-plan__mark.is-end circle { fill: var(--limestone); stroke: var(--limestone); }
.aq-visit-plan__tick { fill: none; stroke: var(--navy); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.aq-visit-plan__mark.is-on circle { fill: var(--vp-flow, var(--flow)); stroke: var(--vp-flow, var(--flow)); }
.aq-visit-plan__mark.is-on text { fill: var(--navy); }
.aq-visit-plan__mark.is-on .aq-visit-plan__pin { stroke: var(--vp-flow, var(--flow)); }
.aq-visit-plan__walker { fill: var(--vp-flow, var(--flow)); stroke: var(--navy); stroke-width: 2; }

/* captions along the base */
.aq-visit-plan__stops {
  list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(var(--cols, 7), minmax(0, 1fr));
  border-top: 1px solid var(--vp-line, var(--line));
}
.aq-visit-plan__stop { min-width: 0; border-left: 1px solid var(--vp-line, var(--line)); }
.aq-visit-plan__stop:first-child { border-left: 0; }
.aq-visit-plan__body { display: flex; flex-direction: column; gap: var(--space-2); height: 100%; padding: var(--space-4) var(--space-3) var(--space-6); color: var(--on-navy); text-decoration: none; outline-offset: -2px; transition: background-color 200ms ease; }
.aq-visit-plan__body:focus-visible { outline: 2px solid var(--on-navy); }
.aq-visit-plan__stop.is-on .aq-visit-plan__body, .aq-visit-plan__body:hover { background: color-mix(in srgb, var(--on-navy) 8%, var(--navy)); }
.aq-visit-plan__fig { display: flex; align-items: center; gap: var(--space-2); }
.aq-visit-plan__mini { display: none; }
.aq-visit-plan__n { display: inline-grid; place-items: center; width: var(--space-8); height: var(--space-8); border: 1.5px solid var(--on-navy); border-radius: 50%; font: 500 12px/1 var(--font-mono); color: var(--on-navy); transition: background-color 200ms ease, color 200ms ease; }
.aq-visit-plan__n svg { width: var(--space-4); height: var(--space-4); fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.aq-visit-plan__stop.is-on .aq-visit-plan__n { background: var(--vp-flow, var(--flow)); border-color: var(--vp-flow, var(--flow)); color: var(--navy); }
.aq-visit-plan__cap { font: 400 12px/16px var(--font-mono); color: var(--on-navy-muted); }
.aq-visit-plan__t { margin: 0; font: 500 16px/22px var(--font-sans); color: var(--on-navy); text-wrap: balance; }
a.aq-visit-plan__body .aq-visit-plan__t::after { content: " →"; color: var(--vp-flow, var(--flow)); }
a.aq-visit-plan__body:hover .aq-visit-plan__t { color: var(--vp-flow, var(--flow)); }
.aq-visit-plan__d { margin: 0; font: 400 14px/20px var(--font-sans); color: var(--on-navy-muted); text-wrap: pretty; }

/* the sign-off item closes the band as one limestone line */
.aq-visit-plan__stop.is-end { grid-column: 1 / -1; border-left: 0; margin-inline: calc(-1 * var(--space-8)); margin-bottom: calc(-1 * var(--space-16)); }
.aq-visit-plan__stop.is-end .aq-visit-plan__body {
  flex-direction: row; align-items: baseline; flex-wrap: wrap; column-gap: var(--space-4); row-gap: var(--space-1);
  padding: var(--space-6) var(--space-8); background: var(--limestone); color: var(--on-limestone);
}
.aq-visit-plan__stop.is-end .aq-visit-plan__fig { align-self: center; }
.aq-visit-plan__stop.is-end .aq-visit-plan__n { background: var(--navy); border-color: var(--navy); color: var(--limestone); }
.aq-visit-plan__stop.is-end .aq-visit-plan__cap { color: var(--on-limestone-muted); }
.aq-visit-plan__stop.is-end .aq-visit-plan__t { font: 300 28px/34px var(--font-sans); letter-spacing: -0.01em; color: var(--navy); }
.aq-visit-plan__stop.is-end .aq-visit-plan__t::after { content: ":"; }
.aq-visit-plan__stop.is-end .aq-visit-plan__d { flex: 1 1 24rem; font: 300 28px/34px var(--font-sans); letter-spacing: -0.01em; color: var(--on-limestone); }
.aq-visit-plan__stop.is-end.is-on .aq-visit-plan__body, .aq-visit-plan__stop.is-end .aq-visit-plan__body:hover { background: color-mix(in srgb, var(--limestone) 85%, var(--surface)); }
.aq-visit-plan__stop.is-end .aq-visit-plan__body:focus-visible { outline-color: var(--focus); }

@container (max-width: 860px) {
  .aq-visit-plan-sec .aq-sec-head .aq-h1 { font: 300 36px/42px var(--font-sans); }
  .aq-visit-plan__sheet { display: none; }
  .aq-visit-plan__stops { display: block; position: relative; border: 0; }
  .aq-visit-plan__stops::before { content: ""; position: absolute; left: calc(var(--space-4) - 1px); top: var(--space-6); bottom: var(--space-24); border-left: 1.5px dashed var(--on-navy-muted); }
  .aq-visit-plan__stop { border: 0; border-top: 1px solid var(--vp-line, var(--line)); }
  .aq-visit-plan__body { display: grid; grid-template-columns: var(--space-8) minmax(0, 1fr) auto; column-gap: var(--space-3); row-gap: var(--space-1); padding: var(--space-4) 0; }
  .aq-visit-plan__fig { display: contents; }
  .aq-visit-plan__n { grid-column: 1; grid-row: 1 / span 3; align-self: start; position: relative; background: var(--navy); }
  .aq-visit-plan__mini { display: block; grid-column: 3; grid-row: 1 / span 3; width: calc(var(--space-16) + var(--space-8)); height: auto; align-self: start; }
  .aq-visit-plan__cap, .aq-visit-plan__t, .aq-visit-plan__d { grid-column: 2; }
  .aq-visit-plan__stop.is-end { margin-inline: calc(-1 * var(--space-4)); margin-bottom: calc(-1 * var(--space-12)); margin-top: var(--space-6); border: 0; }
  .aq-visit-plan__stop.is-end .aq-visit-plan__body { display: grid; padding: var(--space-6) var(--space-4); }
  .aq-visit-plan__stop.is-end .aq-visit-plan__t, .aq-visit-plan__stop.is-end .aq-visit-plan__d { font-size: 20px; line-height: 26px; }
}

/* ---------- VisitRoute: a visit's stops on one route line, drawn on a Plate (grid block as "route") ----------
   Desktop: rows of 3 or 4 stops; odd rows run left to right, even rows right to left, joined by U-turns at the ends
   (placement from --c / --r set by the renderer; DOM order is the route order). Each stop: its figure on the route (a Spot
   vignette with a square numbered tag in its corner, or the tag alone), a name (Geist 500, sentence case) and one line under it.
   The route runs through the middle of the figures (--m figure width, --mh its height). Phones: one vertical route down
   the left, figure | text. */
.aq-visit-route__plate { padding-top: var(--space-8); }
.aq-visit-route {
  --m: var(--space-8); --mh: var(--space-8);
  list-style: none; margin: 0; padding: 0 var(--space-8); display: grid; grid-template-columns: repeat(var(--cols, 3), minmax(0, 1fr)); column-gap: var(--space-8);
}
.aq-visit-route--spots { --m: calc(var(--space-32) + var(--space-12)); --mh: calc(var(--space-32) + var(--space-8)); }
.aq-visit-route__stop { position: relative; grid-column: var(--c, auto); grid-row: var(--r, auto); min-width: 0; padding-bottom: var(--space-12); }
.aq-visit-route__stop.is-last { padding-bottom: 0; }
.aq-visit-route__body { position: relative; z-index: 1; display: flex; flex-direction: column; align-items: flex-start; gap: var(--space-2); }
:where(.aq-page) a.aq-visit-route__body { color: var(--ink); text-decoration: none; }
/* the figure: plate-coloured so the route stops at its edge, the vignette centred, the tag in its top-left corner */
.aq-visit-route__fig { position: relative; display: grid; place-items: center; width: var(--m, var(--space-8)); height: var(--mh, var(--space-8)); margin-bottom: var(--space-2); background: var(--surface-raised); }
.aq-visit-route__spot { background-color: var(--ink); }
/* An Icon standing in for a spot draws at the spot's size (not the 64 px icon size), so every stop's vignette reads
   at the same visual size along the route; muted, because its heavier icon stroke would otherwise outweigh the spots */
.aq-visit-route__spot.aq-spot--icon { width: var(--space-12); height: var(--space-12); background-color: var(--ink-muted); }
.aq-visit-route__n {
  display: inline-grid; place-items: center; min-width: var(--space-8); height: var(--space-6); padding: 0 var(--space-1);
  border: 1px solid var(--flow); border-radius: var(--radius-sm); background: var(--surface-raised);
  font: 500 12px/1 var(--font-mono); font-variant-numeric: tabular-nums; letter-spacing: 0.04em; color: var(--flow);
}
.aq-visit-route--spots .aq-visit-route__n { position: absolute; top: 0; left: 0; }
.aq-visit-route__n svg { width: var(--space-4); height: var(--space-4); fill: none; stroke: currentColor; stroke-width: 2; }
.aq-visit-route__stop.is-end .aq-visit-route__n { background: var(--flow); color: var(--surface-raised); }
.aq-visit-route--spots .is-end .aq-visit-route__fig { outline: 1px solid var(--flow); outline-offset: calc(var(--space-1) * -1); }
.aq-visit-route__cap { font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-muted); }
.aq-visit-route__t { margin: 0; font: 500 17px/24px var(--font-sans); letter-spacing: -0.005em; color: var(--ink); text-wrap: balance; }
.aq-visit-route__d { margin: 0; font: 400 15px/24px var(--font-sans); color: var(--ink-muted); overflow-wrap: break-word; text-wrap: pretty; }
a.aq-visit-route__body .aq-visit-route__t::after { content: "\a0\2192"; color: var(--flow); }
a.aq-visit-route__body:hover .aq-visit-route__t { color: var(--flow); }
a.aq-visit-route__body:hover .aq-visit-route__spot { background-color: var(--flow); }
a.aq-visit-route__body:focus-visible { outline: 2px solid var(--focus); outline-offset: var(--space-1); }

/* The route: ::after runs to the next stop in the row (or to the column edge before a U-turn); ::before is the U-turn
   at the row end, or the lead-in from the column edge on a right-to-left row. */
.aq-visit-route__stop::before, .aq-visit-route__stop::after { content: ""; position: absolute; top: calc(var(--mh, var(--space-8)) / 2); border: 0 solid var(--line-strong); pointer-events: none; }
.aq-visit-route__stop.is-ltr::after { left: calc(var(--m, var(--space-8)) / 2); width: calc(100% + var(--space-8)); border-top-width: 1px; }
.aq-visit-route__stop.is-rtl::after { right: calc(100% - var(--m, var(--space-8)) / 2); width: calc(100% + var(--space-8)); border-top-width: 1px; }
.aq-visit-route__stop.is-ltr.is-turn::after { width: calc(100% - var(--m, var(--space-8)) / 2); }
.aq-visit-route__stop.is-rtl.is-turn::after, .aq-visit-route__stop.is-last::after { display: none; }
.aq-visit-route__stop.is-turn::before { height: 100%; width: var(--space-8); border-width: 1px 0; }
.aq-visit-route__stop.is-ltr.is-turn::before { left: 100%; border-right-width: 1px; }
.aq-visit-route__stop.is-rtl.is-turn::before { right: 100%; border-left-width: 1px; }
.aq-visit-route__stop.is-rtl.is-in::before { left: calc(var(--m, var(--space-8)) / 2); right: 0; border-top-width: 1px; }

/* Motion hooks (motion.js lays the route stop by stop): --aq-run scales the run to the next stop, --aq-turn clips the
   U-turn open from the top and the lead-in from the right. Both default to 1, so the drawing is complete without them. */
.aq-visit-route__stop.is-ltr::after { transform: scaleX(var(--aq-run, 1)); transform-origin: left center; }
.aq-visit-route__stop.is-rtl::after { transform: scaleX(var(--aq-run, 1)); transform-origin: right center; }
.aq-visit-route__stop.is-turn::before { clip-path: inset(0 0 calc((1 - var(--aq-turn, 1)) * 100%) 0); }
.aq-visit-route__stop.is-rtl.is-in::before { clip-path: inset(0 0 0 calc((1 - var(--aq-turn, 1)) * 100%)); }

@media (prefers-reduced-motion: no-preference) {
  .aq-visit-route__t, .aq-visit-route__spot { transition: color 120ms, background-color 120ms; }
  .aq-visit-route__n { transition: transform 160ms cubic-bezier(0.2, 0, 0, 1); }
  a.aq-visit-route__body:hover .aq-visit-route__n { transform: translateY(calc(var(--space-1) * -1)); }
}

/* Phones: still on the plate; one vertical route through the figures at the left, the name and line beside each. */
@container (max-width: 860px) {
  .aq-visit-route__plate { padding-top: var(--space-6); }
  .aq-visit-route { --m: var(--space-8); --mh: var(--space-6); padding: 0; grid-template-columns: minmax(0, 1fr); }
  .aq-visit-route--spots { --m: var(--space-24); --mh: var(--space-24); }
  .aq-visit-route__stop { grid-column: 1; grid-row: auto; padding-bottom: var(--space-6); }
  .aq-visit-route__body { display: grid; grid-template-columns: var(--m, var(--space-8)) minmax(0, 1fr); align-content: start; column-gap: var(--space-3); row-gap: var(--space-1); }
  .aq-visit-route__fig { grid-row: 1 / span 3; margin: 0; }
  .aq-visit-route .aq-visit-route__spot { width: var(--space-24); height: var(--space-24); }
  .aq-visit-route .aq-visit-route__spot.aq-spot--icon { width: var(--space-12); height: var(--space-12); }
  .aq-visit-route__n { min-width: var(--space-6); height: var(--space-6); font-size: 12px; }
  .aq-visit-route__cap { font-size: 12px; }
  .aq-visit-route__cap, .aq-visit-route__t, .aq-visit-route__d { grid-column: 2; }
  .aq-visit-route__t { font-size: 16px; line-height: 24px; }
  .aq-visit-route__d { font-size: 14px; line-height: 22px; }
  .aq-visit-route__stop::before, .aq-visit-route__stop.is-rtl.is-in::before { display: none; }
  .aq-visit-route__stop::after, .aq-visit-route__stop.is-ltr::after, .aq-visit-route__stop.is-rtl::after, .aq-visit-route__stop.is-ltr.is-turn::after, .aq-visit-route__stop.is-rtl.is-turn::after {
    display: block; left: calc(var(--m, var(--space-8)) / 2); right: auto; width: 0; height: 100%; border-width: 0 0 0 1px;
    transform: scaleY(var(--aq-run, 1)); transform-origin: center top;
  }
  .aq-visit-route__stop.is-last::after { display: none; }
}

/* ---------- WalkdownPins: IQ and OQ checks as a table beside the system they inspect (look "walkdown-pins") ----------
   Desktop: the checks as a hairline table on the left (6 of 12: number, check with its IQ or OQ tag, what we verify,
   basis in mono, under a mono column head); the drawing sheet (IsoKit light sheet, iso grid) on the right, held in
   view while the table scrolls. Each check's number marks its part (a small ruled square; two on one part step
   apart, --k); a few parts carry a leader callout with their name over the shelf. IQ tags ruled in ink, OQ filled
   flow (installed versus running). A row pointed at or focused lights its part (aq-iso__part is-lit), its marker
   and its callout. */
.aq-walkdown-pins { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 6fr); gap: var(--space-12); align-items: start; }
.aq-walkdown-pins__fig { position: sticky; top: var(--space-24); }
.aq-walkdown-pins__sheet { position: relative; background: var(--surface-raised); border: 1px solid var(--line); }
.aq-walkdown-pins__svg { display: block; width: 100%; height: auto; }
.aq-walkdown-pins__pin { position: absolute; transform: translate(calc(-50% + var(--k, 0) * var(--space-6)), -50%); display: inline-flex; align-items: center; justify-content: center;
  min-width: var(--space-6); height: var(--space-6); padding: 0 var(--space-1); background: var(--surface); border: 1px solid var(--navy); color: var(--ink); font: 500 12px/1 var(--font-mono);
  transition: background-color 180ms, color 180ms, border-color 180ms; z-index: 1; }
.aq-walkdown-pins__pin.is-on { background: var(--flow); border-color: var(--flow); color: var(--surface); z-index: 2; }
.aq-walkdown-pins__lead .aq-iso__leader-line { stroke: var(--ink-subtle); }
.aq-walkdown-pins__lab { position: absolute; transform: translate(0, calc(-100% - var(--space-1))); white-space: nowrap; font: 400 12px/16px var(--font-mono); letter-spacing: 0.02em; color: var(--ink-muted); transition: color 180ms; }
.aq-walkdown-pins__lab--r { transform: translate(-100%, calc(-100% - var(--space-1))); }
.aq-walkdown-pins__lab.is-on { color: var(--flow); }

.aq-walkdown-pins__cols, .aq-walkdown-pins__row { display: grid; grid-template-columns: var(--space-8) minmax(0, 3fr) minmax(0, 4fr) minmax(0, 3fr); column-gap: var(--space-4); }
.aq-walkdown-pins__cols { padding-bottom: var(--space-2); border-bottom: 1px solid var(--line-strong); font: 400 12px/16px var(--font-mono); letter-spacing: 0.04em; color: var(--ink-subtle); }
.aq-walkdown-pins__tab { min-width: 0; }
.aq-walkdown-pins__list { list-style: none; margin: 0; padding: 0; }
.aq-walkdown-pins__row { align-items: start; padding: var(--space-4) 0; border-bottom: 1px solid var(--line); outline: none; transition: background-color 180ms; }
.aq-walkdown-pins__row:hover, .aq-walkdown-pins__row:focus-visible { background: var(--surface-raised); }
.aq-walkdown-pins__row:focus-visible { outline: 2px solid var(--focus); outline-offset: -2px; }
.aq-walkdown-pins__n { font: 400 13px/22px var(--font-mono); color: var(--flow); padding-left: var(--space-1); }
.aq-walkdown-pins__t { margin: 0; display: flex; align-items: baseline; flex-wrap: wrap; gap: var(--space-1) var(--space-2); font: 500 15px/22px var(--font-sans); color: var(--ink); }
.aq-walkdown-pins__tag { padding: 0 var(--space-1); font: 500 12px/18px var(--font-mono); letter-spacing: 0.08em; border: 1px solid var(--ink); color: var(--ink); }
.aq-walkdown-pins__tag--oq { background: var(--flow); border-color: var(--flow); color: var(--surface); }
.aq-walkdown-pins__v { margin: 0; font: 400 14px/22px var(--font-sans); color: var(--ink-muted); }
.aq-walkdown-pins__m { margin: 0; font: 400 13px/20px var(--font-mono); color: var(--ink-subtle); }

/* the fold is for phones only: desktop shows every check */
.aq-fold:not(.is-open) .aq-walkdown-pins__row.aq-fold-x { display: grid; }
.aq-fold:has(> .aq-walkdown-pins__list) > .aq-fold__btn { display: none; }

@container (max-width: 1080px) {
  .aq-walkdown-pins { grid-template-columns: minmax(0, 1fr); gap: var(--space-8); }
  .aq-walkdown-pins__fig { position: static; order: -1; }
}
@container (max-width: 860px) {
  .aq-walkdown-pins { gap: var(--space-6); }
  .aq-walkdown-pins__cols { display: none; }
  .aq-walkdown-pins__row { grid-template-columns: var(--space-8) minmax(0, 1fr); row-gap: var(--space-1); }
  .aq-walkdown-pins__row > :not(.aq-walkdown-pins__n) { grid-column: 2; }
  .aq-walkdown-pins__n { grid-row: 1; }
  .aq-walkdown-pins__pin { min-width: var(--space-4); height: var(--space-4); padding: 0; font-size: 12px; transform: translate(calc(-50% + var(--k, 0) * var(--space-4)), -50%); }
  .aq-walkdown-pins__lab, .aq-walkdown-pins__lead { display: none; }
  .aq-walkdown-pins__v { font-size: 14px; }
  .aq-walkdown-pins__m { font-size: 12px; line-height: 18px; }
  .aq-fold:not(.is-open) .aq-walkdown-pins__row.aq-fold-x { display: none; }
  .aq-fold:has(> .aq-walkdown-pins__list) > .aq-fold__btn { display: flex; }
}

/* section hook (the look marks its section) */
.aq-walkdown-pins-sec { position: relative; }

/* ---------- WasherTrace: the equipment drawing pinned beside its points, the water route filling hotspot to hotspot ---------- */
.aq-washer-trace-sec { overflow: clip; }
.aq-washer-trace-sec .aq-sec-head .aq-h1 { color: var(--on-navy); }
.aq-washer-trace { display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); column-gap: var(--space-12); margin-top: var(--space-8); align-items: start; }
.aq-washer-trace__stage { position: sticky; top: var(--space-16); display: flex; flex-direction: column; gap: var(--space-3); padding: var(--space-6);
  border: 1px solid color-mix(in srgb, var(--on-navy-muted) 35%, transparent); }
.aq-washer-trace__fig { position: relative; width: min(100%, calc(var(--space-32) * 4.25)); margin-inline: auto; }
.aq-washer-trace__art { background-color: var(--limestone); opacity: 0.92; }
.aq-washer-trace__route { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; pointer-events: none; }
.aq-washer-trace__route path { fill: none; stroke-linecap: round; stroke-linejoin: round; }
.aq-washer-trace__pipe { stroke: var(--navy); stroke-width: 14; }
.aq-washer-trace__water { stroke: color-mix(in srgb, var(--flow) 45%, var(--on-navy)); stroke-width: 4.5; }
.aq-washer-trace__cap { display: flex; justify-content: flex-end; margin: 0; font: 500 11px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-washer-trace__cap span { padding: var(--space-1) var(--space-3); border: 1px solid color-mix(in srgb, var(--on-navy-muted) 40%, transparent); margin-left: -1px; }
.aq-washer-trace__cap span:empty { display: none; }

.aq-washer-trace__hot { position: absolute; width: var(--space-12); height: var(--space-12); margin: calc(var(--space-6) * -1) 0 0 calc(var(--space-6) * -1); display: grid; place-items: center;
  border-radius: 50%; background: var(--navy); border: 1.5px solid var(--limestone); color: var(--limestone); font: 500 15px/1 var(--font-mono);
  transition: background-color 400ms cubic-bezier(0.2, 0, 0, 1), color 400ms, transform 400ms cubic-bezier(0.2, 0, 0, 1); }
.aq-washer-trace__hot::after { content: ""; position: absolute; inset: calc(var(--space-2) * -1); border-radius: 50%; border: 1px solid color-mix(in srgb, var(--limestone) 50%, transparent); }
.aq-washer-trace__hot.is-on { background: var(--limestone); color: var(--navy); transform: scale(1.12); }
.aq-washer-trace.is-scroll .aq-washer-trace__hot:not(.is-on) { opacity: 0.55; }

/* The points: large numbers on a rule, the current one lit */
.aq-washer-trace__steps { list-style: none; margin: 0; padding: 0; }
.aq-washer-trace__step { position: relative; display: flex; flex-direction: column; gap: var(--space-3); min-height: calc(var(--space-32) * 3.5); padding: var(--space-6) 0 var(--space-8) var(--space-8);
  border-left: 1px solid color-mix(in srgb, var(--on-navy-muted) 35%, transparent); transition: opacity 400ms cubic-bezier(0.2, 0, 0, 1); }
.aq-washer-trace__step::before { content: ""; position: absolute; left: -1px; top: 0; bottom: 0; width: 3px; background: var(--limestone); transform: scaleY(0); transform-origin: 50% 0;
  transition: transform 600ms cubic-bezier(0.2, 0, 0, 1); }
.aq-washer-trace__step.is-on::before { transform: scaleY(1); }
.aq-washer-trace.is-scroll .aq-washer-trace__step:not(.is-on) { opacity: 0.5; }
.aq-washer-trace__n { font: 300 64px/60px var(--font-sans); letter-spacing: -0.05em; color: var(--on-navy-muted); }
.aq-washer-trace__step.is-on .aq-washer-trace__n { color: var(--limestone); }
.aq-washer-trace__t { margin: 0; font: 300 30px/36px var(--font-sans); letter-spacing: -0.02em; color: var(--on-navy); }
.aq-washer-trace__d { margin: 0; font: 400 17px/27px var(--font-sans); color: var(--on-navy-muted); max-width: 36ch; }

@container (max-width: 1100px) {
  .aq-washer-trace { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); column-gap: var(--space-8); }
  .aq-washer-trace__t { font-size: 26px; line-height: 32px; }
}

/* Phones: the drawing on top with all hotspots, the points as a numbered run under it */
@container (max-width: 860px) {
  .aq-washer-trace { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-6); margin-top: var(--space-4); }
  .aq-washer-trace__stage { position: relative; top: auto; padding: var(--space-4); }
  .aq-washer-trace__hot { width: var(--space-8); height: var(--space-8); margin: calc(var(--space-4) * -1) 0 0 calc(var(--space-4) * -1); font-size: 13px; }
  .aq-washer-trace__step { min-height: 0; padding: var(--space-4) 0 var(--space-6) var(--space-6); gap: var(--space-2); }
  .aq-washer-trace__step::before { transform: scaleY(1); }
  .aq-washer-trace__n { font-size: 44px; line-height: 44px; color: var(--limestone); }
  .aq-washer-trace__t { font-size: 22px; line-height: 28px; }
  .aq-washer-trace__d { font-size: 16px; line-height: 25px; }
}

/* ---------- WaterPath: the system families on one pipe, feed to point of use ----------
   Drawn by the ProcessDiagram flow (aq-diagram markup; parts/ProcessDiagram.js wFlow) with this modifier: pipe-end
   labels above the row, and a detail panel that carries the family's line, governing standard and page link. */
.aq-water-path .aq-diagram__t { font-size: 13px; }
.aq-water-path.is-live .aq-diagram__d { grid-template-columns: auto minmax(0, 1fr); }
.aq-water-path .aq-diagram__io { display: none; }

/* ---------- WetRunHmi: the explainer read along the test bay's water route, dry or with water (look "wet-run-hmi") ----------
   A navy section (data-theme="dark" on the section, so every token inside takes its dark value in both themes).
   Desktop: the heading at display scale in light type with the two-position switch at its right; under it the route
   drawing across the full width: a double-wall pipe (a 10-unit line-strong wall with a navy bore, so two hairline
   walls), the water a 3-unit flow line inside it, flat symbols in 1.5-unit line-strong. The points are HTML blocks
   placed in % of the drawing beside their stations (inline left/top); numbered markers sit on the stations. State lives on
   the root: is-wet (default, complete without script) or is-dry. Up to a 1080 px container the route turns vertical:
   one CSS pipe down the left, the numbers on it, the points beside it. */
.aq-wet-run-hmi-sec, .aq-section--alt.aq-wet-run-hmi-sec { background: var(--navy); color: var(--ink); }
.aq-wet-run-hmi { display: flex; flex-direction: column; gap: var(--space-12); }
.aq-wet-run-hmi__head { display: flex; align-items: flex-end; justify-content: space-between; gap: var(--space-8); }
.aq-wet-run-hmi__head .aq-sec-head { margin: 0; }
.aq-wet-run-hmi__head .aq-h1 { max-width: 15ch; font-size: clamp(44px, 5.4cqi, 72px); line-height: 1.02; font-weight: 300; letter-spacing: -0.03em; color: var(--ink); }

/* the switch: a sliding thumb under two buttons (ported from sliding-tabs; motion.js springs it) */
.aq-wet-run-hmi__switch { position: relative; flex: none; display: inline-grid; grid-template-columns: 1fr 1fr; border: 1px solid var(--line-strong); isolation: isolate; }
.aq-wet-run-hmi__thumb { position: absolute; z-index: -1; top: 0; bottom: 0; left: 0; width: 50%; background: var(--flow); transform: translateX(100%); }
.is-dry .aq-wet-run-hmi__thumb { transform: translateX(0); background: var(--line-strong); }
.aq-wet-run-hmi__mode { min-height: 44px; min-width: 128px; padding: 0 var(--space-4); border: 0; background: transparent; color: var(--ink-muted); cursor: pointer;
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; transition: color 150ms; }
.aq-wet-run-hmi__mode[aria-pressed="true"] { color: var(--navy); }
.is-dry .aq-wet-run-hmi__mode[aria-pressed="true"] { color: var(--ink); }
.aq-wet-run-hmi__mode:hover:not([aria-pressed="true"]) { color: var(--ink); }
.aq-wet-run-hmi__mode:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }

/* the route */
.aq-wet-run-hmi__fig { position: relative; }
.aq-wet-run-hmi__svg { display: block; width: 100%; height: auto; aspect-ratio: 1200 / 460; overflow: visible; }
.aq-wet-run-hmi__wall { fill: none; stroke: var(--line-strong); stroke-width: 10; stroke-linejoin: round; }
.aq-wet-run-hmi__bore { fill: none; stroke: var(--navy); stroke-width: 7; stroke-linejoin: round; }
.aq-wet-run-hmi__water { fill: none; stroke: var(--flow); stroke-width: 3; stroke-linejoin: round; transition: opacity 300ms; }
.aq-wet-run-hmi__eq { fill: var(--navy); stroke: var(--line-strong); stroke-width: 1.5; stroke-linejoin: round; }
.aq-wet-run-hmi__thin { fill: none; stroke: var(--line-strong); stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; }
.aq-wet-run-hmi__tag { font: 500 13px/1 var(--font-mono); letter-spacing: 0.08em; fill: var(--ink-subtle); }
.aq-wet-run-hmi__rd { fill: none; stroke: var(--line-strong); stroke-width: 1; }
.aq-wet-run-hmi__rdv { fill: var(--flow); transform-box: fill-box; transform-origin: 0 50%; transition: transform 400ms cubic-bezier(0.2, 0, 0, 1); }
.aq-wet-run-hmi__trend { fill: none; stroke: var(--flow); stroke-width: 2; stroke-linejoin: round; transition: opacity 300ms; }
.aq-wet-run-hmi__flat { fill: none; stroke: var(--ink-subtle); stroke-width: 1.5; stroke-dasharray: 4 4; opacity: 0; transition: opacity 300ms; }
.aq-wet-run-hmi__log { fill: none; stroke: var(--ink-subtle); stroke-width: 4; transition: opacity 300ms; }
.aq-wet-run-hmi__mk { position: absolute; transform: translate(-50%, -50%); display: inline-flex; align-items: center; justify-content: center; width: var(--space-8); height: var(--space-8);
  border-radius: 50%; background: var(--flow); color: var(--navy); font: 500 12px/1 var(--font-mono); letter-spacing: 0.04em;
  box-shadow: 0 0 0 var(--space-1) var(--navy), 0 0 0 calc(var(--space-1) + 1.5px) var(--flow); transition: background-color 300ms, color 300ms, box-shadow 300ms, transform 200ms cubic-bezier(0.2, 0, 0, 1); }

/* the points, beside their stations */
.aq-wet-run-hmi__pts { list-style: none; margin: 0; padding: 0; }
.aq-wet-run-hmi__pt { position: absolute; width: 28%; outline: none; }
.aq-wet-run-hmi__pt:focus-visible { outline: 2px solid var(--focus); outline-offset: var(--space-2); }
.aq-wet-run-hmi__n { display: inline-flex; align-items: center; justify-content: center; width: var(--space-8); height: var(--space-8); margin-bottom: var(--space-3);
  border: 1.5px solid var(--flow); color: var(--flow); font: 500 12px/1 var(--font-mono); letter-spacing: 0.04em; transition: background-color 150ms, color 150ms; }
.aq-wet-run-hmi__t { margin: 0; font: 400 20px/26px var(--font-sans); letter-spacing: -0.01em; color: var(--ink); }
.aq-wet-run-hmi__d { margin: var(--space-2) 0 0; font: 400 15px/23px var(--font-sans); color: var(--ink-muted); }
.aq-wet-run-hmi__pt:hover .aq-wet-run-hmi__n, .aq-wet-run-hmi__pt:focus-visible .aq-wet-run-hmi__n { background: var(--flow); color: var(--navy); }

/* dry: empty pipe, blank readouts, stations unlit */
.is-dry .aq-wet-run-hmi__water, .is-dry .aq-wet-run-hmi__trend { opacity: 0; }
.is-dry .aq-wet-run-hmi__flat { opacity: 1; }
.is-dry .aq-wet-run-hmi__log { opacity: 0.25; }
.is-dry .aq-wet-run-hmi__rdv { transform: scaleX(0); }
.is-dry .aq-wet-run-hmi__mk { background: var(--navy); color: var(--ink-subtle); box-shadow: 0 0 0 var(--space-1) var(--navy), 0 0 0 calc(var(--space-1) + 1.5px) var(--line-strong); }
/* pointing at a point swells its station's marker */
.aq-wet-run-hmi:has(.aq-wet-run-hmi__pt[data-part="divert"]:is(:hover, :focus-visible)) .aq-wet-run-hmi__mk[data-part="divert"],
.aq-wet-run-hmi:has(.aq-wet-run-hmi__pt[data-part="outlet"]:is(:hover, :focus-visible)) .aq-wet-run-hmi__mk[data-part="outlet"],
.aq-wet-run-hmi:has(.aq-wet-run-hmi__pt[data-part="record"]:is(:hover, :focus-visible)) .aq-wet-run-hmi__mk[data-part="record"] { transform: translate(-50%, -50%) scale(1.35); }

/* tablet and phone: the route turns vertical */
@container (max-width: 1080px) {
  .aq-wet-run-hmi__svg, .aq-wet-run-hmi__mk { display: none; }
  .aq-wet-run-hmi__pts { position: relative; display: flex; flex-direction: column; gap: var(--space-8); padding: var(--space-2) 0 var(--space-2) var(--space-16); }
  .aq-wet-run-hmi__pts::before { content: ""; position: absolute; left: var(--space-4); top: 0; bottom: 0; width: var(--space-2); border-inline: 1.5px solid var(--line-strong); }
  .aq-wet-run-hmi__pts::after { content: ""; position: absolute; left: calc(var(--space-4) + var(--space-1) - 1.5px); top: 0; bottom: 0; border-left: 3px solid var(--flow); transform-origin: 50% 0; transition: transform 600ms cubic-bezier(0.2, 0, 0, 1); }
  .is-dry .aq-wet-run-hmi__pts::after { transform: scaleY(0); }
  .aq-wet-run-hmi__pt { position: relative; left: auto !important; top: auto !important; width: auto; max-width: 60ch; }
  .aq-wet-run-hmi__n { position: absolute; left: calc(-1 * var(--space-16) + var(--space-1)); top: 0; margin: 0; border-radius: 50%; background: var(--flow); color: var(--navy); box-shadow: 0 0 0 var(--space-1) var(--navy); }
  .is-dry .aq-wet-run-hmi__n { background: var(--navy); color: var(--ink-subtle); border-color: var(--line-strong); }
  .aq-wet-run-hmi__t { padding-top: var(--space-1); }
}
@container (max-width: 860px) {
  .aq-wet-run-hmi { gap: var(--space-8); }
  .aq-wet-run-hmi__head { flex-direction: column; align-items: stretch; gap: var(--space-6); }
  .aq-wet-run-hmi__head .aq-h1 { font-size: 40px; line-height: 44px; }
  .aq-wet-run-hmi__mode { min-width: 0; }
  .aq-wet-run-hmi__t { font-size: 18px; line-height: 24px; }
  .aq-wet-run-hmi__d { font-size: 14px; line-height: 22px; }
}

/* ---------- WindingRoute: a treatment train as one winding pipe across a navy band, a stop per stage ---------- */
/* The pipe is one svg stretched over the stops' band (preserveAspectRatio none, non-scaling strokes), so stop i sits at
   the centre of column i, 25 % (high) or 75 % (low) down the band. Text in columns under the band. */
.aq-winding-route { --band: calc(var(--space-32) + var(--space-24)); --wr-y: calc(var(--space-6) + var(--space-4) + var(--space-2) + var(--space-3)); position: relative; margin-top: var(--space-8); }
.aq-winding-route__line { position: absolute; left: 0; top: 0; width: 100%; height: var(--band, calc(var(--space-32) + var(--space-24))); overflow: visible; pointer-events: none; }
.aq-winding-route__line path { fill: none; vector-effect: non-scaling-stroke; stroke-linecap: round; }
.aq-winding-route__pipe { stroke: var(--limestone); stroke-width: 14; }
.aq-winding-route__flow { stroke: var(--flow); stroke-width: 2; }
.aq-winding-route__fan { stroke: var(--on-navy-muted); stroke-width: 1.5; opacity: 0.7; }
.aq-winding-route__drop { position: absolute; left: 0; top: 0; width: var(--space-3); height: var(--space-3); border-radius: var(--radius-pill);
  background: var(--flow); border: 2px solid var(--on-navy); display: none; pointer-events: none; z-index: 2; }

.aq-winding-route__stops { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(var(--n, 7), minmax(0, 1fr)); column-gap: var(--space-4); }
.aq-winding-route__stop { position: relative; display: flex; flex-direction: column; min-width: 0; }
.aq-winding-route__mark { position: relative; height: var(--band, calc(var(--space-32) + var(--space-24))); }
.aq-winding-route__seg, .aq-winding-route__tail { display: none; }
.aq-winding-route__node { position: absolute; left: 50%; top: 75%; z-index: 1; width: var(--space-8); height: var(--space-8); transform: translate(-50%, -50%);
  border-radius: var(--radius-pill); background: var(--navy); border: 2px solid var(--limestone);
  box-shadow: 0 0 0 var(--space-1) color-mix(in srgb, var(--limestone) 22%, transparent);
  transition: transform 300ms cubic-bezier(0.2, 0, 0, 1), border-color 300ms; }
.aq-winding-route__node::after { content: ""; position: absolute; inset: 0; margin: auto; width: var(--space-2); height: var(--space-2); border-radius: var(--radius-pill); background: var(--flow); }
.is-first .aq-winding-route__node::after, .is-last .aq-winding-route__node::after { width: var(--space-2); height: var(--space-2); border-radius: 0; background: none;
  border-top: 2px solid var(--on-navy); border-right: 2px solid var(--on-navy); transform: translateX(-1px) rotate(45deg); }
.is-high .aq-winding-route__node { top: 25%; }
.aq-winding-route__glyph { position: absolute; left: 50%; transform: translateX(-50%); top: 0; transition: background-color 300ms; }
.is-high .aq-winding-route__glyph { top: auto; bottom: 0; }

/* Rising bubbles over a stage that strips gas (fx: "gas") */
.aq-winding-route__gas { position: absolute; left: 50%; top: 75%; width: 0; height: 0; }
.is-high .aq-winding-route__gas { top: 25%; }
.aq-winding-route__gas i { position: absolute; width: var(--space-1); height: var(--space-1); border-radius: var(--radius-pill); background: var(--on-navy-muted);
  transform: translate(calc(var(--gx, 0) * 1px), calc(var(--gy, 0) * 0.6px)); opacity: 0.6; }
.aq-winding-route__gas i:nth-child(3n) { width: var(--space-2); height: var(--space-2); opacity: 0.35; }

.aq-winding-route__text { display: flex; flex-direction: column; gap: var(--space-2); padding-top: var(--space-6); border-top: 1px solid color-mix(in srgb, var(--on-navy-muted) 35%, transparent); }
.aq-winding-route__code { margin: 0; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-winding-route__code span { color: var(--on-navy); }
.aq-winding-route__t { margin: 0; font: 400 20px/26px var(--font-sans); letter-spacing: -0.01em; color: var(--on-navy); }
.aq-winding-route__d { margin: 0; font: 400 14px/22px var(--font-sans); color: var(--on-navy-muted); }

/* Hover: the stop the reader points at lights */
.aq-winding-route__stop:hover .aq-winding-route__node { transform: translate(-50%, -50%) scale(1.25); border-color: var(--on-navy); }
.aq-winding-route__stop:hover .aq-winding-route__glyph { background-color: var(--on-navy); }
.aq-winding-route__stop:hover .aq-winding-route__text { border-top-color: var(--on-navy); }

/* Replay (motion only, ported from Subframe Motion "Race replay"): the visitor scrubs the water along the route. Stages
   the water has not reached yet step back; the one it has just reached is marked. */
.aq-winding-route__stop { transition: opacity 200ms; }
.aq-winding-route__stop.is-dry { opacity: 0.45; }
.aq-winding-route__stop.is-cur .aq-winding-route__text { border-top-color: var(--on-navy); }
.aq-winding-route__stop.is-cur .aq-winding-route__node { border-color: var(--on-navy); }
.aq-winding-route__scrub { display: flex; align-items: center; gap: var(--space-4); margin-top: var(--space-8); max-width: 32rem;
  font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--on-navy-muted); }
.aq-winding-route__scrub input { flex: 1; min-width: 0; min-height: 44px; margin: 0; accent-color: var(--flow); cursor: pointer; background: transparent; }
.aq-winding-route__scrub input:focus-visible { outline: 2px solid var(--on-navy); outline-offset: 2px; }

@container (max-width: 1100px) {
  .aq-winding-route__stops { column-gap: var(--space-3); }
  .aq-winding-route__t { font-size: 17px; line-height: 24px; }
  .aq-winding-route__d { font-size: 13px; line-height: 20px; }
}

/* Phones: the pipe winds down the left edge, one bend per stage (each stop draws its own segment) */
@container (max-width: 860px) {
  .aq-winding-route { margin-top: var(--space-4); }
  .aq-winding-route__line, .aq-winding-route__drop { display: none; }
  .aq-winding-route__stops { grid-template-columns: minmax(0, 1fr); }
  .aq-winding-route__stop { display: grid; grid-template-columns: var(--space-16) minmax(0, 1fr); column-gap: var(--space-4); }
  .aq-winding-route__mark { height: auto; }
  /* The bend peaks level with the stage name (--wr-y: text padding + code line + gap + half the name line); a straight
     tail carries the pipe on down the rest of the stop */
  .aq-winding-route__seg { display: block; position: absolute; left: 0; top: 0; width: 100%; height: calc(var(--wr-y, var(--space-16)) * 2); overflow: visible; }
  .aq-winding-route__tail { display: block; position: absolute; left: calc(50% - var(--space-1) - var(--space-1) / 4); top: calc(var(--wr-y, var(--space-16)) * 2); bottom: 0;
    width: calc(var(--space-2) + var(--space-1) / 2); background: var(--limestone); }
  .aq-winding-route__seg path { fill: none; stroke: var(--limestone); stroke-width: 10; vector-effect: non-scaling-stroke; stroke-linecap: butt; }
  .aq-winding-route__node, .is-high .aq-winding-route__node { top: var(--wr-y, var(--space-16)); left: 30%; width: var(--space-6); height: var(--space-6); }
  .is-high .aq-winding-route__node { left: 70%; }
  .aq-winding-route__glyph { display: none; }
  .aq-winding-route__gas, .is-high .aq-winding-route__gas { top: var(--wr-y, var(--space-16)); left: 30%; }
  .is-high .aq-winding-route__gas { left: 70%; }
  .aq-winding-route__text { border-top: 0; padding-block: var(--space-6); }
  .aq-winding-route__t { font-size: 18px; line-height: 26px; }
  .aq-winding-route__d { font-size: 14px; line-height: 22px; }
}
@container (max-width: 860px) { .aq-winding-route__gas { transform: scale(0.45); } }
.aq-winding-route-sec { isolation: isolate; }
.aq-winding-route__fan--out { opacity: 0.9; }

/* phones: the route is vertical and has no droplet; no replay */
@container (max-width: 860px) { .aq-winding-route__scrub { display: none; } }

/* ---------- WitnessPlan: ways to witness as ruled rows whose leaders run into the package (look "witness-plan") ----------
   Desktop: rows on the left (5 of 12) under the heading, the IsoKit light drawing of the package in the test bay's
   open frame on the right (7 of 12). The leaders svg covers the whole look (aria-hidden, no pointer events): each
   leader is its row's underline carried on into the drawing and up to the part's marker; the chosen way's leader,
   marker and part turn flow. The sliding indicator (a flow edge on a raised ground) springs between rows.
   Container under 1080 px: the drawing above the rows, leaders off, rows ruled; numbered markers pair them. */
.aq-witness-plan { position: relative; display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: var(--space-8); align-items: center; }
.aq-witness-plan__side { position: relative; z-index: 1; min-width: 0; }
.aq-witness-plan__side .aq-sec-head .aq-h1 { font: 300 56px/60px var(--font-sans); letter-spacing: -0.03em; }
.aq-witness-plan__list { position: relative; list-style: none; margin: var(--space-8) 0 0; padding: 0; }
.aq-witness-plan__opt { position: relative; display: grid; grid-template-columns: var(--space-12) minmax(0, 1fr); column-gap: var(--space-2); width: 100%; min-height: var(--space-12); padding: var(--space-4) var(--space-3) var(--space-4) var(--space-2);
  border: 0; border-bottom: 1px solid var(--line); background: transparent; color: var(--ink); text-align: left; font: inherit; cursor: pointer; transition: background-color 160ms; }
.aq-witness-plan__opt::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--flow); transform: scaleY(0); transition: transform 160ms; }
.aq-witness-plan__opt[aria-pressed="true"] { background: var(--surface-raised); }
.aq-witness-plan__opt[aria-pressed="true"]::before { transform: scaleY(1); }
.aq-witness-plan__opt:hover { background: var(--surface-raised); }
.aq-witness-plan__opt:focus-visible { outline: 2px solid var(--focus); outline-offset: -2px; }
.aq-witness-plan__n { grid-row: 1 / span 2; font: 400 14px/24px var(--font-mono); color: var(--ink-subtle); }
.aq-witness-plan__opt[aria-pressed="true"] .aq-witness-plan__n { color: var(--flow); }
.aq-witness-plan__t { font: 400 19px/24px var(--font-sans); letter-spacing: -0.01em; }
.aq-witness-plan__d { margin-top: var(--space-1); font: 400 14px/21px var(--font-sans); color: var(--ink-muted); }
.aq-witness-plan__list > .aq-witness-plan__ind { display: none; position: absolute; z-index: -1; left: 0; right: 0; top: 0; height: 0; border-left: 3px solid var(--flow); background: var(--surface-raised); pointer-events: none; }
.aq-witness-plan__list.has-ind > .aq-witness-plan__ind { display: block; }
.aq-witness-plan__list.has-ind .aq-witness-plan__opt[aria-pressed="true"], .aq-witness-plan__list.has-ind .aq-witness-plan__opt:hover { background: transparent; }
.aq-witness-plan__list.has-ind .aq-witness-plan__opt::before { display: none; }

.aq-witness-plan__fig { position: relative; z-index: 0; min-width: 0; }
.aq-witness-plan__sheet { position: relative; }
.aq-witness-plan__svg { display: block; width: 100%; height: auto; }
.aq-witness-plan__svg .aq-witness-plan__bay { stroke: var(--line-strong); }
.aq-witness-plan__mk { position: absolute; z-index: 2; transform: translate(calc(-50% + var(--k, 0) * var(--space-6)), -50%); display: inline-flex; align-items: center; justify-content: center; min-width: var(--space-6); height: var(--space-6); padding: 0 var(--space-1);
  background: var(--surface); border: 1px solid var(--line-strong); color: var(--ink-muted); font: 500 12px/1 var(--font-mono); transition: background-color 160ms, color 160ms, border-color 160ms; }
.aq-witness-plan__mk.is-on { background: var(--flow); border-color: var(--flow); color: var(--surface); }
.aq-witness-plan__zone { position: absolute; transform: translate(0, calc(-100% - var(--space-2))); white-space: nowrap; font: 500 12px/16px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-subtle); }
.aq-witness-plan__zone.is-cam { transform: translate(var(--space-2), calc(-100% - var(--space-2))); }

.aq-witness-plan__leads { position: absolute; inset: 0; z-index: 1; width: 100%; height: 100%; overflow: visible; pointer-events: none; }
.aq-witness-plan__lead { fill: none; stroke: var(--line-strong); stroke-width: 1; transition: stroke 160ms; }
.aq-witness-plan__lead.is-on { stroke: var(--flow); stroke-width: 1.5; }
.aq-witness-plan__beam { fill: none; stroke: var(--flow); stroke-width: 3; stroke-linecap: round; }
@container (min-width: 1081px) { .aq-witness-plan__opt { border-bottom-color: transparent; } }

@container (max-width: 1080px) {
  .aq-witness-plan { grid-template-columns: minmax(0, 1fr); gap: var(--space-6); }
  .aq-witness-plan__side { display: contents; }
  .aq-witness-plan__side > .aq-sec-head { order: 0; }
  .aq-witness-plan__fig { order: 1; }
  .aq-witness-plan__list { order: 2; margin-top: 0; }
  .aq-witness-plan__leads { display: none; }
}
@container (max-width: 860px) {
  .aq-witness-plan__side .aq-sec-head .aq-h1 { font-size: 36px; line-height: 42px; }
  .aq-witness-plan__list { margin-top: var(--space-6); }
  .aq-witness-plan__opt { grid-template-columns: var(--space-8) minmax(0, 1fr); }
  .aq-witness-plan__t { font-size: 17px; }
  .aq-witness-plan__mk { min-width: var(--space-4); height: var(--space-4); padding: 0; font-size: 12px; }
}

/* section hook */
.aq-witness-plan-sec { position: relative; }

/* ---------- CompareTable ---------- */
/* A comparison matrix: sentence-case column heads on surface-sunken, numbered row labels in a narrow left column, hairline cells.
   Desktop: a real table. Phones: each row is a record, its first cell the title and every other cell a "Label value" line.
   The --list variant (two columns) is a numbered row list at every width. */
.aq-compare-table {
  counter-reset: aq-compare-row;
  color: var(--ink);
  min-width: 0;
}
/* Column label inside each cell, and the column tabs: phones only (the thead names the column on desktop) */
.aq-compare-table__k, .aq-compare-table__tabs { display: none; }

/* The brand SpecTable look: a table on surface-raised, a surface-sunken head row in sentence case, line hairlines
   between rows only, the row label in Geist 500 with the shared mono index above it. */
.aq-compare-table__table {
  width: 100%; table-layout: fixed; border-collapse: collapse;
  font-family: var(--font-sans); background: var(--surface-raised);
}
.aq-compare-table__table th,
.aq-compare-table__table td {
  text-align: left; vertical-align: top;
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--line);
  overflow-wrap: break-word;
}
.aq-compare-table__table tr > :first-child { width: 22%; }

/* Column heads: Geist 500 14/20 ink-muted on surface-sunken, sentence case */
.aq-compare-table__table thead th {
  background: var(--surface-sunken);
  font: 500 14px/20px var(--font-sans); color: var(--ink-muted);
}
/* Row labels: the narrow left column, numbered */
.aq-compare-table__table tbody tr { counter-increment: aq-compare-row; }
.aq-compare-table__table tbody th {
  font: 500 16px/24px var(--font-sans); color: var(--ink);
}
/* Row index: the shared index style (.aq-index), written by CSS so cells stay plain */
.aq-compare-table__table tbody th::before {
  content: counter(aq-compare-row, decimal-leading-zero);
  content: counter(aq-compare-row, decimal-leading-zero) / "";
  display: block;
  font: 400 13px/24px var(--font-mono); letter-spacing: 0.02em; font-variant-numeric: tabular-nums;
  color: var(--ink-subtle);
}
.aq-compare-table__table tbody td { font: 400 14px/22px var(--font-sans); color: var(--ink); }

/* Routing link: names the destination page, reads "PW generation →" */
.aq-compare-table__table td a {
  font: 500 14px/22px var(--font-sans);
  color: var(--flow); text-decoration: none;
}
.aq-compare-table__table td a::after { content: "092"; content: "092" / ""; }
.aq-compare-table__table td a:hover { text-decoration: underline; text-underline-offset: 0.2em; }
.aq-compare-table__table td a:focus-visible,
.aq-compare-table__tab:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }

/* List variant (two columns): numbered rows, label left, value right; thead becomes a label strip */
.aq-compare-table--list .aq-compare-table__table,
.aq-compare-table--list thead,
.aq-compare-table--list tbody { display: block; }
.aq-compare-table--list tr {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2fr);
}
.aq-compare-table--list tr > * { width: auto; }
.aq-compare-table--list tr > :first-child { width: auto; }

/* Tab button (--tabs, phones) */
.aq-compare-table__tab {
  appearance: none; flex: none; width: var(--space-32); margin: 0; cursor: pointer;
  display: flex; align-items: flex-start; min-height: 44px;
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--line); border-radius: var(--radius-sm);
  background: var(--surface-sunken);
  font: 500 13px/18px var(--font-sans); text-align: left; color: var(--ink-muted);
  overflow-wrap: break-word;
}
.aq-compare-table__tab[aria-pressed="true"] {
  background: var(--surface-raised); color: var(--ink);
  border-color: var(--line-strong); border-top: 2px solid var(--flow); padding-top: calc(var(--space-2) - 1px);
}

/* Row hover (desktop): the row being read tints */
@media (hover: hover) { .aq-compare-table:not(.aq-compare-table--list) .aq-compare-table__table tbody tr:hover > * { background: var(--surface-sunken); } }

@container (max-width: 860px) {
  /* Phones: no frame, no sideways scroll, no tabs. Each row is a record on a hairline: index and title (the row label),
     then one line per other column, "Label  value", the label in small muted type. Link-only columns (__go) end the
     record as a plain link. The column heads stay for screen readers only. */
  .aq-compare-table { padding: 0; border: 0; background: none; }
  .aq-compare-table__table,
  .aq-compare-table__table tbody,
  .aq-compare-table__table tr,
  .aq-compare-table__table th,
  .aq-compare-table__table td { display: block; width: auto; }
  .aq-compare-table__table { background: none; border: 0; outline: 0; }
  .aq-compare-table__table tr > :first-child { width: auto; }
  .aq-compare-table__table thead {
    position: absolute; width: 1px; height: 1px; overflow: hidden;
    clip-path: inset(50%); white-space: nowrap;
  }
  /* Each record sits on a hairline: index, the row label as its title, then "Label: value" lines */
  .aq-compare-table__table tbody { border-bottom: 1px solid var(--line); }
  .aq-compare-table__table tbody tr { padding: var(--space-4) 0; border-top: 1px solid var(--line); }
  .aq-compare-table__table th,
  .aq-compare-table__table td { padding: 0; border: 0; }
  .aq-compare-table__table tbody tr:last-child > * { border: 0; }
  /* Title line: the shared index in the left column, the row label beside it */
  .aq-compare-table__table tbody th, .aq-compare-table__table tbody tr:last-child > th { display: block; margin-bottom: var(--space-2); font: 500 16px/24px var(--font-sans); color: var(--ink); }
  .aq-compare-table__table tbody td { margin-top: 0; padding: var(--space-1) 0 0; font-size: 14px; line-height: 22px; }
  .aq-compare-table__table tbody td[data-empty] { display: none; }
  .aq-compare-table__k { display: inline; margin-right: var(--space-2); font: 500 13px/22px var(--font-sans); color: var(--ink-muted); }
  .aq-compare-table__k::after { content: ":"; }
  /* Link column: last in the record wherever it sits in the table, as a quiet sans link that never strands its arrow */
  .aq-compare-table__table tbody tr { display: flex; flex-direction: column; }
  .aq-compare-table__table td.aq-compare-table__go { order: 1; margin-top: var(--space-1); }
  /* 44 px hit area on inline links (row-head and link-column) without moving the line */
  .aq-compare-table__table td a, .aq-compare-table__table th a { padding-block: calc(var(--space-3) + var(--space-1) / 2); }
  .aq-compare-table__table td a::after { content: "\a0\2192"; content: "\a0\2192" / ""; }

  /* Tabs (four or more value columns): one strip of tabs that scrolls inside itself, never two lines; each row the
     label left (13/20 ink-muted) and the chosen column's value right. */
  .aq-compare-table--tabs .aq-compare-table__tabs { display: flex; gap: var(--space-1); margin-bottom: var(--space-2); overflow-x: auto; scrollbar-width: thin; overscroll-behavior-x: contain; }
  .aq-compare-table--tabs .aq-compare-table__table tbody tr { display: grid; grid-template-columns: minmax(0, 2fr) minmax(0, 3fr); column-gap: var(--space-4); align-items: baseline; }
  .aq-compare-table--tabs .aq-compare-table__table tbody th, .aq-compare-table--tabs .aq-compare-table__table tbody tr:last-child > th { display: block; margin: 0; padding: var(--space-2) 0 0; font: 500 13px/20px var(--font-sans); color: var(--ink-muted); }
  .aq-compare-table--tabs .aq-compare-table__table tbody td { padding-top: var(--space-2); }
  .aq-compare-table--tabs .aq-compare-table__table tbody th::before { display: none; }
  .aq-compare-table--tabs .aq-compare-table__table tbody td { grid-column: 2; margin: 0; padding-left: 0; }
  .aq-compare-table--tabs .aq-compare-table__table tbody td[data-empty] { display: block; }
  .aq-compare-table--tabs[data-col="1"] tbody td:not(:nth-child(2)):not(.aq-compare-table__go),
  .aq-compare-table--tabs[data-col="2"] tbody td:not(:nth-child(3)):not(.aq-compare-table__go),
  .aq-compare-table--tabs[data-col="3"] tbody td:not(:nth-child(4)):not(.aq-compare-table__go),
  .aq-compare-table--tabs[data-col="4"] tbody td:not(:nth-child(5)):not(.aq-compare-table__go),
  .aq-compare-table--tabs[data-col="5"] tbody td:not(:nth-child(6)):not(.aq-compare-table__go),
  .aq-compare-table--tabs[data-col="6"] tbody td:not(:nth-child(7)):not(.aq-compare-table__go) { display: none; }

  /* List variant (two columns): label above value */
  .aq-compare-table--list .aq-compare-table__table tbody th, .aq-compare-table--list .aq-compare-table__table tbody tr:last-child > th { display: block; margin: 0; padding: 0; font: 500 13px/20px var(--font-sans); color: var(--ink-muted); }
  .aq-compare-table--list .aq-compare-table__table tbody th::before { display: none; }
}

/* ---------- KeyFacts: the numbers a page stands on, as a quiet measurement strip ---------- */
/* A row of cells between two `line` hairlines, divided by `line` hairlines, on the section's own ground. Each fact:
   the name in Geist sentence case, the figure in Geist Mono light with its unit beside it in `ink-muted`, and the source
   standard in small mono at the foot. No frame, rulers, fixings or dials. */
.aq-key-facts {
  position: relative; margin: 0;
  display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr);
  border-top: 1px solid var(--line); border-bottom: 1px solid var(--line);
  color: var(--ink);
}

.aq-key-facts > div {
  position: relative; min-width: 0;
  display: flex; flex-direction: column; gap: var(--space-2);
  padding: var(--space-6) var(--space-6) var(--space-6) 0;
}
.aq-key-facts > div + div { padding-left: var(--space-6); border-left: 1px solid var(--line); }

/* Name */
.aq-key-facts dt { font: 400 14px/20px var(--font-sans); color: var(--ink-muted); text-wrap: balance; }

/* Figure with its comparator and unit */
.aq-key-facts dd { margin: 0; }
.aq-key-facts__value, .aq-key-facts dd:first-of-type {
  display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 0.25em;
  font: 300 clamp(28px, 3.2cqi, 40px)/1.15 var(--font-mono); letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums; color: var(--ink);
}
.aq-key-facts:has(> :nth-child(5)) dd:first-of-type { font-size: clamp(24px, 2.4cqi, 32px); }
.aq-key-facts dd.is-long { font-size: clamp(20px, 2cqi, 24px); line-height: 1.25; letter-spacing: -0.01em; }
.aq-key-facts dd.is-long .aq-ph { font-size: 0.8em; }
.aq-key-facts__fig { overflow-wrap: normal; word-break: normal; hyphens: none; }
/* Unconfirmed ranges ("[500–20,000]") are long: set them smaller so they stay on one line in a narrow cell */
.aq-key-facts__fig .aq-ph { font-size: 0.55em; letter-spacing: 0; vertical-align: 0.2em; }
.aq-key-facts__cmp { font-size: 0.8em; letter-spacing: 0; color: var(--ink-muted); }
.aq-key-facts__unit { font: 400 max(14px, 0.42em)/1.3 var(--font-mono); letter-spacing: 0; color: var(--ink-muted); }

/* Source standard, on the cell's last line */
.aq-key-facts dd.aq-key-facts__src {
  margin-top: auto;
  font: 400 12px/16px var(--font-mono); letter-spacing: 0.02em; color: var(--ink-muted);
  overflow-wrap: break-word;
}

.aq-hero .aq-key-facts { margin-top: var(--space-16); }

@container (max-width: 860px) {
  /* Phones: one fact per row between `line` hairlines; the name on top, then the figure left and the source right.
     The figure's column is as wide as the figure, the source takes the rest and wraps in it, so a long source never
     squeezes a short figure. A long value (is-long: words or a placeholder) takes the row and its source sits under
     it, left-aligned. Every label 12 px or more. */
  .aq-key-facts { grid-auto-flow: row; grid-auto-columns: auto; grid-template-columns: minmax(0, 1fr); border-top: 0; }
  .aq-key-facts > div, .aq-key-facts > div + div {
    display: grid; grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "dt dt" "v src";
    align-items: baseline; column-gap: var(--space-3); row-gap: var(--space-1);
    padding: var(--space-4) 0; border-left: 0; border-top: 1px solid var(--line);
  }
  .aq-key-facts > div:has(> .is-long) { grid-template-columns: minmax(0, 1fr); grid-template-areas: "dt" "v" "src"; }
  .aq-key-facts dt { grid-area: dt; font-size: 13px; line-height: 18px; }
  .aq-key-facts__value, .aq-key-facts dd:first-of-type, .aq-key-facts:has(> :nth-child(5)) dd:first-of-type { grid-area: v; font-size: 26px; line-height: 1.15; }
  .aq-key-facts dd.is-long { font-size: 17px; line-height: 1.3; }
  .aq-key-facts dd.aq-key-facts__src { grid-area: src; margin-top: 0; text-align: right; }
  .aq-key-facts > div:has(> .is-long) dd.aq-key-facts__src { text-align: left; }
  .aq-key-facts__unit { font-size: 13px; }
  .aq-hero .aq-key-facts { margin-top: var(--space-8); }
}

/* ---------- LimitGauges ---------- */
/* Limits as a row of quiet instrument faces on a plate. Each cell opens on a line hairline (flow for the key limit):
   the parameter in Geist 500, a dial straight under it (a single-weight line-strong scale arc and ticks, scale
   numbers, the passing side as a flow line, a hairline needle resting on the limit, an ink limit mark and a "Limit"
   label, the limit as a mono readout bottom right), then the basis under a hairline. The full value is in the DOM for
   screen readers (the label and readout show it). A row without a number is a readout cell: the same cell without the
   dial, the value shown. */
.aq-limit-gauges { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-8) var(--space-6); }
/* Exactly four, seven or eight: four across; exactly two: two across. So no row is left with empty cells (a two-limit
   panel, svc-cq, fills the plate instead of leaving a third slot empty) */
.aq-limit-gauges:has(> li:nth-child(4):last-child), .aq-limit-gauges:has(> li:nth-child(7):last-child), .aq-limit-gauges:has(> li:nth-child(8):last-child) { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.aq-limit-gauges:has(> li:nth-child(2):last-child) { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.aq-limit-gauges__item { position: relative; display: flex; flex-direction: column; gap: var(--space-3); min-width: 0; padding-top: var(--space-4); border-top: 1px solid var(--line); }
