.aq-spec:not(.aq-spec--compare) tbody { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: var(--space-12); padding-inline: var(--space-6); background: var(--surface-raised); border-bottom: 1px solid var(--line); }
.aq-spec:not(.aq-spec--compare) tbody tr {
