.aq-spec:not(.aq-spec--compare) tbody tr.is-highlight { background: var(--flow-tint); }
.aq-spec:not(.aq-spec--compare) tbody tr.is-highlight ~ tr.is-highlight { background: none; border-left: 2px solid var(--flow); }
.aq-spec:not(.aq-spec--compare) tbody tr.is-lead + tr.is-lead { border-top: 1px solid var(--line); }
.aq-spec:not(.aq-spec--compare) tbody tr.is-lead + tr:not(.is-lead), .aq-spec:not(.aq-spec--compare) tbody tr.is-lead + tr:not(.is-lead) + tr { border-top: 0; }
.aq-spec:not(.aq-spec--compare) tbody tr.is-lead th { font: 500 20px/28px var(--font-sans); letter-spacing: -0.005em; }
.aq-spec:not(.aq-spec--compare) tbody tr.is-lead .aq-spec__value { align-self: center; font: 400 20px/28px var(--font-mono); letter-spacing: -0.01em; }
.aq-spec:not(.aq-spec--compare) tbody tr.is-lead .aq-spec__status { justify-self: start; }
.aq-spec:not(.aq-spec--compare) tbody tr.is-highlight:not(.is-lead) { margin-inline: calc(var(--space-4) * -1); padding-inline: var(--space-4); }
.aq-spec:not(.aq-spec--compare) tbody tr.is-highlight ~ tr.is-highlight:not(.is-lead) { padding-left: calc(var(--space-4) - 2px); }

/* Readout lead row: a lead row whose value holds a number sets that limit as the section's one readout figure
   (Geist Mono 300 40/44, the unit beside it in ink-muted), with the parameter, the full value and the basis to its
   right. Same flow-tint band as any lead row. The figure is aria-hidden; the value cell keeps the full text. */
