.aq-spec__read-n { font: 300 40px/44px var(--font-mono); letter-spacing: -0.02em; font-variant-numeric: tabular-nums; color: var(--ink); white-space: nowrap; }
.aq-spec__read-u { font: 400 14px/20px var(--font-mono); color: var(--ink-muted); }
.aq-spec:not(.aq-spec--compare) tbody tr.is-readout th { font: 500 20px/28px var(--font-sans); }
.aq-spec:not(.aq-spec--compare) tbody tr.is-readout .aq-spec__value { align-self: start; font: 400 14px/24px var(--font-mono); }
.aq-spec:not(.aq-spec--compare) tbody tr.is-readout .aq-spec__method { color: var(--ink-muted); }

/* Row link (rows[].link): a quiet page link under the basis, "FAT and SAT →" */
.aq-spec__link { display: block; margin-top: var(--space-1); font: 500 14px/20px var(--font-sans); color: var(--flow); text-decoration: none; }
.aq-spec__link::after { content: "\a0\2192"; content: "\a0\2192" / ""; }
.aq-spec__link:hover { text-decoration: underline; text-underline-offset: 3px; }
.aq-spec__link:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
/* Note link (block fields note_link, note_link_label): the note's last words, a text link in the same grammar inline
   in the small line, "… water. What it costs to run →" */
.aq-spec__note-link { font-weight: 500; color: var(--flow); text-decoration: none; }
.aq-spec__note-link::after { content: "\a0\2192"; content: "\a0\2192" / ""; }
.aq-spec__note-link:hover { text-decoration: underline; text-underline-offset: 3px; }
