  .aq-spec:not(.aq-spec--compare) .aq-spec__method,
  .aq-spec:not(.aq-spec--compare) tbody tr.is-highlight .aq-spec__method { display: block; margin-top: var(--space-1); font-size: 13px; line-height: 20px; }
  .aq-spec__link { display: inline; margin: 0; padding-block: calc(var(--space-3) + var(--space-1) / 2); font-size: 13px; line-height: 20px; }
  .aq-spec__note-link { padding-block: calc(var(--space-3) + var(--space-1) / 2); }
  .aq-spec:not(.aq-spec--compare) tbody tr.is-lead.is-readout { display: block; padding: var(--space-4) var(--space-3); }
