  padding: 1px; background: conic-gradient(from var(--aq-a, 0deg), transparent 0 70%, color-mix(in srgb, var(--flow) 40%, transparent) 84%, var(--flow) 94%, transparent 100%);
  -webkit-mask: linear-gradient(black, black) content-box, linear-gradient(black, black); -webkit-mask-composite: xor;
