.wform .aq-field__input { transition: border-color 150ms cubic-bezier(0.2, 0, 0, 1), box-shadow 150ms cubic-bezier(0.2, 0, 0, 1); }
.aq-form__ok { display: inline-grid; place-items: center; vertical-align: -2px; margin-left: var(--space-2); color: var(--pass); }
