@media (prefers-reduced-motion: reduce) { .wform .aq-field__input { transition: none; } }

@container (max-width: 860px) {
  /* Phones: tighter panel, one column, full-width submit */
  .aq-form { gap: var(--space-6); padding: 0 var(--space-4) var(--space-6); }
  .aq-form .aq-form__title { margin-inline: calc(-1 * var(--space-4) - 1px); padding: var(--space-3) var(--space-4); }
  .aq-form__progress li { font-size: 13px; line-height: 18px; padding-right: var(--space-2); }
  .aq-form__num { font-size: 22px; line-height: 26px; }
  .aq-form__grid { grid-template-columns: minmax(0, 1fr); gap: var(--space-4); }
  .aq-form__legend { margin-bottom: var(--space-4); font-size: 18px; line-height: 26px; }
  .aq-form__submit { width: 100%; justify-content: center; }
}

/* ---------- TextField ---------- */
.aq-field { display: grid; gap: var(--space-2); max-width: 420px; min-width: 0; }
.aq-field__label { font: 500 14px/20px var(--font-sans); color: var(--ink); }
.aq-field__optional { font-weight: 400; color: var(--ink-muted); }
.aq-field__input {
  width: 100%; height: 44px; padding: 0 var(--space-4); box-sizing: border-box;
  background: var(--surface-raised); color: var(--ink);
  border: 1px solid var(--line-strong); border-radius: var(--radius-sm);
  font: 400 16px/24px var(--font-sans);
}
textarea.aq-field__input { height: auto; min-height: 120px; padding: var(--space-3) var(--space-4); resize: vertical; }
.aq-field__input::placeholder { color: var(--ink-subtle); }
.aq-field__input:hover { border-color: var(--ink-muted); }
.aq-field__input:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; border-color: var(--ink); }
.aq-field__suffix { position: relative; }
.aq-field__suffix .aq-field__input { padding-right: 64px; font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.aq-field__unit { position: absolute; right: var(--space-4); top: 50%; transform: translateY(-50%); font: 400 14px/20px var(--font-mono); color: var(--ink-muted); }
.aq-field__help { margin: 0; font: 400 14px/22px var(--font-sans); color: var(--ink-muted); }
/* Focus: the field's border and label take flow while the keyboard ring sits outside it */
.aq-field__input:focus { border-color: var(--flow); }
.aq-field:focus-within > .aq-field__label, .aq-fieldset:focus-within > .aq-field__label { color: var(--flow); }
.aq-field:focus-within .aq-form__ref { color: var(--flow); }
/* Error: fail border with a fail edge on the left, and one line under the field saying what to fix */
.aq-field.is-error .aq-field__input { border-color: var(--fail); box-shadow: inset 3px 0 0 var(--fail); }
.aq-field.is-error .aq-field__help { color: var(--ink-muted); }
.aq-field__error { display: flex; align-items: baseline; gap: var(--space-2); margin: 0; font: 500 14px/20px var(--font-sans); color: var(--fail); }
.aq-field__error::before { content: "!"; content: "!" / ""; flex: none; display: inline-grid; place-items: center; width: var(--space-4); height: var(--space-4); border-radius: var(--radius-pill); background: var(--fail); color: var(--surface); font: 600 11px/1 var(--font-mono); transform: translateY(2px); }
.aq-fieldset.is-error .aq-checks label { border-color: var(--fail); }
.aq-fieldset.is-error > .aq-field__error { margin-top: var(--space-2); }
@media (prefers-reduced-motion: no-preference) {
  .aq-field__input, .aq-field__label { transition: border-color 120ms, box-shadow 120ms, color 120ms; }
}
.aq-fieldset { border: 0; padding: 0; margin: 0; min-width: 0; }
.aq-checks { display: flex; flex-wrap: wrap; gap: var(--space-2) var(--space-6); }
.aq-checks label { display: inline-flex; gap: var(--space-2); align-items: center; font: 400 15px/24px var(--font-sans); color: var(--ink); }
